INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-medmcqa-bachelor-medicine-anatomy-en-1','آناتومی · منتخب MedMCQA','bachelor-medicine','reference','medmcqa',NULL,'منبع باز',1793577600000,0,'MedMCQA — Pal, Umapathi & Sankarasubbu, 2022. Validation split via Open Life Science AI; Apache-2.0. متن اصلی انگلیسی؛ آزمون رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('c8893e5286ae375dc3994b74a5a14914','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"ce49098b-cc48-4168-859e-936e3e0c7459","subjectId":"anatomy","chapter":"آناتومی","prompt":"Which of the following are not a branch of external carotid Aery in Kiesselbach''s plexus.","options":["Sphenopalatine aery","Anterior ethmoidal aery","Greater palatine aery","Septal branch of superior labial aery"],"correctIndex":1,"explanation":"*Kiesselbach''s plexus: Antero superior pa is supplied by ANTERIOR & POSTERIOR ETHMOIDAL AERIES which are branches of ophthalmic aery, branch of INTERNAL CAROTID AERY. Antero inferior pa is supplied by SUPERIOR LABIAL AERY - branch of facial aery, which is branch of EXTERNAL CAROTID AERY. Postero superior pa is supplied by SPHENO-PALATINE AERY - branch of MAXILLARY aery, which is branch of ECA. POSTERO INFERIOR pa is supplied by branches of GREATER PALATINE AERY - branch of ECA Antero inferior pa/vestibule of septum contain anastomosis b/w septal ramus of superior labial branch of facial aery & branches of sphenopalatine, greater palatine & anterior ethmoidal aeries. These form a large capillary network called KIESSELBACH''S PLEXUS If dryness persists, bleeding will occur Therefore, in given options, Anterior ethmoidal aery is a branch of ICA not ECA","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ce49098b-cc48-4168-859e-936e3e0c7459","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5721c872e687c77fe9693f7014621324','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"e845e625-845e-4d02-ab3f-e00f2284d62e","subjectId":"anatomy","chapter":"آناتومی","prompt":"Which of the following is the only complete cailage ring in the respiratory tree?","options":["Cricoid cailage","Thyroid cailage","Cunieform cailage","Epiglottis"],"correctIndex":0,"explanation":"Answer- A (Cricoid cailage)(Ref: BDC 5/e Vol lII/p238)Complete cailage ring is seen in Cricoid cailage.Cricoid cailage is shaped like a ring. It encircles the larynx below the thyroid cailage. It is thicker and stronger than the thyroid cailage.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e845e625-845e-4d02-ab3f-e00f2284d62e","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('30accc85fc7dd8b048642599dd92c0df','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"0e46082c-1abc-4330-a12d-6948554559a2","subjectId":"anatomy","chapter":"آناتومی","prompt":"The cells which will proliferate from top to bottom of villi are:","options":["Chief cells","Goblet cells","Paneth cells","Parietal cells"],"correctIndex":2,"explanation":"Paneth cells or zymogen cells are found only in the deeper parts of the intestinal crypts. They contain prominent eosinophilic secretory granules. They also contain high amount of zinc. They are known to produce lysozyme, defensins and TNF alpha that destroy bacteria. They exceptionally migrate towards the base of the crypts of Lieberkuhn instead of going toward the villi","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0e46082c-1abc-4330-a12d-6948554559a2","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3095cbf2be58e5021e400f59aaff3b4a','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"0d96ee7c-7133-4d5a-becf-f9ad47582e54","subjectId":"anatomy","chapter":"آناتومی","prompt":"Artery palpable at the anterior border of the masseter is :","options":["Superficial temporal artery","Facial artery","Lingual artery","Maxillary artery"],"correctIndex":1,"explanation":"Facial artery enters the face by winding around the base of the mandible, and by piercing the deep cervical fascia, at the anteroinferior angle of the masseter muscle. It can be palpated here and is called ‘anaesthetist’s artery’.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0d96ee7c-7133-4d5a-becf-f9ad47582e54","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2807526b86496564a83d74d125142634','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"58d24187-ca26-4e5b-a3d9-c57ce0ff543b","subjectId":"anatomy","chapter":"آناتومی","prompt":"Visual cortex is present in the:","options":["Occipital lobe","Temporal lobe","Frontal lobe","Parietal lobe"],"correctIndex":0,"explanation":"The lateral geniculate body receives retinal fibres of both the eyes (from temporal half of the retina of the same side and nasal half of the retina of the opposite side) through optic tract and gives rise to fibres of the optic radiation which convey visual impulses to the visual cortex of the occipital lobe. Primary visual area is situated mainly on the medial surface of the occipital lobe in the walls and floor of the posterior part of the calcarine sulcus (postcalcarine sulcus) and extends around the occipital pole onto the lateral surface of the occipital lobe as far as the lunate sulcus. Reference: TEXTBOOK OF ANATOMY HEAD, NECK AND Brain, Volume III, second edition page no 384, 393","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"58d24187-ca26-4e5b-a3d9-c57ce0ff543b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5437c1f189022482cf53aa10012c105c','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"4df0486d-1aba-4df0-9a1f-fd86bb8acc9a","subjectId":"anatomy","chapter":"آناتومی","prompt":"Which of the following structure is not present on floor of third ventricle?","options":["Optic stalk","Third nerve","Infundibulum","Mammillary body"],"correctIndex":1,"explanation":"Answer- B (Third nerve)The third nerve (Oculomotor) does not form the floor of the third ventricle although it lies in close relation to the floor.The anterior wall of the third ventricle is formed by Lamina terminalis, Anterior commissure, Anterior columns of the fornixThe posterior wall is formed by the Pineal body, Posterior commissure, Cerebral aqueduct.The roof is formed by Body of fornix and the ependyma lining the undersurface of the tela choroidea of the third ventricle.The floor of the third ventricle is formed by Optic chiasma, Tuber cinereum, Infundibulum, the Mammillary bodies, Posterior perforated substance, and Tegmentum of the midbrain. The lateral wall is formed by the Medial surface of the thalamus, Hypothalamus, and the Hypothalamic sulcus.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4df0486d-1aba-4df0-9a1f-fd86bb8acc9a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('19d0b7226daa7208fc707c0b246a25bd','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"13088525-20c1-4b21-8fba-f48097969211","subjectId":"anatomy","chapter":"آناتومی","prompt":"The fifth nerve innervates the following:","options":["Mylohyoid, anterior and posterior belly of digastric","Mylohyoid, anterior belly of digastric, and tensor tympani","Mylohyoid, posterior belly of digastric and tensor tympani","Mylohyoid, posterior belly of digastric, Stapedius and tensor tympani"],"correctIndex":1,"explanation":"Trigeminal nerve is the 5th cranial nerve. It is a mixed nerve containing both the motor and sensory fibres but predominantly it is sensory. It is a motor nerve to the muscles of mastication and several small muscles and the principal sensory nerve of the head and face. It consists of three large nerves: ophthalmic, maxillary, and mandibular, hence the name trigeminal nerve (L. trigeminus = triplet). Key concept: Mandibular nerve supplies muscles of mastication mylohyoid, anterior belly of digastric, and tensor tympani. Posterior belly of digastric and stapedius are supplied by Facial nerve.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"13088525-20c1-4b21-8fba-f48097969211","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('141dd4b4c358c3c13979fced9c04d1e0','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"b3163789-82b3-4054-aabe-3a2b90aa7a98","subjectId":"anatomy","chapter":"آناتومی","prompt":"Which marker shows holocrine gland?","options":["A","B","C","D"],"correctIndex":0,"explanation":"Marker (A) shows the Holocrine gland i.e, Sebaceous gland related with hair follicle sending sebum to skin surface. Marker (C) - Hair follicle Marker (D) - Sub cutaneous fat (Adipocytes) - empty looking cells with fat & peripheral nucleus - Usually skin & sebaceous glands have - stratified squamous epithelium","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b3163789-82b3-4054-aabe-3a2b90aa7a98","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('fe20ec532f0dfbd5fe750b87f91741a4','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"7060bcf3-fde4-41e3-ad46-260857a92b46","subjectId":"anatomy","chapter":"آناتومی","prompt":"Action of the muscle marked (with arrow) on mandible is","options":["Elevation","Depression","Retraction","Protraction"],"correctIndex":0,"explanation":"Muscle marked - temporalis Elevators of mandible: MTM Masseter Elevation, protraction Temporalis Elevation retraction Medial pterygoid Elevation, protraction Depressors of mandible Lateral pterygoid Depression, protraction Mylohyoid Depression Ant. belly of digastric Depression Muscle of mastication develop from 1st pharyngeal arch Nerve - mandibular branch of trigeminal.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"7060bcf3-fde4-41e3-ad46-260857a92b46","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('0db25279fb124017ebec8642cbd66126','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"69c15b27-e061-413c-a011-854ea197f141","subjectId":"anatomy","chapter":"آناتومی","prompt":"Nucleus in brain common to IX, X and XI cranial nerves:","options":["Nucleus solitarius","Nucleus ambiguus","Dentate nucleus","Red nucleus"],"correctIndex":1,"explanation":"The nucleus ambiguus is a group of large motor neurons, situated deep in the medullary reticular formation. The nucleus ambiguus contains the cell bodies of nerves that innervate the muscles of the soft palate, pharynx, and larynx which are strongly associated with speech and swallowing. Nucleus in brain common to IX, X and XI cranial nerves is nucleus ambiguous.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"69c15b27-e061-413c-a011-854ea197f141","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('cbe0da727c1ed898bd2fb45437200a7e','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"93c4a1a4-7b8b-4d71-b246-3125604bc899","subjectId":"anatomy","chapter":"آناتومی","prompt":"Which of the following muscles causes the forward movement of the condyle in the glenoid fossa?","options":["Masseter","Temporalis","Medial pterygoid","Lateral pterygoid"],"correctIndex":3,"explanation":"The lateral pterygoid muscle has 2 heads, one arising from the outer part of the lateral pterygoid plate and other from the base of sphenoid bone. The two heads come together and are inserted into the neck of the condyle. The main function of this muscle is to draw both the head of the condyle and the disc forward during opening movement. Lateral pterygoid muscles cause the forward movement of the condyle into the glenoid fossa.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"93c4a1a4-7b8b-4d71-b246-3125604bc899","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('6fa5e69292719fa6b8013ca2c71ac1ae','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"b5135682-e700-4fda-a6b2-39b289c3cc41","subjectId":"anatomy","chapter":"آناتومی","prompt":"When a patient is asked to say ''ah'' , if the uvula is drawn upwards to the left, the cranial nerve likely to be damaged is","options":["Vagus","Rt accessory","Lt accessory","Hypoglossal"],"correctIndex":1,"explanation":"{All the muscles of soft palate are supplied by pharyngeal plexus derived from the cranial part of accessory nerve except tensor veli palatine which is supplied by the mandibular nerve. The action of musculus uvula is it pulls up the uvula. As the Right accessory is paralysed the uvula is drawn to the left side due to the normal action of left accessory.}","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b5135682-e700-4fda-a6b2-39b289c3cc41","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9c4fa7830e68ecf98faffc6856e3fc7c','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"e60f51ab-3827-4ddd-9649-a6d601b9682c","subjectId":"anatomy","chapter":"آناتومی","prompt":"Root value of cremaster reflex is","options":["L1, L2","L2, L3","S1, S2","S3, S4"],"correctIndex":0,"explanation":"In Men, Cremaster muscle & cremaster fascia form middle/2nd covering of spermatic cord. This muscle & Its associated fascia are supplied by genital branch of GENITOFEMORAL NERVE(L1 L2) Contraction of this muscle & resulting elevation of testis can be stimulated by reflex arc Gently touching the skin at & around the anterior aspect of superior pa of thigh stimulates sensory fibers in femoral branch of genito-femoral N/ Ilio-Inguinal N. These fibers enter spinal cord at L1 At L1, Sensory fibers stimulate motor fibers carried in genital branch of genito-femoral N, which results in contraction of cremaster muscle & elevation of testis. Cremasteric reflex is more active in children, tending to diminish with age. As with many reflexes, it may be absent in ceain neurological disorders. Although, it can be used for testing spinal cord function at level L1 in men, Its clinical use is limited.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e60f51ab-3827-4ddd-9649-a6d601b9682c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('c77d7657041dad875f3ca6365fe292a0','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"eb41d147-19ed-4497-906a-8997f8979545","subjectId":"anatomy","chapter":"آناتومی","prompt":"The 3 embryonic germ layers: ectoderm, mesoderm and endoderm are derived from:","options":["Epiblast only","Ectoderm from epiblast; mesoderm and endoderm from hypoblast","Ectoderm and mesoderm from epiblast; endoderm from hypoblast","Hypoblast only"],"correctIndex":0,"explanation":"All three embryonic germ layers (ectoderm, mesoderm and endoderm) are derived from the epiblast only. The hypoblast contributes to the development of the extraembryonic mesoderm and yolk sac and plays a key role in signaling to establish axial patterning in the embryo itself","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"eb41d147-19ed-4497-906a-8997f8979545","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('82ff8013b0061544ec1a2970902fcfaa','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"9c1d56d9-5f46-4d3f-87e6-894a31c98f27","subjectId":"anatomy","chapter":"آناتومی","prompt":"Retraction of the protruded mandible is done by","options":["Medial Pterygoid","Lateral pterygoid","Masseter","Temporalis"],"correctIndex":3,"explanation":"Depression of mandible is caused by lateral pterygoid (main), digastric, geniohyoid & mylohyoid. And Elevation of mandible by temporalis, medial pterygoid & masseter.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"9c1d56d9-5f46-4d3f-87e6-894a31c98f27","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('255262a62039633be579047be9ac950c','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"0b81f878-0e23-4c6b-9fcd-697e8ea660c3","subjectId":"anatomy","chapter":"آناتومی","prompt":"Inferiohyroid aery is a branch ol?","options":["Thyrocervical trunk","ICA","Costocervical trunk","ECA"],"correctIndex":0,"explanation":"Ans. A. Thyrocervical trunkRef: Grays Anatomy,4Ia ed., pg. 455458Inferior thyroid aery is branch of thyrocervical trunk of subclan aery.The thyrocervical trunk arises fiom the front of the first pa of the subclan aery near the medial border of scalenus anterior, and divides into the inferior thyroid, suprascapular and superficial cervical aeries.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0b81f878-0e23-4c6b-9fcd-697e8ea660c3","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('6a26ad9527396cc605c364925b194906','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"464d6db1-cbf6-44c5-89b0-1599071e3a72","subjectId":"anatomy","chapter":"آناتومی","prompt":"What is the nerve supply of the angle of the jaw?","options":["Mandibular nerve","Maxillary nerve","Lesser occipital nerve","Greater auricular nerve"],"correctIndex":3,"explanation":"Ans: D. Greater auricular nerve(Ref: Gray''s 41Ie p407, 413, 40Ie p435)The skin over the angle of mandible is supplied by the greater auricular nerve, which carries branches from anterior ramus of C2 and C3. Branches of Upper Cervical Spinal NervesGreat auricular nerveBranches from anterior rami of 2\" & 3rd cervical spinal nervesdegInnervates skin over the angle of mandible, parotid gland & earlobedegLesser occipital nerveBranches from anterior rami of 2\" & 3rd cervical spinal nervesdegInnervates scalp behind the eardeg.Greater occipital nerveBranching off the posterior ramus of the 2\" cervical spinal nervesdegInnervates scalp of occipital areadeg3rd occipital nerve:Branches off the posterior ramus of 3rd cervical nervedegInnervates scalp in occipital & sub occipital areasdeg.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"464d6db1-cbf6-44c5-89b0-1599071e3a72","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9276b78b4c2003778adfc1fdab1246e9','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"8cc0f461-86ab-4fdf-97f4-194da3dc5e26","subjectId":"anatomy","chapter":"آناتومی","prompt":"What is the location of Meissner''s corpuscles?","options":["Lucidum","Basale","Reticular dermis","Papillary dermis"],"correctIndex":3,"explanation":"Ans. d. Papillary dermisMeissner corpuscles are encapsulated nerve endings present in dermal papillae.Merkel cells location: Stratum basalePacinian corpuscle location: Reticular layer of dermis","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"8cc0f461-86ab-4fdf-97f4-194da3dc5e26","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ef330bc1340d35294fd70efc10766839','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"7a51e736-c9fd-452f-8d09-127583a42886","subjectId":"anatomy","chapter":"آناتومی","prompt":"Compament of leg without neurovascular bundle?","options":["Anterior","Lateral","Deep posterior","Superficial posterior"],"correctIndex":3,"explanation":"Ans. d. Superficial posteriorRef: Grays Anatomy, 4lst ed, pg- 1406-1412 and Last anatomy 12th ed, pg. 142Contents of flexor (posterior) compament:Superficial pa:Gastrocnemius, plantaris and soleus musclesDeep pa:Popliteus, Flexor digitorum longus, flexor hallucis longus and Tibialis posterior musclePosterior tibial and peroneal vesselsTibial nerve","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"7a51e736-c9fd-452f-8d09-127583a42886","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1f0c1dbbcd27dba0732829bdfd169324','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"433889ad-6b7a-4b52-b45d-2e2379f81d5e","subjectId":"anatomy","chapter":"آناتومی","prompt":"Which of the following finger has two dorsal interossei (AIIMS May 2019)","options":["Little","Ring","Middle","Index"],"correctIndex":2,"explanation":"Dorsal interossei: Dorsal interossei are major abductors of index, middle & ring fingers. Most dorsally situated of all intrinsic muscles. Palpated through skin on dorsal aspect of hand. Tendons of dorsal interossei pass dorsal to deep transverse metacarpal ligament. - 1st dorsal interosseous muscle - largest & inses into lateral side of index finger. - 2nd& 3rd interosseous muscle - inse into lateral & medial sides respectively of middle finger. - 4th dorsal interosseous muscle - inses into medial side of ring finger. Thumb & little finger do not have dorsal interossei as they have their own abductors in thenar & hypothenar muscle groups respectively. Dorsal interossei + palmar interossei + lumbricals flex-metacarpophalangeal joint & extend inter - phalangeal joint.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"433889ad-6b7a-4b52-b45d-2e2379f81d5e","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('012b342e496013a86b3796bb99bc9f90','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"294f261f-83db-483c-ab08-7ada6462f72b","subjectId":"anatomy","chapter":"آناتومی","prompt":"Spinal cord ends at what level in adults?","options":["T12","L1","L2","L3"],"correctIndex":1,"explanation":"Ans. b. L1 Ref: Grays Anatomy, 4l'''' ed., pg. 762-763In the adult, the spinal cord terminates on average at the level of the middle third of the body of the first lumbar veebra which corresponds approximately to the transpyloric plane.Spinal cord extends from C I to L I (lower border) in adults.Filum terminale extends from lower end of spinal cord to the tip of coccyx.Dural sheath extends up to 52 veebrae.Subdural space extends up to 52.Subarachnoid space extends up to 52.Piamater extends up to tip of coccyx.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"294f261f-83db-483c-ab08-7ada6462f72b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('c261c51b3aeb6bf9cf0faabee45c7f65','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"12342b20-b7a0-4f14-91ed-c764fc51ed7b","subjectId":"anatomy","chapter":"آناتومی","prompt":"Sensory supply of cornea is by?","options":["Infraorbital nerve","Supraorbital nerve","Infratrochlear nerve","Nasolacrimal nerve (probably printing mistake - probably Nasociliary nerve)."],"correctIndex":3,"explanation":"Ans: D. Nasolacrimal nerve (probably printing mistake - probably Nasociliary nerve).Cornea:Richly supplied by nerves (without myelin sheaths & Schwann cell sheath).Extremely sensitive structure - Due to its dense nerve supply.Ooriginate from small ophthalmic division of trigeminal nerve, mainly by long ciliary nerve.Long ciliary nerve - Branch of Nasociliary nerve.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"12342b20-b7a0-4f14-91ed-c764fc51ed7b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('174c2d8eb3b0d3dcc8dc30ee9307a0c9','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"f1f62761-750a-4d61-ae39-13f4c4e131d5","subjectId":"anatomy","chapter":"آناتومی","prompt":"Left superior intercostal vein drains into ?","options":["Azygous vein","Hemiazygous vein","Brachiocephalic vein","Internal thoracic vein"],"correctIndex":2,"explanation":"2,3,4-posterior intercostal vein on left side drains into left superior intercostal which fuher drains into left brachiochephalic vein . Right and left brachiocephalic veins joins to form superior vena cava that opens into right atrium Posterior Intercostal Veins and their drainage: Right side drains into 1stposterior intercostal vein Right brachiocephalic vein 2,3,4 posterior intercostal vein Arch of azygos vein 5 to 11 posterior intercostal vein Azygos vein Left side drains into 1stposterior intercostal vein Left brachiocephalic vein 2,3,4-posterior intercostal vein Left brachiocephalic vein 5,6,7 posterior intercostal vein Superior hemiazygous vein 8,9,10 posterior intercostal vein Inferior hemiazygous vein","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f1f62761-750a-4d61-ae39-13f4c4e131d5","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('fd5f6f5f1fa2c61a161ba1be93e0d951','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"498c56bd-94f3-48de-b981-5c6400ee5700","subjectId":"anatomy","chapter":"آناتومی","prompt":"Located medial to the third molar at the junction of the maxilla and the horizontal plate of the palatine bone:","options":["Posterior nasal spine","Mylohyoid line","Pterygoid hamulus","Greater palatine foramen"],"correctIndex":3,"explanation":"Greater palatine foramen located medial to the third molar at the junction of the maxilla and the horizontal palate of the palatine bone. Greater palatine foramen transmits descending palatine vessels and palatine nerve.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"498c56bd-94f3-48de-b981-5c6400ee5700","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7bc371ddfe9b6342890349d34bf34484','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"42c3b6ae-45e3-405f-b8bd-fa6a17924c6b","subjectId":"anatomy","chapter":"آناتومی","prompt":"In gene studies, the specific site to which the enzyme CRE recombinase binds is:","options":["RE site","LoxP site","NT site","F site"],"correctIndex":1,"explanation":"Ans: B. LoxP siteCre-Lox recombination - Known as \"Site-specific recombinase technology\".* Widely used to carry out deletions, inseions, translocations & inversions at specific sites in cellular DNA.* Consists of Cre-recombinase enzyme. - Recombines a pair of sho target sequences called \"Lox sequences\".* Cre enzyme & original Lox site - Referred as \"LoxP sequence\" - Derived from bacteriophage P1.* Lox P (locus of X-over P1) - Site on bacteriophage P1 consisting of 34 bp.Ref https://en.wikipedia.oig/wiki/Cre-Lox_recombination)","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"42c3b6ae-45e3-405f-b8bd-fa6a17924c6b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('12ab2b26b9bb5cd21a28fc61a603bbe0','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"73ba7368-c001-4d15-b4a3-f0d46feb4b5b","subjectId":"anatomy","chapter":"آناتومی","prompt":"Loss of flexion in the interphalangeal joint of thumb in supracondylar fracture is due to involvement of which nerve","options":["Anterior interosseous","Posterior interosseous","Median","Ulnar"],"correctIndex":0,"explanation":"Flexion at IP joint of thumbs - by flexor pollicis longus Nerves that may be involved in supracondylar humerus : 1. Median nerve - most common Paial injury occurs usually. i.e. fibers involved in forming AIN branch. 2. Radial nerve - less often 3. Ulnar nerve - least commonly involved. AIN supply: Flexor pollicis longus * Lateral 1/2 of flexor digitorum profundus * Pronator quadratus","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"73ba7368-c001-4d15-b4a3-f0d46feb4b5b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3d36821f5bcdd252d051432540ef5b5c','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"650d801f-749f-480f-bad9-399be17408a5","subjectId":"anatomy","chapter":"آناتومی","prompt":"Golgi apparatus in serous acinar cells is at:","options":["Supranuclear","Apical","Adjacent to nucleus","Basal"],"correctIndex":0,"explanation":"Ans. a. SupranuclearSerous cells have a pyramidal shape.They possess large amounts of rough endoplasmic reticulum (RER) with many ribosome free regions, supranuclear Golgi complex and numerous spherical secretory granules.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"650d801f-749f-480f-bad9-399be17408a5","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e4e302204d3e62cf96f089c709847043','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"081f057e-a610-4985-89dd-309cf04cbe5c","subjectId":"anatomy","chapter":"آناتومی","prompt":"Nociceptive signals are transmitted primarily to which of the following?","options":["Nucleus caudalis","Limbic system","Reticular system","Superior cervical ganglion"],"correctIndex":0,"explanation":"Trigeminal Nucleus caudalis is an important site for processing orofacial nociceptive input. After activation of C and A delta fibres, they transmit nociceptive signals primarily via trigeminal nerves to Trigeminal Nucleus caudalis. It is also called as medullary dorsal horn as it has similar anatomical resemblance to spinal dorsal horn.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"081f057e-a610-4985-89dd-309cf04cbe5c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('a4a3c13124cf44aa2c1e4390b4dccd97','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"794874bb-f41b-467b-aea5-7c98b68f7849","subjectId":"anatomy","chapter":"آناتومی","prompt":"The nerve which constitutes the sensory nerve supply of capsule of TMJ is:","options":["Auriculotemporal nerve","Facial nerve","Masseteric nerve","Auricular nerve"],"correctIndex":0,"explanation":"Branches of auriculotemporal nerve i. Slender filaments to the posterior part of the capsule of TMJ ii. One or two thick branches to the parotid gland which mingle with the branches of the facial nerve in its substance. iii. Cutaneous branches to the auricle and temple.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"794874bb-f41b-467b-aea5-7c98b68f7849","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2a5f5bef875e18ac8c00437f8f6c286d','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"d0aaea50-8928-4b40-ad20-7161f679bbc0","subjectId":"anatomy","chapter":"آناتومی","prompt":"Which of the following marked muscles is Involved in Opening of jaw?","options":["A","B","C","D"],"correctIndex":0,"explanation":"Depression of Mandible done by Lateral Pterygoid Mylohyoid Anterior belly of digastric muscle *In the image Marker A - Lateral Pterygoid Marker B - Lateral to mandible bone - Masseter Marker C - TowardsTemporal region - Temporalis (retraction of Mandible) Marker D - Subcutaneous Muscle - Buccinator (Cheek muscle - Accessory Muscle for mastication) *Angle of mandible has Masseter laterally Medial pterygoid medially *ELEVATORS- Mnemonic - MTMe M - Masseter T - Temporalis M - Medial Pterygoid","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d0aaea50-8928-4b40-ad20-7161f679bbc0","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('590ff76e0004a89960ea310d53976f2c','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"d810c51c-b15e-40e7-9d7c-2eff29038877","subjectId":"anatomy","chapter":"آناتومی","prompt":"Ligamentum flavum consists of:","options":["Type-II collagen","Type-III collagen","Reticulin","Elastin"],"correctIndex":3,"explanation":"Ans. D. ElastinLigamentum flavum connects the laminae of adjacent veebrae.The ligamentum flavum has a high content of elastin. So under tension it can be stretched by 80% without damage.Functions of ligamentum flavum to provide a constant smooth lining to the veebral canal, which is never overstretched in flexion and which never goes slack in extension.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d810c51c-b15e-40e7-9d7c-2eff29038877","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('22e9da976f8d7e68dcd709fa4b9c941a','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"45588c4c-da93-43ca-8ee4-05feb851be68","subjectId":"anatomy","chapter":"آناتومی","prompt":"Which is not a branch of the external carotid aery supplying nasal septum?","options":["Sphenopalatine","greater palatine","superior labial","anterior ethmoidal"],"correctIndex":3,"explanation":"Ans. D. anterior ethmoidalThe nasal septum also derives its blood supply from :Branches from the external carotid aery are the sphenopalatine aery, the greater palatine aery, the superior labial aery, and the angular aery.The main branches from the interior carotid are the anterior ethmoidal aery, and the posterior ethmoidal aery that supplies the septum, and these derive from the ophthalmic aery.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"45588c4c-da93-43ca-8ee4-05feb851be68","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('4f9c12cf4421687412ef3236ca66d1e5','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"6f132291-8a44-47a8-9979-1d359c074a7c","subjectId":"anatomy","chapter":"آناتومی","prompt":"Nerve supply of the mucosa of larynx, from epiglottis to the level of the cords is :","options":["Superior laryngeal","External laryngeal","External laryngeal and recurrent laryngeal","Internal laryngeal and recurrent laryngeal"],"correctIndex":0,"explanation":"The larynx is innervated bilaterally by the superior laryngeal nerve (supplies mucosa from the epiglottis to the level of the cords) and the recurrent laryngeal nerve (supplies mucosa below the cords), both branches of the vagus nerve (CN X)..","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6f132291-8a44-47a8-9979-1d359c074a7c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('fe47343c50129e027290a556c42a7390','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"0ec4a50e-3eb2-44e9-97c5-527a8c6fdd68","subjectId":"anatomy","chapter":"آناتومی","prompt":"Which of the following muscle is not inseed to the greater tubercle of humerus?","options":["Supraspinatus","lnfraspinatus","Teres minor","Subscapularis"],"correctIndex":3,"explanation":"Ans: D SubscapularisSubscapularis muscle - Largest component of the posterior wall of the axilla.Origin: From subscapularis fossa & also fills it.Inseion: To lesser tubercle of humerus.Inseions of greater tubercle of humerusSupraspinatusInfraspinatusTeres minor","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0ec4a50e-3eb2-44e9-97c5-527a8c6fdd68","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2eac19dfb5875b80deb2eb4b55f4b521','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"744e4dce-b8f1-447f-a964-bea1bbe98edf","subjectId":"anatomy","chapter":"آناتومی","prompt":"Liver is divided into eight segments according to Couinaud''s classification based upon","options":["Bile Duct","Poal vein","Hepatic Vein","Hepatic aery"],"correctIndex":1,"explanation":"Segmental anatomy of liver. Liver is divided into 8 segments by DAV structures (bile duct, hepatic aery, poal vein) Poal vein is most impoant among them Left hepatic vein separates medial & lateral segments Right hepatic vein separates anterior & posterior segments Poal vein separates upper & lower segments From surgical perspective, right hepatectomy - involve division of liver in principle plane in which segment V, VI, VII, VIII would be removed leaving segments I, II, III, IV Hepatic vein is now removed from couinaud''s classification","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"744e4dce-b8f1-447f-a964-bea1bbe98edf","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('05201ec30a2a02dc4e1eac8011df05ff','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"46872392-e33f-464f-a194-93ea23830da9","subjectId":"anatomy","chapter":"آناتومی","prompt":"Which of the following cranial nerve not associated with olfaction?","options":["XII","IX","V","X"],"correctIndex":0,"explanation":"Ans. A. XIIXII nerve is a motor nerve; does not play role in olfaction and gustation.Cranial Nerves -- Components and FunctionsNumberNameFunctionIOlfactory nerve Smell sensationIIOptic nerve VisionIIIOculomotor Turns eyeball upward, downward,and medially; Raises upper eyelid, alsoconstricts pupil; accommodates eyeIVTrochlear nerve It helps in turning eyeball downwardand laterallyVTrigeminalMaxillarydivisionSupplies dura mater of anterior paof middle cranial fossa, conjunctiva ofinferior eyelid, skin of face over maxilla;teeth of upper jaw; mucous membrane NumberNameFunction OphthalmicdivisionSupplies cornea, superior conjunctiva,skin of dorsum of external nose,forehead, scalp, superior eyelids, andalso mucous nasal cavity, ethmoid,frontal and sphenoid sinuses MandibulardivisionSkin of lower lip, buccal, parotid andtemporal regions of face, external ear(Auricle, tympanic membrane andacoustic meatus), mucous membraneof mouth and anterior two-third paof tongue. Supplies 4 muscles of mastication,mylohyoid, anteriorbelly of digastric, tensor tympani andtensor veli palatini VI Abducent Lateral rectus muscle turns eyeballlaterally NumberName FunctionVIIFacial Taste from anterior two-thirdsof tongue, from floor of mouth andpalate Muscles of face and scalp,stapedius muscle, posterior belly ofdigastric and stylohyoid muscles Submandibular and sublingualsalivary glands,the lacrimal gland, andglands of nose and palate VIII VestibulocochlearCochlear Organ of Coi--hearing VestibularFrom utricle and saccule andsemicircular canals--positionand movement of headIXGlossopharyngeal General sensation and taste fromposterior one-third of tongue andpharynx; carotid sinus (baroreceptor);and carotid body (chemoreceptor) NumberName Function Stylopharyngeus muscle--assistsswallowingParasympathetic parotid salivary gland X Vagus Hea and great thoracic blood vessels;larynx, trachea, bronchi, and lungs;alimentary tract from pharynx tosplenic flexure ofcolon; liver, kidneys, and pancreas XI Spinal accessory Cranial rootSternocleidomastoid and trapeziusmuscles Cranial root Muscles of soft palate (excepttensor veli palatini), pharynx (exceptstylopharyngeal), and larynx (exceptcricothyroid) in branches of vagus XII Hypoglossal Muscles of tongue (exceptpalatoglossus) controlling its shape andmovement","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"46872392-e33f-464f-a194-93ea23830da9","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9f02262244e9c348709c726c7f1655a8','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"95567c10-0007-466a-8b8e-8f8891806716","subjectId":"anatomy","chapter":"آناتومی","prompt":"Purkinje fibers project to which of the following","options":["Caudate nucleus","Red nucleus","Dentate nucleus","Ventero lateral nucleus of thalamus"],"correctIndex":2,"explanation":"Dentate nucleus Information processed in the Purkinje cell layer of cerebellum sent to deep cerebellar nuclei (4 in total), which form the cerebellar output. Largest collection of fibers originates from the dentate nucleus, which then project to contralateral ventral nucleus of thalamus after decussating in superior cerebellar peduncle.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"95567c10-0007-466a-8b8e-8f8891806716","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('67341aa95849be89f2370a11bac3a32e','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"c48fcdd2-948f-41e7-a457-56f42646cc60","subjectId":"anatomy","chapter":"آناتومی","prompt":"Arterial supply to floor of mouth & suprahyoid muscle is","options":["Lingual artery","Maxillary artery","Inferior alveolar artery","Facial artery"],"correctIndex":0,"explanation":"Lingual artery is a branch of external carotid artery. The root of tongue is also supplied by tonsillar and ascending pharyngeal arteries. Venous drainage is mainly by the deep lingual vein.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c48fcdd2-948f-41e7-a457-56f42646cc60","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7f94e509d9e11177a9869080122cbd4b','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"7f0dce8f-c95a-4776-aef1-fe8c6d257fb0","subjectId":"anatomy","chapter":"آناتومی","prompt":"Palatine process begins to fuse at:","options":["6th week of fertilization","8th week of fertilization","10th week of fertilization","12th week of fertilization"],"correctIndex":1,"explanation":"7 weeks - palate consists of the primary palate, formed by the fusion of the medial nasal processes. Behind the primary palate down growth of the nasal septum produces two communications between the oral and nasal cavities the primitive nasal choanae. 8 weeks - Formation of the secondary palate begins with downward growth of the medial parts of the maxillary processes (palatine processes) to a location on either side of the tongue. As the mandible develops and the tongue drops down these palatine processes grow horizontally fusing with the nasal septum in the midline and with the primary palate along their anterior aspect. By 81/2 weeks - the palatal shelves appear above the tongue and in near contact with each other. At 8th & 9th week they come in contact and fusion begins Key Concept - Formation of the secondary palate begins at 8th week with downward growth of the medial parts of the maxillary processes (palatine processes) to a location on either side of the tongue.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"7f0dce8f-c95a-4776-aef1-fe8c6d257fb0","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d7027d04ef2e9242f3d466a555966ee0','reference-medmcqa-bachelor-medicine-anatomy-en-1','anatomy','آناتومی','medium','{"key":"efb7462f-4c82-471a-9050-04c342078b35","subjectId":"anatomy","chapter":"آناتومی","prompt":"Which of the following projects efferent fibers through the marked structure:-","options":["Hippocampus","Mammillary body","Caudate nucleus","Amygdala"],"correctIndex":0,"explanation":"Hippocampus The marked structure is the fornix which is the major output tract for the hippocampus, which is a functional pa of the papez circuit Papez circuit: pa of limbic system associated with memory & emotions.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"efb7462f-4c82-471a-9050-04c342078b35","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
