INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('5401a2e0ed4b336be9ad7eea13eef698','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"17360c6c-2c98-4fe2-aa85-487dcf4678df","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Concentration of tropicamide:","options":["0.01","0.02","0.03","0.04"],"correctIndex":0,"explanation":"Answer- A. 0.01Tropicamide is the shoest acting mydriatic, concentration used is 0.5-l% drops (0.005-0.010).Tropicamide:Concentration used: 0.5-l% drops (0.005-0.010)Duration of action: Though effective for upto 3 hours, maximum effect appear 30 minutes after the last drop and lasts for only 10-15 minutesUsed in Adults.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"17360c6c-2c98-4fe2-aa85-487dcf4678df","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('03ec55374e6413a0ed5edaa883b293af','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"360f90ec-189e-464a-a60d-ed9d9bda46ef","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"What is the usual weight of rabbit used in ophthalmological experiments?","options":["0.5-1 kg","1.5-2.5 kg","5-7 kg","10-12 kg"],"correctIndex":1,"explanation":"Ans: B. 1.5-2.5 kg(Ref: Animal Models in Eve Research/ p188).The usual weight of rabbit used in ophthalmological experiments is between 1.5-2.5 Kg. Laboratory Animals:Laboratory AnimalsAnimalWeightRat180-200 gmGuinea Pig400-600 gmMouse20-25 gmRabbit1.5-2.5 KgdegHamster80-90 gm","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"360f90ec-189e-464a-a60d-ed9d9bda46ef","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e158b0b2f426df0f20186744e2d98bf1','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"cc0d09f8-564d-4fe5-8b22-4b7d3e4ed586","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Most common tumor of lacrimal gland:","options":["Trans-scaphoid perilunate fracture","Scaphoid fracture","Distal radius fracture","Hamate fracture"],"correctIndex":3,"explanation":"Ans. d. Hamate fractureMost common tumor of lacrimal gland is Non-Hodgkin''s lymphoma (37%)> Pleomorphic adenoma (25%). Most commonmalignant epithelial tumor of the lacrimal gland is adenoid cystic carcinoma.Lacrimal Gland TumorMC tumor of lacrimal glandNon-Hodgkin''s lymphomadegMC epithelial tumor of lacrimal glandPleomorphic adenomadegMC malignant epithelial tumor of lacrimal glandAdenoid cystic carcinomadeg","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"cc0d09f8-564d-4fe5-8b22-4b7d3e4ed586","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5e68129915a004e4ee95e36fd30112b6','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"aadafd4c-cb37-460b-8e6f-28f42d01dd60","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Topical administration of I% Pilocarpine failed to produce pupillary constriction in a patient who had a large, dilated pupil What should be the most probable reason?","options":["Adie''s tonic pupil","Diabetic III nerve palsy","Pharmacological blockade","Uncal herniation"],"correctIndex":2,"explanation":"Ans. c. Pharmacological blockade (Ref-YANNOFF 3/E PG,1052-1055)Pilocarpine I% is a sufficient miotic dose for any eye, but a sphincter with all its cholinergic receptor blockade by atropine or tropicamide (i.e. eye with pharmacological blockade) does not constrict with pilocarpine 1%.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"aadafd4c-cb37-460b-8e6f-28f42d01dd60","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('dcd5452886aa399ca32ba53202332a9e','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"845fbff7-6332-49ce-8ecb-d62616e2ae9a","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Keyhole-shaped visual field defect is seen in lesion involving which of the following regions?","options":["Optic disk","Optic chiasma","Lateral geniculate body","Occipital lobe"],"correctIndex":2,"explanation":"Ans: C. Lateral geniculate body(Ref Walsh and Hoyt; Clinical Neuro-Ophthalmology 6/e p122)Key-hole shaped visual field defects are typically seen in the lesions involving lateral geniculate body but keyhole shaped defect (not visual field defect) is seen in the coloboma of Iris.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"845fbff7-6332-49ce-8ecb-d62616e2ae9a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('db271bacf79978819b3dec5e5ad0034e','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"673a0bbe-b4d8-46bb-83b0-e01658f9f22f","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Cherry red spot and Hollenhorst plaque are seen in:","options":["CRAO","CRVO","Branch RAO","Branch RVO"],"correctIndex":0,"explanation":"Ans: A. CRAO(licr Parson''s 22/e p320-32l, 21 /e p313,314: Kanski 7/e p559-562: Yanoff and Duker 4/e p522)Cherry red spot & Hollenhorst plaque:Seen in both Central Retinal Aery Occlusion (CRAO) & BRAG.CRAO incidence is more common than BRAG.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"673a0bbe-b4d8-46bb-83b0-e01658f9f22f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('cc19c0a33040bfa88865afa17f981727','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"b0060b73-4e6b-4537-a556-c1fb94a65c4a","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"A 25-year-old lady presents with sudden severe bilateral loss of vision, more so on the right side, with no perception of light. Rest of the examination including pupillary reflexes, fundus and optokinetic nystagmus are normal. She was able to touch the tips of her fingers with her right eye closed but not with her left eye closed. The most like1 tgnosis is:","options":["Optic neuritis","Anterior ischemic optic neuropathy","CMV retinitis","Functional vision loss"],"correctIndex":3,"explanation":"Ans. d. Functional vision loss (Ref Kanski 6/e p 477, 790, 792-793)The most likely diagnosis in this young lady who presents with sudden severe bilateral loss of vision, more so on the right side, with no perception of light and normal examination findings including pupillary reflexes, fundus and optokinetic nystagmus, who is able to touch tips of her finger with right eye closed but not with left eye closed, is functional vision loss.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b0060b73-4e6b-4537-a556-c1fb94a65c4a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('417e68f9848b8c3a131b3ca26f80d6b6','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"3f6665ca-6b69-4345-88c2-72c2befd4d18","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Which of the following muscle is not supplied by the nerve marked in the diagram?","options":["Superior oblique","Medial rectus","Inferior rectus","Inferior oblique"],"correctIndex":0,"explanation":"The nerve marked in the diagram is oculomotor nerve. It supplies superior rectus, inferior rectus, medial rectus and inferior oblique. Superior oblique is supplied by Trochlear nerve.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"3f6665ca-6b69-4345-88c2-72c2befd4d18","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('56b03ed3a88f03777ca5c8da35b62cef','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"71803632-1b88-4332-88f5-be3ac2515b85","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Gene commonly indicated in congenital cataract:","options":["PAX-6","CRYGS-3","LMX- IB","PITX-3"],"correctIndex":1,"explanation":"Answer- B. CRYGS-3''Gene-S crystalline gene (CRYGS) mutalion causes dominant progressive coical cataract in humans.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"71803632-1b88-4332-88f5-be3ac2515b85","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('db3de56c7d6f2c3bd8e0ddfc9748bd3c','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"18c1a5f9-d998-414e-bb9c-991191c10710","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"A patient with a history of diabetes for one year with no other complications should have an ophthalmic examination?","options":["As early as feasible","After 5 years","After 10 years","Only after visual symptoms level"],"correctIndex":0,"explanation":"Answer- A i.e. As early as feasibleAll diabetic (IDDM & NIDDM both) aged over 12 years and/or entering pubey should be screened (visual activity measurement and fundus examination by ophthalmoscopy)For retinopathy. and those with risk for visual loss referred to an ophthalmologist.Type I DM (IDDM) require ophthalmoscopic examination within 3 years of diagnosis and annual review. (If lt is diagnosed before the age of pubey).Type II DM (NIDDM) require ophthalmoscopic examination at the time of diagnosis (because it is usually diagnosed after the age of 12 years) and annual review.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"18c1a5f9-d998-414e-bb9c-991191c10710","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b880be856324a93b79beb173e4f08db9','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"4a131164-eb3c-4152-9556-b81ae98e2066","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Which of the following is not an indication for evisceration?","options":["Malignancy","Panophthalmitis","Severe globe trauma","Expulsive hemorrhage"],"correctIndex":0,"explanation":"Ans: A. Malignancy(Ref Yanoff and Duker 4/e p1339)Evisceration of eye is not done in malignancy.Evisceration:Surgical technique removing entire intraocular eye contents.Simpler procedure than enucleation surgery.Advantages:Leaves scleral shell & extraocular muscle attachments intact.Offers better orbital anatomy preservation & natural motility of ophthalmic socket tissues.Contraindications:Documented or suspected intraocular malignant tumors.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4a131164-eb3c-4152-9556-b81ae98e2066","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('885c968f6d7b90a7ba449e2dfd93ae23','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"796d7b5d-f79d-4c6a-860c-198e9404ea07","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"High molecular weight proteins in cataractous lens seen only in humans:","options":["HM 1 and 2","HM 2 and 3","HM 2 and 4","HM 3 and 4"],"correctIndex":3,"explanation":"Ans: D. HM 3 and 4(Ref The Eve 3/e p305-307: Biochemistry of Eve by David R/p28)High molecular weight proteins in cataractous lens only in humans = HM 3 & 4.HM3 & HM4:Insoluble high molecular weight proteins.Found in cataractous lens.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"796d7b5d-f79d-4c6a-860c-198e9404ea07","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3193d5de65bd3b725e9764205730686a','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"d12e4d46-e1d9-4320-860c-184a735d9027","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Interruption of the optic chiasm will lead to:","options":["Bitemporal hemianopia","Binasal hemianopia","Homonymous hemianopia","Normal vision"],"correctIndex":0,"explanation":"Answer- A. Bitemporal hemianopiaInterruption of the optic chiasma will lead to bitemporal homonymous hemianopia because optic chiasma contains crossed over meclial fibers from both optic nerves, which are responsible for temporal Jield of vision.\"Hemianopia denotes loss of half of the field of vision. The commonest clinical form is homonymous hemianopia, in which the right or left half of the binocular field of vision is lost, owing to loss of the temporal half of one field and lhe nasal half of the other. This condition is due to a lesion situated in any pa of the visual paths from the chiasma to the occipital lobe.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d12e4d46-e1d9-4320-860c-184a735d9027","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9dd7672ce20c7afc5ee68539a12370ea','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"eaa184bf-53c5-4755-bee8-a9153e587ff0","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Ex-Press glaucoma implant is made up of?","options":["Silicone","Titanium","Gold","Stainless steel"],"correctIndex":3,"explanation":"Ans. d. Stainless steelIt is made of made of surgical-grade stainless steel, nonvalved filtration device designed to shunt aqueous humor from the anterior chamber to a subconjunctival filtration bleb.The EX-PRESS Glaucoma Filtration Device is intended to reduce IOP in glaucoma patients when medication and conventional surgical treatments have failed.The device channels aqueous humor through a secure lumen (of either 50 mm or 200 mm) to a half-thickness scleral flap, creating a subconjunctival filtration bleb.It is a minimally invasive glaucoma surgery (MIGS) to increase aqueous drainage.It has lower complications of ocular hypotony.The commonly used devices are as follows: Shunts using episcleral explants:* Ahmed glaucoma valve: Silicone* Molteno implant: Polypropelene plate and silicone plate* Baerveldt implant: Silicone Mini-shunts:* Ex-Press(tm) Mini-Shunt: Stainless steel * iStent(r): Titanium","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"eaa184bf-53c5-4755-bee8-a9153e587ff0","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('77ee3f6cb4241c4c9c088d198fc8db51','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"eaa33fd8-64a3-47a0-b13c-2b49a1f0e37f","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Phenol red thread test is used for dry eye:","options":["In the test, volume of tears is measured as it changes color on contact with tears","If the color changes to blue, it depicts surface mucin deficiency","Requires pH meter for reading the result","Requires topical anesthetic agent"],"correctIndex":0,"explanation":"Ans: A. In the test, volume of tears is measured as it changes color on contact with tears(Ref: Yanoff & Duker 4/e p277)Phenol red dye test measures the production of tears without topical anesthesia, as the dye changes its color to red on contact with tears.It doesn''t require pH ureter for reading the result.Phenol red is a pH indicator used in cell biopsy as it changes colour from yellow to red on pH range from 6.8 to 8.2.Used to measure residual tears in inferior conjunctival sac, especially in dry eye patients.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"eaa33fd8-64a3-47a0-b13c-2b49a1f0e37f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('bc31d57dae7564f6a7cecebbaaa19d01','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"bee78f93-a09e-491f-856e-846b81e4aa5c","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"The ETDRS cha is used for visual evaluation in diabetic patients. What does ETDRS stand for","options":["Extended treatment for diabetic retinopathy study","Early treatment for diabetic retinopathy study","Emergency treatment for diabetic retinopathy study","Emerging treatment for diabetic retinopathy study"],"correctIndex":1,"explanation":"Answer: B. Early treatment for diabetic retinopathy studyETDRS stands for Early treatment for diabetic retinopathy study","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"bee78f93-a09e-491f-856e-846b81e4aa5c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('a7a0f1497513e3a8611293c5278d3204','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"09657fa4-eeb3-4860-8b8c-f2e25c7eabab","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Enlargement of the blind spot occurs in which of the following","options":["Primary open angle glaucoma","Diabetic macular edema","Optic nerve hypoplasia","Papilledema"],"correctIndex":3,"explanation":"Primary open angle glaucoma - baring of the blind spot Diabetic macular edema - doesn''t lead to any visual field defect Optic nerve hypoplasia - it is not developed enough to develop a proper visual field defect Papilledema (it is raised intracranial pressure causing disc edema ) - leads to enlargement of blind spot","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"09657fa4-eeb3-4860-8b8c-f2e25c7eabab","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('0ac9b9a47f3e58cf518d2d9bac10017a','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"2aacf8d1-b36e-49be-8333-af91aa2a49c9","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Cells affected in glaucomatous optic neuropathy are:","options":["Amacrine cells","Bipolar cells","Ganglion cells","Rods and cones"],"correctIndex":2,"explanation":"Answer- C. Ganglion cellsGlaucoma, the second leading cause ofblindness, is characterized by changes in the optic disc and visual field defects.The elevated intraocular pressure was considered the prime factor responsible for the glaucomatous optic neuropathy involving death of retinal ganglion cellsaand their axons.Glaucoma, a leading cause of irreversible visual loss, is characterized by loss of retinal ganglion cells (RGC) and their axons over a period of many years.Mainly the ganglions cellsa are affected in glaucoma patients, which may lead to glaucomatus optic atrophy.Glaucomatous optic neuropathy is characterized by changes in the optic disc and visual field defects.The morphologic changes in the optic disc are in the form of thinning of neuro retinal rim, pallor and progressive cupping of the optic disc.The hemorrhage-associated retinal nerve fiber layer defects precede measurable changes ofthe optic disc configuration.The visual field defects in glaucoma are often detected only after 40% of the axons are loss.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"2aacf8d1-b36e-49be-8333-af91aa2a49c9","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('09d7cc95a8272f3355737873e5cff540','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"51203235-22e6-43fb-a51f-a2fcceb5f042","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Which of the following is the most common funga. infection of the eye seen in an HIV positive patient?","options":["Aspergillus","Candida","Toxoplasma","Rhinosporidium"],"correctIndex":1,"explanation":"Ans: B. Candida(Ref.: Ryan''s Retina 5/e p733)Candidemia:Most common fungal infection seen in patients with HIVCandida albicans - Impoant nosocomial pathogen - Most common Candida species.Most commonly cause of keratitis, conjunctivitis and endogenous fungal endophthalmitis.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"51203235-22e6-43fb-a51f-a2fcceb5f042","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('cd2d69fbda95da528be732c0d12867c0','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"3920361c-7b00-4cb2-ad43-d4bd71127f00","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"ETDRS grading of vision is done for","options":["Endothelial count","Corneal topography","Primary open angle glaucoma","Classification of diabetic retinopathy"],"correctIndex":3,"explanation":"ETDRS - Early treatment diabetic retinopathy study It is the best cha to measure the vision It is used to early treatment diabetic retinopathy","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"3920361c-7b00-4cb2-ad43-d4bd71127f00","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5c38b0a49eb7ac15cf1d1c5c1d249d24','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"abed431b-5d40-4df7-9f7b-4088185b5728","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"%lost radio-resistant cells in retina","options":["Retinal pigment epithelium","Ganglion cell layer","Rods and cones","Bipolar cells"],"correctIndex":1,"explanation":"Ans. b. Ganglion cell layer (Ref Radiation Retinopatliv. ,(1991) 5. 239-251)Ganglion cells are an example of highly specialized cells that have undergone extensive maturation, are the most radioresistant cells in the retina.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"abed431b-5d40-4df7-9f7b-4088185b5728","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('aacc0e37de53cbb4d79f03c46730d0b5','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"e33fee37-ca36-4d99-887d-2349c1beb5c1","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"As compared to blood, vitreous humor has high concentration of:","options":["Sodium","Potassium","Glucose","Ascorbate"],"correctIndex":3,"explanation":"Ans: D. Ascorbate(Ref Yanoff and Duker 4/e p353)As compared to blood, vitreous humor has high concentration of ascorbate.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e33fee37-ca36-4d99-887d-2349c1beb5c1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('030f9ad9511c6c950d2a9985ab09f5cf','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"8cce7868-0429-4f98-9e6a-4baa045dffcc","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"A 15-year-oldboy presented with headache and blurring of vision. On examination there was diptopia on looking towards left in the right eye.What is your diagnosis?","options":["Tb meningitis","Internuclear ophthalmoplegia","Cranial neuritis","Demyelination"],"correctIndex":1,"explanation":"Ans: B. Internuclear ophthalmoplegiaDemyelinationRef Bilateral Internuclear ophthalmoplegio in Multiple sclerosis,iejm journal,20l6Typically, symptoms & examination findings i.e. diplopia on looking towards left in the right eye is characteristic of internuclear ophthalmoplegia.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"8cce7868-0429-4f98-9e6a-4baa045dffcc","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f3e8eff61f9d44bb8830bd2608a6f3f6','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"c7f81422-57d3-4a31-ae96-83ca3f999334","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Microaneurysms are the earliest manifestation of diabetic retinopathy. Which of the following layer is involved in diabetic etinopathy?","options":["Outer plexiform layer","Inner nuclear layer","Layer of rods and cones","Retinal pigment epithelium"],"correctIndex":1,"explanation":"Ans. b. Inner nuclear layerMlcroaneurysms are the earliest clinical sign of diabetic retinopathy and occur secondary tocapillary wall outpouching due to pericyte loss.. Thev appear as small red dots'' MicroaneurysStructural changes in the retinal microcirculation have been associated with a physiologic breakdown in the bloodretinalbarrier. ihus, the retinal microcirculation in diabetics may be exceptionally leaky, giving rise to macularedema, a common cause of visual loss in these patients.The vascular changes may also produce exudates that accumulate in the outer plexiform layerq","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c7f81422-57d3-4a31-ae96-83ca3f999334","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('4844dc18bed546553a7acf6dbae5e236','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"362c70ed-9bc0-4266-8462-4c8302d7ef52","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Which of the following stain is used for diagnosis of Granular dystrophy of cornea?","options":["Colloidal iron","Congo red","PAS","Masson trichrome"],"correctIndex":3,"explanation":"Ans: D. Masson trichrome(Ref: Kanski 7/e p212-224; Parson :s 22/e p212-214, 21/e p207-209; Yanoff and Duker 4/e p261).Masson trichrome stain - Used for granular corneal dystrophy diagnosis.Granular dystrophy:AD inheritance with gene locus on 5q31Onset: First decade with recurrent erosionsSigns (in chronological order):Small, white, sharply demarcated deposits resembling crumbs or snowflakes in central anterior stroma.Increasing number of lesions with deeper & outward spread but not reaching limbus.Gradual confluence causing visual acuity impairment.Histology:Shows amorphous hyaline deposits staining bright red with Masson trichrome.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"362c70ed-9bc0-4266-8462-4c8302d7ef52","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7e6b11a0f28bdfeaebdd9341f6d34e77','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"2d88e018-637e-47c4-bb63-dd7216c204ae","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"14 year old child with blindness, sensorineural hearing loss, progressive hematuria, hypeension with similar family history in father","options":["Alpo syndrome","Goldenhar syndrome","Goodpasture syndrome","Nager syndrome"],"correctIndex":0,"explanation":"Answer: A. Alpo syndrome* Alpo syndrome is a genetic condition characterized by kidney disease, hearing loss, and eye abnormalities.* People with Alpo syndrome experience progressive loss of kidney function.* Almost all affected individuals have blood in their urine (hematuria), which indicates abnormal functioning of the kidneys.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"2d88e018-637e-47c4-bb63-dd7216c204ae","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5c0ef802ec364b4b6c8ba0c72cd7116d','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"ca0d1703-5a38-474d-bb6b-d6f69f7a7db6","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Capillary microaneurysms is an earliest sign of:March 2013","options":["Vitreous hemorrhage","Non-proliferative diabetic retinopathy","Trauma","Hypeensive retinopathy"],"correctIndex":1,"explanation":"Ans. B i.e. Non-proliferative diabetic retinopathyDiabetic retinopathyFundus examination in DM:- NIDDM: As early as possible- IDDM: 5 years after diagnosis of DMIncidence of diabetic retinopathy increases with disease duration","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ca0d1703-5a38-474d-bb6b-d6f69f7a7db6","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ea10b17d2da8120bec16453d756d55e2','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"3aff7082-0082-4114-a47b-d68bf127c263","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Cells most commonly affected in glaucomatous optic atrophy?","options":["Amacrine cells","Bipolar cells","Ganglion cells","Rods and cones"],"correctIndex":2,"explanation":"Answer-C. Ganglion cellsGlaucoma, the second leading cause of blindness, is characterized by changes in the optic disc and visual field defects''.The elevated intraocular pressure was considered the prime factor responsible for the glaucomatous optic neuropathy involving death of retinal ganglion cells and their axons.Glaucoma, a leading cause of irreversible visual loss, is characterized by loss of retinal ganglion cells (RGC) and their axons over a period of many years.Mainly the ganglions cells are affected in glaucoma patients, which may lead to glaucomatus optic atrophy''","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"3aff7082-0082-4114-a47b-d68bf127c263","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('fdd71e13357a3fd0046d7f8333fe3e70','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"794c0e78-516c-44ae-8eba-768371a3ca6c","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"What is the angle subtended by the largest letter in the Snellen cha on a person''s eye who is reading it from a distance of 6 meters?","options":["1 minute","10 minutes","50 minutes","60 minutes"],"correctIndex":2,"explanation":"Ans: C. 50 minutes(Ref: Yanoff & Duker 4/e p42; Parson 22/e p98, 21/e p98-100)The angular spacing between the bars of the C or E in Snellen''s cha is 1 minute for the 6/6 letter (smallest letter).The largest letter on the Snellen''s cha is the 6/60 letter.When viewed from a distance of 6 meter, this letter subtends an angle of 50 minutes in the eye and the bars of the letter subtend an angle of 10 minutes.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"794c0e78-516c-44ae-8eba-768371a3ca6c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('84843a7a9be5b6380056bc35e0d31c14','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"475b9dc7-c23d-4e3f-a3c7-5dc5893a34b1","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Cherry red spot after trauma is seen in children due to:","options":["CRAO","CRVO","Berlin''s edema","Niemann-Pick''s disease"],"correctIndex":2,"explanation":"Ans: C. Berlin''s edema(Ref Kanski 7/e p882: Parson''s 22/e p392, 21/e p382, 20/e p367; Yanoff and Duker 4/e p671)Cherry red spot after trauma in children due to Berlin''s edema.Commotio retinae (Berlin''s Edema):Common occurrence following a eye blow.Manifests as milky white cloudiness involving posterior pole with a ''cherry-red spot'' in foveal region.Appear after some days or may be followed by pigmentary changes.Most frequently affect temporal fundus.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"475b9dc7-c23d-4e3f-a3c7-5dc5893a34b1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('68a8f9db6feb1e470682bd2fc76d4dc2','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"f80230e3-6a41-4a2d-81a0-86cacead9dcf","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"A 33 years old male came with pain and watering in the right eye for 36 hours. On examination, a 3 x 2 cm corneal ulcer is seen with elevated margins, feathery hyphae, finger like projections and minimal hypopyon in cornea. What is the likely causative organism?","options":["Aspergillosis","Pseudomonas","Acanthamoeba","HSV-1"],"correctIndex":0,"explanation":"Ans: A. AspergillosisRef: Yanoff & Duker 4/e p225; Parson 22/e p203, 21/e p199)Finding suggestive of fungal corneal ulcer. In the question, Aspergillus is the only fungus.Mycotic or fungal keratitis:Commonly due to Aspergillus, Fusarium or Candida albicans.Fungal ulcers are typically seen after injury with vegetable matter such as a thorn or wooden stick and are characterized by a relatively indolent course.Symptoms are much milder than the clinical signs would suggest.Dry slough with feathery borders, surrounded by a yellow line of demarcation, which gradually deepens into a gutter.An immune ring (Wessely) may be visible due to deposition of immune complexes and inflammatory cells around the ulcer.Marked ciliary and conjunctival congestion.Hypopyon is thick and immobile - Due to direct invasion into the anterior chamber of fungal hyphae enmeshed in thick exudates.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f80230e3-6a41-4a2d-81a0-86cacead9dcf","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b49f92b651f1adab6583a206faec0257','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"8f57f95a-a12e-49e9-87b8-eb58ffa6cb9c","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"The spectacles are used in:","options":["Progressive glasses for presbyopia","Bifocal glasses for presbyopia","Bifocals for pediatric pseudophakia","Bifocals for adult aphakia"],"correctIndex":2,"explanation":"The image shows bifocal glasses of executive type which is especially used in case of paediatric pseudophakia and not in adult aphakia or presbyopia. Other types of bifocals are K or D bifocals which are used for adults with presbyopia Progressive glasses avoid the sudden jump in power in the lenses and provide a smooth transition from the power for distance vision to the power for the near vision thereby providing good distance, intermediate and near vision","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"8f57f95a-a12e-49e9-87b8-eb58ffa6cb9c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('aec5620758645b46c63303a1ecd12e35','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"d4c4bf0d-08ef-47e6-b8e2-e530082fa63a","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Which of the following drug should not be given in a patient of narrow angle glaucoma?","options":["Phenylephrine","Timolol","Acetazolamide","Homatropine"],"correctIndex":3,"explanation":"Answer- D. HomatropineHomatropine is a mydriatic, which can precipitate angle closure glaucoma and contraindicated in angle closure glaucoma.Phenylephrine, Timolol and Acetazolamide are used for the treatment of angle closure glaucoma.''Mydriatic drugs such as atropine, Homatropine, cyclopentolate, tropicamide and phenylephrine are precipitating factorsfor angle closure glaucoma, so contraindicated in angle closure glaucoma.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d4c4bf0d-08ef-47e6-b8e2-e530082fa63a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('8d20fbfe7fdae0f18bf7d496ec6fa9b3','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"d58a8e4e-0f5e-42bb-8b24-75a882eacfa2","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"IOL placed in the young male., After 10 year what should be done..?","options":["IOL should be removed in case of Posterior Capsule ossification","Never be removed","Remove when presbyopia sets in","Should be changed after 10 year"],"correctIndex":0,"explanation":"Answer A. IOL should be removed in case of Posterior Capsule ossification 1. The indications for removing an intraocular lens (IOL) are:Chronic uveitisEndothelial corneal dystrophyUncontrollalbe glaucomaMetal loop cutting pupillary sphincterGross decentration of IOL (fibrous bands)Extraocular dislocation of IOL G. Recurrent severe hyphemaDevelopment of rubeosis iridisRemoval of iris (1) Iris tumor (2) Epithelial downgrowthEndophthalmitisUnilateral IOL in pending bilateral aphakia 2. The following may be indications for removing and/or replacing and/or replacing an IOL:Wrong dioptric powerForeign body attached to IOLIOL covered with pigmentRepair retinal detachment after extracapsular cataract extractionChoyce lens too shoDannheim IOL with absorbed supramid loop tipsDislocated Ridley IOLSclero-conjunctival erosion of Strampelli''s \"external-fixation\" IOL loop Reference - <a href=\"","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d58a8e4e-0f5e-42bb-8b24-75a882eacfa2","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('beaa22c388594ae65c416a9aa8a76001','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"c1ac14de-a0f0-47fa-8451-273abce0150a","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"The most common mode of spread of retinoblastoma:","options":["Optic nerve invasion","Lymphatics","Vascular","Direct invasion"],"correctIndex":0,"explanation":"Ans: A. Optic nerve invasion(Ref Kanski 7/e p510-517; Yanoff and Duker 4/e p793)Most common mode of retinoblastoma spread-By optic nerve invasion.Direct extension by continuity to optic nerve & brain seen.Retinoblastoma:Primary malignant intraocular neoplasm.Arising from immature retinoblasts within developing retina.Most common primary intraocular malignancy of childhood in all-racial groups.Strong tendencies invading brain optic nerve & metastasize widely.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c1ac14de-a0f0-47fa-8451-273abce0150a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('8118244f866f90f1cd2a9dcb3e4079b3','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"b01ee962-68d0-4291-aee2-b978c108f65f","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"In which of the following, long spaced collagen present?","options":["Diaphragm","Cornea","Basement membrane","Tympanic membrane"],"correctIndex":1,"explanation":"Answer- B. Cornea''Long-spacing collagen is a common component of normal human corneal stroma and its occurrence seems to correlatewith the age-related changes of the tissue.Corneal transparency is mainly dependent on the arrangement of these collagen fibers in stroma.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b01ee962-68d0-4291-aee2-b978c108f65f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('438624c4139509578c611bf3ff65fe0b','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"ed92d804-ac83-440a-b908-df404df935ad","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Changes seen in conjunctiva after vitamti. A deficiency:","options":["Actinic degeneration","Hyperplasia of goblet cells","Hyperkeratosis of squamous epithelium","Stromal infiltration"],"correctIndex":2,"explanation":"Answer- C. Hyperkeratosis of squamous epitheliumChange seen in coniunctiva after vitamin A deficiency is hyperkeratosis of squamous epithelium.''Vitamin A is necessary for normal differentiation of nonsquamous epithelium; keratinization is a direct consequenceof its deficieny.Reduced aqueous tear production, and irregularities of the keratinized surface may all contribute to stromal melting, which can occur in the absence of inflammatory infiltration or bacterial invasion.Squamous metaplasia and keratinization.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ed92d804-ac83-440a-b908-df404df935ad","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('134effee73def077bbe4727724222909','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"1e8c037d-b7d9-48c9-8aba-39b01a178619","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Optic atrophy is not seen in:","options":["Retinitis pigmentosa","Methanol poisoning","Central retinal aerial occlusion (CRAO)","Polypoidal choroidal vasculopathy"],"correctIndex":3,"explanation":"Answer- D. Polypoidal choroidal vasculopathyRetinitis pigmentosa, Methanol poisoning and Central retinal aerial occlusion (CRAO) can lead to optic atrophy.Occurs secondary to retinal disease (disease of inner retina or its blood supply)Its ascending type of optic atrophy.Causes:Retinitis pigmentosaCRAOExtensive retino choroiditis","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"1e8c037d-b7d9-48c9-8aba-39b01a178619","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('4b0f16acf99eaa71240d8631bda6ff76','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"b9cbbe45-fa4a-4a54-b4f3-143039171071","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Universal marker of limbal epithelial stem cells:","options":["Elastin","Keratin","Collagen","ABCG2"],"correctIndex":3,"explanation":"Ans: D. ABCG2(Ref Indian J Med Res. 2008 Aug:128(2):149-56. PM1D:19001678; http://wwwstembook.org/node/588).ABCG2:Universal marker of limbal epithelial stem cells.Limbal Stem Cell Marker.Keratin (K3-K13) = Corneal Stem Cell Marker","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b9cbbe45-fa4a-4a54-b4f3-143039171071","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e23798680cc3997dafd6c48f2684370a','reference-medmcqa-preinternship-ophthalmology-en-1','ophthalmology','چشم‌پزشکی','medium','{"key":"391dbda5-df38-4a5f-8e4c-f6db24bc164a","subjectId":"ophthalmology","chapter":"چشم‌پزشکی","prompt":"Maximum contribution to the refractive power of the eye is by which pa of the eye?","options":["Anterior surface of cornea","Posterior surface of cornea","Anterior surface of lens","Posterior surface of lens"],"correctIndex":0,"explanation":"Ans: A. Anterior surface of cornea Maximum contribution to refractive power of eye - By anterior surface of cornea.Cornea''s anterior surface is approximately spherical with a radius of curvature that is typically 8 mm.This surface is responsible for about two-thirds of the eye''s refractive power.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"391dbda5-df38-4a5f-8e4c-f6db24bc164a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-medmcqa-preinternship-orthopedics-en-1','ارتوپدی · منتخب MedMCQA','preinternship','reference','medmcqa',NULL,'منبع باز',1793577600000,0,'MedMCQA — Pal, Umapathi & Sankarasubbu, 2022. Validation split via Open Life Science AI; Apache-2.0. متن اصلی انگلیسی؛ آزمون رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('14a0cc016d8afd86c60c6ba9b5d0ac39','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"ccca9015-2ce5-40cf-bed4-187f9428d984","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"A 55 yr old patient presented to the opd with complaint of pain in back. On examination his limbs seemed to be bent with overlying warm and thick skin. Patient also complain of decreased hearing over a few days. On biochemical analysis his serum ALP was raised. X-ray obtained showed the following features. Most probable diagnosis?","options":["Osteoporosis","Osteopetrosis","Pagets disease","Renal osteodystrophy"],"correctIndex":2,"explanation":"Given scenario suggests diagnosis of Paget''s disease. Image shows- a) Ivory veebra, b) Picture frame veebra Osteoporosis- Cod fish veebra Osteopetrosis- bone within a bone appearance Renal osteodystrophy- Rugger jersey spine","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ccca9015-2ce5-40cf-bed4-187f9428d984","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('848bb0426eedc0fac3c693a073b07c7f','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"c6f6754f-21ac-49d0-b8cd-8bf25049d813","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"Elderly female present with pain and swelling in the thigh. Xray shows multiple lytic lesions in distal femur with no periosteal reaction. Aspirate from the swelling shows homogenous serosanguinous fluid with RBCs. Which investigation can confirm the diagnosis?","options":["S. Calcium levels","S. PTH levels","MRI","CD1a IHC"],"correctIndex":1,"explanation":"History is suggestive of blood filled bone tumor seen in Hyperparathyroidism. HYPERPARATHYROIDISM May be primary (due to adenoma or hyperplasia), secondary (due to persistent hypocalcemia) or tertiary (when secondary hyperplasia leads to autonomous overactivity). Fig. X-ray hand--hyperparathyroidism Fig. Brown tumor Figs. A and B: (A) Lamina dura and (B) Resorption of lamina dura Salt pepper skull Parathyroid adenoma Most common cause of primary hyperparathyroidism. Presents with subperiosteal resorption, and replacement of endosteal cavitation marrow by vascular granulation and fibrous tissue (osteitis fibrosa cystica). Classical and pathognomic feature of hyperparathyroidism is subperiosteal coical resorption of middle phalanges on radial aspect Clinical features- Abdominal groans (dyspepsia), psychic moans, renal stones and weak bones (Groans, moans, stones and Bones). Ix- Parathyroid hormone and S. alkaline phosphate are raised. Calcium is high, serum phosphate is low.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c6f6754f-21ac-49d0-b8cd-8bf25049d813","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('fd8f447dad0cc2718185b62a747b730c','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"f822dfed-f142-4583-b7c2-779cf63ccad6","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"Fish tail deformity in a child is seen after injury to?","options":["Distal Tibia","Distal Femur","Distal humerus","Distal Radius"],"correctIndex":2,"explanation":"Fishtail deformity of the elbowis characterized by a contour abnormality of the distal humerus, which develops when the lateral trochlear ossification centers fails to develop or resorbs. It is an uncommon complication usually following a distal humeral fracture in childhood.Whilst initially presumed to be a benign condition, long-term follow-up suggests that patients withfishtail deformityare prone to: functional impairment ongoing pain development of early osteoahrosis","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f822dfed-f142-4583-b7c2-779cf63ccad6","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f806a75547d786f8ba855a87f9188c50','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"31cb149e-7c0f-489f-b2c6-10985226e2ff","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"Most specific for diagnosing Ankylosing spondyliti?","options":["HLA B27","B/l sactoilitis","Lumbar movement","ESR"],"correctIndex":1,"explanation":"According to Modified New York criteria, the diagnosis of definite AS requires the following: established sacroiliitis on radiographs (unilateral or bilateral) and at least one of the following clinical criteria: (1) low back pain and stiffness for more than 3 months improving with activity, (2) reduced chest expansion (3) limited lumbar movements. HLA B27 is present in > 90% cases of ankylosing spondylitis but it is not specific for AS.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"31cb149e-7c0f-489f-b2c6-10985226e2ff","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('6e867de51216db8a9ea84358523f6cdc','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"d75dc767-c74f-4b3d-a2bd-f5e6c082e497","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"A patient of supracondylar humerus fracture is unable to flex interphalangeal joint of the thumb. Which nerve is most likely injured?","options":["Median nerve","Superficial branch of ulnar nerve","AIN","Pin"],"correctIndex":2,"explanation":"Flexion of interphalangeal joint of thumb is carried out by flexor pollicis longus. It is supplied by AIN, a branch of median nerve. Muscles which are supplied by AIN are flexor digitorum profundus (Lateral 1/2 ), flexor pollicis longus and pronator quadratus. PIN a branch of radial nerve causes finger drop Supra condylar fracture of Humerus - Order of nerve involvement in children:AIN > Median Nerve > Radial Nerve > Ulnar Nerve","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d75dc767-c74f-4b3d-a2bd-f5e6c082e497","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('a6d937ab347637ec14684a34a5b87977','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"dac67e00-7708-4533-a6da-38c259fe8403","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"Which Bone does not form the wrist joint","options":["Radius","Triquetrum","Scaphoid","Ulna"],"correctIndex":3,"explanation":"* Bones forming the wrist joint are: radius, scaphoid, lunate, triquetrum and other carpal bones.* The wrist joint is a synol joint between the distal end of radius and the aicular disc overlying the distal end of ulna and the scaphoid, lunate and triquetrum.* Ulna is not pa of wrist joint, only the overlying aicular disc is pa of the wrist joint.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"dac67e00-7708-4533-a6da-38c259fe8403","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('97ba4b9bc96c18662225291ad2e277fa','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"5ccc26af-b2fb-4d7e-b117-e622359b75a2","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"Minimum age of screening of osteoporosis:","options":["55 years","60 years","65 years","50 years"],"correctIndex":2,"explanation":"Osteoporosis - screened using DEXA scan staing from the age group of 65 years It measures - bone mineral density and uses a T score to identify osteoporosis. T score: 0 to -1 - normal 1 to -2.5 - osteopenia < -2.5 - osteoporosis","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"5ccc26af-b2fb-4d7e-b117-e622359b75a2","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('191a60ba81093f946e685016c49281a4','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"b6b91d49-7a30-4a9a-91e6-b2f20341470c","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"Normal Curvature seen in Lumbar","options":["Lordosis","Kyphosis","Scoliosis","Recurvatum"],"correctIndex":0,"explanation":"* Normal curvature of spine:Lordosis(concavity) ? cervical spine, lumbar spineKyphosis (convexity) ? thoracic & sacral spine * Causes of | lumbar lordosis: (excessive posterior concavity)- Spondylolisthesis- Obesity / Osteoporosis- Achondroplasia- Postural* Scoliosis -abnormal lateral curvature of veebral column * Kyphosis - abnormal curvature of the veebral column in the thoracic region causing \"hunchback\" deformity.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b6b91d49-7a30-4a9a-91e6-b2f20341470c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('69f396320fe0b8b94a9d3dca7b0946a4','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"6ca26608-cafb-46c8-80a1-39bc0e70d5ff","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"10 year old present with ankle pain. X-ray has Lytic Lesion with sclerotic rim at calcaneum. Following HPE findings were seen. What is your diagnosis:","options":["Eumycosis","PVNS","Ochronosis","Hemophilic pseudotumar"],"correctIndex":3,"explanation":"X-ray shows multiple lytic lesion. Histopathology shows cells with brown-color deposits, hemosiderin. * Ochronosis: Usually presents with blackening of urine.* Pigmented villo-nodular synovitis (PVNS): is an aggressive disorder arising from synol joints predominantly in the knee. It shows area of synol proliferation with histology showing hemosiderin stained giant cells.* Eumycosis: Commonly found in foot. Presents with sinuses. It shows Dot in circle sign. X-rays shows multiple bone cavities and progressive bone destruction.* Hemophilic pseudotumor: Usually found in ankle joint. Histopathology shows hemosiderin deposit due to haemorrhage.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6ca26608-cafb-46c8-80a1-39bc0e70d5ff","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ee8cd84bf13b11ed107fd3d7accf2a81','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"baacab5b-7e28-4b0d-b78e-73253e5c7dde","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"A young marathon runner is paicipating in a marathon competition. After running for 100 m, he develops at the anteromedial aspect of tibia which was mild to sta with, but increased on fuher running. X ray was normal. The doctor ordered a bonescan. What is the likely diagnosis?","options":["Lisfranc fracture","Jones fracture","Shin splint","Nutcracker fracture"],"correctIndex":2,"explanation":"Shin splints (stress fracture) are seen in runners, army recruits or any vigorous physical activity. STRESS/FATIGUE FRACTUREStress fracture is due to imbalance between load and resistance of bone. It is of 2 types:1. Fatigue Fracture: caused by application of abnormal stress on normal bone.2. Insufficiency Fracture: caused by normal activity on weak bone. Sites of Stress FracturesLower Extremity* March fracture is a stress fatigue fracture of second metatarsal neck > 3rd metatarsal neck.* The most common site is metatarsal neck followed by tibia (proximal third in children, middle third in athlete and lower third in elderly).* Tibia stress fracture = Shin splints* Femoral neck (inferomedial compression side in young and superior tension side in older patients).* Rarely fibula lower end (runners fracture). Upper Extremity* Olecranon is most common site of upper limb stress fractures. Pelvis and SpinePars inter aicularis of 5th lumbar veebral (causing spondylolysis) is commonest in spine. Clinical Presentation* Load related pain often bilateral* The hallmark physical finding is tenderness with palpation and stress. InvestigationMRI provide excellent sensitivity and superior specificity compared to bone scan in differentiating from infections or tumors.Bone scan is preferable for bilateral cases due to feasibility, also bilateral cases go in our of stress fracture as compared to Infection or tumor and also can scan the whole body.* Treatment is symptomatic with cast and cessation of activity.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"baacab5b-7e28-4b0d-b78e-73253e5c7dde","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b43968086d5010b11b96fb016aaa22b9','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"cef58dc3-f340-4f76-909d-8f9fb4866e29","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"Positive pivot shift test in knee is because of injury to -","options":["Posterior cruciate ligament","Anterior cruciate ligament","Medial meniscus","Lateral meniscus"],"correctIndex":1,"explanation":"COLLATERAL LIGAMENT INJURY The most common mechanism of ligament disruption of knee is abduction (valgus), flexion and internal rotation of femur on tibia which usually occur in sports in which the foot is planted solidly on the ground and leg is twisted by rotating body. The medial structures medial (tibial) collateral ligament (MCL) and medial capsular ligament are first to fail, followed by ACL tear, if the force is of sufficient magnitude. The medial meniscus may be trapped between condyles and have a peripheral tear, thus producing unhappy triad of 0’ Donoghue. Main test for MCL (medial collateral ligament) is valgus (abduction) stress in 30° of knee flexion. (Because in full extension it is indicative of combined MCL, posterior oblique ligament injury and posterior cruciate ligament injury). Varus (Adduction) stress test in 30° flexion (removes the lateral stabilizing effect of iliotibial band so that the lateral collateral ligament can exclusively be examined). Apleys distraction test is used for collateral ligaments.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"cef58dc3-f340-4f76-909d-8f9fb4866e29","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('91b94f3307cad27830b5c4ff503c8c8e','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"3d3d18de-8e78-4d58-90f4-2c9257c76a5e","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"Which fracture results in the given deformity?","options":["Supracondylar fracture of humerus","Lateral condylar fracture","Olecranon fracture","Radial head fracture"],"correctIndex":0,"explanation":"The image shows cubitus varus. Supracondylar fracture of humerus causes cubitus varus and Gunstock deformity. Lateral condylar fracture causes cubitus valgus","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"3d3d18de-8e78-4d58-90f4-2c9257c76a5e","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('6ed651aa1f1631a49e735012d7ddb2a7','reference-medmcqa-preinternship-orthopedics-en-1','orthopedics','ارتوپدی','medium','{"key":"f3fac8a7-d3e8-4d02-b4eb-4ac18da8e7c0","subjectId":"orthopedics","chapter":"ارتوپدی","prompt":"What is the use of the given instrument:","options":["To hold bone and plate","To hold bone fragments with traction","To cut the bone","For creating a gap in wound"],"correctIndex":0,"explanation":"For creating a gap in wound Bone Cutter Bone Nibbler Double Action Bone Holding Forceps Bone Plate Holding Forceps Fergusson Bone Holding Forceps Lane Bone Holding Forceps Dynamic Compression Plate (DCP) Locking Compression Plate (LCP) Limited Contact Dynamic CompressionPlate (LCDCP) Screws Osteotome Bone Curette","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f3fac8a7-d3e8-4d02-b4eb-4ac18da8e7c0","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-medmcqa-preinternship-pathology-en-1','پاتولوژی · منتخب MedMCQA','preinternship','reference','medmcqa',NULL,'منبع باز',1793577600000,0,'MedMCQA — Pal, Umapathi & Sankarasubbu, 2022. Validation split via Open Life Science AI; Apache-2.0. متن اصلی انگلیسی؛ آزمون رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('0eb17f0260539a333ec6ef09982f8864','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"07d58883-b752-4898-ab70-a1df892ef7bd","subjectId":"pathology","chapter":"پاتولوژی","prompt":"If the Rb gene phosphorylation is defective, which of the following will happen?","options":["Cell cycle will stop at GI phase","Cell cycle will stop at G2 phase","The cell cycle will progress and the cell will divide","There will be no effect on cell cycle as for Rb gene phosphorylation is not needed"],"correctIndex":0,"explanation":"Answer- A. Cell cycle will stop at GI phaseRb is a tumor suppressor gene. It normally arrests cell division at G1-S phase. Phosphorylation of Rb gene allows the cell to divide, hence inhibition of phosphorylation (which is the constitutive scenario for Rb gene) arrests the cell in GI phase.RB (Retinoblastoma) geneLocated on chromosome on 13q14Tumor suppressive pocket protein that binds E2F transcription factors in hypophophorylated stateKey negative regulator of G1/S cell cycle transition . Tumors associated: Retinoblastoma, osteosarcoma, Glioblastoma, small cell carcinoma of lung, CA breast & CA bladderSequence: Go- G1- S- G2 - M","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"07d58883-b752-4898-ab70-a1df892ef7bd","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('48d72c0dbdd6536cf59bdbb6e6edda3d','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"94e49b87-631d-4d93-bdf8-e8e71ae04654","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Vwf factor is produced by:","options":["Platelets","Endothelial cells","Neutrophils","Monocytes"],"correctIndex":1,"explanation":"Ans: B. Endothelial cellsVon willebrand factor (vWF)* This is the larger component.* It is produced by endothelial cells (main source) and megakaryocytes.It has two major functions ?* Helps in platelets adhesion by interacting with platelet membrane glycoprotein ib-IX.* Stabilizes factor VIllc.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"94e49b87-631d-4d93-bdf8-e8e71ae04654","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('79ca76304206b044a7642e3738ec920a','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"b9546516-2a4a-4179-a956-60d0387bf11f","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Amyloid protein in Hemodialysis associated with amyloidosis is-","options":["AA","A b","b- 2 microglobulin","Transthyretin"],"correctIndex":2,"explanation":"Answer-C. b- 2 microglobulinHemodialysis-associated amyloidosis-Associated disease is Chronic renal failureMajor fibril protein is A","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b9546516-2a4a-4179-a956-60d0387bf11f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('cb75353557e664e5b24418ce3a2889ca','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"e8aa61af-a6f5-49ed-a221-93765caf901f","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Which of the following diseases is diagnosed with the help of the flowcytometry pattern?","options":["Bruton disease","Bare lymphocyte syndrome","Hyper IgM syndrome","Severe combined immunodeficiency disease"],"correctIndex":2,"explanation":"Flow cytometry can rapidly and quantitatively measure several individual cell characteristics, but is mainly used to identify cellular antigens expressed by liquidtumors , those that arise from blood forming tissues. Hyper IgM syndrome - In this disorder the affected patients make IgM antibodies but are deficient in their ability to produce IgG, IgA and IgE antibodies. There is problem in Ig class switching. Approximately 70%of individuals with hyper lgM syndrome have the X linked form of the disease , caused by mutations in the gene coding CD40L located on Xq26. In remaining patients,the disease is inherited in an autosomal recessive pattern. Most of these patients have loss of function mutation involving either CD40 or enzyme called AID. So, B-cells can be detected by flowcytometryhaving low expression of CD40. Bruton''s disease -In this disease, there is defect in B-cell tyrosine kinase enzyme. This leads to hypogammaglobulinemia. Bare lymphocyte syndrome- In this disorder, There is defect in MHC-2 molecule which is required for CD4 T-cell formation. SCID - This is both X-linked and autosomal recessive disorder.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e8aa61af-a6f5-49ed-a221-93765caf901f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('a20221f753f3cdbb90488f17a1a2ffa5','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"9a292f87-6a2d-4bba-bcee-f11ca9a94c73","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Oil red ''0'' stain is used for:","options":["Glutaraldehyde fixed specimen","Alcohol fixed specimen","Formalin fixed specimen","Frozen specimen"],"correctIndex":3,"explanation":"Ans: D. Frozen specimenFor Connective Tissue and LipidsName of stainElements stainedTrichrome StainCollagenVerhoeff-Van Gieson stain (Best for Elastin)Elastic fibersLuna stainElastin & Mast cellsSilver Methenamine stainReticulinOil red ''0'' stain (on Fresh specimen)Sudan black (on fixed specimen)FatMallory''s PTAH stainMuscle striationsMaius scarlet blue (MSB)FibrinPAS, Silver Methenamine stainBasement membraneBielschowsky (silver stain)Neurofibrillary tangles senile plaquesLuxol fast blueMyelin(Ref Netter :s* Essential Histology 2/e p479)","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"9a292f87-6a2d-4bba-bcee-f11ca9a94c73","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('da08c880c126b110837bdfdc5d47acc9','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"40a69530-6238-4f33-8003-86d143d6de77","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Iron entry into enterocytes occurs which of the following?","options":["DMT-1","Ferropoin","Transferrin","Hepcidin"],"correctIndex":0,"explanation":"GI Luminal non-heme iron is mostly in the Fe3+ (ferric) state and must first be reduced to Fe2+ ferrous) iron by ferrireductases, such as b cytochromes and STEAP3. Fe2+ iron is then transpoed across the apical membrane of enterocytes by divalent metal transpoer-1 (DMT1).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"40a69530-6238-4f33-8003-86d143d6de77","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('620ae5c569c90e2cc94948b30123b79a','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"dabfee93-2e1b-4e6c-bff6-03c025bd986f","subjectId":"pathology","chapter":"پاتولوژی","prompt":"A 28 year old man has lenticonus and end stage renal disease now. His maternal uncle also died of the same illness. What is the most likely diagnosis?","options":["Autosomal dominant polycystic kidney disease","Autosomal recessive polycystic kidney disease","Oxalosis","Alport syndrome"],"correctIndex":3,"explanation":"Presentation of male patient with lenticonus and end stage renal disease with a family history of renal disease is highly suggestive of Alport syndrome. AR polycystic kidney is ruled out because the age of presentation in ARPKD is childhood and most of the affected children do not survive beyond their childhood. AD polycystic kidney is ruled out because there is no association of ADPKD with lenticonus as is mentioned in our question. –– Alport syndrome is manifest by hematuria with progression to chronic renal failure, accompanied by nerve deafness and various eye disorders, including lens dislocation, posterior cataracts, and corneal dystrophy. –– In about 85% cases, it is inherited as an X-linked trait. So, males express the full syndrome, and females are carriers in whom manifestations of disease are typically limited to hematuria. –– Autosomal recessive and autosomal dominant forms also exist in which both the sexes are equally susceptible. –– In Alport syndrome, Hematuria is the earliest manifestation and the sensorineural deafness is the commonest extra renal abnormality.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"dabfee93-2e1b-4e6c-bff6-03c025bd986f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9037537c2d99d195174814cb4240a2c4','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"d2f3fa53-c024-4179-bf34-169fd7b99fc9","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Anti-centromere antibodies seen in which of the followings conditions:","options":["Drug induced lupus","SLE","Sjogren syndrome","Scleroderma"],"correctIndex":3,"explanation":"It is seen in scleroderma. Limited form of scleroderma known as CREST has anti centromere antibody positive and generalized form has anti topoisomerase positive antibody Anti histone antibodies are positive in drug induced lupus Anti SS-A (RO) antibodies and anti SS-B(LA) antibodies are positive in Sjogren''s Syndrome Most specific antibody in SLE is anti nuclear antibody and most specific antibody is anti ds-DNA and Anti smith antibody Presence of anti P antibody is associated with development if psychosis /CNS manifestation in SLE patients Presence of anti RO antibody is associated with development of cutaneous lupus and congenital hea block Presence of b2 glycoprotein is associated with development of Antiphospholipid antibody","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d2f3fa53-c024-4179-bf34-169fd7b99fc9","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5b5c54d83a717491c5b043e827a1b0ef','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"59ecbb71-66e3-4d3c-b963-b9ef607449e0","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Histopathologic study of lichen planus shows:","options":["Mixed cellular inflammatory infiltrate","Presence of T-Lymphocytes predominantly","Antiepithelial antibodies","Scattered infiltrate with ill-defined lower border"],"correctIndex":1,"explanation":"Histologic features of lichen planus include: Saw, tooth appearance of retepegs Liquefaction degeneration of basal layer which is replaced by thin band of eosinophilic coagulum Presence of civatte bodies Characteristic band Like subepithelial mononuclear infiltrate consisting of T- lymphocytes and histiocytes sharply limited to papillary and most superficial portion of the reticular layers of connective tissue Hyperparakeratosis or hyperorthokeratosis Thickening of granular layer","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"59ecbb71-66e3-4d3c-b963-b9ef607449e0","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('c0e19aa9cf9df457d671d1d90303400f','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"05863ba7-3f7b-48eb-a74b-7cd2598065b4","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Geniculate neuralgia is caused in the nerve","options":["VII","IX","X","II"],"correctIndex":0,"explanation":"Geniculate neuralgia (Nervus intermedius neuralgia) results from herpes zoster infection of geniculate ganglion and nervus intermedius branch of seventh cranial nerve.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"05863ba7-3f7b-48eb-a74b-7cd2598065b4","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e2d3e2e11f0e6e59f233942f39bc8af4','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"35e5b5ae-82da-4f68-a011-91818a64c684","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Von Willebrand factor is secreted by which of the following?","options":["Macrophages","Endothelial cells","Platelets","Fibroblast"],"correctIndex":1,"explanation":"Endothelial cells contain intracellular stores known as WeibelPallad bodies which contain Von-willebrand factor and P-selectin.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"35e5b5ae-82da-4f68-a011-91818a64c684","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1212f52e777414a25ad3647825f184ed','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"10b14133-7f8a-43dd-ab66-b0cfd0c784c2","subjectId":"pathology","chapter":"پاتولوژی","prompt":"In which stage of neurocysticercosis, there is no edema?","options":["Vesicular","Vesicular colloidal","Granular nodular","Nodular calcified"],"correctIndex":3,"explanation":"Ans. d. Nodular calcified (Ref Robbins 9/e1)395, SA, 1)392-393)Surrounding edema is seen in the colloidal vesicular and granular nodular stages.StageCyst wallScolexCommentVesicularNon-enhancingWall defined membraneOnly one ble scolexEccentric hyperdense hole-with-dot\" appearanceSuggestive of ble larvaColloidalRing Enhancing with perilesional edemaDegenerating scolexFluid becomes more turbidEarliest stage in the cyst involution - larval degenerationGranularFocal nodular enhancing necrotic lesions with perilesional edemaDegenerating scolexEosinophilic structure Bladder and scolex are in various stages of disintegationCalcifiedSmall hyperdense nodules without perilesional edema","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"10b14133-7f8a-43dd-ab66-b0cfd0c784c2","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d5ba4de9bc9c4e7dc6e198bbfe816e59','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"f3f3ad74-951f-4907-913d-f5c6c6c2dd2a","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Which of the following is not a pa of the quadruple test for antenatal detection of Down syndrome?","options":["AFP","Estriol","Beta HCG","Inhibin B"],"correctIndex":3,"explanation":"TRIPLE TEST b Hcg || a feto protein || Estriol || QUADRAPLE TEST BHcg || A feto protein || Estriol || Inhibin A ||","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f3f3ad74-951f-4907-913d-f5c6c6c2dd2a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('41b9ab658f99c76135f985aeb51c8451','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"da143133-e8d3-44d6-a66d-607ed0bcf458","subjectId":"pathology","chapter":"پاتولوژی","prompt":"A voluntary donor underwent apheresis for platelet donation for the first time after which he developed perioral tingling and numbness. This is seen because","options":["His platelet count was low for donation","He underwent apheresis for the first time","Due to fluid depletion","Due to citrate based anticoagulant"],"correctIndex":3,"explanation":"SDP-Single Donor Platelet are preffered. -In this process whole bloodis drawn from one arm into a sterile kit inside a cell separating machine. -The machine separates the bloodso that onlyplateletsand plasma are collected. -The other bloodcomponents (red cells and white cells) are returned to thedonor the same arm. -Because we want the blood to flow in the proper way, so we will do addition of anti-coagulant solution like citrate based anti-coagulant. -This anti-coagulant solution will not only prevent clot formation but will also cause decrease in the concentration of ionized Ca2+ - causing transient hypocalcemia which will lead to Perioral tingling and numbness. To prevent this condition from happening we prescribe oral calcium supplementation to the respective patient or we reduce the flow of device through which the blood is supposed to pass.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"da143133-e8d3-44d6-a66d-607ed0bcf458","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('0d78feb7c293727f6e48b996fb2a36a8','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"543b341f-7350-4a9b-9bc6-63a1a2cee1e8","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Which of the following is a tool used in gene editing?","options":["CRISPR","Gene Xpe","Big Data","HealthCare App"],"correctIndex":0,"explanation":"Answer- A. CRISPRA type of genetic engineering in which DNA is inseed, deleted or replaced in the genome of a living organism using engineered nucleases, or \"molecular scissors.Four Families of Engineered Nucleases being usedMeganucleasesTranscription Activator-Like Effector-based Nucleases (TALEN)Zinc finger nucleases (ZFNs)Clustered Regularly Interspaced Sho Palindromic Repeats (CRISPR)-Cas systemForm the basis of a genome editing technology known as CRISPR/Cas9 that allows permanent modification of genes within organisms.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"543b341f-7350-4a9b-9bc6-63a1a2cee1e8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e4ae0250b25de0993d65edb6b036e17a','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"29d2e3e3-3b3c-4b84-af19-e8e98c5e104e","subjectId":"pathology","chapter":"پاتولوژی","prompt":"The surgical registrar successfully performs a testicu!lar biopsy and hands over the specimen to the attend!ing nurse. The sister asks you how to send the speci!men to the pathologist. What fluid will you tell the sister to put the specimen in?","options":["95% ethanol","Zenker''s solution","Bouin''s solution","10% formalin"],"correctIndex":2,"explanation":"Ans: C. Bouin''s solution(Ref: Surgical Pathology by ''Rosai and Ackerman 9Ie p27; Upper Urinary tract Urothelial Carcinoma by Michael Grasso (2015)1p11)Testicular biopsy specimen should be put into Boitin''s solution.\"Bouin''s is a noncoagulate picrate solution which is routinely utilized to fix testicular biopsies because it preserves nuclear detail.\"","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"29d2e3e3-3b3c-4b84-af19-e8e98c5e104e","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2daf2dfa5a3eb318495981db878428b4','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"75875e90-359b-410d-a777-4cd41003fe93","subjectId":"pathology","chapter":"پاتولوژی","prompt":"APAF-1 is involved in the activation of which of the following casapses?","options":["Caspase 8","Caspase 9","Caspase 3","Caspase 10"],"correctIndex":1,"explanation":"Cytochrome c is released from mitochondria during apoptosis. Once released into the cytosol, cytochrome c binds to a protein called APAF-1 (apoptosis-activating factor-1), forming a multimeric structure called the apoptosome. This complex binds to caspase-9, the critical initiator caspase of the mitochondrial pathway, and promotes its autocatalytic cleavage, generating catalytically active forms of the enzyme.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"75875e90-359b-410d-a777-4cd41003fe93","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b7bb638434dddaf0a72757f5f49a4149','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"4873ac63-79fe-4fdb-a63b-1c4064b80d15","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Iron is taken up into enterocytes through which of the following?","options":["DMT-2","DMT-1","Ferroprotein 1","GLUT1"],"correctIndex":1,"explanation":"Ans: B. DMT-1Iron is brought into the cell through an active transpo processProtein DMT-1 (Divalent Metal Transpoer-1),Expressed on the apical surface of enterocytes in initial pa of duodenum.DMT-1 is not specific to iron & transpos other substances like zinc, copper, cobalt & manganese.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4873ac63-79fe-4fdb-a63b-1c4064b80d15","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f970ed6f81645f87270fb54b7992ecf6','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"bccac3f6-359f-4795-93a7-1b32d014bce0","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Which of the following cannot be diagnosed without positive ANA?","options":["Drug induced lupus","SLE","Sjogren syndrome","Scleroderma"],"correctIndex":1,"explanation":"Repeated negative testing for ANA indicates least chances of having SLE. ANA is positive in 98% of patients with SLE Limited form of scleroderma known as CREST has anti centromere antibody positive and generalized form has anti topoisomerase positive antibody Anti histone antibodies are positive in drug induced lupus Anti SS-A (RO) antibodies and anti SS-B(LA) antibodies are positive in Sjogren''s Syndrome","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"bccac3f6-359f-4795-93a7-1b32d014bce0","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('0bae9f460638b334729eedc61ce49ef0','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"11dce32c-3739-443e-a77c-224198dc55a1","subjectId":"pathology","chapter":"پاتولوژی","prompt":"What is seen in syndrome X?","options":["Prediabetics","Prehypertensive","X chromosome mutation","More chances of syncope during dental extractions"],"correctIndex":0,"explanation":"Syndrome X is a term used as a placeholder for a newly discovered group of symptoms. It may refer to: Cardiac syndrome X Metabolic syndrome Metabolic syndrome (Formerly known as syndrome x) can dramatically increase your risk of serious health problems, such as diabetes, heart attacks, and strokes yet often people don''t even know what it is. Metabolic syndrome is generally defined as a cluster of risk factors, including high blood sugar, extra abdominal fat, high blood pressure, and unhealthy cholesterol levels. Insulin resistance. Insulin is used to metabolize glucose. In people with insulin resistance, there is resistance against insulin action, due to which the body keeps making more and more of it to cope with the rising level of glucose. Eventually, this can lead to diabetes.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"11dce32c-3739-443e-a77c-224198dc55a1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3f38068e730f6becfb315f0ccb0e8fcb','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"4e6da460-99e2-4192-b3b6-b10f8827dce2","subjectId":"pathology","chapter":"پاتولوژی","prompt":"What among the following is the use of this?","options":["Prevent viral infections","Prevent transfusion related reactions","Prevent bacterial contamination","Prevent blood mismatch"],"correctIndex":1,"explanation":"The picture given above shows the WBC filter. | WBC''s entering the body of the recipient | are the chances of development of transfusion related reactions. Purpose of having this kind of filter is that: - lesser chances of entry of WBC inside the body of the host. - Prevent the entry of (Cell) aggregates inside the body of the recipient. The size of the WBC filters can range from 170- 200m. The size of the transfusion needle is 18-19 gauge.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4e6da460-99e2-4192-b3b6-b10f8827dce2","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('38ee793b4ad8c5032e0811d14463a0d7','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"e03a6d53-0c8b-4bf7-9710-c19083bcb018","subjectId":"pathology","chapter":"پاتولوژی","prompt":"A 60-year-old has got severe bulla and target lesion which erythema around halo and genital lesions:","options":["Stevens Jhonson syndrome","Herpes zoster","Herpes simplex","Herpangina"],"correctIndex":0,"explanation":"Stevens — Johnson syndrome is very severe bullous form of erythema multiformae and is characterized by oral, ocular and genital lesions.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e03a6d53-0c8b-4bf7-9710-c19083bcb018","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('cbbeda523293df7bce6c80ceeb31b1af','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"50aa2943-d234-4743-88e0-286d47774107","subjectId":"pathology","chapter":"پاتولوژی","prompt":"V) hich of the following can change the gene expression by methylation and acetylation without affecting the content of the gene?","options":["Epigenetics","Translocation","Inversion","Transduction"],"correctIndex":0,"explanation":"Ans.: A. Epigenetics\"Epigenetics is defined as changes that alter the pattern of gene expression that persist across at least one cell division but are not caused by changes in the DNA code. Epigenetic changes include alterations of chromatin structure mediated bymethylation of cytoosine residues in CpG dinucleotides, modification of histones by acetylation or methylation, or changesin higher-order chromosome structure- \" Harrison\"","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"50aa2943-d234-4743-88e0-286d47774107","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('234d592711de8d77cb0e7d64d77b7b87','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"137a6893-800d-4ef6-a9b9-8e55a19b5476","subjectId":"pathology","chapter":"پاتولوژی","prompt":"A 68 years old man had severe chest pain. The patient died on the way to the hospital. In the hospital, at autopsy tetrazolium chloride staining of the hea was done. What will be the color of ble myocardium?","options":["Red","Blue","Dark brown","Pink"],"correctIndex":0,"explanation":"Answer- A. RedTriphenyltetrazolium chloride (TTC) stain impas a brick-red color to intact, non-infarcted myocardium where the dehydrogenase enzymes are preserved.If the infarct preceded death by 2 to 3 hours, it is possible to highlight the area of necrosis by immersion of tissue slices in a solution of triphenyltetrazolium chloride. This gross histochemical stain impas a brick-red color to intact, non-infarcted myocardium where lactate dehydrogenase activily is preserved.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"137a6893-800d-4ef6-a9b9-8e55a19b5476","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('512eb2eb8c423a54bf3b80154f783222','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"21f2316e-83b3-4c4b-bc86-fec4f0a0e64b","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Syndrome which is characterized by 2X chromosomes and 1Y chromosome is:","options":["Kleinfelter syndrome","Down syndrome","Turner syndrome","Marfan syndrome"],"correctIndex":0,"explanation":"Klinefelter’s syndrome is associated with an extra X chromosome (47, XXY). Mohan H. Textbook of pathology. Jaypee Brothers Medical Publishers; 2015. Edition 7. Page 198","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"21f2316e-83b3-4c4b-bc86-fec4f0a0e64b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d081d4c007a02038aa618c4a1bab4048','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"6fdf54ef-e9b7-4086-97b1-c159316a8d4f","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Naive T cell get activated by:","options":["NK cell","Dendritic cell","Macrophage","B-lymphocyte"],"correctIndex":1,"explanation":"Naive T cell get activated by antigen presenting cells such as Dendritic cell Macrophage B-lymphocyte Most impoant APC in activating naive T cell is dendritic cell Dendritic cell on skin is called as Langerhans''s cell. They have granules called as Bier beck''s granules These granules have rod like appearance with a dilated end hence known to have tennis racquet appearance Markers of Langerhans''s cell CD 1 A S-100 HLA-DR Dendritic cell in lymph node is known as follicular dendritic cell. Follicular dendritic cell acts as a reservoir for HIV","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6fdf54ef-e9b7-4086-97b1-c159316a8d4f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('8e0aa58e5473551fedadaf8ed0474743','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"94b13f6b-7f81-41a0-bbef-d22271e45a47","subjectId":"pathology","chapter":"پاتولوژی","prompt":"A patient presented with headache and fever. His investigations revealed hemoglobin of 16g/dl, TLC of 21,000/ uL, platelet count of 3,75,000. His DLC showed Neutrophils (25%), Lymphocytes (20%), Metamyelocytes and myelocytes 40%and eosinophils5%. Which of the following is the next best investigation in this patient?","options":["JAK 2 mutation","EPO level","Philadelphia chromosome","Bone marrow biopsy"],"correctIndex":2,"explanation":"In the above question, lab investigation of the patient reveals normal hemoglobin, Elevated TLC, normal platelet count, decreased Neutrophils, Elevated metamyelocytes and myelocytes. This lab picture clearly indicates that immature WBC''s are much more in number than the mature WBC''S. Such a condition is given the name \"shift to the left\". This is seen in association with two types of conditions: 1.) Leukemoid reaction 2.) CML To distinguish between the two condition, we can do: LAP score (not commonly performed now). - CML- decreased, Leukemoid reaction- increased. Philadelphia chromosome presence (confirmatory test)- CML- Philadelphia chromosome (+ve), Leukemoid reaction - Philadelphia chromosome(-ve) .","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"94b13f6b-7f81-41a0-bbef-d22271e45a47","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('19b0b7501753d8e4c1744710c6afb9f4','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"1a29fc79-3d2d-40a4-82ca-0f2860d9958a","subjectId":"pathology","chapter":"پاتولوژی","prompt":"In a patient with Hepatitis B infection. Which one of the markers will be increased?","options":["HbsAg","HbcAg","Anti HbsAg IgG","Anti HbcAg IgG"],"correctIndex":3,"explanation":"Answer- D. Anti HbcAg IgGBest marker for diagnosing acute hepatitis B is IgM anti-HBc as it is found only in the acute phase of hepatitis B (In chronic hepatitis IgG anti-HBc is found).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"1a29fc79-3d2d-40a4-82ca-0f2860d9958a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('bcca6b25986c3eeba66a0cf4ff98f483','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"8173e986-5e4f-4c72-b175-8fa07b6c5ad9","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Frey''s syndrome results from surgery of the","options":["a)Submandibular salivary gland","Parotid gland","Sublingual salivary gland","TMJ"],"correctIndex":1,"explanation":"Auriculo temporal syndrome or Frey syndrome or gustatory sweating is due to damage of auricutotemporal nerve following surgery in parotid and mandibular ramus areas, and subsequent innervation of sweat glands by parasympathetic salivary fibres. The patient typically exhibits flushing and sweating of the involved side of the face, chiefly in the temporal area, during eating.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"8173e986-5e4f-4c72-b175-8fa07b6c5ad9","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('bad295a19e654b48a73383f63fa1b5db','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"c5040490-158b-4b0c-9d6d-5c9db9e5935d","subjectId":"pathology","chapter":"پاتولوژی","prompt":"In a platelet poor plasma sample calcium and tissue thromboplastin is added. This is used to assess which of the following pathway?","options":["Extrinsic","Intrinsic","Fibrinolytic","Common"],"correctIndex":0,"explanation":"Whenever we want to assess the Extrinsic or Intrinsic pathway, the sample that is taken is Platelet poor plasma sample. Assessment of EXTRINSIC PATHWAY - tissue thromboplastin is added along with calcium Intrinsic pathway - addition of Ca2+ along with negatively charged substance like Kaolin or Cephalin.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c5040490-158b-4b0c-9d6d-5c9db9e5935d","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('c450cc38c358337d443c49b083969bd3','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"bd0ed5fa-d212-4dfc-bba3-9706fe6a228d","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Which of the following is most common location of intracranial neurocysticercoses:","options":["Brain parenchyma","Spinal cord.","Basal cisternae.","Medulla oblongata."],"correctIndex":0,"explanation":"Cysticercosis is a parasitic infection that results from ingestion of eggs from the adult tapeworm. When cysticercosis involves the central nervous system, it is called neurocysticercosis. The cyst degenerates, leaks fluid from the larval cyst into the brain parenchyma, generating a strong immune response, characterized by enhancement on CT and MRI Downs Syndrome It is first seen either with seizures (70-90%) or headache.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"bd0ed5fa-d212-4dfc-bba3-9706fe6a228d","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('210f0213f539701e06c3d129cd881a5e','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"22f37095-b0aa-4603-a72d-8594c37b6f7e","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Which process shows phases of acute inflammation-","options":["Apoptosis","Pyroptosis","Necroptosis","Necrosis"],"correctIndex":3,"explanation":"Answer- D NecrosisDirect injury to the endothelium causes cell necrosis and appearance of physical gaps at the sites of detached endothelial cells.In necrosis phospholipase activation occurs that leads to cell damage and leakage of enzymes outside the cell is followed by inflammatory cells resulting in inflammation.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"22f37095-b0aa-4603-a72d-8594c37b6f7e","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1d401f355da5a2afbddc7aaa210739ea','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"5141f42f-f120-4531-abe0-8248b8dc1c51","subjectId":"pathology","chapter":"پاتولوژی","prompt":"A 6 year old patient with anemia, on electrophoresis shows HbF of 90% and HbA2 of 3%. Which of the following will be seen on peripheral smear","options":["A,B","A,C","B,C","ABC"],"correctIndex":3,"explanation":"The peripheral smears given shows: A - Target cell B - Howell jolly bodies C - Poikilocytosis. - All these features are characteristic to b- Thalassemia major. - Best investigation for the diagnosis of any kind of hemoglobinopathy-HPLC (High Performance Liquid Chromatography)","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"5141f42f-f120-4531-abe0-8248b8dc1c51","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('a76e092ffffe747cf984fbe2f8926410','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"5a6abefa-9edd-429c-8489-f7d4a3fd2770","subjectId":"pathology","chapter":"پاتولوژی","prompt":"A patient showing inability to close the right corner of the mouth is most probably suffering from:","options":["Myasthenia gravis","Bell''s palsy","TMJ dysfunction syndrome","Multiple sclerosis"],"correctIndex":1,"explanation":"Bell''s palsy is manifested by drooping of corner of mouth, drooling of saliva, watering of eye, inability to blink the eye. The patient has a typical mask-like or expressionless appearance. The patient will have speech diﬃculty and occasionally the taste sensation to anterior portion of tongue is lost or altered. In supranuclear lesions of facial nerve, only the lower part of the face is paralysed. The upper part (frontalis and part of orbicularis oculi) escapes due to bilateral representation in the cerebral cortex. In infranuclear lesions of facial nerve (Bell''s palsy) half of the whole of face is paralysed. The face becomes asymmetrical, and any attempt to smile draws the mouth to the NORMAL SIDE.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"5a6abefa-9edd-429c-8489-f7d4a3fd2770","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b0464579c5905400611f05cc9387574c','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"a8ef25e9-36e4-48e8-b3ad-48c4b138c6f8","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Chimerism phenomenon is associated with which of the following-","options":["Paternity test","Maternity test","Person identification test","organ transplantation case"],"correctIndex":3,"explanation":"Answer- D. organ transplantation caseChimerism can occur in animals is by organ transplantation, giving one individual tissues that developed from a different genome. For example, transplantation of bone marrow often determines the recipient''s ensuing blood type.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a8ef25e9-36e4-48e8-b3ad-48c4b138c6f8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('03e894c7bb6259be465f59953f178cf5','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"4fec3e84-b821-4da3-b300-dc0ad6c32608","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Which of the following is anaplastic lymphoma kinase (ALK) positive neoplasm?","options":["Synol sarcoma","Fibromatosis","Ewing sarcoma","Inflammatory myofibroblastic tumor"],"correctIndex":3,"explanation":"Answer- D. Inflammatory myofibroblastic tumorInflammatory myofibroblastic tumor is anaplastic lymphoma kinase (ALK) positive neoplasm.Inflammatory myofibroblastic tumor, though rare, is more common in children, with an equal male-to-female ratio.Presenting symptoms include fever, cough, chest pain, and hemopytsis. It may also be asymptomatic.Anaplastic Lymphoma Kinase (ALK)- Anaplastic lymphoma kinase also known as ALK tyrosine kinase receptor or CD246 (cluster of diff-erentiation 246) is an enzyme that in humans is encoded by ALK gene.Anaplastic Lymphoma Kinase (ALK) Positive NeoplasmsAnaplastic large-cell lymphomasAdenocarcinoma of lungFamilial neuroblastomaInflammatory myofibroblastic tumor","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4fec3e84-b821-4da3-b300-dc0ad6c32608","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3e1173d9c2bc32715f84f7077b13a7d9','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"6664aae4-2a0e-462e-a8c2-7f91ac2f24cd","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Most impoant but nonspecific regulator of iron metabolism is:","options":["Hepcidin","DMT I","Ferropoin","Ferritin"],"correctIndex":0,"explanation":"Ans: A. Hepcidin(Ref Robbins 91e p650 848 8/e p660)Hepcidin:Main regulator protein for iron absorption.Encoded by HAMP gene.Small circulating peptide synthesized & released from liver in response to increased intrahepatic iron levels.Proteins Involved in Iron MetabolismCeruloplasmindeg (ferrioxidase activity)DMT1degFerrireductasedeg (cytochrome b reductase I)FerritindegFerropinHeme transpoerHemojuvelinHepcidindegHephaestindegHFEdegIron-responsive element-bindingproteindegTransferrindegTransferrin receptors 1 & 2","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6664aae4-2a0e-462e-a8c2-7f91ac2f24cd","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('df4c212b718cefe9d509699e292476d4','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"2ff9fad7-263d-4611-a707-626809334f2c","subjectId":"pathology","chapter":"پاتولوژی","prompt":"What processing should be done of the blood before transfusion to reduce chances of febrile non-hemolytic transfusion reaction (FNHTR)?","options":["Irradiation","Washing","Leucocyte reduction","Glycolisation"],"correctIndex":2,"explanation":"1. The reason for the development of allergy is the presence of plasma and the process of washing helps in the removal of residual plasma. if the Patient is having a history of allergy - Antihistaminic drugs -reduce the chances of development of allergic reactions during blood transfusion. 2. Irradiation - reduces the chance of development of Graft Versus Host Disease. Irradiation - causes - reduction in the number of the immunocompetent cells (lymphocytes mainly) Irradiation of cellular blood components (red blood cells, platelets, and granulocytes) is indicated to prevent the development of transfusion-associated graft-versus-host disease (TA-GVHD). Patients at risk of TA-GVHD include immunocompromised patients who are receiving a bone marrow or stem cell transplant and fetuses undergoing an intrauterine transfusion. Irradiation is also indicated for recipients of components collected from a blood relative or HLA-matched donors. 3. Leukocyte reduction - Leukoreduction of whole blood and blood components has been shown to reduce recurrent febrile non-hemolytic transfusion reactions, reduce alloimmunization to leukocyte antigens that may complicate care of patients whoundergo transplantation or chronic transfusion therapy, and protect against transmission of cytomegalovirus (CMV) to patients at increased risk of CMV disease. antibodies in the recipient - react with donor leukocytes - release of cytokines - cause fever- known as Febrile Non-Hemolytic Transfusion Reaction. 4. Glycolisation - addition of glycol. useful in autologous blood transfusion - increases the life span of RBC. If the patient is having a history of development of anaphylaxis after blood transfusion, the patient is most likely to be suffering from IgA deficiency.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"2ff9fad7-263d-4611-a707-626809334f2c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ff16b3ea5b94e0a66e29a996ae14c169','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"d6f5cf46-9b31-4489-8989-beff9c456484","subjectId":"pathology","chapter":"پاتولوژی","prompt":"Translocation seen in Ewing''s sarcoma is:","options":["t(8,11)","t(11,22)","t(11,18)","t(14,18)"],"correctIndex":1,"explanation":"Ans: B. t(11,22)Genetic exchange between chromosomes can cause cells to become cancerous. Most cases of Ewing''s sarcoma (85%) are the result of a translocation between chromosomes 11 and 22, which fuses the EWS gene of chromosome 22 to the FLI1 gene of chromosome 11. Other translocations are at t(21;22) and t(7;22).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d6f5cf46-9b31-4489-8989-beff9c456484","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ac352b604eff64cc9b2474b1dc94adbf','reference-medmcqa-preinternship-pathology-en-1','pathology','پاتولوژی','medium','{"key":"d0b610ce-0221-413d-8d59-aca1b5a1a254","subjectId":"pathology","chapter":"پاتولوژی","prompt":"In Prothrombin time (PT) estimation, on addition of calcium and thromboplastin to platelet poor plasma. which of the following pathway is activated?","options":["Extrinsic","Intrinsic","Fibrinolysis","Common"],"correctIndex":0,"explanation":"Ans. a. ExtrinsicIn Prothrombin time (PT) estimation, addition of calcium and thromboplastin to platelet poor plasma activates extrinsic pathway.The prothrombin time (PT) assay assesses the function of the proteins in the extrinsic pathway (factors VII, X,and .fibrinogen). In brief tissue factor, phospholipids, and calcium are added to plasma and the time for a fibrin clot to form is recorded.Prothrombin time (PT): This test assesses the extrinsic and common coagulation pathways. The clotting of plasma after addition of an exogenous source of tissue thromboplastin (e.g., brain extract) and Ca\" ions is measured in seconds. A prolonged PT can result from deficiency or dysfunction of factor V, factor VII, factor X, prothrombin. or fibrinogen","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d0b610ce-0221-413d-8d59-aca1b5a1a254","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-medmcqa-preinternship-pediatrics-en-1','اطفال · منتخب MedMCQA','preinternship','reference','medmcqa',NULL,'منبع باز',1793577600000,0,'MedMCQA — Pal, Umapathi & Sankarasubbu, 2022. Validation split via Open Life Science AI; Apache-2.0. متن اصلی انگلیسی؛ آزمون رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('57bd4cdda44511629f65fd796821f67d','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"67add9f9-94b5-40b2-904d-fb4965fb8309","subjectId":"pediatrics","chapter":"اطفال","prompt":"In Erythroblastosis fetalis not involved is –","options":["Anti C","Anti D","Anti E","Anti Lewis"],"correctIndex":3,"explanation":"Erythroblastosis fetalis is caused by the transplacental passage of maternal antibody active against paternal RBC antigens of the infant and is characterized by an increased rate of RBC destruction. Although more than 60 different RBC antigens are capable of eliciting an antibody response, significant disease is associated primarily D antigen of Rh group and with A 0 incompatibility. Other rare antigens involved are - C or E antigen of Rh group RBC antigens - Cw, Cx, Cu, K (kell), M, Duffy, S, P, MNS, Xg, Lutheran, Diego and Kidd. Anti-Lewis antibodies do not cause disease.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"67add9f9-94b5-40b2-904d-fb4965fb8309","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b6c6c3fbe359811d501c3dcb96da5b7d','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"641f160f-eef0-4b8c-9cb8-3241d2d63173","subjectId":"pediatrics","chapter":"اطفال","prompt":"In a child with active liver failure, the most important prognosis factor for death is –","options":["Increasing transaminases","Increasing bilirubin","Increasing prothrombin time","Gram (–)ve sepsis"],"correctIndex":3,"explanation":"Prognosis of hepatic failure in children Children with hepatic failure have somewhat better prognosis. The prognosis varies considerably with - i) Cause of liver failure ii) Stage of hepatic encephalopathy Poor prognostic factors for mortality If cause of liver failure is —> Wilson disease, idiopathic Stage IV coma —> Most common cause of death is brain stem herniation Age < I year Sepsis Severe hemorrhage Renal failure , Need for dialysis before transplantation For option b & c - \"Pretransplant serum bilirubin concentration and the INR (prothrombin time) of coagulation are not predictive of post transplant survival\".","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"641f160f-eef0-4b8c-9cb8-3241d2d63173","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('85c18e9c2f2441ed6d503548fb177131','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"e621e03f-d935-427f-a7a7-14f6f9a0efab","subjectId":"pediatrics","chapter":"اطفال","prompt":"Child of Vasanthi was weaned from breast milk on the 5th day and was given sugarcane juice the child developed hypoglycemia and hepatomegaly biochemical examination showed hypophosphatemia and enzyme deficiencies–reducing substances in urine. The child is probably suffering from which of the following enzyme deficiencies –","options":["Fructokinase","Aldolase B","Glucose 6 Phosphatase","Beta galactosidase"],"correctIndex":1,"explanation":"HEREDITARY FRUCTOSE INTOLERANCE Symptoms of hypoglycemia, hepatomegaly develping after injection of excessive fructose intake (sugar cane juice contains the major dietary source of fructose-Sucrose suggest the diagnosis of hereditary fructose intolerance. Clinical disorders related to fructose metabolism can result from excessive fructose consumption that exceed''s the body''s ability to efficiently convert the sugar into metabolic intermediates. In normal persons fructose is metabolized in the following way","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e621e03f-d935-427f-a7a7-14f6f9a0efab","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('33e9c36c4d9960eb91c68c829eae966e','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"14e05154-05a2-4472-a63e-261d765893ae","subjectId":"pediatrics","chapter":"اطفال","prompt":"Pulsatile varicose veins in lower limbs is seen in –","options":["Klippel trenaunay syndrome","TR","RV failure","Carcinoid stenosis of tricuspid"],"correctIndex":0,"explanation":"Klippel - Trenaunay syndrome (KT syndrome) The triad of KT syndrome is:- Cutaneous vascular malformation —> Most commonly capillary malformation. Bony capillary malformation and soft tissue hypertrophy. Venous abnormalities —> Deep venous system may be absent or hypoplastic. The anomaly present at birth and usually involves lower limb. When there is associated Arterio - venous malformation, it is known as Klippel - Trenaunay - Weber syndrome. Thick walled venous varicocities typically become apparent ipsilateral to the vascular malformation —> May be pulsatile because ofAV malformation.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"14e05154-05a2-4472-a63e-261d765893ae","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3aeded8e24545310014df9d9440690b7','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"82f0f5d7-996b-49cc-8c8c-b9ff7cb35ecc","subjectId":"pediatrics","chapter":"اطفال","prompt":"Cystinuria is characterised by –","options":["Generalised aminoaciduria","Systemic acidosis","Deposition of cystine crystals in Renal tubular cells","Recurrent urinary caliculi"],"correctIndex":3,"explanation":"Cystinuria It is an autosomal recessive disorder. The disease is caused by a defective high affinity transporter for L-cystine and diabasic amioacids present in the proximal tubules. It is characterize by recurrent kidney stone formation.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"82f0f5d7-996b-49cc-8c8c-b9ff7cb35ecc","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2291c556a41ca9a40fd41b3b54e087af','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"790947ee-b119-4f1f-ac07-8f0c5a701010","subjectId":"pediatrics","chapter":"اطفال","prompt":"In a child, surgery was done for biliary stricture with hepatojejunal anastomosis. Postoperative bilirubin level after 2 weeks was 6 mg/dL from a preoperative level 12mg/dL. The reason for this could be:","options":["Normal lowering of bilirubin takes time","Anastomotic stricture","Delta bilirubin","Mistake in lab technique"],"correctIndex":2,"explanation":"Ans: C. Delta bilirubin(Ref Harrison 19/e p280, 18/e p325)Delta Bilirubin:Albumin-linked bilirubin fraction (delta fraction/biliprotein)Is pa of direct-reacting bilirubin fraction including conjugated bilirubin, covalently linked to albumin.Represents an impoant fraction of total serum bilirubin in patients with cholestasis & hepatobiliary disorders.Clearance rate of albumin-bound bilirubin from serum approximates half-life of albumin (12-14 days) rather than sho half-life of bilirubin (4 hours).Due to tight albumin bonding.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"790947ee-b119-4f1f-ac07-8f0c5a701010","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2d6329d361791b76260e019d280e55ef','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"33a697bc-627a-4a24-b381-19c181fcdded","subjectId":"pediatrics","chapter":"اطفال","prompt":"Method of choice for a New born child not passing urine for 36 hours :","options":["Ultrasound of kidney & bladder","CT Scan","Cystoscopy","X–ray pelvis"],"correctIndex":0,"explanation":"A history of Anuria suggests Acute Renal failure. Ultrasonography is the ideal imaging tool in Renal failure because of its non dependence on Renal function. As it allows visualization of : Pelvicalyceal system ofAssessment of Renal Size o Structural anomalies and calculi . Note - In this question DTPA scan has not been provided as an option. So, the best answer is USG.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"33a697bc-627a-4a24-b381-19c181fcdded","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('a44a8703375260c4ffeecb0e0af1c95b','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"c86f02db-18ea-4ef1-a03a-1bee6d661c7b","subjectId":"pediatrics","chapter":"اطفال","prompt":"Which of the following is not an example of a syndrome caused by uniparental disomy?","options":["Prader-Willi syndrome","Angelman syndrome","Russell-Silver syndrome","Bloom syndrome"],"correctIndex":3,"explanation":"Answer- D. Bloom syndromeUniparental disomy is the term used when both chromosome of a pair of chromosome is a person with normal number of chromosome, have been inherited from only one parent (Normally one chromosome of a pair is inherited from only one parent).The two chromosomes inherited from the same parent maybe identical (Uniparental isodisomy) or different (Uniparental heterodisomy).In Uniparental isodisomy, both chromosomes in the pair are identical; consequently the genes on both chromosomes are also identical.Angelman syndrome, Prader-Willi syndrome and Russell-Silver syndrome are ossociated with uniparental disomy.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c86f02db-18ea-4ef1-a03a-1bee6d661c7b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e267be782aa1f5692f7546dbdcae16c5','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"fd315adc-df4b-4a81-895b-6f093eeb71b2","subjectId":"pediatrics","chapter":"اطفال","prompt":"Which of the following is an indiction for tonsillectomy –a) Rheumatic feverb) Glomerulonephritisc) Recurrent upper respiratory infectiond) Persistent carrier of diptheria bacilli","options":["ab","cd","bd","ac"],"correctIndex":1,"explanation":"Indications of tonsillectomy Recurrent sore throat —› If more than six attacks of tonsillitis in a year for two consecutive years. Tonsillar or peritonsillar abscess o Retention cyst of tonsil o Diphtheria carriers Tonsillolith o Suspicious malignancy o Obustructive sleep apnea","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"fd315adc-df4b-4a81-895b-6f093eeb71b2","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7547d06a3d9abe9e36d859e1fed3383f','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"55093e71-8916-4f25-9524-9425d51455e1","subjectId":"pediatrics","chapter":"اطفال","prompt":"A term gestation newborn developed respiratory distress. Which of the following would favour Respiratory distress syndrome (HIVID) ?","options":["History of receiving antenatal corticosteroids","Air bronchogram on chest x–ray","Onset of distress after 6 hours of birth","Term birth"],"correctIndex":1,"explanation":"chest x-ray of an infant with RDS is characterized by atelectasis, air bronchograms, and a diffuse reticular-granular pattern commonly referred to as \"ground glass\". The chest x-ray may progress to a complete \"white out\" with severe disease. About other options Antenatal corticosteroids are given in pre-term (pre-mature) pregnancies not in term pregnancies. Further, antenatal corticosteroids are given to prevent RDS (HMD) --> after antenatal corticosteroids administration, risk of HMD is reduced. Respiratory distress occurs within first 6 hours. HMD occurs in pre-term neonate.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"55093e71-8916-4f25-9524-9425d51455e1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7acc600a66636a5b6cefbc6585cf4aa7','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"4e8f5ba7-452a-464f-a328-d8b96eafade6","subjectId":"pediatrics","chapter":"اطفال","prompt":"A 5 years old child presented with continuous fever and features of sepsis with a BP of 90/60 mm Hg, Pulse rate 144/min and respiratory rate of 30/min. What is the initial fluid of choice for management?","options":["10 mL/kg of 10% dextrose","10 mL/kg of hydroxyethyl starch","20 mL/kg of 0.45% normal saline","20 mL/kg of 0.9% normal saline"],"correctIndex":3,"explanation":"Ans: D : 20 mL/kg of 0.9% normal salineExplanation:(Ref: Ghai 8Ie p718)In hypovolemic or septicemic shock, replacement of intravascular volume by isotonic fluids is the main stay of treatment.Hence, normal saline resuscitation with 20 ml/kg boluses.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4e8f5ba7-452a-464f-a328-d8b96eafade6","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('48d692add967fa0a701a8691685c3557','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"f204b864-ca16-4d18-9d0c-6c6a9cb3533a","subjectId":"pediatrics","chapter":"اطفال","prompt":"A child presented with abdominal distension, hepatomegaly, doll like facies and recurrent episodes of hypoglycemia. Which of the following is the most likely diagnosis?","options":["Menkes disease","Down syndrome","Von gierke disease","Lesch nyhan syndrome"],"correctIndex":2,"explanation":"Menkes disease- aka kinky hair disease - Defect in copper binding ATPase - Involves CNS- intellectual disability, seizures - Characterized by sparse hypopigmented kinky hairs. - Trichorrhexis nodosa and pili toi seen Von Gierke disease is glycogen storage disease type I, in which the child has doll like facies, abdominal distension, hepatomegaly and recurrent episodes of hypoglycemia. On investigation, there is hyperlipidemia, hyperuricemia and lactic acidosis. Lesch nyhan syndrome- mental retardation, microcephaly, seizures and gout.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f204b864-ca16-4d18-9d0c-6c6a9cb3533a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('411042fc61b6d87519f224e4a4907c05','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"4032c899-2223-435f-a007-c513fd59a065","subjectId":"pediatrics","chapter":"اطفال","prompt":"A child has bilirubin of 4 mg. Conjugated bilirubin and alkaline phosphatase are normal, bile salts and bile in urine are absent. However urobilinogen in urine is raised. What is the likely diagnosis –","options":["Obstructive jaundice","Rotor''s syndrome","Biliary cholestasis","Hemolytic jaundice"],"correctIndex":3,"explanation":"Important clues provided in question are - Increased total bilirubin I So, T unconjugated bilirubin Normal conjugated bilirubin Amongst the given options, only hemolytic jaundice causes increased unconjugated bilirubin. Remaining three cause conjugated hyperbilirubinemia.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4032c899-2223-435f-a007-c513fd59a065","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2e142ee4b7c882a2534ef0babd8e8201','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"238019d8-3c6b-486e-9d00-fda1273d22e7","subjectId":"pediatrics","chapter":"اطفال","prompt":"An un-immunized 13 months old child comes to you in OPD, according to the latest immunizations schedule, what vaccines will you advise??","options":["OPV 3 doses, I IPV 3 Pentavalent and I measles","BCG, OPV 3 doses, 3 lPV, 3 Pentavalent and I measles","OPV 3 doses, I IPV 3 Pentavalent and 2 measles","OPV 3 doses, 3 IPV 3 DPI : Hep-B"],"correctIndex":3,"explanation":"Ans: D. OPV 3 doses, 3 IPV 3 DPI : Hep-BRef: ip. o rg/file s/I A P-imm unizution-sc he du le- 2 0 I 6- I P- 2 0 I 6-E p u b. p df* The latest schedule of immunization under NIS is as follows:* vNational Immunization Schedule (NIS) for Infants, children and Presnant women - - OPV 3 doses, 3 IPV 3 DPI : Hep-B","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"238019d8-3c6b-486e-9d00-fda1273d22e7","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d60f803c050b35c9f205d1d61f55009a','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"3b184f01-db13-4379-ab0b-7709853e0326","subjectId":"pediatrics","chapter":"اطفال","prompt":"A case of jaundice with 50% direct bilirubin, other LFTs normal. Diagnosis is –","options":["Rotor syndrome","Gilbert syndrome","Glucuronyl transferase deficiency","Primary biliary cirrhosis"],"correctIndex":0,"explanation":"50% direct bilirubin means conjugated hyperbilirubinemia. Normally the direct (conjugated) bilirubin is less than 15-20% of total bilirubin. Normal Values of bilirubin Total bilirubin > 0.2 - 1.9 mg/d1. Direct bilirubin > 0 - 0.3 mg/dl. So, this child has : - Conjugated hyperbilirubinemia Other LFTs normal Amongst the given options, Rotor syndrome and Primary biliary cirrhosis cause conjugated hyperbilirubinemia. In Primary biliary cirrhosis, other LFTs are also abnormal, e.g., SGOT and SGPT are raised. Now we are left with Rotor syndrome which causes conjugated hyperbilirubinemia. Other LFTs are normal.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"3b184f01-db13-4379-ab0b-7709853e0326","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9f3855bf8872b6e4588f57560f7a7f3e','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"f9739409-2790-47a9-80b7-98c70f0bcc16","subjectId":"pediatrics","chapter":"اطفال","prompt":"A two year old girl child is brought to the out patient with features of hand wringing stereotype movements, impaired language and communication development, breath holding spells, poor social skills and deceleration of head growth after 6 months of age. The most likely diagnosis is –","options":["Asperger''s syndrome","Rett''s syndrome","Fragile x–syndrome","Colarad syndrome"],"correctIndex":1,"explanation":"This 2 years child has following problems. Hand wringing movements. Impaired language and communication development. Breath holding spells Poor social skills Decleration of hand growth after 6 months. Now see the clinical features of Rett syndrome. a. Age of onset is around 5 months. Development may proceed normally until 1 yr of age, when regression of language and motor milestones become apparent. a. Acquired microcephaly (Decleration of head growth due to significantly reduced brain weight). * Most children develop peculiar sighing respirations with intermittent periods of apnea that may be associated with cyanosis --> Breath holding spells. The hallmark of Rett syndrome is repetitive hand wringing movements and a loss ofpurposeful and spontaneous use of the hands. Autistic behavior is a typical finding in all patients. Generalized tonic-clonic convulsions occur in the majority. Feeding disorder and poor weight gain are common. Death occurs in adolescence or in the 3rd decade. Cardiac arrhythmias may result in sudden, unexpected death. Clinical features given in question prefectly match with Rett syndrome Asperger syndrome Qualitative impairment in the development of reciprocal social interaction. More common in males Normal intelligence. Eccentric interests. No language impairments that characterize autism. Children with Asperger syndrome appear to be at high risk for other psychiatric disorder","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f9739409-2790-47a9-80b7-98c70f0bcc16","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('db24c4fbbe55c37ee4a3b7e821e658ab','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"5900458a-b839-47eb-a745-b93e35ba2d40","subjectId":"pediatrics","chapter":"اطفال","prompt":"Most common cause of postauricular lymphadenopathy in children :","options":["Sore throat","Pediculosis capitis","Pulmonary Koch''s","Chronic suppurative otitis media"],"correctIndex":1,"explanation":"Posterior or Suboccipital cervical lymphadenopathy is caused by Roseola, Rubella, Scalp infections. The lymphatic drainage of posterior scalp is to the occipital region. Posterior or Suboccipital cervical lymphadenopathy without obvious disease or secondary infection is characteristic of lice. Secondary pyodenna due to scratching may result in matting together of the hair and cervical and occipital lymphadenopathy.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"5900458a-b839-47eb-a745-b93e35ba2d40","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('feae919dbf7d78a0258a8db0a76f100e','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"0f86c441-70a5-466d-b59f-1512fe88cbfd","subjectId":"pediatrics","chapter":"اطفال","prompt":"A breast fed child presents with hypernatremia (Serum sodium > 170m Eq/L). His urine sodium is 70 mEq/L. Which of the following is the most likely cause –","options":["Diabetes insipidus","Acute necrosis","Severe dehydration","Excessive intake of sodium"],"correctIndex":3,"explanation":"The child is having hypernatremia. Serum sodium >170 rnEq/L (Normal level is 135-145 mEq/L). Urine sodium is also very high, >70mEq/L (Normal urine sodium level in Serum sodium conc. will be high but urine sodium conc. will be very low (Lack of ADH leads to defect in concentration of urine). Acute necrosis -> Urine sodium conc. will be high but serum sodium conc. will be low. Severe dehydration -> Urine sodium concentration will be low.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0f86c441-70a5-466d-b59f-1512fe88cbfd","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5ab38e4faf00cf5f50ded997fddca98b','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"05887319-687e-4b8e-a850-9c4097ceeef7","subjectId":"pediatrics","chapter":"اطفال","prompt":"Which of the following intrauterine infections is associated with limb reduction defects and scarring of skin –","options":["Varicella virus","Herpes virus","Rubella","Parvovirus"],"correctIndex":0,"explanation":"Congenital varicella syndrome is characteristically associated with scarring of skin and limb reduction defect (limb hypoplasia). Perinatal chicken Pox (Perinatal varicella infection) The baby may develop two types of complications depending on the period of gestation.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"05887319-687e-4b8e-a850-9c4097ceeef7","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('008a15b8755509c52d72ca53a3f70862','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"e8b34af9-6a4b-42cf-90ce-fb46a23db79d","subjectId":"pediatrics","chapter":"اطفال","prompt":"Characteristics radiological feature of transient tachypnoea of newborn is –","options":["Reticulogranular appearance","Low volume lungs","Prominent horizontal fissure","Air bronchogram"],"correctIndex":2,"explanation":"The lungs are generally clear without rales or rhonchi and chest roentgenogram shows Prominent pulmonary vascular markings ❑ Overaeration Fluid lines in the fissure ❑ Flat diaphragms Prominent inter lobar fissure ❑ Occasionally pleural fluid.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e8b34af9-6a4b-42cf-90ce-fb46a23db79d","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7c6f52305421c2bfa2e8b698ac073017','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"51bdbdd1-de3d-45e7-8bfb-dbd36e1ae434","subjectId":"pediatrics","chapter":"اطفال","prompt":"4yr boy absence of right testes, diagnostic laparoscopy done, a blind end vessel seen what to do next?","options":["Open laprotomy","Nothing to be done","Scrotal approach","Inguinal approach"],"correctIndex":3,"explanation":"Ans. D. Inguinal approachCryptorchidism is the most common congenital abnormality of the genitourinary tract.Cryptorchidism means hidden testis.An absent testis may be due to agenesis or atrophy secondary to intrauterine vascular compromise also known as the \"vanishing testis syndrome\".Bilaterally absent testes is anorchia which is 10% cases.More common on Right Side.Complications of undescended testesTorsion can be seen in incomplete testicular descentSterility is seen in bilateral cases (especially intra-abdominal testes)Incomplete testicular descent predisposes to malignant disease; cancer is more common in an incompletely descended testes-orchidopexy may or may not diminish the risk.Atrophy of an inguinal testes before pubey may possibly be caused by recurrent minor trauma.In patients with a unilateral nonpalpable testis, a descended testis that is larger than expected suggests an atrophic undescended testis; confirmation requires surgical intervention typically diagnostic laparoscopy to seek an intra-abdominal testis or confirm testicular agenesis. However, scrotal or inguinal exploration is sometimes done if a testicular remnant distal to the internal inguinal ring is suspected.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"51bdbdd1-de3d-45e7-8bfb-dbd36e1ae434","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('61a861635e775e8d4c8f22a2cc2a69d5','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"87c9ed45-4f13-4ec7-9af1-571dc39c84a9","subjectId":"pediatrics","chapter":"اطفال","prompt":"A 5 year-old child presents with non-utatiening macules and pappules on the skin. Skin biopsy revealed a perivascular IgA deposition. Which of the following is the most likely diagnosis?","options":["Henoch Shonlein purpura","Wegener''s granulomatosis","Kawasaki disease","Drug-induced vasculitis"],"correctIndex":0,"explanation":"Ans. a. Henoch-Shonlein purpura (Ref Harrison 19/e p2100, 18/e p2797)Presence of non-blanching palpable purpura (vasculitis of skin) and colicky abdominal pain (vasculitis of gastrointestinal tract) in a five-year-old child together with evidence of IgA deposition in immune complexes suggests the diagnosis of Henoch Scholein Purpura","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"87c9ed45-4f13-4ec7-9af1-571dc39c84a9","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('91169e74fa525ec9d4c06118cbcd5f15','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"16b0d12a-6521-4f27-a70f-2726a7a3f6a3","subjectId":"pediatrics","chapter":"اطفال","prompt":"Treatment of choice in childhood thyrotoxicosis :","options":["Radio Iodine","Lugols Iodine","Carbimazole","Surgery"],"correctIndex":2,"explanation":"Most pediatric endocrinologists recommend initial medical therapy using antithyroid drugs rather than radioiodine or subtotal thyroidectomy. The 2 antithyroid drugs in widest use are methimazole and propylthiouracil.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"16b0d12a-6521-4f27-a70f-2726a7a3f6a3","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f16f704045cf853f5513267be5647256','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"c6da06a8-62d4-49b1-9bce-e4584bbadc62","subjectId":"pediatrics","chapter":"اطفال","prompt":"Vesicoureteric reflux is more common in –","options":["Newborn females","Older girls","Older boys","Only during pregnancy"],"correctIndex":0,"explanation":"Clinical manifestations of VUR In primary reflux the average age ofpresentation is 2-3 years. Reflux is more common in females and it is usually detected earlier in females so we can say that reflux is present from birth but it is usually detected at 2-3 years of age but in feinales the age of detection is earlier. Features are - In primary reflux the patient usually presents with symptoms of pyelonephritis or cystitis. In secondary reflux manifestation of primary diseases are usually the presenting symptoms Reflux is the most common cause of pyelonephritis. It is seen in 30-50% of patients with pyelonephritis. It is present in over 75% of patients with radiological evidence of chronic pyelonephritis Diagnosis of Vesicoureteric reflux - The most useful process for conclusive diagnosis of reflux is micturating cystourethrogram. This will demonstrate the grade of reflux as well as urethral anatomy. The other useful technique for detecting vesicoureteric reflux is radionuclide imaging. It is extremaly sensitive at detecting reflux but do not demonstrate the anatomic detail seen with voiding cystourethro gram. So they are used for follow up after micturating cystourethrogram because they offer less radiation exposure.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c6da06a8-62d4-49b1-9bce-e4584bbadc62","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9c67bc792c3b2e66e89a15e2edfe518b','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"062bbde6-1097-4f2f-a08e-1b055158bbc1","subjectId":"pediatrics","chapter":"اطفال","prompt":"Macrocephaly is seen in which of the following syndromes ?","options":["Metachromatic leucodystrophy","Adrenoleukodystrophy","Canavan''s disease","Krabbe''s disease"],"correctIndex":2,"explanation":"LEUCO J ITS TROPHY Leucodystrophy refers to progressive degeneration of the white matter of the brain clue to imperfect growth or development of the myelin sheath, the fatty covering that acts as an insulator around nerve fibre. Myelin which lends its color to the white matter of the brain, is a complex substance made up of at least ten different chemicals. The leucodystrophy are a group of disorders that are caused by genetic defects in hoW myelin produces or metabolizes these chemicals. Each of the leucodystrophies in the result of a defect in the gene that controls one (and only one) of the chemicals. Specific leusodystrophies include - Metachroinatic leucodystrophy ❑ Adrenoleucodystrophy ​❑ Canavan disease Krabbe''s disease ❑ Pelizaeus-Merzhacher disease ​ ❑ Alexander disease Symptoms vary according to the specific type of leucodystrophy and may be difficult to recognize in the early stages of the disease. Canavan''s disease Autosomal recessive disorder Caused due to deficiency of the enzyme N-Aspertoacylase. This leads to accumulation of N-Acetyl aspartic acid in brain and urine. It is characterized by the clinical traid of --> Hypotonia, Head lag, Macrocephaly ​​Adrenoleucodvstrophy X-linked recessive disorder Caused due to deficiency of AcyI-C''oA synthetase. Onset is about 5-10 years Main symptoms are ataxia, spasticity, motor deficits, cortical blindness. Marocephaly is not a key feature Metachromatic leucodystrophy Autosomal recessive disorder Caused due to Arylsulfatase A deficiency Onset is in the 2nd year. Symptoms are into-ordination, especially gait disturbance, then general regression, optic atrophy, combined upper and lower motor neuron signs. Marocephaly usually late. Krabbe leucodvstrophy Autosomal recessive Caused due to deficiency of Beta-galactosidase deficiency Onset is in the first 6 months of life Optic atrophy, spasticity Head often small","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"062bbde6-1097-4f2f-a08e-1b055158bbc1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3be1a04950f90517f58ecffb402959a6','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"0c4f5b5b-25ec-459f-9872-a01bc925f211","subjectId":"pediatrics","chapter":"اطفال","prompt":"NESTROFT test is a screening test for –","options":["β–thalassemia","Hereditary spherocytosis","Autoimmune hemolytic anemia","Megaloblastic anemia"],"correctIndex":0,"explanation":"NESTROFT ( Naked Eye Single Tube Red Cell Osmotic Fragility Test) is a screening test for detection of beta thalassemia trait. Thalassemia screening Widespead prevlence of thalessemia has led to a pressing demand for community, screening. Various methods for screening of thalassemia trait are available which include peripheral smear examination, RBC indices, 1VIeintzer''s fraction, discriminant functions, NESTROFT etc. NESTROFT TEST is used in many centres in India for screening of thalassemia trait. If mother is NESTROFT positive, the confirmatory test for HbA2 is done for mother and the father is subjected to screening by NESTROFT. If father is also NESTROFT positive, confirmatory test for HbA2 is done for father. If both the parents have thalessemia trait, there is 1:4 chance of fetus having thalassemia major. Therefore, prenatal diagnosis is done by chorionic villus sampling (CVS) in first trimester. If CVS confirms the fetus to be having thalasemia major, termination of pregnancy is indicated after counseling the parents. If the fetus has thalassemia minor (trait) pregnancy is continued as such and baby will have normal lifespan. It is worth noting here that a positive NESTROFT test is seen in other conditions beside beta thalassemia trait. These are iron deficiency anemia, alpha thalassemia trait, homozygous and heterozygous HbE, HbS as well as hereditary persistence of fetal hemoglobin. Therefore, a positive NESTROFT test should always be followed by a confirmatory test for HBA2 ( eg. serum electrophoresis).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0c4f5b5b-25ec-459f-9872-a01bc925f211","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1c7cfd9868d6db2ffebd8a37dd5e4292','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"b8fad18b-75df-42b6-b06d-8902a10f6e16","subjectId":"pediatrics","chapter":"اطفال","prompt":"Which of the following is not a feature of Juvenile Idiopathic Arthritis –","options":["Rheumatoid nodule","Spikes of high fever","Uveitis","Raynaud''s phenomenon"],"correctIndex":3,"explanation":"Juvenile idiopathic arthritis Juvenile idiopathic arthritis is broad term that describes a clinically heterogenous group of arthritides of unknown cause, which begin before 16 years of age. This term encompasses several disease categories : - 1. Juvenile rheumatoid arthritis (see previous explanations) : - i) Pauciarticular (oligoarticular) JRA ii) Poly-articular JRA RA. factor (+) ye RA factor (-) ye iii) Systemic JRA Juvenile psoriatic arthritis Juvenile enthesitis related arthritis (ERA) ​Subgroups of Juvenile Idiopathic Arthritis (JIM","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b8fad18b-75df-42b6-b06d-8902a10f6e16","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('8e5fae9d6c39d6bb4a94093f865a6b90','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"e9d9c003-7fb0-404f-aa20-bea77c101f75","subjectId":"pediatrics","chapter":"اطفال","prompt":"A child had repeated vomiting and developed metabolic alkalosis. The treatment given is –","options":["Ringer lactate","I.V. normal saline and potassium","ORS","I.V. Normal saline"],"correctIndex":1,"explanation":"Treatment of metabolic alkalosis due to vomiting or nasogastric suction. Most children with metabolic alkalosis have one of the chloride responsive etiology (e.g., vomiting). In these situations, administration of suffieeint sodium chloride and potassium chloride to correct volume deficit is necessary to correct metabolic alkalosis. Adequate replacement of gastric losses of sodium and potassium in a child with vomiting can minimize or prevent the development of metabolic alkalosis. With adequate intravascular volume and a normal serum potassium concentration, the kidney is able to excrete the excess bicarbonate within a couple of days.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e9d9c003-7fb0-404f-aa20-bea77c101f75","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('88c1a03733873d67c59dce4dcbbfaec6','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"73b821cd-6c0f-427f-bd1c-ccc14a5f4267","subjectId":"pediatrics","chapter":"اطفال","prompt":"A baby presents with tetany. First thing to be done is administration of :","options":["Diazepam","Vitamin D","Calcium gluconate","Calcitonin"],"correctIndex":2,"explanation":"The baby presenting with tetany is hypocalcemic, so must be treated immediately with calcium gluconate I.V. Treatment of hypocalcemia. Acute or Severe Tetany The objective of the treatment is to correct hypocalcemia immediately with calcium gluconate I.V Maintenance management of hypoparathyroidism and chronic hypocakenzia. The objective is to maintain serum calcium and serum phosphase at approximately normal levels. It usually requires. 1. Diet ---> Calcium supplements and diet rich in calcium. 2. Vitamin D supplementation ---> Ergocakiferol or dihydrotachysterol.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"73b821cd-6c0f-427f-bd1c-ccc14a5f4267","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('592761e2762a4b44dc01f3d0067d8b95','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"e4e4f249-397f-4edb-b3c2-ff0220ef3092","subjectId":"pediatrics","chapter":"اطفال","prompt":"A triad of seizure, mental retardation and sebaceous adenoma is seen in –","options":["Congenital syphilis","Tuberous sclerosis","Toxoplasmosis","Hypothyroidism"],"correctIndex":1,"explanation":"Tuberous sclerosis : It is an autosomal dominant neurocutaneous syndrome. Pathology Characteristics brain, lesion, consists of tubers in the brain. They are typically present in subependyneal region where they undergo calcification producing candle dripping appearance.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e4e4f249-397f-4edb-b3c2-ff0220ef3092","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('211a3a3af310137f83c9c0c2862466c6','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"5fa2e23f-c19c-4828-b240-59b7a0a84834","subjectId":"pediatrics","chapter":"اطفال","prompt":"What should be the ideal temperature in delivery room for the neonates to be kept in warmer?","options":["22-26degC","28-30degC","30-35degC","37degC"],"correctIndex":0,"explanation":"Ans: A. 22-26degC(Ref Ghai 8/e p133).Nursery temperature:Ideal temperature in delivery room for neonates in warmer state - 22-26degC (72-78\"F).Should be free from drill of air.Ventilation system for each delivery & resuscitation room designed to control ambient temperature between 72-78 degrees Fahrenheit (22-26 degrees Centigrade) during delivery, resuscitation & stabilization of newborn.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"5fa2e23f-c19c-4828-b240-59b7a0a84834","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('584b8ab9306fedf3168e443e054a0fb9','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"1a54dc09-051e-419b-879e-6d435f34f711","subjectId":"pediatrics","chapter":"اطفال","prompt":"Which of the following is considered as high risk infant?","options":["Working mother","Antenatal preeclampsia","Third child","Twins"],"correctIndex":0,"explanation":"Ans. A. Working mother Identification of ''At Risk'' Infants * Bih weight < 2.5 Kg* Bih order 5 or more* Aificial feeding* Weight below 70% of expected weight (i.e. grade II & III malnutrition)* Failure to gain weight during 3 successive months* Children with PEM, Diarrhea.* Working mother, one parent.* Spacing of less than 1 year.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"1a54dc09-051e-419b-879e-6d435f34f711","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('459fac4dc5402418b23fb2eb2c6b7196','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"178bda2c-c1fc-47dd-8d73-ef6e7ddf0d22","subjectId":"pediatrics","chapter":"اطفال","prompt":". The most common fungal infection in the neonates transmitted by caregiver''s hand is:","options":["Candida albicans","Candida glabrata","Candida tropicalis","Candida parapsilosis"],"correctIndex":3,"explanation":"Ans. d. Candida parapsilosis\"C. parapsilosis infections are esptecially associated with hyperalimentation solutions, prosthetic devices, and indwellingcatheters, as well as the nosoeomial sprcad of disease throagh the hands of health care workers","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"178bda2c-c1fc-47dd-8d73-ef6e7ddf0d22","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('65e63beb113466f5c43d4fd76f2c679a','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"6d9630ba-dad1-4241-aac6-e09dd761a9c1","subjectId":"pediatrics","chapter":"اطفال","prompt":"Which of the following disorder of mother leads to microcephaly in baby –a) SLEb) Hepatitis A c) Phenylketonuriad) Rubella","options":["ab","cd","bd","ac"],"correctIndex":1,"explanation":"Microcephaly is defined as a head circumference that measures more than three standard deviation below the mean for age. Causes of microcephaly","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6d9630ba-dad1-4241-aac6-e09dd761a9c1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('6b5e9f06696fe290951c91356b94a9b7','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"bc6e7601-e544-4e20-ab7c-ad493a4aa325","subjectId":"pediatrics","chapter":"اطفال","prompt":"Short child with low T4 and raised TSH and swelling of pituitary, what is the diangosis ?","options":["Primary hypothyrodism","Pituitary tumor","TSH Secreting pituitary adenoma","TSH resistance"],"correctIndex":0,"explanation":"Normally, T4 and T3 exert negative feedback on TSH secretion by pituitary in two ways: Block the secretion of TSH by pituitary directly --> major action Block the secretion of TRH by hypothalamus (TRH stimulates the secretion of TSH by pituitary) In primary hypothyrodism, T4 and T3 are not produced or produced in low concentration by thyroid. This results in abolition of negative feedback on TSH secretion. Thus, there is elevated TSH and pituitary can become hyperplastic to produce more TSH. In pituitary cause of hypothyroidism (secondary hypothyroidism) both TSH and Thyroid hormone (T4, T3) are low as pituitary does not secrete TSH and TSH is the major stimulation for production of T4 and T3. About option d TSH resistance can also produce same picture i.e. raised TSH and low T4 with pituitary swelling. There is thyroid insensitivity to TSH which results in hypothyroidism (1T4 and T3). Because of reduced thyroid hormone feedback, TSH is markedly elevated. However, Amongst the given options best option is primary hypothyrodism because TSH resistance is a very rare condition and further T4 levels are normal in Mild and moderate (Partial) TSH resistance.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"bc6e7601-e544-4e20-ab7c-ad493a4aa325","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e9ef004fd9a51744931a15806a50ebea','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"03952f72-4223-48bc-a0df-51af60400a7a","subjectId":"pediatrics","chapter":"اطفال","prompt":"CASE -2 SR visit again but the condition is not improved but this time IV cannula was set. What drug should be given now?","options":["Midazolam","I/V Phenobarbital","Oral valproate","IV carbamazepine"],"correctIndex":1,"explanation":"Ans. In this case the First Line has failed . So for second line therapy I/V Phenobarbital is prefferedReference - <a href=\"","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"03952f72-4223-48bc-a0df-51af60400a7a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7992f330ca8185e41a234e9d4c3a887a','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"0aa56b89-1692-494c-b14f-f794ca9821ec","subjectId":"pediatrics","chapter":"اطفال","prompt":"A 1-month-old child presented with conjugated bilirubinemia and intrahepatic cholestasis. On Liver biopsy staining with PAS, red colored granules were seen inside the hepatocytes. Probable diagnosis is:","options":["Congenital hepatic fibrosis","Wilson''s disease","Alpha-1 antitrypsin deficiency","Hemochromatosis"],"correctIndex":2,"explanation":"Ans: C. Alpha-1 antitrypsin deficiency(Ref Harrison 19/e 367-e2; Nelson 20/e p2052; Robbins. 9/e p815)Most probable diagnosis = Alpha-I Antitrypsin deficiency.Alpha-I Antitrypsin deficiency:Diagnosis:Confirmed by blood tests.Reduced levels of serum AAT & accompanied by Pi determinations.Liver biopsy:Determines stage of hepatic fibrosis.Shows characteristic PAS-positive & diastase-resistant round- to-oval cytoplasmic globular inclusions inside hepatocytes of lobule periphery.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0aa56b89-1692-494c-b14f-f794ca9821ec","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('912c4ce491b07bb8962def35f6ed921a','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"ac195c22-e47e-49f9-87d5-87b26416ea05","subjectId":"pediatrics","chapter":"اطفال","prompt":"18 months old child, who has received one dose of DPT and OPV at 2 months of age. What will be your next immunization plan :","options":["Restart immunization schedule, as per age","Measles, BCG, booster dose of DPT and OPV","Measles, booster dose of DPT and OPV","BCG, 2ND dose of DPT and OPV"],"correctIndex":3,"explanation":"A lapse in the immunization schedule does not require reinitiation of entire vaccine series. Immunization should be given at the next visit in the usual doses assuming that the minimum interval has already elapsed and the imunization should be completed at the next available opportunity\". D.P.T. and oral polio vaccine which the child already had should be considered as the first dose. The child would need further 2 doses of this vaccine to complete the primary vaccination. Booster doses are administered, once the primary immunization is complete. Thus you cannot administer booster doses of D.P.T. and O.P.V. as their primary immunization is not complete.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ac195c22-e47e-49f9-87d5-87b26416ea05","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('bc2237a2a4e8afa34abfd6528c86beba','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"03486244-ec95-4253-81cf-8035e53ac651","subjectId":"pediatrics","chapter":"اطفال","prompt":"A 7–day old infant has a leaky meningomyelocele. The most useful test for diagnosis and management of the condition is –","options":["Blood–culture and sensitivity","Urine–culture and sensitivity","Rectal swab–culture and sensitivity","Wound swab–culture and sensitivity"],"correctIndex":0,"explanation":"Most cases of meningocele are recommended for treatment as soon after birth as possible. In the case of a sac which is leaking fluid, the treatment is most urgent. Generally, treatment includes a surgical procedure to close and remove the soft tissue covering of back. As there are chances of bacterial meningitis and sepsis due to CSF leak, CSF and blood sample should be send for culture and sensitivity and peri-operative antibiotics (broad spectrum) can be changed to the specific antibiotics after the blood and CCF culture and sensitivity report.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"03486244-ec95-4253-81cf-8035e53ac651","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f262d6817dc1b58f039758b16f368079','reference-medmcqa-preinternship-pediatrics-en-1','pediatrics','اطفال','medium','{"key":"350d3b19-c8b4-4e99-b2a0-dc3f2bf4a206","subjectId":"pediatrics","chapter":"اطفال","prompt":"Transient tachypnea of new born (TTN) is commonly seen in which of the following situations –","options":["Term delivery requiring forceps","Term requiring ventouse","Elective caesarean section","Normal vaginal delivery"],"correctIndex":2,"explanation":"In text books, both elective caesarian section and normal preterm or term vaginal delivery have been mentioned as risk factors for transient tachypnea of newborn. But the best answer is caesarian section - \"Delivery by caesarian section and gestational age are the risk factors for TTN\". —Articles Obs & Gynae Transient tachvpnea of Newborn (TTN) Transient tachypnea of the newborn is a benign self-limiting disease occuring usually in term neonates and is due to delayed clearance of lung fluid. It is also called respiratory distress syndrome type H TTN follows - Uneventful normal preterm or term vaginal delivery Cesarean delivery TTN is believed to be secondary to slow absorption of fetal lung fluid resulting in decreased pulmonary compliance and tidal volume and increased dead space therefore also known as wet lung. Clinical manifestations Early onset of tachypnea El Sometimes refraction or expiratory grunting u Occasionally cyanosis Patients usually recover rapidly within 3 days. Hypoxemia, hypercapnia and acidosis are uncommon.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"350d3b19-c8b4-4e99-b2a0-dc3f2bf4a206","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-medmcqa-preinternship-pharmacology-en-1','فارماکولوژی · منتخب MedMCQA','preinternship','reference','medmcqa',NULL,'منبع باز',1793577600000,0,'MedMCQA — Pal, Umapathi & Sankarasubbu, 2022. Validation split via Open Life Science AI; Apache-2.0. متن اصلی انگلیسی؛ آزمون رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('3ea60023292b744ea18fa0b5f7547b34','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"a3da135a-a6a2-4e1c-8823-8ab0913f5668","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"A patient presented to emergency with overdose some drug. There were increased salivation and increased bronchial secretions. On examination, blood pressure was 88/60 mmHg. RBC esterase level is 50. What should be the treatment of this person?","options":["Neostigmine","Atropine","Flumazenil","Physostigmine"],"correctIndex":1,"explanation":"Low esterase levels are suggestive of overdose of some drug which acts by inhibiting acetyl choline esterase like organophosphate poisoning. Inhibition of choline esterase results In increased amount of Ach at synapse, so poisoning or overdose results in cholinergic symptoms like salivation, lacrimation, urination, emesis, increased bronchial secretions, reduction in blood pressure.So treatment Of choice is Atropine. Atropine -It is highly effective in counter-acting the muscarinic symptoms, but higher doses are required to antagonize the central effects. It does not reverse peripheral muscular paralysis which is a nicotinic action. All cases of anti-ChE (carbamate or organophosphate) poisoning must be promptly given atropine2 mg i.v. repeated every 10 min till dryness of mouth or other signs of atropinization appear (upto 200 mg has been administered in a day). Continued treatment with maintenance doses may be required for 1-2 weeks. Neostigmine and physostigmine worsens the signs and symptoms as these also act by inhibiting choline esterase. Physostigmine and flumazenil are respectively used for Atropine and benzodiazepines poisoning.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a3da135a-a6a2-4e1c-8823-8ab0913f5668","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7ed8a8d806c72e942d8bceeb214502d9','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"a570d3c3-865a-41b6-8e21-dccbf7feec4c","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"A patient from,nqh-eastern states was diagnosed to have infection with P. falciparum malaria. What is the most appropriate drug for this patient?","options":["Aemether plus lumefantrine","Sulfadoxine plus pyrimethamine","Chloroquine","Mefloquine"],"correctIndex":0,"explanation":"Ans: A. Aemether plus lumefantrineRef: The ACT recommended in the National Program all over India except noheastern states is aesunate (AS) daily for3 days and Sulfadoxine-pyrimethamine (SP) on Day 0.Noheastern states presently recommended ACT in national drug policy is fixed dose combination of Aemether-lumefaritrine.Hence, the clear-cut answer of this question is Aemether plus lumefantrine.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a570d3c3-865a-41b6-8e21-dccbf7feec4c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('03060b62d27c22e42c55f2759b9f36f3','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"e7f023ea-2147-47d3-9f2a-61fb60a900be","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Which of these drugs is an antidote for fibrinolytic therapy?","options":["Epsilon aminocaproic acid","Protamine","Heparin","Streptokinase"],"correctIndex":0,"explanation":"Answer- A. Epsilon aminocaproic acidEpsilon aminocaproic acid is an antidote for fibrinolytic therapy. Epsilon-aminocaproic qcid is a synthetic inhibitor of theplasmin-plasminogen system. It is the only potent antifibrinolylic agent, which is commercially available.\"Aminocaproic acid is a lysine analog that competes for lysine binding sites on plasminogen and plasmin, blocking theinteraction of plasmin with fibrin.Fibrinolytic overdose - Epsilon Amino Caproic Acid (EACA)","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e7f023ea-2147-47d3-9f2a-61fb60a900be","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b7f505ee3c89993c1693511609fd9ea3','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"e881fcb0-a4f2-45ed-97cf-c53045f98e30","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Absorption of which of the following drugs is increased after a fatty meal?","options":["Amphotericin B","Griseofulvin","Ampicillin","Aspirin"],"correctIndex":1,"explanation":"Ans: B. Griseofulvin (Ref: Goodman Gilman I2/e p1585; Katzung 13/e p632, 12/e p855,. KUT 7/e p790, 6/e p760)The oral administration of a 0.5 g dose of griseofulvin produces peak plasma concentrations of 1ug/mL in 4 hours.Improved drug absorption along with a fatty meal.Drug Absorption Reduced/Delayed by FoodDrug Absorption increased by foodAmpicillindegAspirindegAtenololdegAzithromycindegCaptoprildegCefaclorCephalexinCiprofloxacinDidanosineIndinavirdegIsoniazidaLoratidineNaficillinPenicillin G or VdegPhenobarbitaldegPhenytoindegRifampindegSucralfatedegTetracyclinedegDoxycyclinedegAtovaquonedegCarbamazepinedegChlohiazidedegCefuroximedegClofaziminedegDiazepamdegErythromycin GanciclovirdegHydrochlorothiazidedegItraconazoleaLithiumdegLovastatinMethylphenidateMetoprololdegNelfinavirNitrofurantoinPropranololdegPropoxypheneRitonavirdegSaquinavirdegSpironolactonedeg*Hydralazinedeg","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e881fcb0-a4f2-45ed-97cf-c53045f98e30","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('347fb964270c82f45217a10b9c1abcff','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"da27e783-4c0b-4621-bc3d-938a109d8425","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Use of lithium during pregnancy increases the risk of development of which of the following malformations in the baby?","options":["Facial defects","Cardiac defects","Neural tube defects","Urogenital defects"],"correctIndex":1,"explanation":"Lithium causes Ebstein''s anomaly (malformation in tricuspid valve of hea) if given in pregnancy. Other side effects of lithium includes: Leucocytosis I Tremors (most common adverse effect) Hypothyroidism Increase Urine (polyuria) Mothers (avoided in pregnancy).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"da27e783-4c0b-4621-bc3d-938a109d8425","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('a5f068252e2fad4c2edce8deb1325e9a','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"2dd59aba-38c0-4aff-a000-1bcb640254ff","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Drug adveisement letter is a necessary component of each drug formulation and contains various information about the drug like drug dosing, frequency and half-life. Which of the following information need not be given in the drug adveisement letter?","options":["Research papers and other aicles proving efficacy of the drug","Date of expiry of the drug","Rare, but serious life threatening adverse-effects","Common, not so serious adverse-effects"],"correctIndex":1,"explanation":"Ans: B. Date of expiry of the drug(Ref Goodman Gilman 12/e p1883; Manual of Experimental and Clinical Pharmacology/p 345).Date of drug expiry need not to be given in drug adveisement letter.Regulated according to The Federal Food, Drug, and Cosmetic Act.Amended (Food and Drug Administration Modernization Act of 1997).Permits use of print & television adveising for prescription drugs.Drug adveisements:Contain summary information relating to side effects, contraindications & effectiveness.Current adveising regulations:Specify that this information disclosure needs to include all risk information in a product''s approved labeling or must direct consumers to healthcare professionals to obtain this information.Print adveisements:Include reprinting of risk-related sections of product''s approved labeling (package inse).Television adveising:Not includes reprinting of risk-related.Note:Adveisements cannot be false or misleading or omit material facts.Must present fair balance between effectiveness & risk information.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"2dd59aba-38c0-4aff-a000-1bcb640254ff","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('95863368646c0451443b64ba8249be5f','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"58ffad4a-5613-4d26-88b2-a4bb2ce2b9e6","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Which of the following drugs can be stopped abruptly without any withdrawal symptoms?","options":["Esctilaopram","Fluoxetine","Fluvoxamine","Seraline"],"correctIndex":1,"explanation":"Answer- B. FluoxetineFluoxetine has the lowest incidence of discontinuation syndrome among several antidepressants including paroxetin and venlafaxine. The longer half life of fluoxetine will avoid any withdrawal symptoms because this medication effectively tapers itself from the patient''s system over a few days.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"58ffad4a-5613-4d26-88b2-a4bb2ce2b9e6","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7e943965117a6edc3f28f1af3fd0054a','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"3e4d2174-1e88-4652-9aed-78e71215ffe8","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Vitamin D toxicity is treated with","options":["Chloroquine","Hydroxycholoquine","Dexamethasone","Ketoconazole"],"correctIndex":2,"explanation":"Ans. C. Dexamethasone* Dexamethasone is used in the treatment of hypercalcemia due to vitamin D toxicity. Glucocoicoid (Dexamethasone, prednisolone etc) therapy will decrease plasma calcium levels by blocking the action of vitamin D(1,25 D) which results in reduced intestinal calcium absorption and increased urinary excretion of calcium. * Other drugs like chloroquine and hydroxychloroquine are less effective in treating hypercalcemia due to vitamin D toxicity.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"3e4d2174-1e88-4652-9aed-78e71215ffe8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('67d055b7cbe993eb9359820476bc18fb','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"6bce210a-7174-4c76-b1f0-9bc3f5c835fc","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"CYP50 inhibition is least by:","options":["Pantoprazole","Rabeprazole","Lansoprazole","Omeprazole"],"correctIndex":1,"explanation":"Ans: B. Rabeprazole(Ref: Goodman Gilman 12/e p1990; Katzung131e p1060, 12/e p1089; KDT 7/e p653).Rabeprazole:Exclusively metabolized by CYP2C19 and does not cause any inhibition of CYP450.Highest efficacy.Lansoprazole - Most potent.Rabeprazole & pantoprazole have no significant drug interactions.The FDA has issued a warning about a potentially impoant adverse interaction between clopidogrel and proton pump inhibitors.Proton pump inhibitors should be prescribed to patients taking clopidogrel only if they have an increased risk of gastrointestinal bleeding or require them for chronic gastro-esophageal reflux or peptic ulcer disease, in which case agents with minimal CYP2C19 inhibition (pantoprazole or rabeprazole) are preferred","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6bce210a-7174-4c76-b1f0-9bc3f5c835fc","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('0e9a9a56391682a935022f40b257a5e5','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"3b150083-1a5e-49ef-bc36-41a06b677b32","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Major aim of phase 1 clinical trials is:","options":["Safety","Efficacy","Dose","Pharmacokinetics"],"correctIndex":2,"explanation":"Phase 1 clinical trial : It is first phase in humans. It is conducted mainly on healthy volunteers. In drugs with serious adverse effects and where alternative treatment is not available, phase 1 can be conducted on patients also. Major aim is to know the maximum tolerable dose (MTD). The aim of phase 1 trials should be marked as MTD > Dose > Pharmacokinetics > Safety","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"3b150083-1a5e-49ef-bc36-41a06b677b32","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('42622d57914e995daec01a98f1eb9e45','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"e7278113-c555-4128-a8df-cbd10ca7833f","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"A patient is administered 200 mg of a drug. 75 mg of the drug is eliminated from the body in 90 minutes. If the drug follows first order kinetics, how much drug will remain after 6 hours?","options":["12.5 mg","25 mg","30 mg","50 mg"],"correctIndex":2,"explanation":"Answer- C. 30 mgDrug remains in the body at the end of 4th 90 minutes (6 hours) : 48.7 -18.3 = 30.4 (Approx. 30 mg)","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e7278113-c555-4128-a8df-cbd10ca7833f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('613b83171d9a71f9196a1bb74c551956','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"100d2a31-8f28-4500-99c9-67690fe15625","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Ganglionic transmission is mediated by:","options":["Presynaptic alpha-receptors","Postsynaptic beta-receptors","Postsynaptic dopaminergic receptors","Postsynaptic nicotinic receptors"],"correctIndex":3,"explanation":"Ans: D .Postsynaptic nicotinic receptors(Ref: Goodman Gilman 13/e p108, 12Ie p255; Katzung 13Ie p108, 12/e p98).Ganglionic transmission is mediated by nicotinic receptors present post-synaptically.Nicotinic acetylcholine (ACh) receptor mediates neurotransmission post-synaptically at the neuromuscular junction and peripheral autonomic ganglia.In CNS, controls release of neurotransmitters from presynaptic sites.The receptor is called the nicotinic acetylcholine receptor - Due to both alkaloid nicotine & neurotransmitter ACh can stimulate the receptor.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"100d2a31-8f28-4500-99c9-67690fe15625","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2b7502f6e2056fac7ff28d8d2af44014','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"59ade17d-2139-4c4b-b0b5-ec6d6cf3c073","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Propranolol is drug of choice for -","options":["Ulcerated infantile hemangioma","Lymphangioma","Pyogenic granuloma","Capillary malformation"],"correctIndex":0,"explanation":"Ans. A. Ulcerated infantile hemangiomaRef: Ulceration--the most frequent complication of IH--tends to heal poorly and is associated with pain, bleeding, infection, and scarring.Mainstay treatment modalities include propranolol (b-blocker) and coicosteroids, whose effectiveness is countered by a need for long-term medication and risk of systemic adverse effects and ulcer recurrence.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"59ade17d-2139-4c4b-b0b5-ec6d6cf3c073","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('92d24637038144846353827a8be6e0d0','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"1f93c541-baaf-40f2-bf91-31be29732da2","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Treatment of choice for anaphylactic shock is:","options":["Adrenaline 0.5 mL of 1:1000 solution by intramuscular route","Adrenaline 1 mL of 1:10000 by intravenous route","Atropine 3 mg intravenously","Adenosine 12 mg intravenously"],"correctIndex":0,"explanation":"DOC is adrenaline.Route is intramuscular > subcutaneous.Dose: 0.5 ml of 1:1000(1mg/ml solution).This dose is repeated once gain within 10 minutes.If it''s still not improving; then intravenous 1:10,000 dose is given.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"1f93c541-baaf-40f2-bf91-31be29732da2","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('bfa5f2fb00c24e8d1e4b0c23dfa1091a','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"b8621196-05ba-414e-a112-0b48be3fcd7c","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Which of the following diuretic can be given in mild to moderate hypeension?","options":["Potassium sparing diuretic","Osmotic diuretic","Thiazide diuretic","Loop diuretic"],"correctIndex":2,"explanation":"Ans: C. Thiazide diureticThiazide diuretics :Given in mild to moderate hypeension.Low-dose thiazide diuretics used alone or in combination with other antihypeensive drugs.Safe, efficacious, inexpensive & reduce clinical events. MOA:Inhibits Na/Cl- pump in DCT a Increases sodium excretion.In long term - Acts as vasodilators.Provide additive blood pressure-lowering effects (On combination with beta blockers, ACE-I, ARBs).Drug of Choicein HypeensionConditionDrug of ChoiceHypeensionThiazidesHypeension with BPHPrazosinHypeension with diabetes mellitusACE inhibitorsHypeension with ischemic hea disease (angina)Beta-blockersHypeension with chronic kidney diseaseACE inhibitorsHypeension in pregnancyAlpha-methyldopaHypeensive emergenciesNicardipine + EsmololHypeensive emergencies in cheese reactionPhentolamineHypeensive emergencies in clonidine withdrawalPhentolamineHypeensive emergencies in aoic dissectionNitroprusside + EsmololHypeensive emergencies in pregnancyLabetalol(Ref: Harrison 19/e p1623).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b8621196-05ba-414e-a112-0b48be3fcd7c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e2d9b102adf5941d10d5c328c97b0710','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"c3b4d610-571b-4e86-be27-d41b8b2efc65","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Major determinant of loading dose of a drug is","options":["Half life","Clearance","Volume of distribution","Bioavailability"],"correctIndex":2,"explanation":"LOADING DOSE = Vd * target plasma concentration MAINTENANCE DOSE = Clearance * target plasma concentration","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c3b4d610-571b-4e86-be27-d41b8b2efc65","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5e9cd2532c8b49ce405da21cde1e1e56','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"28b7a6ea-c657-4da7-81dc-88457a064655","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Which of the following is not used in osteoporosis?","options":["Milnacipran","PTH","Strontium ranelate","Denosumab"],"correctIndex":0,"explanation":"Ans: A. Milnacipran(Ref. Goodman Gilman 12/e p1299; Katzung 13/e p761-762, 12/e p775; Harrison 19/e p2493, 18/c'' p3120; Apley 9/e p /3 I-133)Milnacipran:Serotonin-norepinephrine reuptake inhibitor (SNRI).Approved for treatment of pain in fibromyalgia, not in osteoporosis.Drugs useful in OsteoporosisInhibit Bone ResorptionStimulates Bone Both actionBisphosphonates: Alendronate, risedronate & etidronateCalcium receptor agonist: CinacalcetCalcitoninSERMs: Tamoxifen, raloxifeneGallium nitrateRANKL inhibitors: DonesumabTeriparatideCalciumCalcitriolFluorideStrontium ranelate","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"28b7a6ea-c657-4da7-81dc-88457a064655","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('35ad4e9a450d859d6bf5c309fd912bfd','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"a30f9a2b-52f0-4880-980d-d56de2a88910","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Among the following propeies of dopamine, which of them is not helpful in acute shock?","options":["Alpha-1 agonist action leading to peripheral vasoconstriction","Increase in renal perfusion due to agonist action on DI receptors","Releases noradrenaline and causes positive inotropic effect","Direct action on hea beta-1 receptors"],"correctIndex":1,"explanation":"Ans: B. Increase in renal perfusion due to agonist action on DI receptors(Ref: Goodman Gilman 13Ie p1062, 12/e p355; KDT 71e p134, 6Ie p507)Dopamine at low concentrations (2 to 5 mug/kg per minute) primarily acts on vascular D, receptors, especially in the renal, mesenteric, and coronary beds.Increased renal perfusion caused by dopamine due to DI agonism (at low doses) doesn''t improves survival in acute shock.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a30f9a2b-52f0-4880-980d-d56de2a88910","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('c1412ee70aeda1a825a1962d70fc741b','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"5aeb3b7a-9012-4472-a233-740ba0f1dac5","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Which of the following disease modifying anti-rheumatoid drugs acts by increasing extracellular adenosine?","options":["Leflunomide","Hydroxychloroquine","Azathioprine","Methotrexate"],"correctIndex":3,"explanation":"Answer-D. Methotrexate\"Methotrexate is the DMARD of choicefor the treatment of RA and is the anchor drug for most combination therapies.At the dosages ased for lhe treatment of RA, methotrexale has been shown to stimulate adenosine release from cells, producing an anti-inflammatory effect.Methotrexate (MTX) is a folic acid analog that binds with high affinity to the active catalytic site of dihydrofolate reductase (DHFR).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"5aeb3b7a-9012-4472-a233-740ba0f1dac5","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('401139ab1346bce51faf0b16e5eb7dc1','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"5fecb77f-66cc-4650-8201-3759bda2a213","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"A drug X was given continuous intravenous infusion at 1.6 mg/min. The clearance of the drug is 640 mL/min. With a half-life of 1.8 hours, what would be the steady state plasma concentration of drug?","options":["0.002 mg/mL","0.004 trig/mL","2.88 mg/mL","3.55 mg/mL"],"correctIndex":0,"explanation":"Answer- A. 0.002 mg/mLCpss is directly propoional to the dose rate & inversely propoional to the clearance of drug.Cpss = Dose rate/clearanceDose rate= 1.6 mgiml; Clearance= 640 ml/minCpss = 1.61640 = 0.0025 mg/ml = 0.002 mg/ml","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"5fecb77f-66cc-4650-8201-3759bda2a213","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('4674d66e13d9f8e1cfa69dbd56459c18','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"2b110e57-8338-4189-86e2-cbea7d761c30","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"A diabetic patient presented with uncontrolled blood sugar level. He has history of pancreatitis and family history of urinary bladder carcinoma. He does not want to take injectable drugs. Which of the following drug can be added to control his blood sugar?","options":["Liraglutide","Sitagliptin","Canagliflozin","Pioglitazone"],"correctIndex":2,"explanation":"Linaglutide(-ide) is a peptide, so not given orally. It is a GLP 1(incretin) analogue and it can cause pancreatitis.Sitagliptin is a DPP 4(dipeptidyl peptidase 4) inhibitor; can cause pancreatitis.Pioglitazone(PPAR- gamma agonist) can cause urinary bladder carcinoma; so can''t be given.So, canagliflozin (SGLT 2 inhibitor) can be added.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"2b110e57-8338-4189-86e2-cbea7d761c30","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('80de089bd879c33a1a41c682b222921e','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"8788091c-a8ef-4155-a7a3-8e85d643f856","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"A patient presented with acute exacerbation of bronchial asthma. Salbutamol inhalation didn''t improve the condition of the patient. So, intravenous coicosteroids and aminophylline were added and the condition improved. What is the mechanism of action of coicosteroids in this condition?","options":["They cause bronchodilatation when given with xanthines","They increase bronchial responsiveness to salbutamol","They increase the action of aminophylline on adenosine receptors","They increase the mucociliary clearance"],"correctIndex":1,"explanation":"Ans. b. They increase bronchial responsiveness to salbutamol Coicosteroids has a dual effect in acute asthma with an early facilitator effect on airway beta-2 adrenoreceptor sensitivity and a later effect on airway inflammation, which fuher emphasizes the need fir coicosteroids to he administered as early as possible during an acute asthma attack.\"he molecular mechanism of action of coicosteroids involves several effects on the inflammatory process. The major effect of coicosteroids is to switch off the transcription of multiple activated genes that encode inflammatory proteins such as cytokines, chemokines, adhesion molecules, and inflammatory enzymes. This effect involves several mechanisms, including inhibition of the transcription factor NF-KB, but an impoant mechanism is recruitment of HDAC2 to the inflammatory gene complex, which reverses the histone acetylation associated with increased gene transcription. Coicosteroids also activate anti-inflammatory genes, such as mitogen-activated protein (MAP) kinase phosphatase-1, and increase the expression of IQ-receptors. Most of the metabolic and endocrine side effects of coicosteroids are also mediated through transcriptional activation.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"8788091c-a8ef-4155-a7a3-8e85d643f856","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('4dbee78770087e81306fb1be67d5a045','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"d42801fb-0724-4137-b72a-3eb0d50fc9f1","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Which of the following is a schedule X drug?","options":["Thalidomide","Colistin","Ketamine","Halothane"],"correctIndex":2,"explanation":"Ans. C. Ketamine* The following are the Schedule X drugs mentioned in the Drugs and Cosmetics Rules 1945: Amobarbital, Amphetamine, Barbital, Cyclobarbital, Dexamphetamine, Ethchlorvynol, Glutethimide, Meprobamate, Methamphetamine, Methylphenidate, Methylphenobarbital, Phencyclidine, Phenmetrazine, Secobarbital.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d42801fb-0724-4137-b72a-3eb0d50fc9f1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('6c85d97edd7fd17d640dcee3792fd03b','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"17ca6005-346f-4f14-b1a3-430d3667d7f0","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Black deposits on conjunctiva in a patient with glaucoma are seen with the use of:","options":["Prostaglandins","Carbonic anhydrase inhibitors","Epinephrine","Beta blocker"],"correctIndex":2,"explanation":"Ans: C. Epinephrine(Ref: Goodman Gilman 12/e p286, 326; Katzung 13/e p161, 12/e p160; The Cornea by Smolin and Thoft''s/p504)Black deposits on conjunctiva in a patient with glaucoma are seen with use of epinephrine. Latanoprost is associated with iris hyperpigmentation.Epinephrine is unstable in alkaline solution; when exposed to air or light, it turns pink from oxidation to adrenochrome and then brown from formation of polymers.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"17ca6005-346f-4f14-b1a3-430d3667d7f0","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('895ff6e104f54332c4c89b6b3aca7982','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"524d41bf-ef51-49b4-8662-dcaf2c2798fb","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"A diabetic and hypeensive patient taking several drugs presented with septicemia. Serum creatinine levels are 5.7 mg/dL. Which of the following drug should be stopped?","options":["Insulin","Metoprolol","Linagliptin","Metformin"],"correctIndex":3,"explanation":"Serum creatinine levels are raised indicating renal failure. In renal failure and hepatic failure --> Metformin is C/I as it |ses the risk of developing lactic acidosis. Contraindicated in patients with an eGFR below 30 mL/minute/1.73 m2. eGFR should be measured annually for patients taking metformin therapy. eGFR is preferred over serum creatinine concentration to assess renal function for a person taking metformin therapy Linagliptin is a DPP-4 inhibitor. Metoprolol is a b blocker.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"524d41bf-ef51-49b4-8662-dcaf2c2798fb","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('4d2ea134d00f2dbdf3aabe2fabdef3d1','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"c2966f39-a3e7-464d-9048-937bf330c794","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Antimalarial drug used for causal prophylaxis act at which stage of developmental cycle","options":["Gametogony","Erythrocytic schizogony","Pre-erythrocytic schizogony","Exo-erythrocytic schizogony"],"correctIndex":2,"explanation":"Ans. C. Pre-erythrocytic schizogonyPre-erythrocytic schizogony* Occurs inside the parenchymal cells of liver.* Merozoites are liberated into blood.* Drugs acting on this stage will prevent infection of RBC and clinical attack of malaria causal prophylaxis.* Drugs are* Proguanil & Tetracycline - for falciparum.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c2966f39-a3e7-464d-9048-937bf330c794","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('c5044755a272ada6b86d5523d4fb09ac','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"407d4eec-cf0b-460c-bcdb-cf0081ec8c5d","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Methacholine acts at which receptor?","options":["M1","M2","M3","M4"],"correctIndex":1,"explanation":"Ans: B. M2Methacholine is an M2 receptor agonist.ParameterM1M2M3Agonists (Relatively selective)Oxotremorine, MCN-343AMethacholineBethanecholAntagonists (Relatively selective)Pirenzepine, TelenzepineMethoctramine, TripitramineDarifenacin, Solifenacin","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"407d4eec-cf0b-460c-bcdb-cf0081ec8c5d","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('8083d626ae5a418691cfed5912b08b52','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"0ba46472-54a7-4bb9-9802-a0546e24cede","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"A bank employee felt depressed with no interest in activities came to AIIMS OPD. He was staed on Escitalopram. Which of these adverse effects cannot be explained with escitalopram?","options":["Vivid dreaming","Anorgasmia","Sialorrhea","Nausea"],"correctIndex":2,"explanation":"Ans. C. SialorrheaEscitalopram belongs to a class of drugs known as selective serotonin reuptake inhibitors (SSRI).Improves your energy levels and feelings of well-being and decrease nervousness.Used to treat depression and anxiety.MOA: Works by helping to restore the serotonin balance in the brain.S/E:Headache, Nausea, Ejaculation disorder, Somnolence, Insomnia, Dry mouth, Constipation, Fatigue, Libido decreased, Inability to achieve orgasm, Gas (flatulence), Toothache, Weight gain, Menstrual disorder, Neck/shoulder pain, Runny nose & Flu-like syndrome.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0ba46472-54a7-4bb9-9802-a0546e24cede","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9e152e6605b2986653f05e3dc4c4101f','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"4127528f-2cc3-44bc-b07e-446577f5018c","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"What is the dose of adrenaline in anaphylactic shock?","options":["0.5 ml in 1:1000","0.5 ml in 1:10000","1 ml in 1:1000","1.5 ml in 1:1000"],"correctIndex":0,"explanation":"Ans. A. 0.5 ml in 1:1000Severe hypersensitivity reactions, anaphylactic shockIM Injection:* Adults: The usual dose is 500 micrograms (0.5ml of adrenaline 1/1000). If necessary, this dose may be repeated several times at 5-minute intervals according to blood pressure, pulse and respiratory function.* Half doses of adrenaline may be safer for patients who are taking amitriptyline, imipramine or a beta blocker.Paediatric population:* The following doses of adrenaline 1/1,000 are recommended:AgeDoseOver 12 years0.5 mg IM (0.5ml 1:1000 solution)6 - 12 years0.3 mg IM (0.3ml 1:1000 solution)6 months - 6 years0.15 mg IM (0.15ml 1:1000 solution)Under 6 months0.01mg/kg IM (0.01ml/kg 1:1000 solution)* If necessary, these doses may be repeated at 5-15 -minute intervals according to blood pressure, pulse and respiratory function.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4127528f-2cc3-44bc-b07e-446577f5018c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('a81babf8ec55445d52e83a1655911bdb','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"416729b9-8f0b-45d1-aa27-6674dacb9975","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"At low infusion rates of 3-5 mcg/kg/min, what action is produced by dopamine?","options":["Vasoconstriction","Increased renal blood flow","Increased cardiac contractility","Decreased blood pressure"],"correctIndex":1,"explanation":"Ans: B. Increased renal blood flow(Ref: Goodman Gilman 12/e p355; KDT 7/e p134. 6/e p507)Action of dopamine:At low concentrations (2 to 5 mcg/kg per minute):Primarily acts on vascular D1 receptors.Mainly renal, mesenteric & coronary beds.By activating adenylyl cyclase a raising intracellular cyclic AMP concentrations.D1 receptor stimulation a Vasodilation.Increases in glomerular filtration rate, renal blood flow & Nat+ K+ - ATPase pump.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"416729b9-8f0b-45d1-aa27-6674dacb9975","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d1d197e10d6af06acaef44ef3215c76d','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"07c14e46-ad2b-4fde-8652-bd47b36e69ab","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Vasopressin antagonist acts on which pa of the nephron?","options":["Proximal convoluted tubule","Distal convoluted tubule","Coical collecting tubule","Medullary collecting duct"],"correctIndex":3,"explanation":"Answer- D (Medullary collecting duct)''The mechanism by which vasopressin exes its anti-diuretic effect is activated by V2 receptors and involves the inseion of aquaporin-2 into the apical (luminal) membranes at the principle cells of the collecting duct.''","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"07c14e46-ad2b-4fde-8652-bd47b36e69ab","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('916deb233ce83eef73bccdc854903b6a','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"604ef1a2-7595-4718-9f8c-12292063e19f","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Which of the following anti-tubercular drug can cause ophthalmological toxicity?","options":["Isoniazid","Rifampicin","Ethambutol","Pyrazinamide"],"correctIndex":2,"explanation":"Ethambutol side effect: causes Red Green color blindness (Ophthalmological toxicity) Isoniazid side effects: Neurotoxicity, Hepatotoxicity. Pyrazinamide side effects: Hyperuricemia (gouty ahritis). Rifampicin side effects: Hepatotoxicity, orange red urine and tears etc.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"604ef1a2-7595-4718-9f8c-12292063e19f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('0bdf7ab2b14cce5939a38e22ef7ca82f','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"7a3a771f-2b56-4af8-b967-3c991b394bc6","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Compared to unfractionated heparin, Low molecular weight heparin (LMWH) has reliable anticoagulant action because:","options":["It interferes with thrombin and antithrombin III simultaneously","It is less protein bound","It is given subcutaneously","It is cleared by macrophages"],"correctIndex":1,"explanation":"Answer- B. It is less protein boundCompared to unfractionated heparin, Low molecular weight heparin (LMWH) has reliable anticoagulant action because it is less protein bound.Indications of LMW heparins:Prophylaxis of DVT and pulmonary embolism in high-risk patients undergoing surgery stroke or other immobilized patientsTreatment of established DVTUnstable anginaTo maintain patency of cannulae and shunts in dialysis patients and in extracorporeal circulation.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"7a3a771f-2b56-4af8-b967-3c991b394bc6","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d5b7fc4be076b7689dc7e21248f09020','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"49b456da-591f-4221-b56b-9a04eaa21b77","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"There was an outbreak of MRSA in the hospital and it was found that a nurse of NICU had MRSA colonisation of anterior nares. What is the best treatment?","options":["Topical bacitracin","Oral Vancomycin","Inhaled colistin","IV cefazolin"],"correctIndex":0,"explanation":"Ans. A. Topical bacitracinMRSA (methicillin-resistant Staphylococcus aureus) infection is a life-threatening bacterial infection caused by Staphylococcus aureus that is resistant to the antibiotic methicillin. Severe cases usually require hospitalization for treatment.MRSA infections are usually treated with systemic antibiotics, either orally or intravenously.Topical bacitracin in combination with neomycin and polymyxin B might be added to the therapy.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"49b456da-591f-4221-b56b-9a04eaa21b77","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b66590cb44077eedfbc678d6768f8896','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"a97ea051-7425-4f6f-b909-c32f3801a91f","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"G-protein coupled receptor that does not act through opening of potassium channels is","options":["Muscarinic M2 receptor","Dopamine D2 receptor","Serotonin 5 HT 1 receptor","Angiotensin 1 receptor"],"correctIndex":3,"explanation":"* DGPCR which act through opening of K+ channels lead to hyper polarisation, thus leading to inhibition.So, receptor which causes stimulation will not act through opening of K+ channels. o Muscarinic M2 receptor, Dopamine D2 receptor and serotonin 5HT1 receptor act through opening of K+ channels.o Whereas Angiotensin 1 receptor act by increasing Ca+2.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a97ea051-7425-4f6f-b909-c32f3801a91f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('731db65f5e3e549033bcaa5eeb6b0d4e','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"380d5a44-a18e-4bdf-90be-c812b1ff3885","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Prolonged administration of streptomycin may result in damage to the:","options":["Optic nerve","Facial nerve","Auditory nerve","Trigeminal nerve"],"correctIndex":2,"explanation":"Streptomycin (antitubercular) causes vestibular damage on prolonged use. Adverse effects This class of drugs is notorious for their adverse effects like ototoxicity and nephrotoxicity. About 1/5th patients given streptomycin 1 gm BD i.m. experience vestibular disturbances although auditory disturbances are less common. Streptomycin has the lowest nephrotoxicity among aminoglycosides; probably because it is not concentrated in the renal cortex. Reference: Essentials of Medical Pharmacology Eighth Edition KD TRIPATHI page no 94,798","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"380d5a44-a18e-4bdf-90be-c812b1ff3885","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('32799156b9bf785ffe4bfb65d4b0ad19','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"6e3b014e-fe90-47f0-8e12-e176a809198f","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Which of the following drugs can be given in renal failure safely?","options":["Saxagliptin","Linagliptin","Vildagliptin","Sitagliptin"],"correctIndex":1,"explanation":"Ans: B. Linagliptin(Ref Goodman Gilman 12/e p1264; Katzung 13/e p740, 12/e p761; FDA website: http://wwwfda.gov/ Safety/ MedWatch/Safetylnformation/ircm3 I 9215.htm)Linagliptin:Given safely in renal failure.Chronic kidney disease:Major complication in type 2 diabetes.Metformin usage is challenging.More severe renal disease - Less likely for metformin use.Due to safety concerns.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6e3b014e-fe90-47f0-8e12-e176a809198f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('96c479e3baa12e3ec99d8709c528c03b','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"8efe2632-49e7-4558-b438-a44fadccdd03","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Digoxin is obtained from a plant product and has a half-life of 36 hours. How does this information help us in formulating treatment?","options":["To adjust maintenance dose of digoxin required to keep the blood levels within therapeutic range","Intravenous administration in emergency and urgent dosing","Long half-life permits altemate day dosing","It requires a high loading dose to be administered"],"correctIndex":0,"explanation":"Ans: A. To adjust maintenance dose of digoxin required to keep the blood levels within therapeutic range(Ref Goodman Gilman 12/e p33. 37: KDT 7/e p31, 515)Half- life of drug:Determines the maintenance dose of digoxin.Helps maintain therapeutic plasma levels.Maintenance dose also determined by creatinine clearance.Half-life of dioxin:36 to 48 hrs in patients with normal renal function.3.5 to 5 days in anuric patients.In patients with normal renal function, an oral daily maintenance dose without loading dose - steady-state blood concentration in approximately 7 days.Hence daily maintenance dose decided based on half-life ofthe drug.Usual digoxin therapeutic serum concentrations range - 0.8 to 2 ng/mL.(Note: Loading dose governed by volume of distribution).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"8efe2632-49e7-4558-b438-a44fadccdd03","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('a9d041af87086333ed08a7d1f5123533','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"5419a97a-9132-4f87-9bb5-3ca06dd47507","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Which of the following cause an increase in ACh release from the presynaptic neuron?","options":["Blocking calcium channels on presynaptic","Blocking chloride channel on presynaptic","Blocking Na channel","Blocking K channels"],"correctIndex":3,"explanation":"Ans. D. Blocking K channels* Potassium channel blocker will cause an increase in ACh release from the presynaptic neuron.* Blockade of presynaptic potassium channels promotes activation of voltage-gated calcium channels leading to the increased release of acetylcholine in the neuromuscular junction. Aminopyridines used in the treatment of Lambe-Eaton myasthenic syndrome acts by this mechanism and improves the muscle strength in the patients","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"5419a97a-9132-4f87-9bb5-3ca06dd47507","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1dc2e59a4d614c65bd6c21cc75caee72','reference-medmcqa-preinternship-pharmacology-en-1','pharmacology','فارماکولوژی','medium','{"key":"8b2bc220-f5f6-4651-89b7-c38432303837","subjectId":"pharmacology","chapter":"فارماکولوژی","prompt":"Latest drug reccntly approved for Amyotrophic Lateral sclerosis is?","options":["Piracetam","Ceftriaxone","Edaravone","Doxycycline"],"correctIndex":2,"explanation":"Ans: C. EdaravoneRef href=\"https://www/\">https://www.br ai ntrop ic. c om/noo t rop ics/p i rac etam/Edaravone is a novel neuroprotective agent for the treatment of amyotrophic lateral sclerosis (ALS)","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"8b2bc220-f5f6-4651-89b7-c38432303837","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-medmcqa-preinternship-psychiatry-en-1','روان‌پزشکی · منتخب MedMCQA','preinternship','reference','medmcqa',NULL,'منبع باز',1793577600000,0,'MedMCQA — Pal, Umapathi & Sankarasubbu, 2022. Validation split via Open Life Science AI; Apache-2.0. متن اصلی انگلیسی؛ آزمون رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('d646920e90390763bb8899aa0aed3b30','reference-medmcqa-preinternship-psychiatry-en-1','psychiatry','روان‌پزشکی','medium','{"key":"36eda6ec-6654-41ba-937b-60a3052e6c49","subjectId":"psychiatry","chapter":"روان‌پزشکی","prompt":"A patient believes he is the most impoant person in the world than anyone so his neighbors and family is trying to harm him as they are jealous of him. His wife says otherwise and says he behaves like this recently only before he was working as a school-teacher peacefully and brought to OPD. He is suffering from:","options":["Delusion of grandiosity","Delusion of persecution","Delusion of grandiosity and persecution","Delusion of grandiosity, persecution and reference"],"correctIndex":3,"explanation":"Ans. d. Delusion of grandiosity, persecution and reference The given description suggests that the patient is having delusion of grandiosity, persecution and reference.Delusion of grandeurExaggerated conception of one''s impoance, power, or identity.Delusion of persecutionFalse belief of being harassed or persecuted; often found in litigious patients who have a pathological tendency to take legal action because of imagined mistreatment.MC delusion.Delusion of referenceFalse belief that behavior of others refers to oneself or that events, objects, or other people have a paicular & unusual significance, usually of a negative natureDerived from idea of reference, in which persons falsely feel that others are talking about them (e.g., belief that people on television or radio are talking to or about the person).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"36eda6ec-6654-41ba-937b-60a3052e6c49","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('eb80c2ce1ec0963cb21d09e64dd0a1af','reference-medmcqa-preinternship-psychiatry-en-1','psychiatry','روان‌پزشکی','medium','{"key":"7c9b4d7b-6290-430f-a097-96d88c65ecd8","subjectId":"psychiatry","chapter":"روان‌پزشکی","prompt":"Z tracking technique is used in?","options":["Administering long acting antipsychotic","Lithium monitoring","Carbamazepine monitoring","Nicotine patch"],"correctIndex":0,"explanation":"Z track technique Used for giving i.m. injections. In this technique, the skin and tissue are pulled and held firmly while injection is given, and after removing the needle, skin and tissue are released. This prevents tracking (leakage) of the medication into the subcutaneous tissue (underneath the skin) as the track that needle forms is zig zag and drug can''t come out.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"7c9b4d7b-6290-430f-a097-96d88c65ecd8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('37e67dba52f5c1ca42f3829164ea6a39','reference-medmcqa-preinternship-psychiatry-en-1','psychiatry','روان‌پزشکی','medium','{"key":"2d98e8a0-829a-47ef-87e1-c6bbd54473a1","subjectId":"psychiatry","chapter":"روان‌پزشکی","prompt":"Which of the following is not an adverse effect of Escitalopram?","options":["Nausea","Vivid dreams","Anorgasmia","Sialorrhoea"],"correctIndex":3,"explanation":"Adverse effects of SSRI''s MC: GI side effects- Nausea, Vomiting Dyspepsia, Diarrhea Sexual side effects- Decreased libido, Anorgasmia, Delayed ejaculation Increased sweating Decreased platelet aggregation Vivid dreams Sialorrhea is a very common side effect of Clozapine.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"2d98e8a0-829a-47ef-87e1-c6bbd54473a1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('c9a9ec8284fca27fdef31a69fffe1ee7','reference-medmcqa-preinternship-psychiatry-en-1','psychiatry','روان‌پزشکی','medium','{"key":"97648c60-2ed9-4c8e-9142-48806639731a","subjectId":"psychiatry","chapter":"روان‌پزشکی","prompt":"Most common complication of ECT is -","options":["Antegrade amnesia","Retrograde amnesia","Psychosis","Depression"],"correctIndex":1,"explanation":"Amnesia is the most common side effect of ECT. Both retrograde and anterograde amnesia are seen, however retrograde amnesia is much more common.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"97648c60-2ed9-4c8e-9142-48806639731a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('466bc6bd47bc6d1940e1372c70691adb','reference-medmcqa-preinternship-psychiatry-en-1','psychiatry','روان‌پزشکی','medium','{"key":"b22457e3-c620-4a3d-bde1-0aa6e6c185a7","subjectId":"psychiatry","chapter":"روان‌پزشکی","prompt":"A person with histrionic, shy, anxious avoidant per!sonality comes under which cluster?","options":["A","B","C","D"],"correctIndex":2,"explanation":"Ans: C. C(Ref Niraj Ahuja 7/e p113)ClusterDisordersCluster A (Odd and eccentric)Paranoid PDSchizoid PDSchizotypal PDCluster B (Dramatic, emotional and Antisocial PDHistrionic PDNarcissistic PDBorderline PDCluster C (Anxious and fearful)Anxious (avoidant) PDDependent PDAnankastic (Obsessive and compulsive) PD","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b22457e3-c620-4a3d-bde1-0aa6e6c185a7","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('c8e10285570c43eea48928160bab6ede','reference-medmcqa-preinternship-psychiatry-en-1','psychiatry','روان‌پزشکی','medium','{"key":"af75fc76-911b-48da-9ca0-75a8c912c18b","subjectId":"psychiatry","chapter":"روان‌پزشکی","prompt":"SPIKES protocol is used for:","options":["Triage","Communication with patients/attendants regarding bad news","Writing death ceificate","RCT"],"correctIndex":1,"explanation":"It''s a protocol for breaking the bad news to patients about their illness Involved six steps S-setting up to the interview P- perception (what patient knows about his condition) I- invitation (finding out how much patient want to know) K- knowledge and information (diagnosis and treatment) E -addressing patients'' emotion (how patient feel and respond) S- strategy and summary","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"af75fc76-911b-48da-9ca0-75a8c912c18b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7f636a91edc691249eea4d0f99bb7540','reference-medmcqa-preinternship-psychiatry-en-1','psychiatry','روان‌پزشکی','medium','{"key":"5a2f9e25-3acb-4830-9f18-009480595be1","subjectId":"psychiatry","chapter":"روان‌پزشکی","prompt":"Not a side effect of Escitalopram?","options":["Nausea","Vivid dreams","Anorgasmia","Sialorrhoea"],"correctIndex":3,"explanation":"Side effects of Escitalopram GI side effects: MC Vivid Dreams Sexual dysfunction on long term intake Sialorrhea is a side effect of clozapine","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"5a2f9e25-3acb-4830-9f18-009480595be1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2a53b7f478de15b26a54add5205748a4','reference-medmcqa-preinternship-psychiatry-en-1','psychiatry','روان‌پزشکی','medium','{"key":"c757d1c6-e17b-4b88-baa3-38720c1dd5eb","subjectId":"psychiatry","chapter":"روان‌پزشکی","prompt":"Which of the following best describes paradoxical suicide?","options":["Suicide after taking low dose of drug","Suicide occurring at the time when the pt. stas to recover","Suicidal tendency increase as the patient improves","Accidental completion of suicide"],"correctIndex":1,"explanation":"Paradoxical suicide Occurs after the patient''s improvement from a depression episode. Despite having suicidal thoughts there is no action taken on those thoughts but after taking medication the patient acts on it. Also seen in patients with schizophrenia.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c757d1c6-e17b-4b88-baa3-38720c1dd5eb","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1189b224b302c5e9e9f536b4efc54e6f','reference-medmcqa-preinternship-psychiatry-en-1','psychiatry','روان‌پزشکی','medium','{"key":"8729556c-a513-42d6-abc1-ed7f6c9ca397","subjectId":"psychiatry","chapter":"روان‌پزشکی","prompt":"A man comes with history of abnormal excessive blinking and grunting. He says he has no control over his symptoms, which have risen in frequency of late. This has staed affecting his social life making him depressed. Which of the following medications should be used in him?","options":["Risperidone","Imipramine","Carbamazepine","Methylphenidate"],"correctIndex":0,"explanation":"Ans: A. Risperidone(Ref Kaplan and Sadock 11/e p1091; Niraj Ahuja 7/e p168).* This case suggests motor & vocal tics associated with Tourette''s disorder.Treatment:* Pharmacotherapy - treatment of choice - Antipsychotics (haloperidol & resperidone). - DOC - Haloperidol.Other useful drugs:* Resperidone, Olanzapine, Aripiprazole.* SSRIs - Fluoxetine for co-morbid obsessive-compulsive symptoms.* Methylphenidate & Imipramine - Used in ADHD child.* Adjunct - Behavior therapy.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"8729556c-a513-42d6-abc1-ed7f6c9ca397","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9c4c57e51a2f603c0865c060919961f9','reference-medmcqa-preinternship-psychiatry-en-1','psychiatry','روان‌پزشکی','medium','{"key":"bdc34663-b39a-47bb-b034-7f804e437c09","subjectId":"psychiatry","chapter":"روان‌پزشکی","prompt":"A young male patient is on 5 mg haloperidol for many days, recently for last 4 days of duration he has inner restlessness and urges to move. Diagnosis is?","options":["Akathisia","Tardive dyskinesia","Rabbit syndrome","Acute Dystonia"],"correctIndex":0,"explanation":"Antipsychotic drugs Extrapyramidal symptoms- dur to D2 blockade in limbic system Extrapyramidal symptoms Clinical features Special DOC Acute dystonia Oculogyric crisis ocular muscles spasm and opisthotonos Toicollis Protrusion of tongue leading to laryngospasm grimacing Earliest to develop (days) Anticholinergic drugs Acute akathisia Constant purposeless involuntary movement from one place to another Most common EPS Days to week Propranolol Tardive dyskinesia chewing and sucking movements grimacing choreoathetoid movements-akathisia Seen after long(years) use of anti-psychotic Tetrabenazine Malignant neuroleptic syndrome Fluctuating level of consciousness hypehermia -muscles rigidity increase level of CPK Increase level of liver enzyme confusion - Diaphoresis Most common cause of death in this syndrome is acute renal failure Most serious side effect dantrolene DRUG induced parkinsonism Few weeks anticholinergics","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"bdc34663-b39a-47bb-b034-7f804e437c09","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-medmcqa-preinternship-radiology-en-1','رادیولوژی · منتخب MedMCQA','preinternship','reference','medmcqa',NULL,'منبع باز',1793577600000,0,'MedMCQA — Pal, Umapathi & Sankarasubbu, 2022. Validation split via Open Life Science AI; Apache-2.0. متن اصلی انگلیسی؛ آزمون رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('788dadc0b05d2464904cf9b98a8d33f5','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"9078aaca-bbfd-41cd-ad69-03057fca84ba","subjectId":"radiology","chapter":"رادیولوژی","prompt":"Characteristic of venous blood flow of lower limb in duplex Doppler is?","options":["Monophasic","Biphasic","Triphasic","Non phasic"],"correctIndex":0,"explanation":"* Doppler is based on frequency shift and color coding depends on the direction of blood flow* Direction of blood flow:- Flow towards the probe- Red- Flow away from probe- Blue Intensity of color depends on velocity of flow Doppler effect: change in frequency because of relative motion between moving source of sound and observer. Direction of flow Color doppler showing CCA bifurcation Spectral doppler: Cursor is placed into the area of blood vessel we want to trace and its velocity is measured.An angle has to be maintained to obtain a proper image- Ideal angle = 0o (practically not possible)- Optimal angle = 45o-60o (never 90o) Spectral doppler of aeries Low resistance High resistance Example:* Brain aeries* ICA* CCA* VA- Renal aeries| Monophasic with pattern pulsatility Example: - Extremity aeries* ECA | Triphasic pattern Normal Peripheral Aerial Waveform Triphasic waveform Initial high velocity forward flow component Early diastolic reverse flow component Late diastolic forward flow component Narrow systolic window * Venous doppler:- It is Monophasic- during free breathing variations in amplitude due to cardiac and respiratory phasicity- In breath hold- pressure changes of . Atrium are reflected back in the major veins","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"9078aaca-bbfd-41cd-ad69-03057fca84ba","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('25bfff20bed7c4fc7ab6203f6e61d3bf','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"0f2b4bd8-8032-44cf-bf8e-ff24900ded1e","subjectId":"radiology","chapter":"رادیولوژی","prompt":"26 year old, 6 feet 4 inch male presented to the emergency depament with complaints of acute onset dysnea. On examination, he was tachypneic, other vitals were stable. A chest xray was done which shown the following pathology:","options":["Pneumothorax","Hydropnemo thorax","Massive pleural effusion","Pulmonary embolism"],"correctIndex":0,"explanation":"- The given image shows * Absent of Bronchovascular markings on the left lung compared to right lung * Left lung shifted or pushed toward the hilum- Hence, the given image is a case of Pneumothorax- If patient has pneumothorax with mediastinal shift, it is Tension pneumothorax and should be immediately managed with needle inseion in 5th ICS in mid-axillary line.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0f2b4bd8-8032-44cf-bf8e-ff24900ded1e","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('06cd167f42fc2742d0921a55b6d9c923','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"07549da1-d7ff-4fc2-85a0-a27023bbb810","subjectId":"radiology","chapter":"رادیولوژی","prompt":"Which of the following is the least useful for diagnosis of Spondylolisthesis?","options":["CT","MR","X-ray lumbar spine- AP view","X-ray lumbar spine- Lateral view"],"correctIndex":2,"explanation":"Ans. c. X-ray lumbar spine- AP view (Ref Tureks 6/e p503; Maheshwarl 3e/p 237; Wolfgang 7/e p 228-29, 206; Sutton 7/e p/66''Although for imaging of spondylolisthesis usually all are done, AP view appears to be least useful of these choices. On AP view, spondylolisthesis can show a sign called Napolean Hat sign. The lateral view is useful in detecting spondylolisthesis; it may demonstrate the pars defect.Spondylolisthesis is forward slip of one veebrae upon another; so it is best viewed (or seen earliest) in sagittal images of spine i.e. lateral and oblique X-ray of spine and saggital and axial views of CT and MRIQ","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"07549da1-d7ff-4fc2-85a0-a27023bbb810","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('8d062b3f99cc0bc222787010692e1935','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"e96fadd5-fac8-4cde-9957-d69ed40b3364","subjectId":"radiology","chapter":"رادیولوژی","prompt":"Which of these is not a pa of catatonia?","options":["Akathisia","Ambivalence","Ambitendency","Akinesia"],"correctIndex":0,"explanation":"Ans: A. Akathisia(Ref Kaplan and Sadock 11/e p329, 871; Niraj Ahuja 7/e p59).Akathisia:Not a pa of catatonia.Characterized by a subjective & objective sense of restlessness, anxiety & agitation.Ambitendency:Example of negativism.Considered an ambivalence form.Ambivalence:Sign of Schizophrenia.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e96fadd5-fac8-4cde-9957-d69ed40b3364","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f6563748afb93949b66628ffd06c534a','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"dde225f7-adf4-41e8-afe5-f12ab7801578","subjectId":"radiology","chapter":"رادیولوژی","prompt":"The principal reason for placing an aluminium filter in the primary beam of radiation is to:","options":["Reduce exposure time","Decrease development time of the films","Reduce radiation to the skin of the patient","Obtain greater definition of the images of teeth"],"correctIndex":2,"explanation":"Although an x-ray beam consists of a continuous spectrum of x-ray photon energies, only photons with sufficient energy to penetrate through anatomic structures and reach the image receptor (digital or film) are useful for diagnostic radiology. Low-energy photons that cannot reach the receptor contribute to patient risk but do no offer any benefit. Consequently, it is desirable to remove these low-energy photons from the beam. This removal can be accomplished in part by placing a metallic disk (filter) in the beam path. A filter preferentially removes low-energy photons from the beam, while allowing high energy photons that are able to contribute to making an image to pass through. Ref: Oral Radiology, Principles and Interpretation / Stuart C. White, Michael J. Pharoah - 7th ed - pg - 10","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"dde225f7-adf4-41e8-afe5-f12ab7801578","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('59f357db5cf98289f69f1bbc83c57548','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"41de4a10-ea29-4f5d-817c-570c5e537bc9","subjectId":"radiology","chapter":"رادیولوژی","prompt":"Patient with history of tachyarrhythmias is on implantable cardioveer defibrillator. He develops shock. Best method to know the position and integrity of ICD is:","options":["CECT","MRI","USG","Plain radiograph"],"correctIndex":0,"explanation":"Ans: A. CECT (Ref Hurst ''s The Hea 13/e p1050)Plain radiograph:Best method to know ICD position & integrity.ICD Lead dislodgement:Radiographically visible.Significant increase in pacing threshold /decline in electrogram amplitude.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"41de4a10-ea29-4f5d-817c-570c5e537bc9","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('103c33cc7653db5f1b2e02e26ea8de13','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"7f20e2a3-7048-4782-8dbe-c53dd6ccabc1","subjectId":"radiology","chapter":"رادیولوژی","prompt":"The single most effective method of reducing patient somatic exposure when taking radiograph is to use:","options":["A lead apron","Speed E film","Added filtration","An open ended, shielded cone"],"correctIndex":1,"explanation":"Intraoral dental X-ray film is available in two speed groups: D and E/F. Clinically, film of speed group E/F is approximately twice as fast (sensitive) as film of group D and thus requires only half the exposure. Fast films are desirable from the standpoint of exposure reduction. Multiple studies have found that E/F-speed film is preferred, because it has the same useful density range, latitude, contrast, and image quality as D-speed films and can be used in routine intraoral radiographic examinations without sacrifice of diagnostic information. Current digital sensors offer equal or greater dose savings than E/F-speed film and comparable diagnostic utility. Reference: White and Pharoah''s Oral Radiology Principles and Interpretation 7th edition page no 33","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"7f20e2a3-7048-4782-8dbe-c53dd6ccabc1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5de1ea6960c365d4e702c4738889c25b','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"48f3a95b-0f17-4c55-a104-7ae269bfcc0d","subjectId":"radiology","chapter":"رادیولوژی","prompt":"What is the most poable diagnosis based on the findings in the CT scan given below?","options":["Extradural hemorrhage","Subdural hamorrhage","Intracerebral hamorrhage","Subarachnoid hamorrhage"],"correctIndex":0,"explanation":"Epidural Hematoma- Biconvex/lentiform hyperdensity seen Subdural Hematoma - Concavo- convex or crescentic shaped. Subarachnoid Hemorrhage- Shows Hyperdensity in:* Syln fissure* Basal cisterns* Sulcal Spaces","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"48f3a95b-0f17-4c55-a104-7ae269bfcc0d","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3316801a324ee6b59cd0136871c7874e','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"477dea37-f0b6-4a6d-b77a-766ded28f2b6","subjectId":"radiology","chapter":"رادیولوژی","prompt":"A patient with pain abdomen for 2 hours presents to the casualty and the following X-ray was obtained. What is the most likely diagnosis?","options":["Pneumoperitoneum","Subphrenic abscess","Pneumomediastinum","Amebic liver abscess"],"correctIndex":0,"explanation":"Answer-A. PneumoperitoneumMC cause of pneumoperitoneum: Perforation of hollow viscus (leading to release of air from bowel and collection just below the diaphragm)Best projection to derhonstrate pneumoperitoneum: Chest X-rayIf the patient cannot get into an erect position then left lateral decubitus projection is required.Patient should be in that position for l0 mina at least for air to rise up.By careful technique even 1 ml of air can be detected","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"477dea37-f0b6-4a6d-b77a-766ded28f2b6","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('45c6b1af28753b6d46bb921653cd437b','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"3588f845-135e-4167-8455-ecc975821b3a","subjectId":"radiology","chapter":"رادیولوژی","prompt":"The radiopacity that frequently obliterate the root apices of maxillary molars is","options":["Maxillary sinus","Palatine bone","Zygoma and Zygomatic process of Maxilla","Orbital process of Zygomatic bone"],"correctIndex":2,"explanation":"FigureA shows the inferior border of the zygomatic process of the maxilla over the molars. This structure lies buccal to the teeth and appears to move mesially as the x-ray beam is oriented more from the distal. Similarly, as the angulation of the beam is increased vertically, the zygomatic process is projected occlusally over the teeth.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"3588f845-135e-4167-8455-ecc975821b3a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('c37a453b98ab3f07fdba60b2f1073ce9','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"c08067b4-7695-49f9-8c51-efbca491078a","subjectId":"radiology","chapter":"رادیولوژی","prompt":"Decay of enamel following radiotherapy is initiated due to:","options":["Decrease in salivary flow","Direct radiations contacting the enamel","Dessication of tooth structure","Hypocalcification and pitting of enamel"],"correctIndex":0,"explanation":"Radiation caries is a rampant form of dental decay that may occur in individuals who receive a course of radiotherapy that includes exposure of the salivary glands. Patients receiving radiation therapy to oral structures have increase in Streptococcus mutans, Lactobacillus, and Candida. Caries results from changes in the salivary glands and saliva, including reduced flow, decreased pH, reduced buffering capacity, increased viscosity, and altered flora. White and Pharoah, pg-22","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c08067b4-7695-49f9-8c51-efbca491078a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f032859f88acb96f298118b95fdbb21b','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"c03c5c4d-5433-4515-a343-12c7f0ea1e07","subjectId":"radiology","chapter":"رادیولوژی","prompt":"In cephalometric radiography, the distance between the subject and the source of X-ray is","options":["2 feet","48 inches","4.8 metres","5 feet"],"correctIndex":3,"explanation":"By convention, the distance from the X-ray source to the subject''s midsagittal plane is 5 feet. Contemporary Orthodontics, William Proffit, 6th ed, pg-174","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c03c5c4d-5433-4515-a343-12c7f0ea1e07","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3d2466c485bf085adddbfe8156439071','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"e22b0ef5-df61-4475-b22b-30f2932f90fe","subjectId":"radiology","chapter":"رادیولوژی","prompt":"Patient''s cross infection with bite block of orthopantamograph machine is prevented by","options":["Cover with autoclaved cloth with each use","Using disposable bite blocks","Clean with 5.25% sodium hypochlorite in each patient","Cover with impervious barrier"],"correctIndex":1,"explanation":"Panoramic and cephalometric equipment should receive the same maintenance for decontamination and disinfection as other equipment. Panoramic bite-blocks, chin rest, and patient handgrips should be cleaned with detergent-iodine disinfectant and covered with a plastic bag. Disposable bite-blocks may be used. The head-positioning guides, control panel, and exposure switch should be carefully wiped with a paper towel that is well moistened with disinfectant. Note: disposable bite-blocks are the preferred method, although they may not be cost effective. Oral radiology ; White and Pharaoh 7th edition page no: 256","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e22b0ef5-df61-4475-b22b-30f2932f90fe","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7d6e39af77fca0d8fb41591e8f2bc4ae','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"2f703c9f-2d54-4833-b319-25f8dc8b500c","subjectId":"radiology","chapter":"رادیولوژی","prompt":"Which type of laser is used in waterlase system?","options":["Argon laser","Diode Laser","Nd:YAG laser","YSGG Laser"],"correctIndex":3,"explanation":"It is an erbium laser (Er,Cr:YSGG) that has the ability to remove both hard and soft tissue safely and effectively. The WaterLase iPlus™ laser from BIOLASE, he says, is exceptionally versatile. “This is an all-tissue laser. Not only can it manipulate soft tissue by removing it for procedures such as biopsies and gingivectomies, it can also safely and effectively ablate tooth and bone structure.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"2f703c9f-2d54-4833-b319-25f8dc8b500c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('6e5807b2f879b44891ea1702f72c45a9','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"479e5139-f840-4d95-b13b-d1a95e2ff3e4","subjectId":"radiology","chapter":"رادیولوژی","prompt":"Patient with carcinoma endometrium treated with pelvic external beam irradiation to whole pelvis. Which of the following organs is most radiosensitive in the pelvic region?","options":["Ovary","Vagina","Bladder","Rectum"],"correctIndex":0,"explanation":"Ans: A. Ovary(Ref Perez and Brady''s Principles of Radiation Oncology 6/e p65)Among the given options, most radiosensitive organ is ovary >rectum >bladder >vagina.(Radiation tolerance dose: Ovary = 2-3 Gy; Rectum = 60 Gy; Bladder = 65 Gy; Vagina = 90 Gy).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"479e5139-f840-4d95-b13b-d1a95e2ff3e4","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ac3d50df6c3d81844c4010914c7f9c4c','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"73bd4537-a8bc-420a-a85e-93d08adc318b","subjectId":"radiology","chapter":"رادیولوژی","prompt":"Expansion of the contrast filled space in myelography is seen in:","options":["Intramedullary tumor","Intradural extramedullary tumor","Spinal dysraphism","Extradural tumor"],"correctIndex":0,"explanation":"Ans: A. Intramedullary tumor(Ref Sutton 6/e p254: Neurology in Clinical Practice 4/e Vol I p579)Myelography:Expansion of contrast filled space (i.e. subarachnoid space) - Any intramedullaty extradural lesion (meningioma).Sometimes filling defect causing \"meniscus sign\" demonstrable.Levels of Block in MyelographySiteTypical AppearanceExtradural blockFeathered appearanceIntradural Extramedullary blockMeniscus signWidening of ipsilateral subarachnoid spaceIntramedullary blockWidening of the cordTrouser leg appearance","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"73bd4537-a8bc-420a-a85e-93d08adc318b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('975cbb52a0c24df07e25ebef366ff29d','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"94f81251-43c1-4ba0-a67c-4f6412742774","subjectId":"radiology","chapter":"رادیولوژی","prompt":"The speed with which the electrons travel from the filament of cathode to the anode depends upon","options":["Potential difference between the two electrodes","Number of milliamperes in the tube circuit","Angle between the filament and target","Voltage of the filament"],"correctIndex":0,"explanation":"The primary functions of the power supply of an X-ray machine are to: Provide a low-voltage current to heat the X-ray tube filament. Generate a high potential difference to accelerate electrons from the cathode to the focal spot on the anode. The X-ray tube and two transformers lie within an electrically grounded metal housing called the head of the X-ray machine. White and Pharoah, pg-6","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"94f81251-43c1-4ba0-a67c-4f6412742774","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('0e9eb7925461e2a66c685d406bfdb298','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"d5070ff9-a3de-4f6c-a9ba-12918fa6ef04","subjectId":"radiology","chapter":"رادیولوژی","prompt":"Which among the following is not a risk factor for contrast-induced nephropathy?","options":["Diabetic nephropathy","High osmolar agent","Obesity","Dehydration"],"correctIndex":2,"explanation":"Ans. CSide effects of iodinated contrast material are:Idiosyncratic - Anaphylactoid reaction. They are complement-mediated reactions and not IgE. The patient develops bronchospasm and hypotension.Dose-dependent side effect - Contrast-induced nephropathy and seen especially with high osmolar agents.Contrast-induced nephropathy:The patient has non-oliguric transient nephropathy and occurs due to tubular damage. It is defined as the impairment of renal function and is measured as either a 25% increase in serum creatinine from baseline or 0.5 mg/dl increase in absolute value, within 48-72hrs of intravenous contrast administration.Risk Factors for Contrast Medium-Induced Nephropathy:Patient-related:eGFR < 60 mL/min/1.73 m2 before intra-aerial administrationeGFR < 45 mL/min/1.73 m2 before intravenous administrationIn paicular in combination with:Diabetic nephropathyDehydrationCongestive hea failure (NYHA grade 3-4) and low LVEFRecent myocardial infarction (Intra-aoic balloon pumpPeri-procedural hypotensionLow hematocrit levelAge over 70Concurrent administration of nephrotoxic drugsKnown or suspected acute renal failureProcedure-related:Intra-aerial administration of contrast mediumHigh-osmolality agentsLarge doses of contrast mediumMultiple contrast medium administrations within a few daysIf the patient is on Metformin and is having de-arranged RFT, then before giving contrast agent metformin should be stopped since it can precipitate lactic acidosis","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d5070ff9-a3de-4f6c-a9ba-12918fa6ef04","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('96e387237424b459e979d40f7a07086d','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"9a21d76c-9104-4bd2-be55-a37c3b71c0f5","subjectId":"radiology","chapter":"رادیولوژی","prompt":"Which type of radiation effect results in radiation induced thyroid cancer?","options":["Somatic","Genetic","Teratogenic","Autosomal"],"correctIndex":0,"explanation":"Based on the object that shows the effects: Somatic Effects: These are biological effects that occur on the exposed individuals. Somatic effects can be of 2 types. Prompt somatic effect occur after an acute dose. Eg: Temporary hair loss occurs about three weeks after a dose of 400 rad to scalp. Delayed somatic effects are those that occur years after radiation doses are received. Eg: Increased potential for development of cancer and cataracts. Genetic or heritable effects: Appear in the future generations of the exposed person as a result of radiation damage to reproductive cells.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"9a21d76c-9104-4bd2-be55-a37c3b71c0f5","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9ecd394e44989d20fc590ce2ed624e64','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"a456bf4d-1f3e-42a4-8976-b1b81ff466ee","subjectId":"radiology","chapter":"رادیولوژی","prompt":"For a maxillary premolar in a radiograph, the facial root appears distal to the palatal root, the film was exposed with:","options":["Increased vertical angulation","Decreased vertical angulation","From mesial side of the tooth","From distal side of the tooth"],"correctIndex":2,"explanation":"If the tube is shifted mesially and the object in question appears to move distally, it lies on the buccal aspect of the reference object. These relationships can be easily remembered by the acronym SLOB: same lingual, opposite buccal. Thus, If the object in question appears to move in the same direction with respect to the reference structures as does the X-ray tube, it is on the lingual aspect of the reference object. If it appears to move in the opposite direction as the X-ray tube, it is on the buccal aspect. If it does not move with respect to the reference object, it lies at the same depth (in the same vertical plane) as the reference object. Ref: ORAL RADIOLOGY Principles and Interpretation, Stuart C. White, Michael J. Pharoah Edition 7 page no 88","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a456bf4d-1f3e-42a4-8976-b1b81ff466ee","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d14badec059e8d5e2326648e6c3ed394','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"427b1e29-9386-4ca4-af88-7c3fe4b37e15","subjectId":"radiology","chapter":"رادیولوژی","prompt":"In an internal derangement of TMJ fracture, panoramic view has been taken for the patient. To confirm our diagnosis, we may take the help of","options":["MRI","CT scan","Arthroscopy","Bone scan"],"correctIndex":0,"explanation":"Soft tissues of the joint (articular disk) can be imaged with MRI or Arthrography. MRI produces superb images of the soft tissues in internal derangement of the disk. Arthrography is invasive and has the risk of infection and allergic reaction due to the contrast agent.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"427b1e29-9386-4ca4-af88-7c3fe4b37e15","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e55f58f854202e2ba5fc89c077bd249e','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"ddf70117-84c0-4fe8-a4f4-143205abf2c9","subjectId":"radiology","chapter":"رادیولوژی","prompt":"A 10 year old presented to ohopaedic OPD with a Curved Back, AP and Lateral Radiographs are obtained, what is the most likely cause of such deformity?","options":["Congenital","Neurofibromatosis","Idiopathic","Neuromuscular"],"correctIndex":0,"explanation":"- In the given A-P view X-ray we could see the curvature of the spine and the presence of Hemiveebrae indicating it as a case of Scoliosis with congenital origin 3D CT image & Radiograph image showing Hemiveebrae SCOLIOSIS:* Scoliosis is defined as a lateral spinal curvature with a cobb angle of 10o or more* A curve with a Cobb angle of less than 10o is asymptomatic and does not progress; this state is known as spinal asymmetry, not Scoliosis * Cobb''s angleo The angle formed by meeting of the two parallel tangential lines drawn from End Veebrae is known as Cobb''s angleo Apex veebra - Fahest veebra from the spineo End veebra - Veebra that is tilted the mosto Neutral veebra - Veebra that is tilted the leasto Stable veebra - Veebra that is in line with the central sacral line * Levoscoliosis: Curvature towards the left* Dextroscoliosis: Curvature towards the right* Major/Main curvature: Curvature formed by the deformity* Minor curvature: It is a compensatory curvature Main Class and Subtype Demographic and Clinical Characteristics Idiopathic Infantile Occurs in the first 3 years of life; male preponderance; levoscoliosis is more common than dextroscoliosis Juvenile Occurs at age 4-10 years; female preponderance; dextroscoliosis is more common than levoscoliosis Adolescent Occurs at age 10-18 years; female preponderance; dextroscoliosis is more common than levoscoliosis Congenital Osteogenic Wedge - shaped veebrae, hemiveebrae, fused veebrae, unilateral bar Neuropathic Tethered cord, syringomyelia, Chiari malformation, (myelo) meningocele, diastematomyelia Developmental Skeletal dysplasia Achondroplasia Skeletal dyostosis Neurofibromatosis, osteogenesis imperfecta Neuromuscular Neuropathic (acquired) Cerebral palsy, spinocerebellar, degeneration, poliomyelitis Myopathic Muscular dystrophy of various types (eg, Duchenne dystrophy) Tumor - associated Osseous Osteoid osteoma, osteoblastoma Extraosseous Extramedullary (eg, neurofibroma) or intramedullary (eg, astrocytoma) tumor","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ddf70117-84c0-4fe8-a4f4-143205abf2c9","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('6174431b572b5df4c4c7a439ecb2b8cd','reference-medmcqa-preinternship-radiology-en-1','radiology','رادیولوژی','medium','{"key":"ec6114a9-5426-4d90-bdde-2511889a20ec","subjectId":"radiology","chapter":"رادیولوژی","prompt":"A middle aged female presents with slowly progressive weakness of lower limbs, spasticity and recent onset hesitancy of Micturition. On neurological examination there is evidence of dorsal myelopathy. MRI scan of spine reveals middorsal intradural contrast enhancing mass lesion. Diagnosis is:","options":["Intradural lipoma","Dermoid cyst","Meningioma","Epidermoid cyst"],"correctIndex":2,"explanation":"Ans. c. Meningioma (Ref. Harrison 19/e p602, I 8/e p3388; Chapman 4/e p431; Sahicton /9/e p 1888- 1889; Schwa/17 9/e p1540- I 541: Bailey 26/e p614, 25/e p633)Diagnosis in a middle aged female with slowly progressive weakness of lower limbs, spasticity and recent onset hesitancy of micturition with evidence of dorsal myelopathy and middorsal intradural contrast enhancing mass lesion on MRI is meningioma.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ec6114a9-5426-4d90-bdde-2511889a20ec","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-medmcqa-preinternship-surgery-en-1','جراحی · منتخب MedMCQA','preinternship','reference','medmcqa',NULL,'منبع باز',1793577600000,0,'MedMCQA — Pal, Umapathi & Sankarasubbu, 2022. Validation split via Open Life Science AI; Apache-2.0. متن اصلی انگلیسی؛ آزمون رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('1a8ad8cf8add08e3a1932ac98d24eafb','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"9a3940ff-8c7a-492c-86d4-259c47cef675","subjectId":"surgery","chapter":"جراحی","prompt":"Which one of the following is a muscle splitting incision?","options":["Kocher''s incision","Rutherford-Morrison incision","Pfannenstiel incision","Lanz incision"],"correctIndex":3,"explanation":"Ans: D. Lanz incisionLanz incision:An oblique (transverse skin crease), muscle splitting incision used for an appendectomy.A modification of McBurney''s (Grid Iron) incision.Advantages:Considered cosmetically better.Exposure is better.The extension is easier.Measurements:Incision, appropriate in length to size & obesity of patient - Approximately 2 cm below umbilicus centered on the midclavicular-mid inguinal line.It can be extended medially - With retraction or suitable division of rectus abdominis muscle.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"9a3940ff-8c7a-492c-86d4-259c47cef675","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('8b7c86de99b43a3992a850ad5c2d9224','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"890982b8-3906-44be-aff1-437a7c6c373d","subjectId":"surgery","chapter":"جراحی","prompt":"In a couple for treatment of infeility from the last four years, female paner is normal. Male paner has 0.8 ml semen volume per ejaculate on two repeated samples and absent fructose, with no sperms on examination under microscope. What is the next line of management?","options":["Per-rectal examination to check ejaculatory duct obstruction","Give antioxidants","Testicular biopsy","Transrectal ultrasound to detect duct obstruction"],"correctIndex":3,"explanation":"Answer- D. Transrectal ultrasound to detect duct obstructionAbsent fructose with no sperms in ejaculate is suggestive of obstruction of vas deferens with seminal vesicle agenesis or obstruction. Next line of management in this patient would be transrectal ultrasound to detect duct obstruction.Transrectal Ultrasound-High-frequency (5-7) mHz transrectal ultrasound (TRUS) offers superb imaging of the prostate, seminal vesicles, and ejaculatory ducts.Due to both accuracy and convenience, TRUS has replaced surgical vasography in the diagnosis of obstructive lesions that cause infeility.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"890982b8-3906-44be-aff1-437a7c6c373d","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('4cc49b06c39df558d4dfc738ca58d70e','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"ed111e74-8d76-4f2f-ac59-56e7ddc2be88","subjectId":"surgery","chapter":"جراحی","prompt":"Most common presentation of abdominal desmoids tumor is?","options":["Abdominal pain","Abdominal mass","Fever","Urinary retention"],"correctIndex":1,"explanation":"Desmoid tumors: \"Clinically, the most common areas of origin include the extremity, intraperitoneal, abdominal wall, and chest wall. Affected patients may present with a painful versus asymptomatic firm mass, bowel obstruction, or bowel ischemia.\" -Sabiston 20/e p765 \"Patients with a desmoid tumor present with an asymptomatic mass or with symptoms related to mass effect from the tumor.\" -Sabiston 20/e p1073","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ed111e74-8d76-4f2f-ac59-56e7ddc2be88","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f03b619164e541f3b6cd00d46f4bdcea','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"f213cf1e-b5d6-4a25-8027-f1e39514ff20","subjectId":"surgery","chapter":"جراحی","prompt":"A 75 year old chronic smoker who is diabetic and edentulous for the last 30 years has a bilateral body fracture, best treatment modality is","options":["ORIF with reconstruction plate","Gunning splints","Two mini plates","Wire osteosynthesis"],"correctIndex":1,"explanation":"Non surgical management is the best approach in patients who are at increased risk of non/delayed healing. Medical history of the patient indicates risk factors which can interfere with recovery so Gunning splint is the best approach.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f213cf1e-b5d6-4a25-8027-f1e39514ff20","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f65a089ad3cd8628bd64cf49edcbbfb3','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"2674faba-e6d7-4790-b13e-97c597408919","subjectId":"surgery","chapter":"جراحی","prompt":"Most common mediastinal tumor:","options":["Neurogenic tumor","Thymoma","Lymphoma","Bronchogenic cyst"],"correctIndex":0,"explanation":"M/C Mediastinal tumor - Neurogenic tumor M/C anterior mediastinal tumor - Thymoma Mediastinal Tumors in Adults Tumor Type Percentage of Total Location Neurogenic tumors 21 Posterior Cysts 20 All Thymomas 19 Anterior Tumor Type Percentage of Total Location Lymphomas 13 Anterior/middle Germ cell tumors 11 Anterior Mesenchymal tumors 7 All Endocrine tumors 6 Anterior/middle Mediastinal Tumors in Children Tumor Type Percentage of Total Location Neurogenic tumors 400 Posterior Lymphomas 180 Anterior/middle Cysts 18 All Germ cell tumors 11 Anterior Mesenchymal tumors 9 All Thymomas Rare Anterior MEDIASTINAL MASSES (MM) MC anterior MM: Thymoma Q MC middle MM: Cyst (Pericardial cyst is MC) MC posterior MM: Neurogenic tumors MC MM (overall): Neurogenic tumors MM seen in all three compaments of mediastinum: Lymphoma, bronchogenic cyst & mesenchymal tumors IOC for diagnosis of MM (except neurogenic tumors): CT IOC for diagnosis of neurogenic tumors: MRI","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"2674faba-e6d7-4790-b13e-97c597408919","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('59609880dfbb1b6eae96939730954019','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"62081a5c-5ffc-4a88-9aca-c9e430490e73","subjectId":"surgery","chapter":"جراحی","prompt":"A female with suspected child abuse was brought to the casualty with severe bleeding from the perineum. What should be the first line of management?","options":["Airway maintenance","Internal iliac aery ligation","Whole blood transfusion","Inform police before staing the treatment"],"correctIndex":0,"explanation":"Ans. a. Airway maintenanceThe primary survey aims to identify and manage the most immediately life-threatening pathologies first and follows ABCDE.c- exsanguinating external hemorrhageA- Airway maintenanceB- Breathing & ventilationC- Circulation & hemorrhageD- DisabilityE- Exposure","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"62081a5c-5ffc-4a88-9aca-c9e430490e73","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('da2825be3b3861fb0684b04d826dec17','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"cb8ad6b2-009b-443e-9237-85b46e3a87a5","subjectId":"surgery","chapter":"جراحی","prompt":"What is the name of the given instrument, used for harvesting the graft from healthy area in split thickness skin graft?","options":["Dermatome","Silver''s knife","Catlin amputating knife","Humby knife"],"correctIndex":3,"explanation":"Humby Knife A knife with a roller attached, used for cutting skin grafts of varying thickness The distance between the roller and blade of knife can be varied by means of a calibration device.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"cb8ad6b2-009b-443e-9237-85b46e3a87a5","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3db109730c2fa4711f54c1848f6af02c','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"70be9151-2441-49de-8dd1-3bd6ee597992","subjectId":"surgery","chapter":"جراحی","prompt":"Self injury most likely caused after extraction in children is","options":["Inadvertent lip biting after anesthesia","Chemical burn","Permanent palsy","Trismus"],"correctIndex":0,"explanation":"Inadvertent lip biting after inferior alveolar nerve block is most commonly seen in children after extraction. This self-injury mostly occurs due to dentist fail to mention/provide important instructions to child/ their parents that he/she should not eat anything till effect of anesthesia completely wears off as it leads to unknowing/ Inadvertent lip biting during eating. Sometimes this also happens if child/parents fail to follow the instructions mentioned by dentist.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"70be9151-2441-49de-8dd1-3bd6ee597992","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('90a6e08caaff42a64e49fd92dcd1e7fc','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"78b95ab4-b15f-4942-b618-8b36e946a5d0","subjectId":"surgery","chapter":"جراحی","prompt":"A 55-year-old male presents with severe backache for 10 days and urinary incontinence with a H/o Interveebral lumbar disc prolapse. There is no H/o fever or weight loss. What is the likely diagnosis?","options":["Potts spine","Multiple myeloma","Cauda equine syndrome","Bone metastasis"],"correctIndex":2,"explanation":"Ans: C: Cauda equine syndromeRef: Apley!c system of ohopaedics and fracture 9\" ed., pg. 246,480Cauda equina is tuft of fibres which begins at the end of spinal cord.Compression over this pa may cause cauda equina syndrome.Causes of Cauda equina syndrome are:Lumbar disc herniation, Spinal canal stenosis, Trauma, Abscess etc.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"78b95ab4-b15f-4942-b618-8b36e946a5d0","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('4985c30e401452d43c094aab5419f700','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"a629e297-c858-4665-8991-b4c49606bf38","subjectId":"surgery","chapter":"جراحی","prompt":"Infected mandibular angle fracture is treated by?","options":["Mini plates","Reconstruction plates","Champy plate at upper border","IMF + ID"],"correctIndex":3,"explanation":"We can never place a foreign object(implant mini plates or reconstruction plates) at infection site.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a629e297-c858-4665-8991-b4c49606bf38","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('701951624fbe366c3788ee68e5c0d61e','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"6ec2995f-3b3d-495c-8768-98368ad2b08d","subjectId":"surgery","chapter":"جراحی","prompt":"Which of the following PPE (Personal Protective Equipment) is removed first?","options":["Gloves","Face shield","Gown","Mask"],"correctIndex":0,"explanation":"Personal protective equipment: PPE - protect the user against health or safety risks at work. Can include items such as safety helmets, gloves, eye- protection, high visibility clothing, safety footwear and safety harness. It can also include respiratory protective equipment (RPE) Order of removing PPE: Gloves Face shield Gown Mask","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6ec2995f-3b3d-495c-8768-98368ad2b08d","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('40f8cdbe4c5724816006233303f9911d','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"d8c8d387-cac9-4633-b85c-9fd5f0aa2dd2","subjectId":"surgery","chapter":"جراحی","prompt":"A patient underwent laparoscopic cholecystectomy and was discharged on the same day. On postoperative day 3, he presented to the hospital with fever. Ultra-sonography showed a 5 x 5 cm collection in the right sub diaphragmatic region. What will be the manage!ment?","options":["Observe with antibiotic cover","Re-explore the wound with T-tube inseion","Pigtail inseion and drainage","ERCP and proceed"],"correctIndex":2,"explanation":"Answer- C. Pigtail inseion and drainageThis patienl is most likely having a biliary leak from the cystic duct stump, which has formed a large 5 x 5 cm collection.Such a patient needs to be managed with intravenous antibiotics as well as drainage of the collections (as it acts as source of injection). Ultrasound guided pigtail inseion is the easiest method to obtain adequate drainage of the bile leak.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d8c8d387-cac9-4633-b85c-9fd5f0aa2dd2","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('fe0cb19bce6d1c65b1988b9983606117','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"5c0f862f-2651-4ed4-88d4-2456dab0f036","subjectId":"surgery","chapter":"جراحی","prompt":"A patient sustained A and endotracheal intubation was done. Most likely GCS score of such a patient would be:March 2013 (b, c, d)","options":["8","10","12","15"],"correctIndex":0,"explanation":"Ans. A i.e. 8Patients with severe head injury, an altered level of consciousness, or a Glasgow Coma Scale (GCS) score of 8 or less usually require placement of a definitive airway.Orotracheal or nasotracheal intubation can be attempted with cervical spine precautions if a second person maintains axial immobilization of the head to prevent destabilization of the spine.In this patient, GCS score was 8, so endotracheal intubation was done to secure airway.You don''t have to calculate the GCS score of this patient after intubation.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"5c0f862f-2651-4ed4-88d4-2456dab0f036","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('577cb2d556cc5cc61480cb7a1337dd47','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"1bcbe056-96b4-41aa-a7aa-044d7d2ac555","subjectId":"surgery","chapter":"جراحی","prompt":"A young patient is diagnosed to have irreparable tear of the rotator cuff. Treatment of choice will be:","options":["Tendon transfer","Total shoulder replacement","Reverse c shoulder replacement","Acromioplasty"],"correctIndex":0,"explanation":"Ans: A. Tendon transfer(Ref Apley 9/e p347,348)Treatment of choice for irreparable tear of rotator cuff in young patient = Tendon transfer.Subacromial decompression and debridement of degenerate cuff tissue:Useful for irreparable massive full thickness tears.Pain relief allows reasonable shoulder abduction by remaining muscles.Other methods:Supraspinatus advancement.Latissimus dorsi transfer.Rotator cuff transposition.Fascia Iota autogruit.Synthetic tendon graft.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"1bcbe056-96b4-41aa-a7aa-044d7d2ac555","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f3d9e4de387d5c153b7ff20db6cfef5c','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"a963bf66-e44e-445f-b3ba-26efcd836ad9","subjectId":"surgery","chapter":"جراحی","prompt":"Best guide for the management of Resuscitation is:","options":["CVP","Urine output","Blood pressure","Saturation of Oxygen"],"correctIndex":1,"explanation":"The best measure of organ perfusion and the best monitor of the adequacy of shock therapy remains the urine output\". Minimum urine output in ADULTS - 1ml/min Minimum urine output in CHILDRENS - (0.5 - 1) ml/min","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a963bf66-e44e-445f-b3ba-26efcd836ad9","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e026e7d6b1fce8c723e1466020a268fd','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"a1726527-12af-47e3-82f1-b1ea871d2659","subjectId":"surgery","chapter":"جراحی","prompt":"Nimodipine is approved for use in:","options":["Subdural hemorrhage","Extradural hemorrhage","Intracerebral hemorrhage","Subarachnoid hemorrhage"],"correctIndex":3,"explanation":"Ans: D. Subarachnoid hemorrhage(Ref: Harrison 19/e p1787, 1735; Ratting 13/e p202, 12/e p204).Nimodipine is approved for use in subarachnoid hemorrhage.Subarachnoid hemorrhage:Typically treated with the calcium channel blocker nimodipine, aggressive IV fluid administration, and therapy aimed at increasing blood pressure, typically with vasoactive drugs such as phenylephrine.The IV fluids and vasoactive drugs (hypeensive hypervolemic therapy) are used to overcome the cerebral vasospasm.Early surgical clipping or endovascular coiling of aneurysms is advocated to prevent complications related to re-bleeding.Hydrocephalus, typically heralded by a decreased level of consciousness, may require ventriculostomy drain.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a1726527-12af-47e3-82f1-b1ea871d2659","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('8cf94b81444aef17896d530590db5c89','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"20c4de15-f187-4a56-941f-0aa7bc2702ba","subjectId":"surgery","chapter":"جراحی","prompt":"A 60-year-old chronic smoker presented with progres-sive jaundice, pruritus and clay colored stools for 2 months. History of waxing and waning of jaundice was present. A CT scan revealed dilated main pancre-atic duct and common bile duct. What is the likely di-agnosis?","options":["Carcinoma head of pancreas","Periampullary carcinoma","Chronic pancreatitis","H lar cholangiocarcinoma"],"correctIndex":1,"explanation":"Ans: B. Periampullary carcinoma(Ref Sabiston 201e p1544, 19/e p1535-1544; Schwaz 10/e p1408, 9/e p1220-1225 Bailey 27/e p1234, 26/e p1138, Blumga 5/e p919-925; Shackelford 7/e p1190-1196)Suggestive diagnosis is periampullary carcinoma.Since history of waxing and waning episode is seen.The waxing and waning nature of jaundice is due to sloughing of ampullaty cancer, resulting in transient resolution of the jaundice.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"20c4de15-f187-4a56-941f-0aa7bc2702ba","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('aeebdbea64a7dde0fc5bec34645c545e','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"dcf755f4-a047-4777-b656-544752fb83d7","subjectId":"surgery","chapter":"جراحی","prompt":"Patellar cluck syndrome is interposition of soft tissue at or hyperophied scar:","options":["Superior pole of patella and impinging on femoral component during flexion","Superior pole of patella and impinging on femoral component during extension","Inferior pole of patella and impinging on femoral component during flexion","Inferior pole of patella and impinging on femoral component during extension"],"correctIndex":1,"explanation":"Ans: B. Superior pole of patella and impinging on femoral component during extension Patellar Clunk Syndrome is a painful condition associated with a mechanical catching or clunking during active extension following total knee ahroplasty (TKA).The syndrome is caused by growth of interposing soft tissue usually at the superior pole of the patella.This interposed soft tissue cannot be visualized on plain radiographs.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"dcf755f4-a047-4777-b656-544752fb83d7","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('34e17502cdba888fb4a91cc84c2e4b05','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"14a9e3be-384f-4b56-99c5-dfd851243951","subjectId":"surgery","chapter":"جراحی","prompt":"Which is not associated with GDM (Gestational DM)?","options":["Past history of fetal abnormality","Obesity","Hypeension","Macrosomia"],"correctIndex":2,"explanation":"Answer- C. HypeensionA previous diagnosis of gestational diabetes or prediabetes, impaired glucose tolerance, or impaired fasting glycaemia.Being overweight, obeseA previous pregnancy which resulted in a child with a macrosomia.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"14a9e3be-384f-4b56-99c5-dfd851243951","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1f4f5a998c5187da62bc8e0fa510469c','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"1f253e11-f50e-40f8-a36a-16101d47d319","subjectId":"surgery","chapter":"جراحی","prompt":"ABCDE mnemonic is used for which disease?","options":["SCC","Melanoma","Basal Cell carcinoma","Verrucous carcinoma"],"correctIndex":1,"explanation":"Answer- B. MelanomaABCDE rule: Asymmetry (one half of the mole doesn''t match the other), Border irregularity, Color that is not uniform, Diameter greater than 6 mm (about the size of a pencil eraser), and Evolving size, shape or color","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"1f253e11-f50e-40f8-a36a-16101d47d319","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ce80a7a178a8161fb39adaf28cf4b4ce','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"91ef49a3-d73b-408b-abf1-0fbfe43805dd","subjectId":"surgery","chapter":"جراحی","prompt":"A 70 years old patient presents with a lesion on the cheek with raised, pearly borders and with telangiectasias on surface of the lesion. What is the likely diagnosis?","options":["Basal cell carcinoma","Squamous cell carcinoma","Was","Actinic keratosis"],"correctIndex":0,"explanation":"Ans: A. Basal cell carcinoma(Ref: Harrison 19/c p500; Robbins 9/e p1157)Lesion on the cheek with raised, pearly borders and with telangiectasia on surface of the lesion is highly suggestive of basal cell carcinoma.Basal cell carcinomas:Present as pearly papules containing prominent dilated subepidermal blood vessels (telangiectasias).Arises from epidermal basal cells.Present as a small, slowly growing pearly nodule, often with touous telangiectatic vessels on its surface, rolled borders, and a central crust (nodular BCC).The occasional presence of melanin in this variant of nodular BCC (pigmented BCC) may lead to confusion with melanoma.Morpheaform (fibrosing), infiltrative, and micronodular BCC, the most invasive and potentially aggressive subtypes, manifest as solitary flat or slightly depressed, indurated whitish, yellowish, or pink scar-like plaques.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"91ef49a3-d73b-408b-abf1-0fbfe43805dd","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('6bb0e46cf61a5cdc1b9a2f2b13189e2f','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"251499f8-5ddb-4d75-9acb-71fa169e64dc","subjectId":"surgery","chapter":"جراحی","prompt":"Most common cause of recurrent laryngeal nerve palsy is:","options":["Bronchogenic carcinoma","Thyroid surgery","Mediastinal tumors","Pancoast tumor"],"correctIndex":1,"explanation":"\"Previous surgery, mostly thyroid surgery, is the most common cause of laryngeal nerve paralysis. Revision thyroidectomy bears a paicularly high risk for inferior and superior laryngeal nerve trauma.\" - Surgery of Larynx and Trachea by Marc Remacle (2015)/ p271","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"251499f8-5ddb-4d75-9acb-71fa169e64dc","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5c41c9246c1b371f9f7b00a13819dfa9','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"36b43626-f928-486f-b724-abecea127f62","subjectId":"surgery","chapter":"جراحی","prompt":"A surgeon decides to operate a patient of carcinoma cecum and perform a right hemicolectomy through a midline laparotomy approach. You have been instructed to prepare the pas of the patient for surgery. What will you do?","options":["Clean and drape from the level of nipple to mid-thigh","Clean and drape from chin to knee","Clean and drape from umbilicus to mid-thigh","Clean and drape from rib cage to inguinal regions"],"correctIndex":0,"explanation":"Ans: A. Clean and drape from the level of nipple to mid-thighArea of Cleaning & Draping in SurgeriesCranial surgeryDepends upon surgeonThyroid or neck surgeryChin to nipple with shoulder & axilladegEye surgeryCut eyelashes of affected eyeNasal surgeryNo shaving unless with mustacheEar surgeryTwo & half inches around eardegChest surgeryBase of neck to waist, axilla & inner armdegAbdominal & pelvic surgeryBase of neck to waist, axilla & inner armdegKidney-anteriorNipple to perineum, side to side; supra scapular region to buttocksVaginal, scrotal, rectal surgeryWaist to perineum plus anterior & inner aspect of thigh & 6 inches from groin; posterior?entire buttocks & anusdegLower extremitiesDigits 2 inches above knee, entire extremity and groindegUpper extremitiesDistal arm 2 inches above elbow, elbow up to axilladeg","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"36b43626-f928-486f-b724-abecea127f62","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ccd7142dbbd4c4d8b034be22d33568bd','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"13ea1b71-7d4f-4dec-babf-485274305ed8","subjectId":"surgery","chapter":"جراحی","prompt":"Injury to which of the following vessels is least likely to result in significant damage:","options":["Renal aery","Superior mesenteric aery","Inferior mesenteric aery","Celiac trunk"],"correctIndex":2,"explanation":"Ans. c. Inferior mesenteric aeryInjury to inferior mesenteric aery is least likely to result in significant damage among the given options.Occlusion of the inferior mesenteric aery does not always result in irreversible ischaemia of the descending and sigmoid colon, because the marginal aery of the colon usually receives an adequate supply from the left branch of the middle colic aery.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"13ea1b71-7d4f-4dec-babf-485274305ed8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('6135f1ffac3c61d26875a11009792360','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"c25d4907-49a0-4104-83d2-df515cdcf676","subjectId":"surgery","chapter":"جراحی","prompt":"A Iaday 35 years old lactating mother Presented with a Painful breast lump. Most appropriate initial investigation should be:","options":["Mammography","USG","MRI","X-ray"],"correctIndex":1,"explanation":"Ans. b. USG(Ref Sutton''s Radiology 7/e p1456; Schwaz 9/e p467; Sabiston 19/e p2035-p846) Indications of Breast Ultrasound: ,Itton''s Radiology 7/e p1456)Symptomatic breast lump in women < 35 yearsBreast lump during lactation and pregnancyAssessment of mammographic abnormality (+- fuher mammographic views)Assessment of MRI or scintimammography detected lesionsClinical breast mass with negative mammogramBreast inflammationAugmented breast (together with MRI)","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c25d4907-49a0-4104-83d2-df515cdcf676","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('954e5d7cb32395e191fef6f208fb2cf5','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"fda4a6bd-3eb5-4641-88da-513b72c1d320","subjectId":"surgery","chapter":"جراحی","prompt":"A young healthy male patient presented with abdominal pain and history of altered bowel habits from the last 6 months. On CT examination, there was dilated distal pa of ileum, thickened ileocecal junction with thickened cecum with presence of sacculations on the antimesenteric border. The vascularity of adjoining mesentery is also increased and there is surrounding mesentery fat. Which of the following is not a differential diagnosis?","options":["Ulcerative colitis","Crohn''s disease","Tuberculosis","Ischemic bowel disease"],"correctIndex":3,"explanation":"Answer- D. Ischemic bowel diseaseCT scans associated with bowel ischemia include dilation of the bowel lumen, bowel wall thickening abnormal bowel wall enhancement, aerial occlusion, venous thrombosis, and intramural or poal venous gasDilation of an ischemic bowel segment suggests interruption of normal peristaltic activity.Symmetrical bowel wall thickening greater than 3 mm in a distended segment.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"fda4a6bd-3eb5-4641-88da-513b72c1d320","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9d9d4e5a3a8386876c5182061219ab86','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"4720c165-03b3-4a1a-9e51-1f36c0bcd1be","subjectId":"surgery","chapter":"جراحی","prompt":"In esophageal varices bleeding, which of the following is not used?","options":["Endoscopy banding","Octreotide","Platelet transfusion","TIPS"],"correctIndex":2,"explanation":"Answer- C. Platelet transfusionBeta-blockersEndoscopic sclerotherapyEndoscopic variceal ligation (banding)A medication called octreotide - will lower the pressure in the swollen veins by tightening the blood vessels and reducing blood flow.Transjugular intrahepatic poosystemic shunt (TIPS) procedure is another potential treatment option for recurrent bleeding esophageal varices","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4720c165-03b3-4a1a-9e51-1f36c0bcd1be","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e4ddbc94ff66b8fcd876c7cd03bf4f4f','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"23022df5-e07c-40f9-9f79-b3adff072f5e","subjectId":"surgery","chapter":"جراحی","prompt":"Marathon runner had pain in anteromedial tibia on regular walking/jogging for long hours. X ray is normal. Doctor orders a bone scan. What may be the probable diagnosis","options":["Jones fracture","Shin splint","Lisfranc fracture","Nutcracker"],"correctIndex":1,"explanation":"Answer: B. Shin splintShin splints (medial tibial stress syndrome) is an inflammation of the muscles, tendons, and bone tissue around your tibia.Pain typically occurs along the inner border of the tibia, where muscles attach to the bone.Shin splint pain most often occurs on the inside edge of your tibia","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"23022df5-e07c-40f9-9f79-b3adff072f5e","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7fec0b313ddce71fd0c454f1d35b4037','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"01cc2fa2-924b-4470-8ef2-a85b934cedb1","subjectId":"surgery","chapter":"جراحی","prompt":"Judet view of X-ray is for:","options":["Calcaneum","Scaphoid","Shoulder","Pelvis"],"correctIndex":3,"explanation":"Ans: D. Pelvis(Ref Maheshwari 5/e p38, 369)Judet''s view of X-ray - For acetabular (pelvic) fracture.Judet''s views:Standard radiographic projections employed in acetabulum fractures patients.Basically 45\" oblique of affected hip.45\" angle best achieved by rolling patient.Uses:Generally only performed as supplementary view.Useful in demonstrating or confirming acetabular fractures in acute injury cases.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"01cc2fa2-924b-4470-8ef2-a85b934cedb1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('04691580edeff0cf71ee45f70bccb730','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"fb136952-1310-4610-aff7-95e8b923ffd9","subjectId":"surgery","chapter":"جراحی","prompt":"Which of the following is not removed in radical neck dissection","options":["Sternocleidomastoid muscle","Digastric muscle","Spinal accessory nerve","Internal jugular vein"],"correctIndex":1,"explanation":"Answer- B. Digastric muscle* The radical neck dissection consists of removal of all five lymph node groups of one side of the neck (levels I-V).* This includes removal of the sternocleidomastoid muscle, the internal jugular vein, and the spinal accessory nerve.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"fb136952-1310-4610-aff7-95e8b923ffd9","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7bc700094c70ada1e586863f3c778df2','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"131f5cb9-45ff-4698-992a-dfb143a3c237","subjectId":"surgery","chapter":"جراحی","prompt":"The given below device is/used for:","options":["Pneumatic compression stocking","Varicose vein","Hypothermia","Cellulitis"],"correctIndex":0,"explanation":"Pneumatic compression stocking is used to prevent DVT in patients with immobilization for longer duration of time. These are helpful in patients at moderate risk for DVT as a prophylactic measure but these are not effective against established thrombosis. It is used especially in bariatric population and can be used in their room, operation room or post-operative area. - DVT should be initially managed by heparin or low-molecular-weight heparin. - Long-term management is done by anti-coagulation with warfarin. - Inferior vena cava filter is indicated for patients not benefiting from medical treatment.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"131f5cb9-45ff-4698-992a-dfb143a3c237","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('dcc256ee803874f2f3f8fe8c15ebd0fe','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"285a31c4-9b01-416d-956d-82fa46d60bbb","subjectId":"surgery","chapter":"جراحی","prompt":"Percentage of surgical site infection in patients with clean contaminated wound after prophylactic antibiotic?","options":["1-2%","<10%","10-20%","20-30%"],"correctIndex":1,"explanation":"Wounds classification: Clean - 5% Clean contaminated - 10% Contaminated - 20-30% Diy - 30-40% Wounds Class Definition I: Clean Uninfected operative wound without inflammation Respiratory, alimentary, genital or infected urinary tract is not entered Wounds are closed primarily, if necessary drained with closed drain Examples of Clean Wound Inguinal hernia Joint replacement Thyroidectomy Mastectomy Abdominal aoic aneurysm (AAA) repair II: Clean contaminated Operative wound in which respiratory tract GIT or genitourinary tract is entered under controlled condition without unusual contamination Examples of Clean Contaminated Wound Cholecystectomy CBD exploration Elective GI surgeries (elective colonic resection, gastrectomy) III: Contaminated Open, fresh accidental wounds Operations with major break in sterile techniques Gross spillage from GIT Incision in which acute non-purulent inflammation is encountered Examples of Contaminated Wound Spill during elective GI surgery Perforated gastric ulcer Appendicular perforation Penetrating abdominal trauma Enterotomy during bowel obstruction Human bite Open fracture TYPE OF SURGERY INFECTION RATE WITH PROPHYLAXIS IN % INFECTION RATE WITHOUT PROPHYLAXIS IN % CLEAN(no viscus opened) 1-2 1-2 CLEAN CONTAMINATED (viscus opened, minimal spillage) 3 6-9 CONTAMINATED (open viscus with spillage or inflammatory disease) 6 13-20 DIY (pus/perforation/incision through abscess) 7 40 Table no. 5.4 from Bailey and love''s Sho practice of surgery, 27 Ed , Pg no-53","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"285a31c4-9b01-416d-956d-82fa46d60bbb","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9d39fabf676a1c77f305377ef71e12dd','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"38eb248f-7849-45e2-ac3c-6cb74c930f3e","subjectId":"surgery","chapter":"جراحی","prompt":"A Young Male complained of intermittent pain , swelling and discharge at the base of spine. He also had episodes of fever and repeated abscesses that had burst spontaneously , in recent past. By occupation , he is a jeep driver. On physical examination, diagnosis of pilonidal sinus was made. Which flap-based procedure is used for pilonidal sinus surgery?","options":["Rhomboid flap","Circular flap","Free flap","Rotational flap"],"correctIndex":0,"explanation":"Pilonidal sinus surgery - excision of pilonidal sinus and cyst and repair of defect by flap. Flaps used: 1. Limber''s flap 2.Karydakis flap 3. Rhomboid flap 4. Bascom procedure","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"38eb248f-7849-45e2-ac3c-6cb74c930f3e","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7392430012f701006be73ff177ab74b1','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"b2fbf8f3-4379-40fe-83ac-c1deb1b5c045","subjectId":"surgery","chapter":"جراحی","prompt":"Haglund''s deformity is seen in which joint?","options":["Elbow","Wrist","Knee","Ankle"],"correctIndex":3,"explanation":"Answer- D. AnklePrbminence of posterosuperior poion of calcaneus leading to heel pain is called Haglund deformity.A Haglund deformity, or pump bump, is caused by chronic inflammation of the adventitious superficial pretendinousAchilles bursa that separutes the Achilles tendon from the overlying skin.\"-Campbell''s operative","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b2fbf8f3-4379-40fe-83ac-c1deb1b5c045","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('62791c0288cd7869684a2120efeb7789','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"eae98f93-8d7a-4920-9c80-298de99d64a8","subjectId":"surgery","chapter":"جراحی","prompt":"Which of the following does not cause head and neck squamous cell carcinoma","options":["Alcohol","Betel nut","HPV","EBV"],"correctIndex":3,"explanation":"Answer- D .EBVThe most impoant risk factors for developing HNSCC are tobacco smoking and alcohol consumption.Consumed in betel quids containing areca nut increases the risk of developing HNSCC.HNSCCs of the oral cavity and oropharynx, are becoming more prevalent, which may be related to an increase in oral and oropharyngeal HPV infection.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"eae98f93-8d7a-4920-9c80-298de99d64a8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('35a4da5385672d94484786d64fab8bbd','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"876554c4-4b7a-4093-b3a4-13ed7262578e","subjectId":"surgery","chapter":"جراحی","prompt":"Which metabolic condition has phosphaturia and osteomalacia?","options":["Fibrosarcoma","Osteosarcoma","Undifferentiated sarcoma","Malignant peripheral nerve sheath tumor"],"correctIndex":0,"explanation":"Ans: A. FibrosarcomaPhosphatonin (FGF-23) oncogenic osteomalacia (paraneoplastic syndrome) seen in fibrosarcoma.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"876554c4-4b7a-4093-b3a4-13ed7262578e","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('91ffa76d13d5cb12c9afaa961d6eed0c','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"6343810a-6571-4662-b3a6-aa7e13a7c65b","subjectId":"surgery","chapter":"جراحی","prompt":"How will you check the functioning of an ICD tube?","options":["By observing for continuous air bubbles coming out of the underwater drain","By observing the movement of air water column in the tube during respiration","By taking X ray chest repeatedly","By auscultation"],"correctIndex":1,"explanation":"Chest drainage system: Follow-up: Patency of chest tube is assessed by observing the oscillations in water seal chamber with respiratory movements. Position of chest tube & resolution of intrapleural air or liquid is checked by x-ray (AP & cross table lateral). Tube should be pulled back if it crosses the mediastinum Removal: Chest tubes are generally removed when there has been air or fluid drainage of 24 hours .","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6343810a-6571-4662-b3a6-aa7e13a7c65b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5ed17bb94c9d293341a4918a93a39628','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"216bbc8e-3544-417f-8104-c9508f5b5db5","subjectId":"surgery","chapter":"جراحی","prompt":"Which pa of 2nd metatarsal is involved in the March fracture?","options":["Head","Neck","Shaft","Base"],"correctIndex":1,"explanation":"Answer- B. NeckMost common site of stress fracture or March fracture is second metatar''sal neck.likely site for stress fracturces are common in distance runners and ballet dancers. The second metatarsal neck is the most likety sitefor stressfractures, but all metatarsals are susceptible","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"216bbc8e-3544-417f-8104-c9508f5b5db5","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('a3194ba6a896f1bf5c76cba7be34b14e','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"5dd3fc6a-7e12-4899-a250-102f79d9a7fd","subjectId":"surgery","chapter":"جراحی","prompt":"Most common functional tumors of endocrine pancreas?","options":["Vipoma","Gastrinoma","Glucagonoma","Somatostatinoma"],"correctIndex":1,"explanation":"Answer- B. GastrinomaInsulinoma is the most common functional tumour but if that wasnt there in the optios then gastrinoma is the next answer.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"5dd3fc6a-7e12-4899-a250-102f79d9a7fd","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ebe0f9216ab31e91331b62eb7298ff8b','reference-medmcqa-preinternship-surgery-en-1','surgery','جراحی','medium','{"key":"2ef81315-d954-4729-87c9-20a5d20da4a8","subjectId":"surgery","chapter":"جراحی","prompt":"On massive blood transfusion the following complication occurs-","options":["Respiratory acidosis","Metabolic acidosis","Metabolic alkalosis","Respiratory alkalosis"],"correctIndex":2,"explanation":"Answer- C. Metabolic alkalosisBanked blood has a pH of 6.8 and is acidotic.After massive transfusion citrate in the stored blood is conveed into bicarbonate resulting in metabolic alkalosis.Other complications are-HypokalemiaHypothermiaHypocalcemiaRef: Transfusion Medicine and Hemostasis: Clinical and Laboratory Aspects By Christopher D. Hillye, Page 291 ; Yao and Ausio''s Anesthesiology: Problem-Oriented Patient Management By Fun-Sun F. Yao, 6th Edition, Page 1148","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"2ef81315-d954-4729-87c9-20a5d20da4a8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-medmcqa-residency-dermatology-en-1','پوست · منتخب MedMCQA','residency','reference','medmcqa',NULL,'منبع باز',1793577600000,0,'MedMCQA — Pal, Umapathi & Sankarasubbu, 2022. Validation split via Open Life Science AI; Apache-2.0. متن اصلی انگلیسی؛ آزمون رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('08f0e4bad1652482b75d343751acd2b5','reference-medmcqa-residency-dermatology-en-1','dermatology','پوست','medium','{"key":"f6bb3faa-6ccb-4838-a2d9-1ae2f2d63e7d","subjectId":"dermatology","chapter":"پوست","prompt":"Which type of oral candidiasis does not presents with white patch?","options":["Chronic atrophic candidiasis","Chronic hyperplastic candidiasis","Chronic mucocutaneous candidiasis","Pseudomembranous candidiasis"],"correctIndex":0,"explanation":"Ans: A. Chronic atrophic candidiasisChronic erythematous (atrophic) candidiasis appears as a red, raw-looking lesion instead of a white patch seen in all other types.Erythematous (atrophic) candidiasis:Appears as a red, raw-looking lesion.Subtypes of erythematous candidiasis:Denture-related stomatitis, angular stomatitis, median rhomboid glossitis & antibiotic-induced stomatitis.Since they are commonly erythematous/atrophic.Precede pseudomembrane formation,.Left when membrane is removed, or arise de novo.Tongue:Loss of lingual papillae, leaving a smooth area on tongue.Occurs on dorsum of tongue in long-term coicosteroids or antibiotic patient.But occasionally it can occur after only a few days of using a topical antibiotic.This is usually termed ''antibiotic sore mouth/stomatitis'' because it is commonly painful as well as red.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f6bb3faa-6ccb-4838-a2d9-1ae2f2d63e7d","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d85adba47b6ef9c6088a6169a828febf','reference-medmcqa-residency-dermatology-en-1','dermatology','پوست','medium','{"key":"c8d2885b-1529-4575-abcd-b8afdfb64512","subjectId":"dermatology","chapter":"پوست","prompt":"A young female presented with vaginal itching and green frothy genital discharge. Strawberry vagina is seen on examination. What w ill be the drug of choice?","options":["Doxycycline","Oral fluconazole","Metronidazole","Amoxicillin"],"correctIndex":2,"explanation":"Answer- C. MetronidazoleHistory of vaginal itching and green frothy genital discharge in a young female with strawberry vagina on examinstion ishighly suggestive of Trichomoniasis. The drag of choice for Trichomoniasis is metronidazole.Treatment:DOC: Metronidazolea (tinidazole is also effective)All sexual paners must be treated concurently to prevent reinfection","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"c8d2885b-1529-4575-abcd-b8afdfb64512","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('a5158f7a877328e0044f166260329340','reference-medmcqa-residency-dermatology-en-1','dermatology','پوست','medium','{"key":"0c970c10-c97d-4025-b24d-e70245231e41","subjectId":"dermatology","chapter":"پوست","prompt":"A patient came with history of joint pain and fever for one week. For which the patient took NSAIDS foilowing which he developed rash and hyperpigmentation on nose. What is the most likelv diagnosis?","options":["Dengue","fixed Drug eruption","Chikungunya","melasma"],"correctIndex":2,"explanation":"Ans : C ChikungunyaRef: Hypapigmqtdion and &ilangurwfetEn &hasnw A\" An has Demaor 20 I 6;9 I :g60-I r.Chikungunya fever (cF) is an acute febrile illness presenting with symptoms like intense asthenia, ahralgia, myalgia and headache and is caused by chikungunya virus (CV).Among the skin lesions, maculopapular rash is common, but seen in several viral illnesses, therefore, not useful in suspecting CF.Hyperpigmentation is a unique feature noted in CF.Hyperpigmentation associated with CF is macular and most commonly affects nose and cheeks.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0c970c10-c97d-4025-b24d-e70245231e41","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7d344470ce77382c50916578fd8a7c50','reference-medmcqa-residency-dermatology-en-1','dermatology','پوست','medium','{"key":"725d9973-1082-4c9b-b4fb-9c63a4615e63","subjectId":"dermatology","chapter":"پوست","prompt":"Postherpetic neuralgia is defined as pain lasting beyond how many weeks?","options":["1 week","2 weeks","3 weeks","4 weeks"],"correctIndex":3,"explanation":"Ans: D. 4 weeks(Ref Fitzpatrick 6/e p2302, 7/e p490-493, 1873-1898; Rooks 8/e p33.14-33.22; Roxburgh 18/e p52-54).Post-herpetic neuralgia (PHN):Most common & impoant neurologic complications of herpes zoster.Defined as pain after the rash has healed or pain 1 month or 3 months after rash onset.Best answer would be 4 weeks.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"725d9973-1082-4c9b-b4fb-9c63a4615e63","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('28bc5142a8b93707adfe8c5315c68044','reference-medmcqa-residency-dermatology-en-1','dermatology','پوست','medium','{"key":"aa677f5e-3b2c-4ec8-8b77-78610a8a38cf","subjectId":"dermatology","chapter":"پوست","prompt":"Treatment of choice for erythrodermic psoriasis:","options":["Methotrexate","Coicosteroids","Coal tar topical","Topical steroids"],"correctIndex":0,"explanation":"Ans: A. Methotrexate (Ref Fitzpatrick 6/e p2676)Methotrexate or oral retinoids (Acitretin) - DOC for erythrodermic psoriasis management.Current use of methotrexate to treat psoriasis is most common in patients with severe or refractory plaque-type disease that requires systemic treatment.It is also very useful for erythrodermic and pustular psoriasis, as well as psoriatic ahritis.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"aa677f5e-3b2c-4ec8-8b77-78610a8a38cf","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('13e248bbf2ecd1f0dc8b2f5755898ea8','reference-medmcqa-residency-dermatology-en-1','dermatology','پوست','medium','{"key":"6f78cdec-b48a-497c-bf8d-6b5b9b083ecf","subjectId":"dermatology","chapter":"پوست","prompt":"A 45 years old male presents with itchy papules over face, neck and V area of chest for the last three years, which are exacerbated in summers and improved in winters. What test will you do to confirm diagnosis?","options":["Patch test","Prick test","IgE levels","Skin biopsy"],"correctIndex":0,"explanation":"Ans: A. Patch test(Ref: Rooks 8/e p26.93, Fitzpatrick 6/e p1451, 1309)The clinical picture mentioned above is suggestive of air-borne contact dermatitis, which is a type of allergic contact dermatitis.Most common source is Pahenium exposure and it leads to dermatitis involving the exposed pas, i.e. Face, upper neck, cubital and popliteal fossa.The only useful and reliable methodfir the diagnosis of allergic contact dermatitis remains the patch test.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6f78cdec-b48a-497c-bf8d-6b5b9b083ecf","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1e2297ede4cb12126174b92c48d6b5b0','reference-medmcqa-residency-dermatology-en-1','dermatology','پوست','medium','{"key":"26124571-60c3-4509-9c33-981bc3b40054","subjectId":"dermatology","chapter":"پوست","prompt":"Maculopapular rash is not seen in ?","options":["Dengue","Rubella","measles","Zoster"],"correctIndex":3,"explanation":"Ans. D. ZosterMaculopapular rashes are seen in:* Rubella* Dengue(febrile phase)* Measles* Chikungunya (acute infectious phase)* Erythema infectiosum* Zika virus* West nile virus* Infectious mononucleosis","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"26124571-60c3-4509-9c33-981bc3b40054","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('8c49d55f302c8303db164c218415a1e7','reference-medmcqa-residency-dermatology-en-1','dermatology','پوست','medium','{"key":"105be08b-3a40-4e47-831d-f8cae8b90240","subjectId":"dermatology","chapter":"پوست","prompt":"A child presented with complaint of severe itching over the web of fingers, more at night. Examination revealed burrows. Most probable diagnosis is:September 2009","options":["Tinea cruris","Scabies","Infantile eczema","Papular uicaria"],"correctIndex":1,"explanation":"Ans. B: ScabiesScabies is essentially a disease of the children. The itching appears a few days after infestation. It may occur within a few hours if the mite is caught a second time.The itch is characteristically more severe at night and affects the trunk and limbs.It does not usually affect the scalp.Burrow is the pathognomic lesion of scabies.Scabies burrows appear as tiny grey irregular tracks between the fingers and on the wrists.They may also be found in armpits, buttocks, on the penis, insteps and backs of the heels. Microscopic examination of the contents of a burrow may reveal mites, eggs or mite faeces (scybala).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"105be08b-3a40-4e47-831d-f8cae8b90240","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('52d49d646c784a2fb3990960502e44f4','reference-medmcqa-residency-dermatology-en-1','dermatology','پوست','medium','{"key":"0f49668c-7988-48a6-ba11-ad49aa561259","subjectId":"dermatology","chapter":"پوست","prompt":"A man presents it n rashes on face and also complains of decreased mental function. He is also having few macular lesions on his skin. On CT scan, intracranial calcification was seen. His wife is normal. His 10-year old daughter is also normal but his 6-year old son is also having similar skin lesions. What would be the most likely diagnosis?","options":["Neurofibrornatosis-1","Neurofibromatosis-2","Xeroderma pigmentosum","Autosomal dominant inheritance"],"correctIndex":3,"explanation":"Answer- D. Autosomal dominant inheritanceClinical findings like rashes on face, decreased mental function with macular lesions on the skin and intracranial calcification on CT scan is highly suggestive of tuberous sclerosis, which has an autosomal dominant condition.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0f49668c-7988-48a6-ba11-ad49aa561259","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('0b2dbb8603b086b935969cc20ccac465','reference-medmcqa-residency-dermatology-en-1','dermatology','پوست','medium','{"key":"ce4876e4-6a17-465e-a1c4-6353dad02e85","subjectId":"dermatology","chapter":"پوست","prompt":"A 12 years old boy came with complaints of 4 hypopigmented patches on back and on left arm. The patches had loss of sensation. Which of the following is the treatment for this case?","options":["Rifampicin (450 mg) + Dapsone (50 mg) + Clofazimine (150 mg) monthly and 50 mg daily","Rifampicin (600 mg) + Dapsone (150 mg) only","Rifampicin (450 mg) + Dapsone (50 mg) + Clofazimine (150 mg) monthly and 50 mg alternate days","Rifampicin (600 mg) + Dapsone (150 mg) + Clofazimine (300 mg) monthly and 50 mg daily"],"correctIndex":2,"explanation":"Answer- C. Rifampicin (450 mg) + Dapsone (50 mg) + Clofazimine (150 mg) monthly and 50 mg alternate daysThe clinical history fits the patient into multibacillary leprosy and requires extensive multidrug therapy for 12 months.Since the patient is aged 12 years, doses are Rifompicin (450 mg) * Dapsone (50 mg) + Clofazimine (150 mg) monthly and 50 mg alternate days.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ce4876e4-6a17-465e-a1c4-6353dad02e85","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('444b5c82403935534454f91e482d6199','reference-medmcqa-residency-dermatology-en-1','dermatology','پوست','medium','{"key":"53cc935b-3123-4b83-ad62-307b2b736c9e","subjectId":"dermatology","chapter":"پوست","prompt":"After sequential arrangement of blistering disorder staing from superficial to deep blisters, which is the deepest among these?","options":["IgA pemphigus","EBD","PV","Bullous pemphigoid+"],"correctIndex":2,"explanation":"Ans. C. PVPemphigus vulgaris (PV) is a rare and serious (potentially life-threatening) condition that causes painful blisters to develop on the skin and lining of the mouth, nose, throat and genitals.The blisters are fragile and can easily burst open, leaving areas of raw unhealed skin that are very painful and can put you at risk of infection.H&E: Subepidermal bullaeDIF: linear IgG and C3 deposition at the basement membrane zone","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"53cc935b-3123-4b83-ad62-307b2b736c9e","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-medmcqa-residency-ent-en-1','گوش، حلق و بینی · منتخب MedMCQA','residency','reference','medmcqa',NULL,'منبع باز',1793577600000,0,'MedMCQA — Pal, Umapathi & Sankarasubbu, 2022. Validation split via Open Life Science AI; Apache-2.0. متن اصلی انگلیسی؛ آزمون رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('f90f063626ad0f6f3f240cd2b02ba815','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"671eebea-f741-4ed8-bf68-36e36c8de1eb","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Noise induced hearing toss inosto affects:","options":["Inner hair cell","Outer hair cell","Macula","Cupula"],"correctIndex":1,"explanation":"Ans. b. Outer hair cell Noise induced hearing loss mostly affects outer hair cell.\"Noise induced hearing loss (NIHL) causes damage to hair cells, staing in the basal turn of cochlea. Outer hair cells are affected before the inner hair cells.\"\"Noise-induced hearing loss damages hair cells, which begin at the basal turn of cochlea. Outer hair cells are affected earlier than the inner hair cells.\"","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"671eebea-f741-4ed8-bf68-36e36c8de1eb","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('290179cc549b748ac89fd4936dbeef00','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"38810794-2735-4239-b36f-d9a509a2997f","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"According to the WHO definition of hearing loss, what is the value to classify as profound hearing loss?","options":["61-71 dB",">81 dB",">91 dB",">101 dB"],"correctIndex":1,"explanation":"Ans: B. >81 dB(Ref: http://wwwwlio.intipbaideulne.ssilieuring_impairment_gracies/en/)According to the WHO (2008) definition of hearing loss, hearing threshold in better ear >81 dB is classified as profound hearing loss.WHO (2008) Classification of Degree of Hearing LossHearing threshold in better ear (average of 500, 1000, Grade of Impairment0-25No impairment26-40Milddeg impairment41-60Moderatedeg impairment61-80SevereQ impairment>81Profound impairment including","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"38810794-2735-4239-b36f-d9a509a2997f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('02b8771c6f609fd8e6e7664aba07a6d7','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"624cf635-1421-416e-978a-996781f350c0","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"A 60-year old male presents with painful, 141 oupet. vesicles over erythematous plaques in T3 dermatome region of trunk. Which of the following would be the most likely causative organism?","options":["Varicella zoster","Herpes simplex","Pox virus","Papilloma virus"],"correctIndex":0,"explanation":"Ans. a. Varicella zosterA 60-year-old male presents with painful, grouped vesicles over erythematous plaques in T dermatome region of trunk. Varicella zoster is the most likely causative organism.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"624cf635-1421-416e-978a-996781f350c0","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2f1bd2c2cdf1d19020ed07481111de63','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"16ce8442-864b-43f1-b815-f9096e55fa54","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"First paranasal sinus to develop at bih is:","options":["Maxillary","Ethmoidal","Frontal","Sphenoidal"],"correctIndex":0,"explanation":"Development of SinusesSinusGestational Month WhenDevelopment StasPresent in ClinicallySignificant SizeFully DevelopedMaxillary2degBihdeg12 yearsdegEthmoid30Bihdeg12 yearsdegFrontal4deg3 yearsdeg18-20 yearsdegSphenoid3deg8 yearsdeg12-15 yearsdeg","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"16ce8442-864b-43f1-b815-f9096e55fa54","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f6faf1028b2b36000730720cd19a8591','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"b192b045-d178-4bbf-8796-3c26dae548f3","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Topical treatment for recurrent respiratory papillomatosis includes:","options":["Acyclovir","Cidofovir","Ranitidine","Zinc"],"correctIndex":1,"explanation":"Ans: B. Cidofovir(Ref Dhingra 74, p346, 6/c, p305).Cidofovir:Topical treatment for recurrent respiratory papillomatosis (Incomplete in stopping tumor growth).Mostly injected to control frequency of tumor growth.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b192b045-d178-4bbf-8796-3c26dae548f3","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('17789d7a32d2e6349a8d6794ecc9405d','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"8b538660-2509-4f93-a358-104099bb3cb8","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"The wave '' V '' in BERA represents activity in which of the following ?","options":["Lateral lemniscus","Superior olivary complex","Cochlear nerve","Cochlear nucleus"],"correctIndex":0,"explanation":"The wave ''V'' in BERA represents activity in lateral lemniscus.Auditory brainstem response (ABR):Is used to elicit brainstem responses to auditory stimulation by clicks or tone bursts.It is a non-invasive technique to find the integrity of central auditory pathways through the VIIIth nerve, pons and midbrain.The first, third and fifth waves are most stable and are used in measurements.Wave V Generation of wave V reflects the activity of multiple anatomic auditory structures. The sharp positive peak of wave V arises mainly from the lateral lemniscus, following slow negative wave represents the dendritic potential in the inferior colliculus.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"8b538660-2509-4f93-a358-104099bb3cb8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1e41d484107216eab8d525d2a1f90b4a','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"ec1866a1-00c2-425a-8886-ff7321defbd9","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Which focal length in the objective piece of microscope is commonly used for ear surgery?","options":["100mm","250 mm","450mm","950 mm"],"correctIndex":1,"explanation":"Focal length of objective lens: For ear surgery - 200 mm/ 250 mm For Nose / Paranasal sinus surgery - 300 mn For Laryngeal surgery-400 mn","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ec1866a1-00c2-425a-8886-ff7321defbd9","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('0e5d60cb1d8c2030df983581cb7c26ea','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"be68160f-1668-4576-abcc-882aa211beb3","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"A patient has bilateral conductive deafness, tinnitus with positive family history. The diagnosis is -","options":["Otospongiosis","Tympanosclerosis","Meniere''s disease","B/L otitis media"],"correctIndex":0,"explanation":"Conductive deafness means the disease process leading to deafness is limited to external ear tympanic membrane, middle ear including the footplate of stapes. Bilateral conductive deafness rules out meniere’s disease (as it presents with SNHL). Amongst the remaining three options, positive family history is seen mainly in case of otosclerosis (Otospongiosis), so it is our answer. Ref. Dhingra 6/e, p 30, 87","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"be68160f-1668-4576-abcc-882aa211beb3","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1e8e8018603db56166edf9576ba7a3f3','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"ac97880a-0862-45cf-bed5-a2000a93343c","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"The treatment of choice for stage I cancer larynx is-","options":["Radical surgery","Chemotherapy","Radiotherapy","Surgery followed by radiotherapy"],"correctIndex":2,"explanation":"Friends remember 2 very important concepts regarding laryngeal Ca: If the site of larynx caner viz supra glottis, glottis or subglottis is not mentioned, the cancer should be considered glottic (since it is the M/C variety) Generally stage I, II, III, IV means stage T1 , T2 , T3 , T4 respectively. According to Dhingra Radiotherapy is the treatment of choice for all stage I cancers of larynx, which neither impair mobility nor invade cartilage or cervical nodes. The greatest advantage of radiotherapy over surgery in Ca larynx glottic cancer is - preservation of voice.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ac97880a-0862-45cf-bed5-a2000a93343c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3a0a3fb68bfbfbbd9c7c443a8ff32781','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"97ed634a-a034-41a1-b92d-3781331b6f5a","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Which of the following sinus grows till early adulthood:-","options":["Maxillary","Ethmoidal","Frontal","Sphenoid"],"correctIndex":2,"explanation":"Development of paranasal sinuses Sinus Present at bih 1st X-Ray appearance, Adult size Maxillary Yes 4-5 months after bih 15-18 yrs. Ethmoid Yes 1yr 12yr Sphenoid Yes 6-7yr 15yr Frontal No 4-5yr 18yr","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"97ed634a-a034-41a1-b92d-3781331b6f5a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('df78b8948d66397e0452dad198307695','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"6ace03e9-b26c-455d-a158-71cbf9a0854b","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"The main vessel involved in bleeding from Juvenile nasopharyngeal angiofibroma:","options":["Facial aery","Ascending pharyngeal aery","Internal maxillary aery","Anterior ethmoidal aery"],"correctIndex":2,"explanation":"Ans: C. Internal maxillary aery(Ref Dhingra 7/e p281-282, 5/261-263)Juvenile Nasopharyngeal Angiofibroma:MC benign tumor of nasopharynx (but overall angiofibroma rare).MC site:Posterior pa of nasal cavity close to the margin of sphenopalatine foramen.Seen exclusively in males of 10-20 years.Testosterone dependent tumor - Seen in pre-pubeal to adolescent males.Features:Locally invasive vasoformative tumor consisting of endothelium lined vessels with no muscle coat.Main feeding vessel in most cases = Internal maxillary aery.Internal maxillary aery - External carotid aery branch.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6ace03e9-b26c-455d-a158-71cbf9a0854b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ea450498bc4f385ddf243fdb3e8bfd55','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"e584f190-0cb1-4ef7-9e2a-e4f0ccc8e01b","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Cranial nerve that is not involved in olfaction:-","options":["Glossopharyngeal","Vagus","Hypoglossal","Trigeminal"],"correctIndex":2,"explanation":"Olfaction - 1. Ohonasal (odor in inspired air) 2. Retro nasal (odor in expired air) Food in mouth - swallowing and deglutition 1. Chorda tympani (branch of facial nerve): taste from anterior 2/3rd tongue 2. Lingual nerve: pain, tactile and temperature from anterior tongue 3. Greater superficial petrosal nerve: taste from palate 4. 9th and 10th CN: taste from posterior tongue and throat CN 5,7,9 & 10 help to regulate olfaction. Add smell to taste. Hypoglossal nerve that is pure motor nerve supply muscle of tongue.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e584f190-0cb1-4ef7-9e2a-e4f0ccc8e01b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('be0cb8db04442f974ecb4c8b2b390c97','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"b9e53e10-851b-41bd-b2e3-0ddc302ffd99","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"A patient of carcinoma larynx with stridor presents in casualty, immediate management is -","options":["Planned tracheostomy","Immediate tracheostomy","High dose steroid","Intubate, give bronchodilator and wait for 12 hours, if no response, proceed to tracheostomy"],"correctIndex":1,"explanation":"Carcinoma larynx presenting with stridor means it is subglottic laryngeal carcinoma .Ideally in such cases emergency laryngectomy should be performed. “In the case of a large subglottic tumour presenting with respiratory obstruction a case could be made for doing an emergency laryngectomy.” But it is not given in the options: Intubation can not be done as growth is seen in subglottic area therefore tube can not be put. Planned tracheostomy can not be done as patient is suffering from stridor, which is an emergency. Therefore we will have to do emergency tracheostomy. With the precaution that the area of cancer should be removed within 72 hours.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b9e53e10-851b-41bd-b2e3-0ddc302ffd99","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('df6785a07030c59328da58c627f9c8c5','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"751d9564-7804-41b2-a03d-210ffdcba7d6","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Pharyngeal Pseudosulcus is seen secondary to-","options":["Vocal Abuse","Laryngopharyngeal Reflux","Tuberculosis","Corticosteroid usage"],"correctIndex":1,"explanation":"Vocal Sulcus/Laryngeal Sulcus It is a groove along the mucosa and can be classified into three types: Laryngeal sulcus","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"751d9564-7804-41b2-a03d-210ffdcba7d6","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('678f73f9220bb3dac5200e7e3dab1454','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"4bab5fce-dd4d-4196-906d-11354ffa1c8d","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Which of the following is not a cause of Squamous cell Carcinoma for Head & Neck:","options":["EBV","HPV","Betel Nut","Vitamin A"],"correctIndex":3,"explanation":"Risk factors for head and neck cancer Tobacco Alcohol Prolonged sun exposure Viruses (HPV) & (EBV) Gender M>F, age > 40yrs Poor oral / dental hygiene; betel nut consumption Environmental or occupational factors Poor nutrition - vitamin A & B deficiency, iron deficiency In question they have mentioned vitamin A NOT vitamin A deficiency","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4bab5fce-dd4d-4196-906d-11354ffa1c8d","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9bab74003aef965d25556bfd86e63ef8','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"04f192d7-760b-468b-a895-658b0efeb566","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Arrange the sequence of auditory pathway from peripheral to central: Inferior colliculus Cochlear nucleus Auditory coex Medial geniculate body","options":["B>A>D>C","B>D>C>A","A>D>B>C","C>A>B>D"],"correctIndex":0,"explanation":"Auditory neural pathway. From below upwards are ( Mnemonic - E. COLI-MA) E - Eighth nerve (vestibulocochlear nerve) C - Cochlear nucleus (spiral ganglion) O - Superior Olivary complex (opposite) L - Lateral lemniscus (largest) I - Inferior colliculus M - Medial geniculate body A - Auditory coex E - 8th nerve COLI - Brainstem MA - Cerebrum Crossing over phenomenon takes places at Superior Olivary complex","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"04f192d7-760b-468b-a895-658b0efeb566","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('efc633fd32bc9839401af64e2832df6f','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"99f08890-7505-4062-9293-1f135de62e5c","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"A 16-year-old male complains of nasal obstruction and recurrent epistaxis for several months. On CT scan of Nose and Paranasal Sinuses, an enhancing mass is seen in the nasopharynx with minimal extension into sphenoid sinus and no lateral extension. What is the stage of this lesion?","options":["IA","IB","IIA","IIB"],"correctIndex":1,"explanation":"Session''s/ Radowski staging for Juvenile Nasopharyngeal angiofibroma Stage I Stage I a Limited to nasal cavity / nasopharynx Stage I b Extension into one or more sinuses. Stage II Stage II a Minimal extension into pterygopalatine fossa pterygomaxillary fissure. Stage II b Fills pterygomaxillary fossa, bowing the posterior wall of maxillary antrum anteriorly extending into the orbit the inferior orbital fissure without orbital erosion. Stage II c Infratemporal fossa extension without check or pterygoid plate involvement. Stage III Stage III a Erosion of skull base (middle cranial fossa or pterygoids) with minimal intracranial spread. Stage III b Erosion of skull base with intracranial extension with or without cavernous sinus involvement.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"99f08890-7505-4062-9293-1f135de62e5c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f5314e33b36d0976da604e7f7913b539','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"4d1e7661-fffc-42d0-8bed-1e4ecc040fe8","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"A 35 years old female patient present with hearing loss with improvement in hearing in noisy environment. On examination Rinne''s is negative and weber''s is centralized. Following is the audiometry repo. What is the most likely diagnosis:","options":["Meniere''s disease","Perilymph fistula","Stapedial Otosclerosis","Vestibular Schwannoma"],"correctIndex":2,"explanation":"POINTS OURING STAPEDIAL OTOSCLEROSIS: - Conductive hearing loss. - MC seen in females 20-30 yrs. - hears better in noisy surrounding (Paraacusis willisii) - Audiometry repo a dip at 2000Hz (Carha''s notch) Meniere''s disease causes SNHL. Perilymph fistula will cause SNHL. Vestibular schwannoma also will cause SNHL.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4d1e7661-fffc-42d0-8bed-1e4ecc040fe8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f956b5382165c579e319ea4cb7f6c409','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"fd03f7de-6c4a-4244-97c6-12829919c1ed","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"female patient came with right side hearing loss, better heard in a noisy environment,Audiogram shown with about 30-40 dB gap between AC-BC of right & left ear. Rinne''s test negative, Weber''s test centralised. Which of the following condition shown?","options":["Meniere''s disease","stapedial otosclerosis","Presbycusis","Vestibular schwannoma"],"correctIndex":1,"explanation":"Answer-B- stapedial otosclerosisIn otosclerosis the normal dense endochondral layer of the bony otic capsule gets replaced by irregularly laid spongy bone. Most common site is fissula ante fenestram (anterior tothe oval window)Age group affected is 20-45 years (maximum between 20-30 years). Male:female ratio is 1:2.meniere''s disease i.e Endolymphatic hydrops leads to SNHL and not conductive hearing loss.Tuning ForkTests in Otosclerosis: Rinnes test-negative ,Weber''s test-lateralized to ear with greater conductive loss.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"fd03f7de-6c4a-4244-97c6-12829919c1ed","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('957d5f0e20e829156a7779ff5313c341','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"d1ef23c9-e756-4ae2-a91c-992fa658c4c3","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Immediate treatment of CSF Rhinorrhoea requires-","options":["Antibiotics and observation","Plugging with paraffin guage","Blowing of nose","Craniotomy"],"correctIndex":0,"explanation":"Early cases of post traumatic CSF rhinorrhea are managed conservatively (by placing the patient in propped up position, avoiding blowing of nose, sneezing and straining) and Prophylactic antibiotics (to prevent meningitis). Persistent cases are treated surgically by nasal endoscopy or by intracranial route. According to Scott-Brown’s Endoscopic closure of CSF leak is now the treatment of choice in majority of patients but it should not be done immediately. First patient should be subjected to diagnostic evaluation and after site of leakage is confirmed, it should be closed endoscopically.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d1ef23c9-e756-4ae2-a91c-992fa658c4c3","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1dc76400e757000a5e768ed0e22c94af','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"86e26dc5-2f48-45b1-82df-b14ffbc11fcb","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Which is the most common site for congenital cholesteatoma","options":["Anterior superior quadrant of tympanic membrane","Posterior superior quadrant of tympanic membrane","Anterior inferior quadrant of tympanic membrane.","posterior inferior quadrant of tympanic membrane"],"correctIndex":0,"explanation":"Ans: A .Anterior superior quadrant of tympanic membrane followed by posterior superior quadrant.Congenital cholesteatoma was defined as a white, pearly lesion behind an intact tympanic membrane, which after removal was identified on pathological examination as a cholesteatoma.It is the more common causes for onset of childhood conductive hearing loss unrelated to middle ear effusion.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"86e26dc5-2f48-45b1-82df-b14ffbc11fcb","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3fd74eff547e9d8c4bf30288d15407f9','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"6beed60d-08f5-4efa-bd22-4a6901e451a2","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Most common cause for nose bleeding is-","options":["Trauma to little''s area","A.V. aneurysm","Postero superior part of nasal septum","Hiatus - semilunaris"],"correctIndex":0,"explanation":"Little area (also called as Kiesselbach’s plexus) is a highly vascular area in the anteroinferior part of nasal septum just above the vestibule It is the most common site for nasal bleeding as this area is exposed to the drying effect of inspiratory current and to finger nail trauma.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6beed60d-08f5-4efa-bd22-4a6901e451a2","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d08b033a510718ec9430d184ef6b9b70','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"1fc80d00-8929-4d18-9f07-25d005ceec59","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Best surgery to relieve intractable veigo in a menieres disease patient is?","options":["Surgical Labyinthectomy","Vestibular neurectomy","Endolymphatic sac decompression","Cochleosacculotomy"],"correctIndex":0,"explanation":"Gold standard treatment for intractable veigo in patient of Menier''s disease - Surgical Labyinthectomy Rx of Menier''s disease Acute episode: Labyrinthine sedatives Maintenance phase Medical K+sparing diuretics B blockers Antihistamines Surgical Conservative :Decompression of endolymphatic sac ,Vestibular neurectomy. Radical :Surgical Labyinthectomy Intratympanic Gentamycin therapy Silverstein microwick microcatheter Meniett''s device","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"1fc80d00-8929-4d18-9f07-25d005ceec59","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5bed8147e2053f7a867fb3ab98045476','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"8f57df40-4509-4083-a86d-d53e7bcaf328","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Olympian brown and rhagdes are seen in-","options":["CMV inclusion disease","Ectodermal dysplasia","Congenital syphilis","Hyper IgE syndrome"],"correctIndex":2,"explanation":"Ans. c. Congenital syphilisClinical Presentation of SyphilisEarly Congenital Syphilis:Snuffles (rhinitis)Q is earliest feature.Lesions are vesicobullousQ, and snail track ulcers on mucosaClinical Presentation of SyphilisLate Congenital Syphilis:Characterized by Hutchinson''s triad (interstitial keratitis + 8th nerve deafness + Hutchinson''s teeth i.e. peggedcentral upper incisors)QSaddle nose, sabre tibia, mulberry molarsQBull dog''s jaw (protrusion of jaw)Rhagadesdeg (linear fissure at mouth, nares)Frontal bossing, hot cross bun deformity of skullClutton''s jointdeg (painless swelling of joints, most commonly both knee)Palatal perforationdegHigaumenakis sign (periostitis leads to unilateral enlargement of sterna end of clavicle)Primary Syphilis:Painless, indurated, nonbleeding, usually single punched out ulcer (hard chancre)QPainless, rubbery shotty lymphadenopathySecondary Syphilis:Bilateral symmetrical asymptomatic localized or diffuse mucocutaneous lesiondeg (macule, papule, paulosquamousand rarely pustule)Non-tender generalized lymphadenopathyQHighly infectious condylomata late, in warm moist interiginous areasMoth eaten alopecia, ahritis, proteinuriaQTeiary Syphilis:Gumma, neurosyphilis/tabes dorsalisQOstitis, periostitisAoitis, aoic insufficiency, coronary stenosis and nocturnal anginaQ","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"8f57df40-4509-4083-a86d-d53e7bcaf328","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('43ffcea08a1cbcd82737c6819dfe0107','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"b3554a03-5d0e-42ef-8033-6b3062193ae1","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Kamla 4 yrs of age presented in emergency with mild respiratory \"stress. On laryngoscopy she was diagnosed to have multiple juvenile papilomatosis of the larynx. Next line of management is -","options":["Tracheostomy","Microlaryngoscopy","Steroid","Antibiotics"],"correctIndex":1,"explanation":"The patient (a 4 years girl) in the question is presenting with mild respiratory distress due to multiple Juvenile papillomatosis of larynx. The management in such a case is microlarygoscopic surgery using CO2 laser to ablate the lesion. Steroids and antibiotics have no role. Tracheostomy is reserved for those patients who have severe respiratory distress.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b3554a03-5d0e-42ef-8033-6b3062193ae1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2efe7884e6bb116b6863fe6da7d2eab4','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"99f0588d-fd2b-405a-ac4e-5615d0533fff","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Patient underwent surgery at the lateral pa of the skull. Postoperatively patient had aspirations without voice change","options":["Vagus","RLN","Glossopharyngeal","SLN"],"correctIndex":3,"explanation":"Ans. D (Superior Laryngeal nerve)* Vagus, RLN involvement leads to hoarseness of the voice* SLN divide into internal and external laryngeal* External laryngeal nerve supplies only one muscle- cricothyroid - tensor* Internal laryngeal nerve- safety nerve of larynx- prevents aspiration and supplies supraglottic pa of larynx.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"99f0588d-fd2b-405a-ac4e-5615d0533fff","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f7cab77153cc71b3e8be4d47b3942caf','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"357eebd0-e51d-46c8-8cc4-0fff4a79387b","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Eustachian tube function is best assessed by:","options":["Tympanometry","VEMP","Rhinomanometry","Politzer test"],"correctIndex":0,"explanation":"Ans: A. Tympanometry(Ref Dhingra 7/e p62-63, 6/e p59)Assessment of eustachian tube function:Tympanometry & Politzer test.Tympanometry better than Politzer test.Tympanometry:Positive & negative pressures created in external ear canal.Patient swallows repeatedly.Normal tubal function:Ability of tube to equilibrate positive & negative pressures to ambient pressure.Done both in patients with perforated or intact tympanic membrane.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"357eebd0-e51d-46c8-8cc4-0fff4a79387b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('c0131baad7e47188a0aabe66e1fbf68e','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"09b9375c-41ee-4295-ad27-2a11074d4434","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Angio fibroma is classified as what stage if it extends to one or more paranasal sinuses","options":["Stage I","Stage II","Stage III","Stage IV"],"correctIndex":0,"explanation":"Staging of angiofibromaRadkowski Classifications:I ALimited to nose and/or nasopharyngeal vaultBExtension into 1 paranasal sinusIIAMinimal extension through sphenopalatine foramen intosphenopalatine/pterygomaxillary fossaBFills sphenopalatine fossa bowing the posterior wall of themaxillary antrum anteriorly or extending into the orbit theinferior orbital fissure.CExtends beyond sphenopalatine fossa into infratemporal fossaIllAErosion of skull base-minimal intracranial extensionBErosion of skull base-Extensive intracranial extension with orwithout cavernous sinus invasion.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"09b9375c-41ee-4295-ad27-2a11074d4434","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('60e55709cc498077f67d70cc9a021f29','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"a86db080-2d2a-4eb2-abb0-11de110167f8","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"An elderly male presents with T3NO laryngeal carcinoma. What would be the management?","options":["Neoadjuvant chemotherapy followed by radiotherapy","Concurrent chemoradiotherapy","Radical radiotherapy followed by chemotherapy","Radical radiotherapy without chemotherapy"],"correctIndex":1,"explanation":"Ans. b. Concurrent chemoradiotherapyAn elderly male presents with T3N0 laryngeal carcinoma. Treatment is concunent chemoradiotherapy.''Advanced laryngeal cancers are ofien treated by combining radiation with concurrent chemotherapy for larynxpresemation and total laryngectomy for bulky T4 disease or salvage.''''Concurrent radiation therapy plus Cisplatin resulted in a statistically higher percentage ofpatients with an intact larynxat I0 years.''","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a86db080-2d2a-4eb2-abb0-11de110167f8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f3221bf89a9c6b9341c14e58f2517c61','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"a43a0fc3-9d61-45a2-8ebd-f90bb31af019","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Which of the following is not the branch of external carotid aery in Kiesselbach''s plexus?","options":["Anterior Ethmoidal aery","Sphenopalatine aery","Greater palatine aery","Septal branch of superior labial aery"],"correctIndex":0,"explanation":"NASAL SEPTUM Internal Carotid System 1. Anterior ethmoidal aery 2. Posterior ethmoidal aery External Carotid System Branches of ophthalmic aery 1. Sphenopalatine aery (branch of maxillary aery) gives Nasopalatine and posterior medial nasal branches. 2. Septal branch of greater palatine aery (branch of maxillary aery). 3. Septal branch of superior labial aery (branch of facial aery). LATERAL WALL Internal carotid System 1. Anterior ethmoidal 2. Posterior ethmoidal External Carotid System Branches of ophthalmic aery 1. Posterior lateral nasal branches 2. Greater palatine aery 3. Nasal branch of anterior superior dental 4. Branches of facial aery To nasal vestibule From sphenopalatine aery From maxillary aery From infraorbital branch of maxillary aery","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a43a0fc3-9d61-45a2-8ebd-f90bb31af019","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('21e8414c0e5b5158f92604b86b81878e','reference-medmcqa-residency-ent-en-1','ent','گوش، حلق و بینی','medium','{"key":"69f1a181-5580-4146-ba87-bbd3980f948c","subjectId":"ent","chapter":"گوش، حلق و بینی","prompt":"Which of the following vessel is not ligated in case of epistaxis control?","options":["Maxillary aery","Anterior ethmoidal aery","Internal carotid aery","External carotid aery"],"correctIndex":2,"explanation":"Answer- C. Internal carotid aerySurgical ligation of vessels or embolization is the last reso to control epistaxis when all other methods fail. Internal carotid aery is not ligated in case of epistaxis control, as it is the msinvessel supplying the central nervous system.\"Endoscopy identifies the source of posterior epistaxis in over 80 percent of the cases. Ligation should be performed as close as possible to the likely bleeding point. Thus the hierarchy of ligation is: Sphenopalatine aery; internal maxillary aery; external carotid aery; anterior/posterior ethmoidal aery.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"69f1a181-5580-4146-ba87-bbd3980f948c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-medmcqa-residency-epidemiology-en-1','اپیدمیولوژی · منتخب MedMCQA','residency','reference','medmcqa',NULL,'منبع باز',1793577600000,0,'MedMCQA — Pal, Umapathi & Sankarasubbu, 2022. Validation split via Open Life Science AI; Apache-2.0. متن اصلی انگلیسی؛ آزمون رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('07908da2604ea64c1d6c8fd2afa68fcc','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"f0f91922-12fd-4213-871c-19e47532a6d6","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"In a study, two groups of newborns are checked for their weights based on whether their mothers received food supplements or not. The appropriate test which can be used for comparing the data is:","options":["Chi square test","Paired T-test","Student''s T-test","Fischer exact test"],"correctIndex":2,"explanation":"Ans: C. Student''s T-test(Ref Park 22/e p795; Biostatistics by Mahajan 7/e p134)Here, comparing a parametric quantitative variable (weight) in two unrelated group of people.Hence, \"Student''s t-test\" used.Student t-test:Used when outcome variable is normally distributed in population (for quantitative data).Ex: BP, blood glucose.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f0f91922-12fd-4213-871c-19e47532a6d6","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1dab270db556268d62a8a27ecf87d3a7','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"ddb3f2a6-295a-4d4b-8478-5c15049b62a8","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Which of the following committees has recommended a 3-year bachelor degree in medical education for rural health service?","options":["High level expe group of universal health program for india","Central bureau of health investigation","Srivastava committee","Sundar committee"],"correctIndex":0,"explanation":"Answer- A. High level expe group of universal health program for indiaConcept of 3 years bachelor para-medical course for rural health service was proposed by Ministry of health and family welfare and received backing of Planning Commission of India''s High level expe group of universal health program.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ddb3f2a6-295a-4d4b-8478-5c15049b62a8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d36d72c11732907e7198ec524fab2ec5','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"fe1ce20a-009c-45a2-8279-bff1d2e4abcf","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"The blood pressure data of 200 persons were collected. The first quaile BP of the data was 94 mm Hg and third quaile was 110 mm. How many patients have blood pressures between the 3rd and 4th quaile?","options":["25","50","100","200"],"correctIndex":1,"explanation":"Ans: B. 50Quaile:Type of quantile.In descriptive statistics - Quailes are ranked set of data values.Are 3 points dividing data set into four equal groups.Each group comprising quaer of data.1stquaile (Q1):25'' percentile (splits off lowest 25% of data from highest 75%).2ndquaile (Q2):50'' percentile (cuts data set in half).3rdquaile (Q3):75\" percentile (splits off highest 25% of data from lowest 75%).Interquaile range (IQR):Difference between upper & lower quailes.IQR = Q3 - Q1.Per question:Between every two quailes one/ fouh of total number of patients present.I.e. 200/4 = 50 patients.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"fe1ce20a-009c-45a2-8279-bff1d2e4abcf","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('18d44a87020c8fdcb6af860b4824044e','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"6506849d-8885-4adf-88b7-4e010e026d6c","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Denominator in perinatal moality rate","options":["Total bihs","Total live bihs","Live bihs + Still bih","Total number of newborns"],"correctIndex":0,"explanation":"Ans: A. Total bihs* PERINATAL MOALITY RATE is the sum of the number of resident fetal deaths of 28 or more weeks gestation plus the number of resident newborns dying under 7 days of age in a specified geographic area (country, state, county, etc.) divided by TOTAL BIHS includes the sum of the number of resident live bihs plus the number of resident fetal deaths of 28 or more weeks gestation for the same geographic area (for a specified time period, usually a calendar year) and multiplied by 1,000.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6506849d-8885-4adf-88b7-4e010e026d6c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('4309e00adda1258c212e88fd0667e415','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"2902efec-b01a-417c-94b9-406e94662f27","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"According to the new RNTCP guidelines, the following is not a suspect of tuberculosis","options":["Confirmed extra-pulmonary tuberculosis patient with cough of 2 weeks or more","HIV-positive patient with cough of any duration","Contacts of sputum positive tuberculosis patient with cough of any duration","Any individual having cough of duration 2 weeks or more"],"correctIndex":0,"explanation":"Ans: A. Confirmed extra-pulmonary tuberculosis patient with cough of 2 weeks or more(Ref: Park 24/e p188-189, 23/e p178: 22/e p 168; htip://tbcindia.nic.in)A contact of confirmed extra-pulmonary tuberculosis patient - TB suspect.If persistent cough of any duration (2 weeks is not required).TB suspects:Pulmonary TB Suspect:Defined as:Any individual having cough of >2 weeks.Contacts of smear positive TB patients having cough of any duration.Suspected/confirmed extra-pulmonary TB patient having cough of any duration.HIV-positive patient having cough of any duration.MDR-TB Suspect:Any TB patient who fails an RNTCP Category failing I or III treatment regimen.Any RNTCP Category II patient with sputum smear positive at end of 4th month of treatment or later.Close contacts of MDR-TB patients with smear positive pulmonary TB.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"2902efec-b01a-417c-94b9-406e94662f27","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('82978844974e41e4c6d4fc3683e21d5a','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"f5f3cd4b-3180-4f0e-b585-d681407b89d0","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"A study was conducted to find average intra-ocular pressure. IOP was measured in 400 people and the mean was found to be 25 mm Hg with a standard detion of 10 mm Hg. What is the range in which 10P of 95% of the population would be lying?","options":["22-28 mm Hg","20-30 mm Hg","24-26 mm Hg","23-27 mm Hg"],"correctIndex":2,"explanation":"Ans: C. 24-26 mm HgStandard error, SE = {standard detion / n)}n = sample sizeC= Confidence coefficient = 1.96 for 95% confidence interval = 2.58 for 99% confidence interval= 3.29 for 99.9% confidence intervalHence in this question, n = 400SD = 10SE = 10/400 = 10/20 = 0.5Mean statistic = 25 mm Hg.Now for 95% confidence interval,C = 2 approximately 95%CI = 25 - 2x0.5 to 25 + 2x0.5 = 24-26 mm HgHence, 95% CI of IOP = 24 to 26 mm Hg.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f5f3cd4b-3180-4f0e-b585-d681407b89d0","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('01822fb69802519bdae8a7884f3b1a0c','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"b0d97337-7157-40c6-984d-87e24959fa80","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Child Pugh score put patients into three categories of Score A (<7), Score B (7-9) and Score C (10-15). The following is a type of which scale?","options":["Nominal","Ordinal","Quantitative","Continuous"],"correctIndex":1,"explanation":"Child Pugh Score'' divides the scores into 3 CATEGORIES, hence it is a CATEGORICAL scale. The variables are qualitative and arranged in an order of increasing severity, hence it is an example of ORDINAL scale. Other options: Nominal scale is also a type of categorical scale in which the variables are not arranged in any order. Metric scale is used for quantitative variables. Continuous is a type of variable and not a type of scale.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b0d97337-7157-40c6-984d-87e24959fa80","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('62096d524d1945a030e6c91d392dee0c','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"796e190d-09a8-4eef-98a4-26eecd5b7de7","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Data about recent trends of immunization in the community can be found by:","options":["Sample registration system","District level health survey","Rural survey","Census data"],"correctIndex":1,"explanation":"Ans: B. District level health survey(Ref Park''s 22/e p786)District Level Health Survey - Objectives:Coverage of ante-natal, natal and post-natal checkups and child immunization.Propoion of institutional/safe deliveries.JSY beneficiaries.Contraceptive prevalence rates.Unmet need for contraceptives - Spacing & limiting.Awareness about I/ STI and HIV/AIDS.Ministry of Health and Family Welfare (MOHFW), Government of India, has included the Clinical, Anthropometric and Biochemical (CAB) component for data collection in the District Level Household Survey (DLHS)-4.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"796e190d-09a8-4eef-98a4-26eecd5b7de7","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b1f5cabc6d785bf0fc82935ac71b29df','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"9220447e-0ac6-41b7-b22d-07d1340b3641","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Case control study was done regarding breast cancer & risk factors & odds ratio was obtained. Which of the following are causative factors ?ParameterCaseControlORAge at menarche>12171423291.04Menopause177124081.53OCP use93511051.02Smoking932140.97Family history5135021.10BMI>27.51654930.53Breastfeeding94225140.56Multiparity(2)277833661.05","options":["6","5","3","2"],"correctIndex":1,"explanation":"Ans. (B) 5An odds ratio (OR) is a statistic that quantifies the strength of the association between two events, A and B.Two events are independent if and only if the OR equals 1: the odds of one event are the same in either the presence or absence of the other event.If the OR is greater than 1, then A and B are associated (correlated) in the sense that, compared to the absence of B, the presence of B raises the odds of A, and symmetrically the presence of A raises the odds of B.Conversely, if the OR is less than 1, then A and B are negatively correlated, and the presence of one event reduces the odds of the other event.Most Impoantly Odds ratio does not demonstrate causality .But we can say that they are positively correlated. Since 5 Factors have odds ratio more than 1 so the answer will be B","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"9220447e-0ac6-41b7-b22d-07d1340b3641","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('273864e5d01816aafb893f5b8866f85f','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"2166e021-8b96-47ad-9e4d-fa55a623938b","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Tuberculin test is a cheap and easily available test. In which of the following situations there is high failure in the interpretation of the test?","options":["High percentage of immunized people","HIV cases are less","High prevalence of disease","Environmental mycobacterium infections are less"],"correctIndex":0,"explanation":"Ans: A. High percentage of immunized people(Ref Park 24/e p195-196, 23/e p186)High failure of tuberculin test:High percentage of immunized people - Due to higher BCG coverage producing tuberculin hypersensitivity.Exaggerated responses:In presence of atypical mycobacteria infection & ''boosting effect'' of second tuberculin dose producing larger reaction than 1st.Tuberculin test lost its sensitivity as an indicator of true prevalence of infection.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"2166e021-8b96-47ad-9e4d-fa55a623938b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('08fa9136f9c1a049cd4e87439115398f','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"1acc9c45-12a8-4fd0-92e6-c7980c21348a","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Which of the following parameters is used to determine the sensitivity of vaccine due to heat?","options":["VVM","VMV","VCM","VMM"],"correctIndex":0,"explanation":"Ans: A. VVMRef: K Park, 23''d ed, pg. 110VVM (Vaccine Vial Monitor)VVM is a label containing a heat-sensitive material which is placed on a vaccine l to register cumulative heat exposure over time.It has outer blue circle and inner white square.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"1acc9c45-12a8-4fd0-92e6-c7980c21348a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('da1df00bb4a08c277a77acd9ccaeb5bb','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"1badc5bb-d61a-48ea-9288-3754612f74a5","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"In a JubLeitter arca pith crude bih rate of 211, what would be the expected number of ANC registrations?","options":["60","80","100","120"],"correctIndex":0,"explanation":"Ans. a. 60In a subcenter area with crude bih rate of 20, the expected number of ANC registrations should be approximately 55.Number of Expected Pregnancies per Year Expected no. of live-bihs (Y)/year= Bih rate (per 1000 population) x Population of the area/1000 Number of Expected Pregnancies per YearAs some pregnancies may not result in a live bih (i.e., aboions & stillbih may occur), the expected number of live bihs would be an under-estimation of the total number of pregnancies. Hence, a correction factor of 10% is required, i.e., add 10% to the figure obtained above.Total number of Expected Pregnancies Z = Y + 10% of YPopulation under the subcentre = 5000Bih rate = 20Expected no. of live-bihs (Y)/year = 20 x 5000/1000 = 100Total number of Expected Pregnancies Z = Y + 10% of Y =100 + 10% of 100 = 110Expected number of ANC registrations will be half of yearly calculation = 55","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"1badc5bb-d61a-48ea-9288-3754612f74a5","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('c0ec4eaffb018b69f2cae0dd06c20cc5','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"fc83df2a-e58c-4bb9-b4e8-d20541d3f9c4","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"The prevalence of disease in a population is expected to be 50%. An investigator is interested in the range of 45 to 55% with 95% confidence. The minimum sample size required for the study is:","options":["100","200","300","400"],"correctIndex":3,"explanation":"Answer- D (400)In this question, use Standard Error of propoions.The 95% confidence limits for a propoion are p +- 1.96 s.e.p, where s.e.p is the standard error of a propoion.p = sample propoion = propoion of diseased persons = 0.5 q = 1-p = 0.5 s.e.p .NI(p x q / n) Now here, the range of propoions with 95% confidence is mentioned as? 45-55%Hence, 2 s.e.p = 0.55-0.50 = 0.05 s.e.p = 0.0250.025= J(pxq/n)n = 400Thus, the sample size required will be 400.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"fc83df2a-e58c-4bb9-b4e8-d20541d3f9c4","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5a28caafb140ca1cbd921323fdbfea99','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"0113aaf1-61d3-4d61-a9c7-b5b46e51e7e8","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"A study finds no significant association between two variables but truly there exists a difference. What type of error is this?","options":["Type I error","Type II error","Random error","Systematic error"],"correctIndex":1,"explanation":"Ans: B. Type II error(Ref: High Yield Biostatistics/p46)Type I ErrorType II ErrorThe null hypothesis is true but rejected (False positive)degProbability of type I error is given by p valuedegSignificance (alpha) level is the maximum tolerable probability of type I errorsdegKeep type I error to be minimum; then results are declared to be statistically significantNull hypothesis is not false but is not rejected/accepted (false negative)degProbability of type II error is given by betadeg","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0113aaf1-61d3-4d61-a9c7-b5b46e51e7e8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('56e64517887861bfaba3627c52458c91','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"23d97589-5dbe-4c51-b3ff-3d102f13d781","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Crude Bih rate for a sub-center is 20. What the number of pregnant woman registered in sub-center?","options":["80","100","110","60"],"correctIndex":3,"explanation":"Population of a sub-centre =5000 Crude bih rate= 20 per 1000 mid-year population Therefore, no. of bihs= 20/1000 x 5000=100 Pregnancy wastage factor = 10% (i.e. not all pregnancies result in a live bih, and roughly 10% ANC women have a \"wastage\" of their pregnancy. Therefore, total ANC= 100+ =110 As a thumb rule, Minimum number of ANC that should be registered at a time= 50%. - Min. No. registered in the sub-centre= 110 x 50/100=55 ~ ~60","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"23d97589-5dbe-4c51-b3ff-3d102f13d781","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ce1fea07b0f65db19d4e59a5247a88df','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"bbb8ca0b-54ed-4f08-a87d-8eef087e37f1","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Human Developmental Index is a composite measure, which uses?","options":["Life expectancy at age one, literacy and infant moality","Freedom, spice and right to express oneself","Life expectancy at bih, infant moality and quality of life","Life expectancy at bih, knowledge and decent standard of living."],"correctIndex":3,"explanation":"Ans: D. Life expectancy at bih, knowledge and decent standard of living.(Ref Park 24/e p17, 23/e p17)Human Development Index (HDI):Published on 4 November 2010.Updated on 10 June 2011.Composite statistic of life expectancy, education & income indices.Used to rank countries into 4 tiers of human development. 2010 HDI Repo:Combines three dimensions:A long & healthy life: Life expectancy at bih.Education index: Mean years of schooling and Expected years of schooling.A decent standard of living: GNI per capita (PPP US$).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"bbb8ca0b-54ed-4f08-a87d-8eef087e37f1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('286d6c60ab0aee00dcbc445e0216672a','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"484de2a0-f89b-4e79-88c3-11cb2da4fcde","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"If the distribution of intra-ocular pressure (IOP) seen in 100 glaucoma patients has an average 30 mm with a SD of 1.0, what is the lower limit of the average IOP that can be expected 95% of times?","options":["26","28","32","259"],"correctIndex":1,"explanation":"In the given question, Mean (μ) = 30 mm and SD (σ) = 1.0 mm Thus, 95% values are contained in the range of Mean ± 2 SD (µ ± 2σ) or 30 ± 2 (1) So, 95% values are contained in the range 30 – 2 mm and 30 + 2 mm OR between 28 and 30 mm.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"484de2a0-f89b-4e79-88c3-11cb2da4fcde","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('12a4cb4bb0dfb2bdaf3cc564c0dfd907','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"1348a664-1ccc-422f-a083-91d77cb24b92","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Natural disaster causing maximum deaths","options":["Hydrological","Meterological","Geological","Fires"],"correctIndex":0,"explanation":"Ans is ''a'' i.e. Hydrological DisasterA \"disaster\" can be defined as ''any occurrence that causes damage, ecological disruption, loss of human life or deterioration of health and health services on a scale stiffly-lent to warrant an extraordinary response from outside the affected community or area''.* A \"hazard\" can be defined as any phenomenon that has the potential to cause disruption or damage to people and their environment. - There are many types of disasters such as eahquakes, cyclones, floods, tidal waves, landslides, volcanic eruptions, fires, snowstorms, building collapse, toxicologic accidents, and warfare, etc.* Hydrological disasters (i.e. floods, tsunamis) are associated with causing a maximum death toll. Geological disasters: includes Eahquakes, Avalanches & Volcanic eruptionsMeteorological disasters: include Cyclones, Tornadoes, Hailstorms, Drought, Heatwaves, Blizzards (Blizzards are severe winter storms characterized by low temperature, strong winds, and heavy snow).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"1348a664-1ccc-422f-a083-91d77cb24b92","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('a480520295100524dd55dbf7bcff2843','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"764c0c80-b716-45a1-9fe7-b13588090401","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Central value of a set of 180 values can be obtained by","options":["2nd tertile","90th percentile","2nd quartile","9th decile"],"correctIndex":2,"explanation":"Quartile: Divides a distribution into 4 equal parts, so the number of intercepts required will be 3, i.e. Q1, Q2, Q3 – So, Zero – Q1 covers 25% values – Similarly, Q2 – Q1, Q3 – Q2 and 100 – Q3 all cover 25% values each – Thus, Q2 – Zero, 100 – Q2 and Q3 – Q1 all cover 50% values each – Q1 divides a distribution in a ratio of 25 : 75 OR 1 : 3 – Q2 divides a distribution in a ratio of 50 : 50 OR 1 : 1, Thus second quartile is equivalent to median – Q3 divides a distribution in a ratio of 75 : 25 OR 3 : 1. In the given question, n = 180 Thus Q2 which is equivalent to median, divides a distribution in a ratio of 50 : 50 OR 1 : 1.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"764c0c80-b716-45a1-9fe7-b13588090401","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2d94c2371ced0a54476858c3f678711b','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"ae3aa91a-4bfb-42a5-b8f6-7f8217e18fb0","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"You went to a sub center as pa of an audit. How many infants should be registered with a health worker working there?","options":["50","100","150","200"],"correctIndex":1,"explanation":"Ans: B. 100Ref: K Park, 23d ed., pg. 524, 567Estimated no. of infants in a health sub centre covering 5000 population can be calculated as follows:No. of live bih = Bih rate x Population/ 1000= 20.4 x 5000/1000 = 102Infant moality for sub centre = No. of live bih x IMR/1000= 102 x 34/1000= 3.5 (for calculation purpose we assume it 4)Therefore, total number of infants = 102 -- 4= 98Hence correct answer is 100 (nearest value).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ae3aa91a-4bfb-42a5-b8f6-7f8217e18fb0","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5f7498456045a01ed925ed2f233a1379','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"007d53f1-6364-4482-b62e-5b51134a222c","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"A child has received full Rabies vaccination in December 2018 and now presented with oozing wound on Great toe and the pet had vaccination also. Next line of management is","options":["No vaccine required","RIG + 5 doses of vaccine","5 doses of vaccines only","2 doses of Rabies vaccine"],"correctIndex":3,"explanation":"According to NRCP 2015,National Rabies prophylaxis Guidelines (NRPG) says even the pet is vaccinated, no chance is taken, Rabies is 100% Fatal disease. So, Pet''s vaccination status is not so relevant in India guidelines Post exposure prophylaxis. 2 IM doses of Rabies vaccine on Day 0,3. Day 0 3 7 14 28 ESSEN Regimen IM 1 1 1 1 1 THAI updated ID Red close R. 2 2 2 0 2 All these vaccinations come under primary level prevention & specific protection. New Recommended Regimens/ Schedules { NEW GUIDELINES} Type of prophylaxis Regimen POST EXPOSURE INTRAMUSCULAR Essen Regimen (1-1-1-1-1) Day 0,3,7,14,28 POST EXPOSURE INTRADERMAL Updated Thai Red Cross Regimen (2-2-2-0-2) Day 0,3,7,28 POST-EXPOSURE IN VACCINATED INDIVIDUALS Day 0,3 PRE-EXPOSURE PROPHYLAXIS Day 0,7,21/28","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"007d53f1-6364-4482-b62e-5b51134a222c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('500096878536119924ca2277e35a938d','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"7c6fe266-845b-4f4b-8ddb-ca5d016e0396","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Key indicator for AFP surveillance ?.","options":["At least one case of non-polio AFP per year per 1000 population of under 5 years","At least one case of non-polio AFP per year per 100000 population of under 5 year","At least one case of non-polio AFP per year per 1000 population of under 15 years","At least one case of non-polio AFP per year per 100000 population of under 15 years"],"correctIndex":3,"explanation":"Ans.d) At least one case of non-polio AFP per year per 100000 population of under 15 years The number of AFP cases repoed each year is used as an indicator of a country''s ability to detect polio, even in countries where the disease no longer occurs. Polio surveillance It is the most impoant pa of whole polio eradication intiative. It has two components:?Acute flaccid paralysis (AFP) surveillanceAcute flaccid paralysis is defined as acute onset (< 4 weeks) of flaccid paralysis (reduced tone) without other obvious cause in children WHO recommends the immediate repoing and investigation of every case of AFP in children less than 15 years.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"7c6fe266-845b-4f4b-8ddb-ca5d016e0396","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3a36af2220a81a1f829cfd5b8aad8a4a','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"f8f510ef-4928-4806-ba2a-f984e29463c8","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Which of the following is the best for determining the threshold for diagnosis of a positive test?","options":["Analysis of variance","Pearson coefficient","Receiver-operating characteristic curve","Pre-test probability"],"correctIndex":2,"explanation":"Ans: C. Receiver-operating characteristic curve(Ref http:ilvvwwlexjansen.com/nesteg/ne.sug10/hl/h107.pdf)Receiver-operating characteristic (ROC) curve:Defined as a plot of test sensitivity as they coordinate versus its I-specificity or false positive rate (FPR) as the x coordinate.Graphic presentation of relationship between both sensitivity & specificity.Uses:Effective method for evaluating diagnostic test''s performances.Excellent way to compare diagnostic tests.Best for determining threshold for diagnosis of positive test.Helps decide optimal model through determining best threshold for diagnostic test.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f8f510ef-4928-4806-ba2a-f984e29463c8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('7f02e8a9625631fc3af5630460694471','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"4f50899d-3016-461b-bd81-c1c29fbe6d29","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"A psychiatrist is not posted at:","options":["PHC","Military hospitals","District hospitals","Hospitals with medical colleges"],"correctIndex":0,"explanation":"Ans: A. PHC(Ref Park 24/e p944, 23/e p9Ob, 221e p847).A psychiatrist is not posted at PHC.For sub-centre area of PHCApa from the essential staff, the desirable staff for both type A and type B PHC are:One of the two medical officers (MBBS) should be lady doctor, if the delivery case load is 30 or more per month.One AYUSH medical officer to provide choice to the people, where as AYUSH facility is not available in the vicinity.One staff nurse/nurse midwife.One health educator at the PHC.That makes total staff at type A PHC 18 and at type B PHC 21.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4f50899d-3016-461b-bd81-c1c29fbe6d29","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e354bba6d7d1066513b23264f9edfe4d','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"11271a83-0b83-4fb4-b809-05e352546743","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Which of the following is used for selecting patients with respect to potential factors that will affect the results?","options":["Systematic random sampling","Simple random sampling","Stratified random sampling","Cluster sampling"],"correctIndex":2,"explanation":"Ans: C. Stratified random samplingRef. Park 24/e p886, 23/e p850, 22/e p792; BK Malunan 6th/100-101).Stratified random sampling is used for selecting patients with respect to potential factors that will affect the results.Stratified random sample:The sample is deliberately drawn in a systematic way so that each poion of the sample represents corresponding strata of universe.This method is paicularly useful where one is interested in analyzing the data by a ceain characteristic of population, viz. Hindus, Christians, Muslims, age-groups etc.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"11271a83-0b83-4fb4-b809-05e352546743","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('57d74d7af36ced9e838598e16a553297','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"ba54a2e5-0beb-4a2b-a1ec-f34e58a5e679","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Which of the following does not include Specific protection under primary prevention?","options":["Tab Rifampicin to those in contact with meningitis","Health education","Pentavalent vaccination","Wheat flour foified with added iron"],"correctIndex":1,"explanation":"Tab. Rifampicin to the meningitis patients is chemoprophylaxis which is given when a risk factor is present. Hence this is primary level prevention specific protection. Pentavalent vaccines; vaccines are always given when risk factors are present. Primary level prevention with Specific protection. Foification done when there is need or deficiency in a population (risk factors): primary level prevention. Protection from occupational hazards, Road traffic accidents, carcinogens will come under primary level Specific protection. Health education is primordial prevention.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ba54a2e5-0beb-4a2b-a1ec-f34e58a5e679","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('85399cfc991bb4e9ead39145f5245eb4','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"e5b8bc30-3a2c-4d33-8b63-f01d20590f5e","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Annual new case detection rate of leprosy as on 31st March, 2016 is:","options":["0.66 /10,000 population","0.66/1,00,000 population","9.7/10,000 population","9.7/1,00,000 population"],"correctIndex":3,"explanation":"Ans. d. 9.7/1,00,000 populationAnnual new case detection rate of leprosy as on 31\" March, 2016 is 9.7/1,00,000 population.NLEP - Annual Repo for the year 2015-16:Based on the repos received from all the States and UTs for the year of 2015 -16 (Annexure -I), current leprosy situation in the country is as below:A total of 127334 new cases were detected during the year 2015-16, which gives Annual New Case Detection Rate (ANCDR) of 9.71 per 100,000 population, as against 125785 cases in 2014-15.A total of 86028 leprosy cases are on record as on 1st April 2016, giving a Prevalence Rate (PR) of 0.66 per 10,000 population, as against 88833 cases in 1 ''t April 2015.Detailed information on new leprosy cases detected during 2015-16 indicates the propoion of MB (51.27%), Female (38.33%), Child (8.94%), Grade II Deformity (4.60%), ST cases (18.79%) and SC cases (18.57%).A total of 5851 Gr. II disability detected amongst the New Leprosy Cases during 2015-16, indicating the Gr. II Disability Rate of 4.46 / million population (Annexure-II)A total of 11389 child cases were recorded, indicating the Child Case rate of 8.94% (Annexure-III).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e5b8bc30-3a2c-4d33-8b63-f01d20590f5e","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9761611ae07afe0b3461034b918ca386','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"0c9337fa-55ba-4441-8da7-99d451749ccf","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Broken ampula is thrown into which coloured bin?","options":["Red","Yellow","Blue","Black"],"correctIndex":2,"explanation":"Ans. C. BlueCOLOR CODING & TYPES OF CONTAINER: Colour codingType of ContainerWaste CategoryTreatment optionsYellowPlastic BagsHuman and animal wastes, Microbial and Biological wastes and soiled wastes(Cat 1,2,3 and 6)Incineration/ Deep BurialRedDisinfected container/ Plastic bagsMicrobiological and Biological wastes, Soiled wastes, Solid wastes(Cat 3,6,7)Autoclave/ Microwave/ Chemical Treatment)Blue/ White/ TransparentPlastic bag, Puncture proof containerWaste sharps and solid waste( Cat 4 &7)Autoclave/ Microwave/ Chemical Treatment Destruction and ShreddingBlackPlastic bagDiscarded medicines, Cytotoxic drugs, Incineration ash and chemical waste(Cat 5,9 & 10)Disposal in secured land fillsGreenPlastic ContainerGeneral waste such as office waste, food waste & garden wasteDisposed in secured landfills","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"0c9337fa-55ba-4441-8da7-99d451749ccf","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ea3fec7dbcbf439389705c13baea1df4','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"3b261ffc-4ab3-4e68-a7b8-8e3881edfa55","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Pneumococcal vaccine PCV 23 polysaccharide has shown the best results in the following people","options":["Sickle cell anemia","Cystic fibrosis","Child less than 2 year age","Recurrent otitis media and sinusitis"],"correctIndex":0,"explanation":"- PCV 23 vaccine is recommended for, - Older people > 65 years age - 2-64 years age if they have, Chronic cardiovascular disease Chronic pulmonary disease Diabetes mellitus Alcoholic Chronic smokers Chronic liver disease / cirrhosis Asplenia like sickle cell disease or splenectomy Immunosuppressed like HIV Organ transplantation Renal disease / transplantation - For children < 2 years age, PCV- 23 is strictly contraindicated.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"3b261ffc-4ab3-4e68-a7b8-8e3881edfa55","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2fccc740fedf3147792943cf49823f87','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"579951c3-517c-41e4-ac39-0a48f474c01b","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"In a village of 20,000 population 456 bihs occurred in april, 56 showed no signs of life at bih, 56 died before 28 days of life, 34 died between 28 days- 1 year, 500 was total number of deaths in that year. Infant moality rate?","options":["197.4","320","225","125"],"correctIndex":2,"explanation":"Ans.C.225IMR = Number of deaths of children less than 1 year of age in a year X 1000/number of live bihs in the same year.IMR=56+34 X1000/400= 225","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"579951c3-517c-41e4-ac39-0a48f474c01b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('5c8359fac1019d4f037c6a67e76d38fd','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"6a2018d0-b742-44ff-a1df-5d0ce3483984","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"A latex agglutination test for detection of meningitis was approved. Calculate the sensitivity and specificity of the test based on the data given below: Test PositiveTest NegativeDiseased273Non-diseased595","options":["Sensitivity 90% Specificity 95%","Specificity 90% Sensitivity 95%","Sensitivity 80% Specificity 90%","Sensitivity 75% Specificity 95%"],"correctIndex":0,"explanation":"Ans: A. Sensitivity 90% Specificity 95%Sensitivity:Introduced as a statistical index of diagnostic accuracy.Defined as the ability of a test to identify correctly all those who have the disease, that is ''true positive:\"Specificity:Measures the propoion of negatives that are correctly identified as such, e.g., the percentage of healthy people who are correctly identified as not having the condition, that is true negative. Sensitivity = Propoion of persons with the condition who test positive: a /(a + c)`t = 27/30 = 90% .Specificity = Propoion of persons without the condition who test negative: d /(b + d)deg = 95/100 = 95%.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6a2018d0-b742-44ff-a1df-5d0ce3483984","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('4509b12a693d14d9c0154012c90b2488','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"98e20d31-45bf-46c2-80cd-a9020dcaf014","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"A recently delivered woman with a 15 days old child suffering from cough, sneezing and fever needs help. She has no money for transpoation to nearby hospital. Which of the national programme can help this woman?","options":["JSSK","Indira Gandhi YojanaF-IMNCI","F-IMNCI","Home-based Care"],"correctIndex":0,"explanation":"Ans: A. JSSK(Ref Park 24/e p476, 23/e p456, 22/e p420; Shishu Suraksha Karyakaram (JSSK), the national programme can help this woman. Janani-Shishu Suraksha Karyakram (JSSK)The initiative entitles all pregnant women delivering in public health institutions to absolutely free and no expense to delivery, including cesarean section.Includes free drugs and consumables, free diet up to 3 days during normal delivery and up to 7 days for cesarean section, free diagnostics, and free blood wherever required.Provides for free transpo from home to institution, between facilities in case of referral and drop back home.Similar entitlements for all sick newborns & infants accessing public health institutions for treatment till 30 days after bih.Aims to eliminate out of pocket expenses incurred by the pregnant women and sick new borns while accessing services at Government health facilities.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"98e20d31-45bf-46c2-80cd-a9020dcaf014","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('4dace8ac0ef6e532ec07d6ae83173266','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"2cc7bf03-5a41-4a8c-a8c9-9f969afac49f","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Which of the following is the best study design to assess in quick time the strength of association between smoking and lung cancer?","options":["Cross-sectional study","Case controlstudy","Randomized controlled trial","Coho study"],"correctIndex":1,"explanation":"Ans: B. Case controlstudy(Ref: Park 24/e p76, 23Ie p71; 22/c p76).Best study design to assess in quick time the strength of association between smoking and lung cancer is case control study.Permanent method of epidemiological investigation.Case control studies, often called retrospective studies are a common first approach to test causal hypothesis.Distinct features:Both exposure and outcome (disease) have occurred before the sta of study.Study proceeds backwards from effect to cause.Uses a control or comparison group to suppo or refute an inference.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"2cc7bf03-5a41-4a8c-a8c9-9f969afac49f","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('19c508a00d29816d4ea5231f02019189','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"f8c7a8c6-351b-4ffe-b108-dc3363837624","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"A new method of measuring Haemoglobin levels has been developed. Ten successive readings of a single sample are as follows: 9.4, 10.4, 9.6, 9.1, 10.8, 12.1, 10.1, 9.8, 9.2, 9.5. But the Haemoglobin measured by standard calorimetry was 10.2. Therefore the given method has","options":["Low validity, low reliability","High validity, low reliability","High validity, high reliability","Low validity, high reliability"],"correctIndex":1,"explanation":"Reliability is precision (repeatability) and Validity is accuracy (close to true/actual value) In the given question, 10 successive readings are all different and they have a mean value of 9.4+10.4+9.6+9.1+10.8+12.1+10.1+9.8+9.2+9.5/10 = 10.0 Thus it has low reliability (non-consistent) and high validity (close to true/actual value of 10.2)","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f8c7a8c6-351b-4ffe-b108-dc3363837624","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('e5761bfd286465379bf2fba14708fa70','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"4b376e03-6fe0-40fd-b3be-aea6048bf7fa","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Extremely axle insecticide according to WHO classification, are coded as:","options":["Red","Green","Yellow","Blue"],"correctIndex":0,"explanation":"Answer- A. RedExtremely toxic insecticide, according to WHO classification, is coded as Red.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"4b376e03-6fe0-40fd-b3be-aea6048bf7fa","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('8df0bdf03aad05dc583a5d1464325e36','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"112a2f9e-e59f-4ae5-913f-9592aa573e18","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"HIV sentinel surveillance provides data:","options":["To monitor disease trends","To identify high risk population","To estimate disease incidence","To assess the quality of related services"],"correctIndex":0,"explanation":"Ans. a. To monitor disease trendsAlthough the HIV sentinel surveillance data has been primarily used for monitoring the trends, i.e. to assess how rapidly HIV infection increases or decreases over the time in different groups and areas, it can also provide an estimate of the total burden of HIV infection in the counttyHIV Sentinel SurveillanceAfter the establishment of the fact that the HIV infection is present in wide geographic areas, the objective of the sentinel surveillance was redefined to monitor the trends of HIV infectionQThe objective of the surveillance is best achieved by annual cross-sectional survey of the risk group in the same place over a few years by unlinked anonymous serological testing procedures by two ERS (i.e. when HIV testing is carried out without identification of name of samples collected for other purposes such as VDRL in STD clinics.) The number of samples to be screened must represent the risk group under study and the sample size is determined accordingly.Although the HIV sentinel surveillance data has been primarily used for monitoring the trends, i.e. to assess how rapidly HIV infection increases or decreases over the time in different groups and areas, it can also provide an estimate of the total burden of HIV infection in the countryQ","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"112a2f9e-e59f-4ae5-913f-9592aa573e18","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f2da5635c71716c32f697648e8dc623d','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"46653ca7-d61a-4d6a-a135-91309eff9b49","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Which is the best index for burden of disease?","options":["Case fatality rate","Morbidity data","Dependency ratio","Disability adjusted life years"],"correctIndex":3,"explanation":"Disability adjusted life years : Is a measure of the burden of disease in a defined population and the effectiveness of interventions; It expresses years lost to premature death and years lived with disability adjusted for its’ severity","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"46653ca7-d61a-4d6a-a135-91309eff9b49","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ba6bc02ddb34a7970520ab5ff4d80af6','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"fb47f171-c6d7-4871-8d28-92f2b97acc88","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Dengue discharge protocol includes","options":["24 hours after Recovery from shock","Urine volume > 200 ml","24 hours after absence of fever with use of Paracetamol","Return of normal appetite"],"correctIndex":3,"explanation":"National Vector Borne Disease Control Programme (NVBDCP) of India given the dengue discharge criteria as follows: 1. Absence of fever > 24 hours (without paracetamol) 2. Return of appetite 3. Good urine output 4. Platelet > 50,000 5. No Respiratory distress 6. > 2-3 days after recovery form shape 7. Visible clinical improvement","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"fb47f171-c6d7-4871-8d28-92f2b97acc88","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('11e3a5632b56cc38969ede0af5038771','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"658ebcea-6f61-4281-a426-848ad0dcf8bf","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Which of these indicators is used at anganwadi centers for growth monitoring in children?","options":["Height for age","Weight for age","Weight for height","Mid-arm circumference"],"correctIndex":1,"explanation":"Ans: B. Weight for ageRef: Park 241e p582, 23/e p547, 22/e p506)India has adopted the new WHO Child Growth Standards (2006) in February 2009 for monitoring the young child growth and development within the National Rural Health Mission and the ICDS.These are based on weight for age.Weight for age is used at anganwadi centers for growth monitoring in children.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"658ebcea-6f61-4281-a426-848ad0dcf8bf","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('98f875fa361a92218b9006a389eae036','reference-medmcqa-residency-epidemiology-en-1','epidemiology','اپیدمیولوژی','medium','{"key":"fab688a9-c8b9-49de-9fd1-596e226477e6","subjectId":"epidemiology","chapter":"اپیدمیولوژی","prompt":"Under National Health Mission which committee makes plan for village health?","options":["Panchayat health committee (PHC)","Village health planning and management committee (VHPMC)","Village health sanitation and nutrition committee (VHSNC)","RogiKalyan Samiti"],"correctIndex":2,"explanation":"Ans: C. Village health sanitation and nutrition committee (VHSNC)Ref: K Park, 23''d ed,, pg. 450-451 and Health Policies and Programmes in India, DK Taneja, I2''h ed., pg. 82VHSNC:Sub-committee or a standing committee of the Gram Panchayat.The VHSNC acts as a platform for convergence between different depaments & committees at village level.The VHSNCs shall be suppoed to develop village health plans to ensure convergent action on social determinants of health, ensure access to health services, especially of the more marginalised sections in the village, and suppo the organization of the Village Health and Nutrition Day.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"fab688a9-c8b9-49de-9fd1-596e226477e6","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-medmcqa-residency-gynecology-en-1','زنان و زایمان · منتخب MedMCQA','residency','reference','medmcqa',NULL,'منبع باز',1793577600000,0,'MedMCQA — Pal, Umapathi & Sankarasubbu, 2022. Validation split via Open Life Science AI; Apache-2.0. متن اصلی انگلیسی؛ آزمون رسمی ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('52a947b39a42517d3e122c587fdb87dd','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"7f0270fd-7d45-43ec-b77e-0038115bb845","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A mother is Hbs Ag positive and anti Hbe Ag positive. Risk of transmission of Hep. B in child is:","options":["20%","50%","0%","90%"],"correctIndex":0,"explanation":"Before answering these questions lets first discuss hepatitis in brief. Maternal infection: The acute infection is manifested by flu like illness as malaise, anorexia, nausea and vomiting. In majority, it remains asymptomatic. Jaundice is rare and fever is uncommon. Clinical course (HBV): Nearly 90–95% of patients clear the infection and have full recovery. 1% develop fulminant hepatitis resulting massive hepatic necrosis. 10-15% become chronic and 10% of these chronic cases suffer from chronic active hepatitis, cirrhosis and hepatocellular carcinoma. Diagnosis is confirmed by serological detection of HBsAg, HBeAg (denote high infectivity) and antibody to hepatitis B core antigen (HBcAg) and HBV DNA titer (107–1011). Screening: All pregnant women should be screened for HBV infection at first antenatal visit and it should be repeated during the third trimester for ‘high risk’ groups (intravenous drug abusers, sexual promiscuity, hemophilics, patients on hemodialysis or having multiple sex partners). Hepatitis C (HCV): It is recognized as the major cause of non-A, non-B hepatitis worldwide and is the leading cause of transfusion associated hepatitis. Transmission is mainly blood borne and to a lesser extent by faecal-oral route. It is responsible for chronic active hepatitis and hepatic failure. Perinatal transmission (10–40%) is high when coinfected with HIV and HBV. Detection is by antibody to HCV by EIA, which develops usually late in the infection. Confirmation is done by recombinant immunoblot assay (RIBA-3). Chronic carrier state is present. Breastfeeding is not contraindicated. Hepatitis D (HDV): It is seen in patients infected with HBV either as a co-infection or super infection. Perinatal transmission is known. Hepatitis E (HEV): Hepatitis E is the most important cause of non-A, non-B hepatitis in developing countries like India. Chronic carrier state is present. Perinatal transmission is uncommon. Maternal mortality is very high (15–20%).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"7f0270fd-7d45-43ec-b77e-0038115bb845","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('da025342195cd0af11478c3ca0453b4a','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"3a13e9bb-48ab-46c1-9d50-e1612840d922","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A patient went into shock immediately after normal delivery, likely cause:","options":["Amniotic fluid embolism","PPH","Uterine inversion","Eclampsia"],"correctIndex":2,"explanation":"Friends this is one of those questions where we can derive the answer by excluding other options as very little information has been provided to us. Sudden post partum collapse – may be seen in all the four cases viz – amniotic fluid embolism, PPH, uterine inversion and eclampsia. But in case of PPH antecedent H/O excessive blood loss, in eclampsia – H/O antecedent convulsions and in amniotic fluid embolism – H/O abrupt onset of respiratory distress before collapse should be present, which is not given in the question so these options are being excluded. The clinical picture of acute inversion occurring in the third stage of labour is characterised by shock and haemorrhage, the shock being out of proportion to the bleeding. Since this a problem which occurs due to mismanaged third stage of labour, patient doesnot have any complain in the antenatal period or during labour. Uterine inversion – “It should be suspected whenever a woman has unexplained postpartum collapse.” Textbook of Obs, Sheila Balakrishnan, p 489","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"3a13e9bb-48ab-46c1-9d50-e1612840d922","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('993bb9605cfa9b0f86bfd669aeff5482','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"740f528e-5192-44dc-89a3-4e2a1249e3c6","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A child born with multiple congenital defect including cleft palate, neural tube defect, atrial septal defect and microcephaly which of the following drug is used by mother during pregnancy:","options":["Erythromycin","Isotretinoin","Ibuprofen","Metronidazole"],"correctIndex":1,"explanation":"Friends, Remember CNS anomaly (NTD) + CVS anomaly + facial defects are seen with the use of isotretinoin.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"740f528e-5192-44dc-89a3-4e2a1249e3c6","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f200c9487195c663ed8859227aa04f02','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"3592f545-8b31-4f41-9ccc-89eb67bc818a","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"In Galactorrhoea--amenorrhea syndromes, which is the investigation you should advise (apa from serum prolactin)?","options":["TSH","LH","hCG","Urinary ketosteroids"],"correctIndex":0,"explanation":"Ans: A. TSH(Ref Harrison I9/e p2 p2267)Galactorrhea - amenorrhea syndromes:Serum prolactin &TSH advised.Laboratory diagnosis:Measure basal, fasting morning PRL levels - To assess hypersecretion.Normal PRL levels 1000 ,ug/L) -Falsely lowered.Due to assay aifacts & aggregated circulating PRL forms.Sample dilution required for accurate measurement.Usually biologically inactive (macroprolactinemia).Measuring TSH and T4 levels - To exclude hypothyroidism.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"3592f545-8b31-4f41-9ccc-89eb67bc818a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1e996a36086908db5bc331344603fe57','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"e5e1f694-5bce-4ea7-8d47-b629076533e1","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Best parameter for ultrasound evaluation of IUGR is:","options":["Placental membrane","Length of femur","Abdominal circumference","BPD"],"correctIndex":2,"explanation":"“Abdominal circumfernece (AC) is the single most sensitive parameter to detect IUGR. Serial measurements of AC and estimations of fetal weight are more diagnostic to fetal growth restriction.” Dutta 7/e, p 463 “The biometric parameters, AC is most affected by fetal growth” Williams 24/e, p 199","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"e5e1f694-5bce-4ea7-8d47-b629076533e1","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ed4744f35c46da642f246ff3555cf102','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"5682860b-5ef4-4c1d-88b4-eb81546548ba","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Kamlesh, a 2 year old girl, has Down''s syndrome. Her karyotype is 21/21 translocation. What is the risk ofrecurrence in subsequent pregnancies if the father is a balanced translocation carrier :","options":["100%","50%","25%","0%"],"correctIndex":0,"explanation":"Down Syndrome– (Trisomy 21) Seen in 11n 800 to 1000 newborns M/C Nonlethal trisomy Risk of Down syndrome increases with increase in maternal age At maternal age of 35 years, the risk of having a baby with Down syndrome is 1:365. to 1:400. Recurrent Risk of Down’s syndrome","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"5682860b-5ef4-4c1d-88b4-eb81546548ba","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d583a7ccde4dca58be9c8e3ed54c1555','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"93d8bac0-76ae-4440-91c0-fa3b724bbc65","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Which of the following will not decrease mother to child transmission of HIV?","options":["Avoid breastfeeding","Vaginal delivery","Zidovudine given to mother antenataly and to neonate after bih","Vitamin A supplementation given to mother"],"correctIndex":1,"explanation":"Answer- B (Vaginal delievery)Vaginal delivery increases risk of mother to childhood transmission of HIV.''HIV can be transmitted through breast milk, avoiding breast feeding decreases the mother to child transmission of HIV.''","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"93d8bac0-76ae-4440-91c0-fa3b724bbc65","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('629e5e008fe8275b8be6b7933021fb04','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"a6cc1419-094c-4675-b250-ba45e4569bd2","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A 32-year-old P2L2 lady comes five days after unpro!tected sexual intercourse. What will be your advice for contraception in this lady?","options":["Copper IUCD","Levonorgestrel 0.75 mg","Two tablets of high dose OCP, repeated after 24 hours","Laparoscopic tubectomy"],"correctIndex":0,"explanation":"Ans: A. Copper IUCD(Ref Dutta 8/e p615, 7/e p551)Best contraceptive for 32-year old P2L2 lady coming after 5 days after unprotected sexual intercourse - Copper-containing IUCD.Copper IUCD:Inseion within maximum period of 5-7 days after accidental unprotected exposure.Prevents implantation.Unsuitable for women with multiple sex paners & rape victims.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a6cc1419-094c-4675-b250-ba45e4569bd2","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('26efd79fee8d118c3f1b6036705ecc55','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"ae0f40e1-2d9f-4d1a-a431-3062793ef007","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"The following is used in which procedure in gynecology?","options":["Pap smear","Endometrial Biopsy","Cervical Biopsy","Vulval Biopsy"],"correctIndex":0,"explanation":"The image shown in question is of Ayre''s spatula which is used in papsmear Sensitivity of the cervical cytology for the detection of CIN 2 or 3 ranged from 47% to 62% Errors occurred because of - Poor fixation on the glass slide, leading to air drying - Smear were thick and obscured by vaginal discharge, blood, or mucus. Liquid - based Cytology Liquid samples are processed to provide a uniform, thin layer of cervical cells without debris on a glass slide & this eliminates air drying. The cell sample is collected with an endocervical brush used in combination with a plastic spatula or with a plastic broom. The sample is rinsed in a l containing liquid alcohol-based preservative. Hence 80% to 90% of the cells are retrieved The cells are retrieved from the l by passing the liquid through a filter. Recommendation : 2020 Novaks For women 21 to 29 years Screening with cytology every 3 year From 30 to 65 years Co - testing with conventional cytology and high - risk HPV testing every 5 years Or Cytology alone every 3 years are appropriate alternatives After the age of 65 it is Discontinue screening when 3 negative cytology results or 2 negative co test in the previous 10 years","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ae0f40e1-2d9f-4d1a-a431-3062793ef007","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1d3e7cb7eaf5fa837008362dbdf11dae','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"b02a0880-4fc7-46d1-83a9-d86a8f1f077c","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Estrogen and progesterone in the first 2 months pregnancy are produced by:","options":["Fetal ovaries","Fetal adrenal","Placenta","Corpus luteum"],"correctIndex":3,"explanation":"Ans: D. Corpus luteum(Ref Williams 24/e p169; Ganong 25/e p412, 24/e p414).Estrogen and progesterone in first 2 months of pregnancy - Produced by Corpus luteum.Functions of corpus luteum:Enlarged corpus luteum of pregnancy secretes estrogens, progesterone & relaxin.Progesterone & relaxin -Helps maintain pregnancy.By inhibiting myometrial contractions.Progesterone prevents prostaglandin production by uterus - Stops contractions.Corpus luteum function begins to decline after 8 weeks of pregnancy.Yet persists throughout pregnancy.In humans placenta produces sufficient estrogen & progesterone from maternal & fetal precursor taking over corpus luteum function after 6th week of pregnancy.Ovariectomy before 6th week a Hence cause aboion.Ovariectomy after 6th week doesn''t affect pregnancy.Note:hCG secretion decreases after initial marked rise.Estrogen & progesterone secretion increase until just before paurition.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b02a0880-4fc7-46d1-83a9-d86a8f1f077c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('fb757e4b00f63b0faafaab4c88d549c7','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"64fefa75-a0d1-45da-a81b-961ed7565c9c","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"What is the drug of choice of Bacterial vaginosis in pregnancy","options":["Metronidazole","Clindamycin","Erythromycin","Rovamycin"],"correctIndex":0,"explanation":"BV is a maldistribution of normal vaginal flora Lactobacilli are decreased, and Anaerobic bacteria species are overrepresented. Anaerobes include Gardnerella, Prevotella, Mobiluncus, and Bacteroides species; Atopobium vaginae; BV-associated bacteria, provisionally named BVAB1, BVAB2, and BVAB3. Pregnancy -DOC - Metronidazole 500 mg twice daily orally for 7 days; 0.75-percent gel, intra-vaginally, daily for 5 days Clindamycin 2% One applicator intra-vaginally nightly for 7 days. 300 mg orally twice daily for 7 days 100-mg clindamycin ovules Vaginally nightly for 3 days","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"64fefa75-a0d1-45da-a81b-961ed7565c9c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('c07f0e99ff3395594bb807a5ac73dc3f','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"ae4e70ec-f2cc-4afa-b122-cdb5a4eede13","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Hematuria during labour in previous LSCS is sign","options":["Impending rupture of scar","Urethral trauma","Prolong labour","Sepsis"],"correctIndex":0,"explanation":"Now friends - here in the question it is asked specifically that hematuria is seen in a patient with previous LSCS during labour - which indicates impending rupture of scar. \"There are no reliable signs of impending uterine rupture that occurs before labor, although the sudden appearance of gross hematuria is suggestive.” COGDT 10/e, p 340 Here in this questions obstructed labor is not given in the options, but even if it was given, I would have still opted for impending scar rupture as the question is specifically asking, in a case of previous LSCS.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ae4e70ec-f2cc-4afa-b122-cdb5a4eede13","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('fee04e37a905d522956221b92af5806b','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"05f7f85c-a5f7-438b-a8b4-afd025228b21","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A 32 weeks pregnant female presented with labor pains and minimal vaginal discharge, on analysis of the cervicovaginal discharge showed presence of fetal fibronectin. What is the probable diagnosis?","options":["Preterm labour","IUGR","IUD","Cervical infection"],"correctIndex":0,"explanation":"Fibronectin is a glycoprotein that binds amnion and chorion to the decidua of uterus. Normally present in the cervicovaginal secretions before 22 weeks and after 37 weeks of pregnancy. Presence of Fibronectin (>50ng/ml) in between these weeks is suggestive of preterm labor. When the test is negative it reassures that delivery will not occur within next 7 days.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"05f7f85c-a5f7-438b-a8b4-afd025228b21","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('bc8612cb545fc7b014e456fcb61eebed','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"086cd30e-0ed9-4b7b-9346-38529b1445b8","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A midwife at a PI-IC is monitoring pregnancy and maintaining the paograph of pregnancy progression. At how much cervical dilation should the paograph plotting be staed?","options":["4 cm","5 cm","6 cm","8 cm"],"correctIndex":0,"explanation":"Answer- A. 4 cmPaograph recording is usually staed after a cervical dilation of 3 cm (not the 4 cm), i.e. the active stage of labor As 3 cm is not given in the option, we have to choose 4 cm.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"086cd30e-0ed9-4b7b-9346-38529b1445b8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1f14dd7abbc48f8db4f8059c18409c39','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"7ce281ed-c512-4456-a9f7-87b7620d628d","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"An absolute indication for LSCS in case of a Heart disease is:","options":["Co-arctation of Aorta","Eisenmenger syndrome","Ebsteins anomaly","Pulmonary stenosis"],"correctIndex":0,"explanation":"Heart disease during pregnancy, in itself is not an indication for cesarean section. Cesarean section in heart disease is done in specific cases. “In coarctation of aorta, elective cesarean section is indicated to prevent rupture of the aorta or mycotic cerebral aneurysm.” Dutta Obs. 7/e, p 278","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"7ce281ed-c512-4456-a9f7-87b7620d628d","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('96b79714984d5daf11ed88637e96ae47','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"a2106819-7406-4698-8f7d-b166a05fe17e","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"P3L3 came to opd with postcoital bleeding and pap positive p/v cervix hyperophied bleed on touch diagnosis -","options":["CA cervix","Fibroid","Cervicitis","Cervical polyp"],"correctIndex":0,"explanation":"Ans. A. CA cervixSYMPTOMS:Arises from: Squamo-columnar junctionEarliest symptom: Post-coital bleedingAs the cancer progresses, symptoms may include:Unusual vaginal dischargeVaginal bleeding between periodsBleeding after menopausePyometraBleeding or pain during sexMC site: EctocervixLymph nodes affected: Obturator, hypogastric and external iliacTime taken for conversion of CIN to invasive Ca: 10 yearsMC type: Squamous cell Ca100% cure rates are seen in: CISUremia: altered sensorium and is having hiccupsMC cause of death: Renal failureCa cervix can be prevented by screeningBoth positive Pap smear and test is suggestive of CA cervix","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"a2106819-7406-4698-8f7d-b166a05fe17e","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('97c091de990d6c2fb422a92c29a34864','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"f9be858f-ef2f-475e-9c82-ced530a1a623","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A pregnant lady is diagnosed to be HBs Ag positive. Which of the following is the best way to prevent infection to the child:","options":["Hepatitis vaccine to the child","Full course of Hepatitis B vaccine and immunoglobulin to the child","Hepatitis B immunoglobulin to the mother","Hepatitis B immunization to mother"],"correctIndex":1,"explanation":"The best way to prevent infection in a child born to HBsAg positive mother is to give both active and passive immunization. Infants born to HBsAg positive mothers should be given hepatitis immunoglobulin (0.5 m 1/m) within 12 hours after birth. Along with this the first dose of hepatitis B recombinant vaccine is given. This is followed by hepatitis B vaccine at 1 and 6 months. Hepatitis B is not a contraindication for breastfeeding.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f9be858f-ef2f-475e-9c82-ced530a1a623","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('2cbadf1de14d41ce6d672e548a26b5ba','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"721d3b8f-c3a4-4f82-899a-db8078710935","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"The one measurement of fetal maturity that is not affected by a ''bloody tap'' during amniocentesis is:","options":["L/S ratio","Phosphatidyl glycerol","α-fetoprotein","Bilirubin as a measured by DOD 450"],"correctIndex":1,"explanation":"The best test to detect fetal lung maturity in diabetic mothers is presence of phophatidyl glycerol (PG) in amniotic fluid. If PG is present in amniotic fluid fetal lungs are considered mature and vice versa.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"721d3b8f-c3a4-4f82-899a-db8078710935","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b10a4627ef6e2c3e83a673b19334b9ee','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"71905d50-bffe-468f-ada2-77d845d55daf","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Which of the following histories is not an indication to perform oral glucose tolerance test to diagnose gestational diabetes mellitus?","options":["Previous Eclampsia","Previous Congenital anomalies in the fetus","Previous Unexplained fetal loss","Polyhydramnios"],"correctIndex":0,"explanation":"Indications for performing GCT: All those conditions in which there is risk of having diabetes. On the basis of risk factors females are categorised into 3 category: Low risk All of the folowing: Member of an ethnic group with a low prevalence of GDM No known diabetes in first degree relatives Age 25 years Overweight before pregnancy Weight high at birth (previous baby) High risk Marked obesity Strong family history of type II DM Previous history of GDM impaired glucose metabolism or glucosouria Unexplained stillbirth H/o previous congenitally malformed baby","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"71905d50-bffe-468f-ada2-77d845d55daf","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('fa339dfe71d079ee79979930696bff69','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"b467f831-a659-457d-9132-1f205935bee8","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"In pregnancy, the most common cause of transient- diabetes insipidus is:","options":["Severe preeclampsia","Hydramnios","Multiple pregnancy","IUGR"],"correctIndex":0,"explanation":"Diabetes insipidus can be caused by: Deficiency of antiduretic hormone Resistance of ADH action ↓ ↓ Central diabetes insipidus Nephrogenic diabetes insipidus. A transient form of DI occurs during pregnancy due to: – Excessive placental production of vasopressinase – Decreased hepatic clearance due to abnormal liver function there in case of: Preeclampsia Fatty liver Hepatitis. Approximately 60% of women with previously known DI worsen, 20% improve and 20% do not change during pregnancy. Worsening is attributed to excessive placental vasopressinase production. Some females with DI who develop placental insufficiency show DI improvement, which is attributed to decreased vasopressinase production by the damaged placenta. Symptoms: Polyuria (4-15 liters/day) Intense thirst particularly for ice cold fluids. Diagnosis: is confirmed by water deprivation test. Treatment: of choice intranasal L-deamino 8D arginine vasopressin (DDAVP) which is a synthetic analogue of ADH and is resistant to vasopressinase.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"b467f831-a659-457d-9132-1f205935bee8","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b8a8ded0656b9836c11e7c2dd5ec4cad','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"641830d8-81c8-4a90-abaf-1d0fc4de838d","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A 61 years old post-menopausal woman with a family history of ovarian cancer presents with pain abdomen. She is on hormone replacement therapy. An abdominal ultrasound revealed a smooth cyst in the right ovary. What should be done next?","options":["Observe and reassure the patient","Laparoscopic surgery to visualize the nature of the cyst","Drilling of cysts","Check CA-125 levels and advise regular follow-up if normal"],"correctIndex":3,"explanation":"Answer-D. Check CA-125 levels and advise regular follow-up if normalThis is a post-menopausal patient with a simple (smooth) qtst in the ovary. Such a cyst doesn''t needfuher investigations,but this patient has two risk factors for malignancy: Family history of ovarian tamor and history of Hormonal therapy.Hence, CA-125 levels should be evaluated and the RMI-I score (Risk of Malignancy index) calcalated before proceedingfor regular follow up. If RMI score exceeds 200,fuher imaging laparoscopic surgery will be needed in this patient.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"641830d8-81c8-4a90-abaf-1d0fc4de838d","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('65d69bec2c8e6049034cd2ab9f43d20f','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"05c55694-331d-4f11-a9b4-a5efbc32de79","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Which of these is seen in Asherman syndrome?","options":["Oligomenorrhea","Hypomenorrhea","Metromenorrhagia","Polymenorrhea"],"correctIndex":1,"explanation":"Ans: B. Hypomenorrhea(Ref: Shaw''s 16/e p250; Novaks 13/e p351)Hypomenorrhea:Seen in Asherman syndromeAsherman''s syndrome:More common with secondary amenorrhea or hypomenorrhea.Causes:In patients with risk factors for endometrial or cervical scarring (history of uterine or cervical surgery), infections related to IUD use & severe pelvic inflammatory disease.Found in 39% patients undergoing hysterosalpingography with previous postpaum curettage.Rare cause: Infections (tuberculosis & schistosomiasis).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"05c55694-331d-4f11-a9b4-a5efbc32de79","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('f86418e84fd9b375b714704929c41a2f','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"ff070552-6e90-4e3b-ad82-918bed4d632c","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A G2 P1+0+0 diabetic mother present at 32 weeks pregnancy, there is history of full term fetal demise in last pregnancy. Her vitals are stable, sugar is controlled and fetus is stable. Which among the following will be the most appropriate management?","options":["To induce at 38 weeks","To induce at 40 weeks","Cesarean section at 38 weeks","To wait for spontaneous delivery"],"correctIndex":0,"explanation":"The most common time of IUD in a diabetic patient is last two weeks of pregnancy, since in this patient there is history of a full term demise as well, so logically speaking we should terminate her pregnancy at 38 weeks.This is what logic says, now let us see what references have to say- High risk gestational diabetes: History of stillbirth History of neonatal death History of fetal macrosomia Concomitant obesity and/or hypertension Development of oligohydramnios, polyhydramnios preeclampsia or fetal macrosomia Inadequate metabolic control with diet alone. “High risk gestational diabetic patients should have their labor induced when they reach 38 weeks with exception of those with a macrosomia fetus (Efw > 4000 g) who should be delivered by cesarean section because of the increased risk of shoulder dystocia”. Fernando Arias 3/e, p 449 Induction of labor: The indications are Diabetic women controlled on insulin (GDM or class B diabetes) are considered for induction of labor after 38 completed weeks Women with vascular complications (pre-eclampsia, IUGR) often require induction after 37 weeks.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ff070552-6e90-4e3b-ad82-918bed4d632c","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('02efeafc66d96010225cdb6075a2d671','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"dfb6dc4a-a4ac-4270-8bf2-807e6efead3a","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A pregnant female with known cardiac disease presents to you in the first trimester with history of warfarin embryopathy what should be advised now?","options":["Continue warfarin throughout the pregnancy","Replace warfarin with heparin in First trimester","Give acicoumarin","Use LMW heparin"],"correctIndex":1,"explanation":"Ans. B. Replace warfarin with heparin in First trimesterRef: Williams Obstetrics, 24''h ed.Warf''arin has a low molecular weight and readily crosses the placenta.Exposure between the 6th and 9th weeks may result in warfarin embryopathy characterized by stippling of the veebrae and femoral epiphyses and by nasal hypoplasia with depression ofthe nasal bone.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"dfb6dc4a-a4ac-4270-8bf2-807e6efead3a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b24becfb98d9ed3a3760443f9a1f8114','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"21618a55-4eaf-457c-a8fa-a1a2149c566a","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Birth weight of a baby can be increased by:","options":["Cessation of smoking","Aspirin","Ca++ and vitamin D supplement","Bed rest"],"correctIndex":0,"explanation":"“Smoking is the single most preventable cause of IUGR in infants born in the united states—women who quit smoking at 7 months gestation have newborns with higher mean birthweights than do women who smoke throughout the pregnancy. Women who quit smoking before 16 weeks of gestation are not at any increased risk for an IUGR infant.” COGDT 10/e, p 293 The answer is further supported by Williams 24/e, p 882 “In prevention of fetal growth restriction – smoking cessation is critical” Williams 24/e, p 882","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"21618a55-4eaf-457c-a8fa-a1a2149c566a","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('6651273e7f91bc9009c6fc3c37657c85','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"901769b9-8f5f-48e3-869a-879c1d57ad93","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Which of the following abnormalities can be diagnosed in the I st trimester of pregnancy?","options":["Anencephaly","Encephalocele","Meningocele","Microcephaly"],"correctIndex":0,"explanation":"Answer- A. Anencephaly\"Anencephaly is diagnosed by the absence of cranial vault (calvarium) and telencephalon. Brain tissue is angiomatous.Early diagnosis is possible at aboat 13 weeks","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"901769b9-8f5f-48e3-869a-879c1d57ad93","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('94c37c7a1cae47fc4c71c503923c56dc','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"ab34e961-f641-4c92-9324-06da16cc52ef","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Loading dose MgSO4 (IV) to be prepared as","options":["4 ml 50% w/v plus 16 ml NS","8 ml 50% w/v plus 12 ml NS","12 ml 50% w/v plus 8 ml NS","16 ml 50% w/v plus 4 ml NS"],"correctIndex":1,"explanation":"Loading dose of Mgso4: Total: 14 gms Ampule commercially available is: Each 2 ml of injection (50%) = 1 gm of MgSO4 4 gm I/V as a 20 % solution that is 4 ampules (8 mL=4 gm) + 12 mL NS making it 20 % solution + 10 gm I/M (5gm IM in each buttock as 50 % solution)","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"ab34e961-f641-4c92-9324-06da16cc52ef","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('b4bc2953b2c5e8eb8e1c771c1acbd6fd','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"743f2305-10ed-4d66-b6fa-911cacdf2622","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Which type of Hb is not affected by Rh isoimmunisation:","options":["Anti C","Anti E","Anti lewis","Anti D"],"correctIndex":2,"explanation":"“An antigen frequently found in routine antenatal screening is the Lewis group (Lea and Leb). The Lewis antigens do not cause erythroblastosis fetalis and differ from all of the other red cell antigens in that they are not synthesized in the red cell membrane but are absorbed into it.” Fernando Arias 2/e, p 116","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"743f2305-10ed-4d66-b6fa-911cacdf2622","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('0f5f814ec758735fa8608ba23a5e2d29','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"f3f48369-3b19-470a-bdaa-a5d8fa4d8afa","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Preconceptional intake of which of the following results in decrease in incidence of neural tube defect:","options":["Vitamin A","Folate","Vitamin E","Vitamin C"],"correctIndex":1,"explanation":"“Folic acid has been shown to effectively reduce the risk of neural tube defects (NTDs). A daily 4 mg dose is recommended for patients who have had a previous pregnancy affected by neural tube defects. It should be started atleast 1 month (ideally 3 months) prior to pregnancy and continued through the first 6–12 weeks of pregnancy.” COGDT 10/e, p 197 Remember: Therapeutic dose of folic acid (to be given in females with previous history of baby with NTD) - 4 mg. Prophylactic dose of folic acid = 0.4 mg i.e. 400 mg Duration: It should be started 1 month before conception and continued till 3 months of pregnancy.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"f3f48369-3b19-470a-bdaa-a5d8fa4d8afa","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('95eb35d711e4ec88c166d34aa2ef948d','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"065b4850-1738-4a30-9c3f-1fb89d9c0123","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Maximum level of alpha fetoprotein is seen in:","options":["Fetal serum","Placenta","Amniotic fluid","Maternal serum"],"correctIndex":0,"explanation":"Alpha fetoprotein is the most abundant protein in the fetal serum throughout fetal development. It is transferred from fetus to amniotic fluid when fetus passes urine. The concentration of AFP in amniotic fluid is approximately 100 folds less than in fetal serum, peaks at 13-14 weeks and then decreases in the second trimester (by 10% per week). AFP reaches the maternal serum by diffusion across the amniotic membranes and via the placenta. The level of AFP in maternal serum is less than fetal serum as is suggested by: “Fetal serum contains AFP in a concentration 150 times that of maternal serum”. COGDT 10/e, p 185 “Ordinarily high level of fetoprotein are found in developing fetus and low levels exist in maternal serum and amniotic fluid”. Mannual of Laboratory and Diagnostic Test Fishback 7/e, p 995","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"065b4850-1738-4a30-9c3f-1fb89d9c0123","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('8a8b6e7f47be38411895bcd8700ce45e','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"9ccd0247-2723-4707-b569-ca0402842cd9","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Which of these is not a non-contraceptive use of levonorgestrel?","options":["Endometriosis","Premenstrual tension","Complex endometrial hJperplasia","Emergencycontraception"],"correctIndex":1,"explanation":"Ans: B. Premenstrual tension(Ref Williams 24/e p701: Goodman Gilman 12/e p1184, 1190)Pre-menstrual tension is not a non-contraceptive use of levonorgestrel.Therapeutic Uses - Levonorgestrel:Emergency contraception:Useful within 120 hours as emergency bih control.Idiopathic menorrhagia:Excessively heavy, regular menses in the absence of intracavitary pathology or coagulopathy.Menometrorrhagia:Excessive bleeding in amount prolonged in duration (regular or irregular intervals).An alternative delivery system - Protect against endometrial hyperplasia in women taking SERM.Management of recurrent pelvic pain secondary to multi- treated endometriosis.LNG-IUS is licensed for use in menorrhagia & to provide endometrial protection to perimenopausal & postmenopausal women on estrogen replacement therapy.LNG-IUS beneficial in endometriosis, adenomyosis, fibroids, endometrial hyperplasia & early stage endometrial cancere (where the patient is deemed unfit for primary surgical therapy).","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"9ccd0247-2723-4707-b569-ca0402842cd9","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('3d7aa97b2835b37f857bf1d836621f26','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"770a2934-5df3-4d53-a79c-0d4358b95016","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"In a female, intraocular metastasis most commonly occurs from which of the following gynaecological primary?","options":["Breast","Ovary","Cervix","Endometrium"],"correctIndex":0,"explanation":"Answer- A (Breast)Breast cancer is the most common tumor to metastasize to the eye followed by lung cancer.Intraocular metastases are the most common malignancy of eye, and the primary cause is breast cancer.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"770a2934-5df3-4d53-a79c-0d4358b95016","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('9018011e7b5ad87d6e68781e140d2300','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"d9f1b19f-12f5-467d-a831-ba3d9020d230","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Amniotic fluid contains acetyl cholinesterase enzyme. What is the diagnosis ?","options":["Open spina bifida","Gastroschisis","Omphalocele","Osteogenesis imperfecta"],"correctIndex":0,"explanation":"Amniotic fluid Acetylcholineesterase level is elevated in open neural tube defect: It has a better diagnostic value than AFP. In case of suspected neural tube defect, on Amniocentesis, if amniotic fluid AFP levels are raised but Acetylcholinesterase levels are normal, patient should be reassured that elevated AFP levels are probably caused by fetal blood contamination but, if acetyl cholinesterase is also elevated along with AFP it is indicative of NTD. It also helps to distinguish between neural tube defect and abdominal wall defects (both of which cause elevated MSAFP): – Acetyl cholinesterase is raised in open NTD, but is low in abdominal wall defects. – In patients with NTD, the ratio of acetylcholinesterase to butyrlcholinesterase levels is 0.14 or more. In case of abdominal wall defects this ratio is less than 0.14.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"d9f1b19f-12f5-467d-a831-ba3d9020d230","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('0f2407028cfe52c328e82f8db9bc8a0b','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"faf4af2f-9fe4-4062-9bdb-e21778b5cccd","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"The commonest cause of occipitoposterior position of fetal head during labor is:","options":["Maternal obesity","Multiparity","Deflexion of fetal head","Android pelvis"],"correctIndex":3,"explanation":"In vertex presentation when the occiput is placed posteriorly over the sacroiliac joint or directly over the sacrum. It is called as occiptoposterior position. Causes of Occipitoposterior Position: Most common cause of occipitoposterior position is anthropoid and android pelvis:","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"faf4af2f-9fe4-4062-9bdb-e21778b5cccd","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('1656a05921ff130a48cf82f7bbfd4911','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"76ad139f-2d71-44b7-aca8-bd96da79500b","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A 45 years old patient presented with complaints of pain in abdomen and menorrhagia. Endometrial biopsy was normal and sonogram of uterus showed diffusely enlarged uterus with no adnexal mass. What is the diagnosis?","options":["Fibroid uterus","Endometritis","Endometriosis","Adenomyosis"],"correctIndex":3,"explanation":"Ans: D: Adenomyosis(Ref: Shaw''s 16Ie p413-413, 13/c p4T 3; Novak''s 13Ie p184; Robbins 9Ie p1012)Clinical features like abdominal pain and menorrhagia with normal endometrial biopsy and on ultrasound diffuse, symmetrical enlargement of uterus, in a perimenopausal women without any focal lesion is highly suggestive of Adenomyosis.Clinical symptoms include menometrorrhagia (irregular and heavy menses), colicky dysmenorrhea, dyspareunia, and pelvic pain, paicularly during the premenstrual period.Coexist with endometriosis.Often asymptomatic.Uterus is diffusely enlarged, although usually less than 14 cm in size, and is often soft and tender, paicularly at the time of menses.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"76ad139f-2d71-44b7-aca8-bd96da79500b","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d8150ad7f1a405de75d8e64ceb4764df','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"15cebe53-6289-419d-af57-d6f5c6177147","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"What is the level of proteinuria to diagnose severe preeclampsia?","options":["20 mg","200 mg","300 mg","3000 mg"],"correctIndex":2,"explanation":"Ans: C. 300 mg(Ref: Hypeension in pregnancy (ACOG laskforce on hypeension in pregnancy)-Obstetrics and gynaecology, Vol-122, No.5, November 2013; William''s 24/e p181; Danfoh 10/e p264)Diagnostic criteria for pre-eclampsia:Proteinuria - 2300 mg per 24 hour urine collection.Removed from essential criterion for pre-eclampsia diagnosis by American College of Obstetricians and Gynecologists in 2013.In absence of diagnostic requirement of 5 gm as massive proteinaria for severe eclampsia - General definition of proteinuria (>300 mg) sufficient.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"15cebe53-6289-419d-af57-d6f5c6177147","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('96a3938cf0b57116818129583c7df752','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"6e814124-0dfa-4060-a9a5-c6510f5301d4","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A pregnant female, 38 years old, had a child with Down''s syndrome. How do you assess the risk of Down''s syndrome in the present pregnancy:","options":["Material alpha-feto protein","Material HCG","USG","Chorionic villous biopsy"],"correctIndex":3,"explanation":"In patients with previous history of Down syndrome “The risk of recurrence is greater than the risk of genetic diagnosis and these patients should be advised to seek genetic counselling and to have a genetic diagnosis.” Fernando Arias 3/e, p 27 Therefore amniocentesis /Chorionic villous biopsy should be done.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"6e814124-0dfa-4060-a9a5-c6510f5301d4","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('ef09ddb32518a7365d2a3cd00ce9ed48','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"8ec544be-913f-4b14-9858-8026a462af96","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"Kalindi 25 years female admitted as a case of septic abortion with tricuspid valve endocarditis. Vegetation from the valve likely to affect is:","options":["Liver","Spleen","Brain","Lung"],"correctIndex":3,"explanation":"“Right sided endocarditis which usually involves the tricuspid valve causes septic pulmonary emboli occasionally with infarction and lung abscesses.”","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"8ec544be-913f-4b14-9858-8026a462af96","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('20c27030cf3336f0446edb2fb809074a','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"621316dd-5ef8-4ba1-953c-6f214b414b56","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A woman with 20 weeks pregnancy presents with bleeding per vaginum. On speculum examination, the os is open but no products have comes t. The most likely diagnosis is:","options":["Incomplete aboion","Complete aboion","Inevitable aboion","Missed aboion"],"correctIndex":2,"explanation":"Answer- C. Inevitable aboionInevitatrle Aboion:Clinical picture: Bleeding, pain and shockSize of uterus: Equal or lessInternal os: Open with products feltUltrasound: Dead fetus","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"621316dd-5ef8-4ba1-953c-6f214b414b56","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}'),
('d40f6007aecd348df9ea8dc239d95133','reference-medmcqa-residency-gynecology-en-1','gynecology','زنان و زایمان','medium','{"key":"7bb29056-c6b1-4d7b-b513-e6eab45eeb86","subjectId":"gynecology","chapter":"زنان و زایمان","prompt":"A 16 years old girl walks into your clinics and asks for Ca cervix vaccination.Which of the following should be administered?","options":["Gardasil 9","Biovac","Polymer 7","Cohen 5"],"correctIndex":0,"explanation":"Ans. A.Gardasil 9Gardasil 9 is an HPV vaccine approved by the U.S. Food and Drug Administration and can be used for both girls and boys.This vaccine can prevent most cases of cervical cancer if given before a girl or woman is exposed to the virus.HPV Vaccines* Cervarix - Protects against HPV-16, 18.* Gardasil 4 Protects against HPV - 6, 11, 16, 18.* Gardasil -9 - Protects against HPV - 6, 11, 16, 18, 31, 33, 45, 52, 58.","difficulty":"medium","topic":null,"language":"en","source":{"name":"MedMCQA — Pal, Umapathi & Sankarasubbu (2022)","url":"https://huggingface.co/datasets/openlifescienceai/medmcqa","license":"Apache-2.0","questionId":"7bb29056-c6b1-4d7b-b513-e6eab45eeb86","revision":"b768a1ea34afc9f80d3106d9b21f80fa8a00ec450a1f6cd641af72ca9e591021"}}');
