INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('35489532ee8751c97c46bacce48c30ae','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"94a1b13a2357632de91b5d7451110b95","subjectId":"histology","chapter":"ساختار سلول","prompt":"Which of the following organisms is a prokaryote?","options":["amoeba","influenza A virus","charophyte algae","E. coli"],"correctIndex":3,"explanation":"Published solution key: D — E. coli. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-idm71000708","license":"CC-BY-4.0","questionId":"m66446#fs-idm71000708","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('2fd95672b0f36d739fb61f05c702a75e','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"3f497ee01e95dbca19ba196526a76956","subjectId":"histology","chapter":"ساختار سلول","prompt":"Which of the following is surrounded by two phospholipid bilayers?","options":["the ribosomes","the vesicles","the cytoplasm","the nucleoplasm"],"correctIndex":3,"explanation":"Published solution key: D — the nucleoplasm. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66449/index.cnxml#fs-id1798051","license":"CC-BY-4.0","questionId":"m66449#fs-id1798051","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('ce81b8a261de003fb6fdc931b8092cf2','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"d4f5ea6ed0c25ec92c39091e4b6a3770","subjectId":"histology","chapter":"ساختار سلول","prompt":"Peroxisomes got their name because hydrogen peroxide is:","options":["used in their detoxification reactions","produced during their oxidation reactions","incorporated into their membranes","a cofactor for the organelles’ enzymes"],"correctIndex":1,"explanation":"Published solution key: B — produced during their oxidation reactions. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66449/index.cnxml#fs-id2004118","license":"CC-BY-4.0","questionId":"m66449#fs-id2004118","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('54096e49d8be13627c0d99811ad64557','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"cdf4efe2d7ca0206357686ec4990e873","subjectId":"histology","chapter":"ساختار سلول","prompt":"In plant cells, the function of the lysosomes is carried out by __________.","options":["vacuoles","peroxisomes","ribosomes","nuclei"],"correctIndex":0,"explanation":"Published solution key: A — vacuoles. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66449/index.cnxml#fs-id1429843","license":"CC-BY-4.0","questionId":"m66449#fs-id1429843","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('ae93d45873c1990a5574da7b7ba80d4f','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"741f41ddf0653b38a61937d1a095e88c","subjectId":"histology","chapter":"ساختار سلول","prompt":"Which of the following is both in eukaryotic and prokaryotic cells?","options":["nucleus","mitochondrion","vacuole","ribosomes"],"correctIndex":3,"explanation":"Published solution key: D — ribosomes. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66449/index.cnxml#fs-id1624048","license":"CC-BY-4.0","questionId":"m66449#fs-id1624048","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('2a6282eff46195505a0e3eb6b83771c8','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"c31972e24339136473261ed8859b4bea","subjectId":"histology","chapter":"ساختار سلول","prompt":"Tay-Sachs disease is a genetic disorder that results in the destruction of neurons due to a buildup of sphingolipids in the cells. Which organelle is malfunctioning in Tay-Sachs?","options":["lysosome","endoplasmic reticulum","peroxisome","mitochondria"],"correctIndex":0,"explanation":"Published solution key: A — lysosome. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66449/index.cnxml#fs-idm71000710","license":"CC-BY-4.0","questionId":"m66449#fs-idm71000710","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('0acb2c13a6ae493407a62a764ba228d1','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"742bbc2155f357bfb36badcd966a63c0","subjectId":"histology","chapter":"ساختار سلول","prompt":"Which of the following is not a component of the endomembrane system?","options":["mitochondrion","Golgi apparatus","endoplasmic reticulum","lysosome"],"correctIndex":0,"explanation":"Published solution key: A — mitochondrion. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66452/index.cnxml#fs-id1486983","license":"CC-BY-4.0","questionId":"m66452#fs-id1486983","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('8481fd8fc81a48b6940cf53396567892','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"582dd5e6d2352d4ae0d5df01f51507ba","subjectId":"histology","chapter":"ساختار سلول","prompt":"The process by which a cell engulfs a foreign particle is known as:","options":["endosymbiosis","phagocytosis","hydrolysis","membrane synthesis"],"correctIndex":1,"explanation":"Published solution key: B — phagocytosis. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66452/index.cnxml#fs-id1758285","license":"CC-BY-4.0","questionId":"m66452#fs-id1758285","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('2677da1618cda05931b0aef176357c27','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"71a7cf43543f9b4fc77b07439da1f604","subjectId":"histology","chapter":"ساختار سلول","prompt":"Which of the following is most likely to have the greatest concentration of smooth endoplasmic reticulum?","options":["a cell that secretes enzymes","a cell that destroys pathogens","a cell that makes steroid hormones","a cell that engages in photosynthesis"],"correctIndex":2,"explanation":"Published solution key: C — a cell that makes steroid hormones. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66452/index.cnxml#fs-id833165","license":"CC-BY-4.0","questionId":"m66452#fs-id833165","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('296c362696f04b30fca792006d221354','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"997385cbdb86ed956d14fb4e25f19d1a","subjectId":"histology","chapter":"ساختار سلول","prompt":"Which of the following sequences correctly lists in order the steps involved in the incorporation of a proteinaceous molecule within a cell?","options":["protein synthesis of the protein on the ribosome; modification in the Golgi apparatus; packaging in the endoplasmic reticulum; tagging in the vesicle","synthesis of the protein on the lysosome; tagging in the Golgi; packaging in the vesicle; distribution in the endoplasmic reticulum","synthesis of the protein on the ribosome; modification in the endoplasmic reticulum; tagging in the Golgi; distribution via the vesicle","synthesis of the protein on the lysosome; packaging in the vesicle; distribution via the Golgi; tagging in the endoplasmic reticulum"],"correctIndex":2,"explanation":"Published solution key: C — synthesis of the protein on the ribosome; modification in the endoplasmic reticulum; tagging in the Golgi; distribution via the vesicle. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66452/index.cnxml#fs-id1703517","license":"CC-BY-4.0","questionId":"m66452#fs-id1703517","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('bca8959261825974080e528c1f7edd2f','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"2ecca1e87f3feced2d0f73ba1b560c3f","subjectId":"histology","chapter":"ساختار سلول","prompt":"Congenital disorders of glycosylation are a growing class of rare diseases. Which organelle would be most commonly involved in the glycoprotein disorder portion of the group?","options":["RER","ribosomes","endosomes","Golgi apparatus"],"correctIndex":3,"explanation":"Published solution key: D — Golgi apparatus. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66452/index.cnxml#fs-idm71000711","license":"CC-BY-4.0","questionId":"m66452#fs-idm71000711","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('3d9d400c8c560cc4fcbdf4f801d85dac','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"dd96fe437c8243d776cc1efb75067407","subjectId":"histology","chapter":"ساختار سلول","prompt":"Which of the following have the ability to disassemble and reform quickly?","options":["microfilaments and intermediate filaments","microfilaments and microtubules","intermediate filaments and microtubules","only intermediate filaments"],"correctIndex":1,"explanation":"Published solution key: B — microfilaments and microtubules. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66454/index.cnxml#fs-id1645274","license":"CC-BY-4.0","questionId":"m66454#fs-id1645274","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('6375fc4b6ef448c874f969e74b8845eb','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"30b1109e69d522b490839587cc2ef7af","subjectId":"histology","chapter":"ساختار سلول","prompt":"Which of the following do not play a role in intracellular movement?","options":["microfilaments and intermediate filaments","microfilaments and microtubules","intermediate filaments and microtubules","only intermediate filaments"],"correctIndex":3,"explanation":"Published solution key: D — only intermediate filaments. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66454/index.cnxml#fs-id2219667","license":"CC-BY-4.0","questionId":"m66454#fs-id2219667","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('f0acee6daff728707b57680f7bab5682','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"9a844ffac9ff81cb8b6a99c781505869","subjectId":"histology","chapter":"ساختار سلول","prompt":"In humans, _____ are used to move a cell within its environment while _____ are used to move the environment relative to the cell.","options":["cilia, pseudopodia","flagella; cilia","microtubules; flagella","microfilaments; microtubules"],"correctIndex":1,"explanation":"Published solution key: B — flagella; cilia. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66454/index.cnxml#fs-idm71000714","license":"CC-BY-4.0","questionId":"m66454#fs-idm71000714","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('d866346a7ab0dee64fb4a9060f274ad5','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"cff098889b35ddee75957da994bb96e1","subjectId":"histology","chapter":"ساختار سلول","prompt":"Which of the following are only in plant cells?","options":["gap junctions","desmosomes","plasmodesmata","tight junctions"],"correctIndex":2,"explanation":"Published solution key: C — plasmodesmata. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66455/index.cnxml#fs-id1722302","license":"CC-BY-4.0","questionId":"m66455#fs-id1722302","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('7246af5e10298a55f790a27cb30a0f26','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"03f944baa368b49f746532b5143bea1d","subjectId":"histology","chapter":"ساختار سلول","prompt":"The key components of desmosomes are cadherins and __________.","options":["actin","microfilaments","intermediate filaments","microtubules"],"correctIndex":2,"explanation":"Published solution key: C — intermediate filaments. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66455/index.cnxml#fs-id1434588","license":"CC-BY-4.0","questionId":"m66455#fs-id1434588","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('2c37b6ceb2a701bf3aad39a85c0c87e3','reference-openstax-bachelor-medicine-histology-en-1','histology','ساختار سلول','medium','{"key":"9569439ef710bdec903c8553b67fcc76","subjectId":"histology","chapter":"ساختار سلول","prompt":"Diseased animal cells may produce molecules that activate death cascades to kill the cells in a controlled manner. Why would neighboring healthy cells also die?","options":["The death molecule is passed through desmosomes.","The death molecule is passed through plasmodesmata.","The death molecule disrupts the extracellular matrix.","The death molecule passes through gap junctions."],"correctIndex":3,"explanation":"Published solution key: D — The death molecule passes through gap junctions.. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66455/index.cnxml#fs-idm71000716","license":"CC-BY-4.0","questionId":"m66455#fs-idm71000716","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
