INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('30b582a323b283080d03ef48b1b8f4a7','reference-openstax-bachelor-medicine-histology-fa-1','histology','ساختار سلول','medium','{"key":"60200f97a53035e90125402c0a1ec9c0","subjectId":"histology","chapter":"ساختار سلول","prompt":"دانشمندان هنگام مشاهدهٔ نمونه با میکروسکوپ نوری، برای تمایز اجزای سلول از چه چیزی استفاده می‌کنند؟","options":["باریکهٔ الکترونی","ایزوتوپ‌های رادیواکتیو","رنگ‌های ویژه","دمای بالا"],"correctIndex":2,"explanation":"رنگ‌آمیزی، کنتراست اجزای سلول را در میکروسکوپ نوری افزایش می‌دهد. باریکهٔ الکترونی مربوط به میکروسکوپ الکترونی است.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66445/index.cnxml#fs-id1775146","license":"CC-BY-4.0","questionId":"m66445#fs-id1775146","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('354bbee58720accd209c8e3dd306e9b2','reference-openstax-bachelor-medicine-histology-fa-1','histology','ساختار سلول','medium','{"key":"aafb00a225f4a46a704a1b82c0c244ca","subjectId":"histology","chapter":"ساختار سلول","prompt":"واحد پایهٔ حیات کدام است؟","options":["جاندار","سلول","بافت","اندام"],"correctIndex":1,"explanation":"سلول کوچک‌ترین واحد ساختاری و عملکردی حیات است. بافت‌ها و اندام‌ها از سازمان‌یافتن سلول‌ها پدید می‌آیند.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66445/index.cnxml#fs-id1989359","license":"CC-BY-4.0","questionId":"m66445#fs-id1989359","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('94ab1d86a1b5d3d252a64369aaae3c6f','reference-openstax-bachelor-medicine-histology-fa-1','histology','ساختار سلول','medium','{"key":"49c087763ba066310136acd82320c776","subjectId":"histology","chapter":"ساختار سلول","prompt":"پروکاریوت‌ها برای دریافت برخی مواد و دفع مواد زائد، به کدام فرایند وابسته‌اند؟","options":["ریبوزوم‌ها","تاژک‌ها","تقسیم سلولی","انتشار"],"correctIndex":3,"explanation":"اندازهٔ کوچک پروکاریوت‌ها و نسبت سطح به حجم بالای آن‌ها، تبادل برخی مواد با انتشار را امکان‌پذیر می‌کند. ریبوزوم نقش ساخت پروتئین دارد و تاژک در حرکت دخالت می‌کند.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-id1617238","license":"CC-BY-4.0","questionId":"m66446#fs-id1617238","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('1aa90a45216bb565d2da25f47ecd4196','reference-openstax-bachelor-medicine-histology-fa-1','histology','ساختار سلول','medium','{"key":"e9b6214f2f0e17275232c4a80dcafad5","subjectId":"histology","chapter":"ساختار سلول","prompt":"باکتری‌های فاقد فیمبریه، در انجام کدام کار توانایی کمتری دارند؟","options":["چسبیدن به سطح سلول‌ها","شناکردن در مایعات بدن","ساخت پروتئین","حفظ توانایی تقسیم"],"correctIndex":0,"explanation":"فیمبریه‌ها زوائد کوتاه سطح باکتری هستند و در اتصال باکتری به سطوح نقش دارند. حرکت شناوری معمولاً به تاژک مربوط است.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-id866358","license":"CC-BY-4.0","questionId":"m66446#fs-id866358","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-openstax-bachelor-medicine-physiology-en-1','فیزیولوژی · تمرین‌های OpenStax','bachelor-medicine','reference','openstax',NULL,'منبع باز',1793577600000,0,'Biology 2e — Mary Ann Clark, Matthew Douglas, Jung Choi / OpenStax. CC BY 4.0, نسخهٔ ۲۰ دسامبر ۲۰۲۴. ترجمه و توضیح فارسی در موارد مشخص افزوده شده است؛ سؤال کنکور ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('ab0859a85929704adb585ab62233b6ac','reference-openstax-bachelor-medicine-physiology-en-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"5b5603e832f43e970f03a036776eb7db","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"A scientist compares the plasma membrane composition of an animal from the Mediterranean coast with one from the Mojave Desert. Which hypothesis is most likely to be correct?","options":["The cells from the Mediterranean coast animal will have more fluid plasma membranes.","The cells from the Mojave Desert animal will have a higher cholesterol concentration in the plasma membranes.","The cells’ plasma membranes will be indistinguishable.","The cells from the Mediterranean coast animal will have a higher glycoprotein content, while the cells from the Mojave Desert animal will have a higher lipoprotein content."],"correctIndex":1,"explanation":"Published solution key: B — The cells from the Mojave Desert animal will have a higher cholesterol concentration in the plasma membranes.. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-idm71000716","license":"CC-BY-4.0","questionId":"m66373#fs-idm71000716","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('e68a3552e81166ae6315046a044a6048','reference-openstax-bachelor-medicine-physiology-en-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"0712e704dc7bf561087bfa3f564bdcb5","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"What problem is faced by organisms that live in fresh water?","options":["Their bodies tend to take in too much water.","They have no way of controlling their tonicity.","Only salt water poses problems for animals that live in it.","Their bodies tend to lose too much water to their environment."],"correctIndex":0,"explanation":"Published solution key: A — Their bodies tend to take in too much water.. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66374/index.cnxml#fs-id1986270","license":"CC-BY-4.0","questionId":"m66374#fs-id1986270","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('e8dd8c62d566fcc619914923f83c47b2','reference-openstax-bachelor-medicine-physiology-en-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"5d245be605dfd9caecaadf02694514ef","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"In which situation would passive transport not use a transport protein for entry into a cell?","options":["water flowing into a hypertonic environment","glucose being absorbed from the blood","an ion flowing into a nerve cell to create an electrical potential","oxygen moving into a cell after oxygen deprivation"],"correctIndex":3,"explanation":"Published solution key: D — oxygen moving into a cell after oxygen deprivation. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66374/index.cnxml#fs-idm71000720","license":"CC-BY-4.0","questionId":"m66374#fs-idm71000720","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('11d356adddd1432dc70890c86405f3c3','reference-openstax-bachelor-medicine-physiology-en-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"4683ba67ab3ca66138baeee5300bd9a5","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"Active transport must function continuously because __________.","options":["plasma membranes wear out","not all membranes are amphiphilic","facilitated transport opposes active transport","diffusion is constantly moving solutes in opposite directions"],"correctIndex":3,"explanation":"Published solution key: D — diffusion is constantly moving solutes in opposite directions. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66375/index.cnxml#fs-id2000653","license":"CC-BY-4.0","questionId":"m66375#fs-id2000653","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('94c25abf791be969ed73db551af5393c','reference-openstax-bachelor-medicine-physiology-en-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"8f65b03ae6ae1756d9969c615b19bac0","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"How does the sodium-potassium pump make the interior of the cell negatively charged?","options":["by expelling anions","by pulling in anions","by expelling more cations than are taken in","by taking in and expelling an equal number of cations"],"correctIndex":2,"explanation":"Published solution key: C — by expelling more cations than are taken in. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66375/index.cnxml#fs-id1421748","license":"CC-BY-4.0","questionId":"m66375#fs-id1421748","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('f976f23cddf2465d1dc6fb19a6f1317b','reference-openstax-bachelor-medicine-physiology-en-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"80e8752a8e8d8faa16f77f50fc214046","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"What is the combination of an electrical gradient and a concentration gradient called?","options":["potential gradient","electrical potential","concentration potential","electrochemical gradient"],"correctIndex":3,"explanation":"Published solution key: D — electrochemical gradient. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66375/index.cnxml#fs-id2188234","license":"CC-BY-4.0","questionId":"m66375#fs-id2188234","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('f0788a601dcccc74c5903b62d7cc671d','reference-openstax-bachelor-medicine-physiology-en-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"4da9027bef48e7d71843b95ed6147a4c","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"What happens to the membrane of a vesicle after exocytosis?","options":["It leaves the cell.","It is disassembled by the cell.","It fuses with and becomes part of the plasma membrane.","It is used again in another exocytosis event."],"correctIndex":2,"explanation":"Published solution key: C — It fuses with and becomes part of the plasma membrane.. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66376/index.cnxml#fs-id1853625","license":"CC-BY-4.0","questionId":"m66376#fs-id1853625","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('b266c520500807833a27193b3ad9c280','reference-openstax-bachelor-medicine-physiology-en-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"0dabca215235069cfd21d57434cd431c","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"Which transport mechanism can bring whole cells into a cell?","options":["pinocytosis","phagocytosis","facilitated transport","primary active transport"],"correctIndex":1,"explanation":"Published solution key: B — phagocytosis. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66376/index.cnxml#fs-id2116533","license":"CC-BY-4.0","questionId":"m66376#fs-id2116533","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('b2754d982cd252ff3c674c80ff8e28fe','reference-openstax-bachelor-medicine-physiology-en-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"95ebead97a1725375deb2bac1c016ef6","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"In what important way does receptor-mediated endocytosis differ from phagocytosis?","options":["It transports only small amounts of fluid.","It does not involve the pinching off of membrane.","It brings in only a specifically targeted substance.","It brings substances into the cell, while phagocytosis removes substances."],"correctIndex":2,"explanation":"Published solution key: C — It brings in only a specifically targeted substance.. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66376/index.cnxml#fs-id1702994","license":"CC-BY-4.0","questionId":"m66376#fs-id1702994","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('8539975664c178e75270460328fcce29','reference-openstax-bachelor-medicine-physiology-en-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"998a9c640467ed19331818e9a12dbe90","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"Many viruses enter host cells through receptor-mediated endocytosis. What is an advantage of this entry strategy?","options":["The virus directly enters the cytoplasm of the cell.","The virus is protected from recognition by white blood cells.","The virus only enters its target host cell type.","The virus can directly inject its genome into the cell’s nucleus."],"correctIndex":2,"explanation":"Published solution key: C — The virus only enters its target host cell type.. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66376/index.cnxml#fs-idm71000723","license":"CC-BY-4.0","questionId":"m66376#fs-idm71000723","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('a30c39bb38ddfb65559f29ce03cdc367','reference-openstax-bachelor-medicine-physiology-en-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"9fa08723deb1982edf1019869ac9612e","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"Which of the following organelles relies on exocytosis to complete its function?","options":["Golgi apparatus","vacuole","mitochondria","endoplasmic reticulum"],"correctIndex":0,"explanation":"Published solution key: A — Golgi apparatus. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66376/index.cnxml#fs-idm71000725","license":"CC-BY-4.0","questionId":"m66376#fs-idm71000725","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('31b9f404b62cde93ca84de17e884084a','reference-openstax-bachelor-medicine-physiology-en-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"fd37e9813c27894be736f73573767bdf","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"Imagine a cell can perform exocytosis, but only minimal endocytosis. What would happen to the cell?","options":["The cell would secrete all its intracellular proteins.","The plasma membrane would increase in size over time.","The cell would stop expressing integral receptor proteins in its plasma membrane.","The cell would lyse."],"correctIndex":1,"explanation":"Published solution key: B — The plasma membrane would increase in size over time.. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66376/index.cnxml#fs-idm71000726","license":"CC-BY-4.0","questionId":"m66376#fs-idm71000726","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
