INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('b96d2499ed7b26c52967fd5878b90d34','reference-openstax-bachelor-medicine-physiology-fa-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"39dc68cfa0a9fe3b3be3503133698c7e","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"کدام جزء غشای پلاسمایی می‌تواند هم روی سطح غشا و هم درون ساختار آن قرار گیرد؟","options":["پروتئین","کلسترول","کربوهیدرات","فسفولیپید"],"correctIndex":0,"explanation":"پروتئین‌های محیطی روی سطح غشا قرار می‌گیرند، در حالی که پروتئین‌های یکپارچه در دولایهٔ لیپیدی جای دارند یا از آن عبور می‌کنند.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-id1511651","license":"CC-BY-4.0","questionId":"m66373#fs-id1511651","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('9d8efa2615a690ab6f9ccc8104cb0da4','reference-openstax-bachelor-medicine-physiology-fa-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"43dac3985a6dbbab4c1828ad68a5c03e","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"کدام ویژگی فسفولیپید به سیالیت بیشتر غشا کمک می‌کند؟","options":["سر آن","کلسترول","دم اسید چرب اشباع","پیوندهای دوگانه در دم اسید چرب"],"correctIndex":3,"explanation":"پیوندهای دوگانهٔ سیس در اسیدهای چرب، خمیدگی ایجاد می‌کنند و مانع فشرده‌شدن کامل دم‌ها کنار هم می‌شوند؛ در نتیجه سیالیت غشا افزایش می‌یابد.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-id1268735","license":"CC-BY-4.0","questionId":"m66373#fs-id1268735","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('40e87867c62b4d5855e1a27c10100b56','reference-openstax-bachelor-medicine-physiology-fa-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"5d12a68db2288c059ba84b93be8c3bf8","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"کارکرد اصلی کربوهیدرات‌های متصل به سطح بیرونی غشای سلول چیست؟","options":["شناسایی سلول","انعطاف‌پذیری غشا","تقویت مکانیکی غشا","ایجاد کانال در غشا"],"correctIndex":0,"explanation":"زنجیره‌های کربوهیدراتی سطح سلول، در شناسایی سلولی و برهم‌کنش میان سلول‌ها نقش دارند. این زنجیره‌ها به پروتئین‌ها یا لیپیدها متصل‌اند.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66373/index.cnxml#fs-id2163365","license":"CC-BY-4.0","questionId":"m66373#fs-id2163365","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('f5fd4dbadfb069e0e7b166f69442567f','reference-openstax-bachelor-medicine-physiology-fa-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"1907c7dbe84b0c7d055e0ca866dfdbf4","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"آب در فرایند اسمز در کدام جهت حرکت می‌کند؟","options":["در سراسر سیتوپلاسم بدون وابستگی به غلظت","از ناحیهٔ با غلظت بیشتر سایر مواد حل‌شده به غلظت کمتر آن‌ها","از ناحیهٔ با غلظت بیشتر آب به ناحیهٔ با غلظت کمتر آب","از ناحیهٔ با غلظت کمتر آب به ناحیهٔ با غلظت بیشتر آب"],"correctIndex":2,"explanation":"اسمز، حرکت خالص آب از میان غشای دارای نفوذپذیری انتخابی است. در صورت نبود اختلاف فشار مؤثر، آب از ناحیهٔ با غلظت بیشتر آب به ناحیهٔ با غلظت کمتر آب می‌رود.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66374/index.cnxml#fs-id1422483","license":"CC-BY-4.0","questionId":"m66374#fs-id1422483","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('70843030f97c5c609b42c590a2eabf5a','reference-openstax-bachelor-medicine-physiology-fa-1','physiology','غشا و جابه‌جایی مواد','medium','{"key":"22e39a9ab2ef56a72b9c3963ce5e75d7","subjectId":"physiology","chapter":"غشا و جابه‌جایی مواد","prompt":"در نخودفرنگی، غلاف پُر بر غلاف فشرده غالب است. اگر در نسل F2 یک آمیزش تک‌صفتی ۶۵۰ گیاه با غلاف پُر به دست آید، حدوداً چند گیاه با غلاف فشرده انتظار می‌رود؟","options":["۶۰۰","۱۶۵","۲۱۷","۴۶۸"],"correctIndex":2,"explanation":"نسبت فنوتیپی مورد انتظار در F2 این آمیزش ۳ غالب به ۱ مغلوب است. پس تعداد غلاف فشرده تقریباً ۶۵۰ تقسیم بر ۳، یعنی ۲۱۷ است.","difficulty":"medium","topic":{"title":"غشا و جابه‌جایی مواد","important":["پیوند دوگانهٔ سیس مانع بسته‌بندی فشردهٔ دم‌های لیپیدی می‌شود.","پروتئین‌های غشا می‌توانند محیطی یا یکپارچه باشند."],"microLesson":"غشای سلول از دولایهٔ فسفولیپیدی و پروتئین‌ها تشکیل می‌شود. ترکیب دم‌های اسید چرب بر سیالیت اثر می‌گذارد. کربوهیدرات‌های سطح بیرونی در شناسایی سلولی نقش دارند. اسمز، جابه‌جایی خالص آب از میان غشایی با نفوذپذیری انتخابی است.","branches":[{"title":"ترکیب غشا","points":["فسفولیپید و پروتئین","کربوهیدرات سطحی برای شناسایی"]},{"title":"ویژگی‌های عملکردی","points":["غیراشباع‌بودن و سیالیت","اسمز و حرکت آب"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66374/index.cnxml#fs-id1243838","license":"CC-BY-4.0","questionId":"m66374#fs-id1243838","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
INSERT INTO learning_packs (id,title,track,bank,provider,year,period,available_at,is_sample,attribution,created_at) VALUES ('reference-openstax-dental-basics-biochemistry-en-1','بیوشیمی · تمرین‌های OpenStax','dental-basics','reference','openstax',NULL,'منبع باز',1793577600000,0,'Biology 2e — Mary Ann Clark, Matthew Douglas, Jung Choi / OpenStax. CC BY 4.0, نسخهٔ ۲۰ دسامبر ۲۰۲۴. ترجمه و توضیح فارسی در موارد مشخص افزوده شده است؛ سؤال کنکور ایران نیست.',1793577600000);
INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('6ce8882f82ae31815b003d523ae6ff57','reference-openstax-dental-basics-biochemistry-en-1','biochemistry','مولکول‌های زیستی','medium','{"key":"036b2c1d05ac6f1031c740598512f13a","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"The following chemical reactants produce the ester ethyl ethanoate (C4H8O2): C2H6O + CH3COOH What type of reaction occurs to make ethyl ethanoate?","options":["condensation","hydrolysis","combustion","acid-base reaction"],"correctIndex":0,"explanation":"Published solution key: A — condensation. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66438/index.cnxml#fs-idm71000699","license":"CC-BY-4.0","questionId":"m66438#fs-idm71000699","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('ae5b053f28e0c2c4caa38c06e3855386','reference-openstax-dental-basics-biochemistry-en-1','biochemistry','مولکول‌های زیستی','medium','{"key":"6b86e70c3433b2ce6a71838b7ccdf075","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"Plant cell walls contain which of the following in abundance?","options":["starch","cellulose","glycogen","lactose"],"correctIndex":1,"explanation":"Published solution key: B — cellulose. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66440/index.cnxml#fs-id1730970","license":"CC-BY-4.0","questionId":"m66440#fs-id1730970","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('6d48df092b59d08f92b42dbe624bcd1c','reference-openstax-dental-basics-biochemistry-en-1','biochemistry','مولکول‌های زیستی','medium','{"key":"8c94cd1adeca6238901403b727d96253","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"Lactose is a disaccharide formed by the formation of a ________ bond between glucose and ________.","options":["glycosidic; lactose","glycosidic; galactose","hydrogen; sucrose","hydrogen; fructose"],"correctIndex":1,"explanation":"Published solution key: B — glycosidic; galactose. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66440/index.cnxml#fs-id1478280","license":"CC-BY-4.0","questionId":"m66440#fs-id1478280","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('f826aec16e9a1c4d6dbb4ec490bbf01c','reference-openstax-dental-basics-biochemistry-en-1','biochemistry','مولکول‌های زیستی','medium','{"key":"cadc2b833131a69ae41a70ea82a4b241","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"Which of the following is not an extracellular matrix role of carbohydrates?","options":["protect an insect’s internal organs from external trauma","prevent plant cells from lysing after the plant is watered","maintain the shape of a fungal spore","provide energy for muscle movement"],"correctIndex":3,"explanation":"Published solution key: D — provide energy for muscle movement. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66440/index.cnxml#fs-idm71000702","license":"CC-BY-4.0","questionId":"m66440#fs-idm71000702","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('cdc0ae717ddeeb35e5e5eaac6c08a0e7','reference-openstax-dental-basics-biochemistry-en-1','biochemistry','مولکول‌های زیستی','medium','{"key":"8d82993fea9cdc9568a565a59d29c569","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"Saturated fats have all of the following characteristics except:","options":["they are solid at room temperature","they have single bonds within the carbon chain","they are usually obtained from animal sources","they tend to dissolve in water easily"],"correctIndex":3,"explanation":"Published solution key: D — they tend to dissolve in water easily. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66441/index.cnxml#fs-id1292143","license":"CC-BY-4.0","questionId":"m66441#fs-id1292143","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('7cd1911db5b387e9cd84020eb4953a85','reference-openstax-dental-basics-biochemistry-en-1','biochemistry','مولکول‌های زیستی','medium','{"key":"e40e99e73da64154daf9c0e0a6e99645","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"Phospholipids are important components of ________.","options":["the plasma membrane of cells","the ring structure of steroids","the waxy covering on leaves","the double bond in hydrocarbon chains"],"correctIndex":0,"explanation":"Published solution key: A — the plasma membrane of cells. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66441/index.cnxml#fs-id1407667","license":"CC-BY-4.0","questionId":"m66441#fs-id1407667","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('9e1f3aee1eee660f314a556e6c6179f3','reference-openstax-dental-basics-biochemistry-en-1','biochemistry','مولکول‌های زیستی','medium','{"key":"64b252a9a9ce5dfc7f8ba0883b43366f","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"Cholesterol is an integral part of plasma membranes. Based on its structure, where is it found in the membrane?","options":["on the extracellular surface","embedded with the phospholipid heads","within the tail bilayer","attached to the intracellular surface"],"correctIndex":2,"explanation":"Published solution key: C — within the tail bilayer. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66441/index.cnxml#fs-idm71000704","license":"CC-BY-4.0","questionId":"m66441#fs-idm71000704","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('2318cf9663412cbd08d8a41259488891','reference-openstax-dental-basics-biochemistry-en-1','biochemistry','مولکول‌های زیستی','medium','{"key":"f22782b08a67017b92f479487108d533","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"The monomers that make up proteins are called ________.","options":["nucleotides","disaccharides","amino acids","chaperones"],"correctIndex":2,"explanation":"Published solution key: C — amino acids. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66442/index.cnxml#fs-id2385460","license":"CC-BY-4.0","questionId":"m66442#fs-id2385460","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('70ebaf158b4907d578ed5baddd8efa51','reference-openstax-dental-basics-biochemistry-en-1','biochemistry','مولکول‌های زیستی','medium','{"key":"e79c21f7aaa1efcc6e34394c2fa93273","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"The α-helix and the β-pleated sheet are part of which protein structure?","options":["primary","secondary","tertiary","quaternary"],"correctIndex":1,"explanation":"Published solution key: B — secondary. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66442/index.cnxml#fs-id1837286","license":"CC-BY-4.0","questionId":"m66442#fs-id1837286","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('0b57e85cf791132cc4e8c1812823ddcd','reference-openstax-dental-basics-biochemistry-en-1','biochemistry','مولکول‌های زیستی','medium','{"key":"14230ae1dc09f274cb9cefb09b3cd6b5","subjectId":"biochemistry","chapter":"مولکول‌های زیستی","prompt":"Mad cow disease is an infectious disease where one misfolded protein causes all other copies of the protein to begin misfolding. This is an example of a disease impacting ____ structure.","options":["primary","secondary","tertiary","quaternary"],"correctIndex":2,"explanation":"Published solution key: C — tertiary. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66442/index.cnxml#fs-idm71000707","license":"CC-BY-4.0","questionId":"m66442#fs-idm71000707","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
