INSERT INTO learning_questions (id,pack_id,subject_id,chapter,difficulty,content) VALUES
('c096f99a41e0f5bb36140459518322a6','reference-openstax-dental-basics-histology-fa-1','histology','ساختار سلول','medium','{"key":"60200f97a53035e90125402c0a1ec9c0","subjectId":"histology","chapter":"ساختار سلول","prompt":"دانشمندان هنگام مشاهدهٔ نمونه با میکروسکوپ نوری، برای تمایز اجزای سلول از چه چیزی استفاده می‌کنند؟","options":["باریکهٔ الکترونی","ایزوتوپ‌های رادیواکتیو","رنگ‌های ویژه","دمای بالا"],"correctIndex":2,"explanation":"رنگ‌آمیزی، کنتراست اجزای سلول را در میکروسکوپ نوری افزایش می‌دهد. باریکهٔ الکترونی مربوط به میکروسکوپ الکترونی است.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66445/index.cnxml#fs-id1775146","license":"CC-BY-4.0","questionId":"m66445#fs-id1775146","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('bd107e3acae1d346c0efde66d58c7ed8','reference-openstax-dental-basics-histology-fa-1','histology','ساختار سلول','medium','{"key":"aafb00a225f4a46a704a1b82c0c244ca","subjectId":"histology","chapter":"ساختار سلول","prompt":"واحد پایهٔ حیات کدام است؟","options":["جاندار","سلول","بافت","اندام"],"correctIndex":1,"explanation":"سلول کوچک‌ترین واحد ساختاری و عملکردی حیات است. بافت‌ها و اندام‌ها از سازمان‌یافتن سلول‌ها پدید می‌آیند.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66445/index.cnxml#fs-id1989359","license":"CC-BY-4.0","questionId":"m66445#fs-id1989359","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('082ddb77cba3a632a11f8b155f4d1a08','reference-openstax-dental-basics-histology-fa-1','histology','ساختار سلول','medium','{"key":"49c087763ba066310136acd82320c776","subjectId":"histology","chapter":"ساختار سلول","prompt":"پروکاریوت‌ها برای دریافت برخی مواد و دفع مواد زائد، به کدام فرایند وابسته‌اند؟","options":["ریبوزوم‌ها","تاژک‌ها","تقسیم سلولی","انتشار"],"correctIndex":3,"explanation":"اندازهٔ کوچک پروکاریوت‌ها و نسبت سطح به حجم بالای آن‌ها، تبادل برخی مواد با انتشار را امکان‌پذیر می‌کند. ریبوزوم نقش ساخت پروتئین دارد و تاژک در حرکت دخالت می‌کند.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-id1617238","license":"CC-BY-4.0","questionId":"m66446#fs-id1617238","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('e4e6843aef1f9acde1cd10405b4d85c8','reference-openstax-dental-basics-histology-fa-1','histology','ساختار سلول','medium','{"key":"e9b6214f2f0e17275232c4a80dcafad5","subjectId":"histology","chapter":"ساختار سلول","prompt":"باکتری‌های فاقد فیمبریه، در انجام کدام کار توانایی کمتری دارند؟","options":["چسبیدن به سطح سلول‌ها","شناکردن در مایعات بدن","ساخت پروتئین","حفظ توانایی تقسیم"],"correctIndex":0,"explanation":"فیمبریه‌ها زوائد کوتاه سطح باکتری هستند و در اتصال باکتری به سطوح نقش دارند. حرکت شناوری معمولاً به تاژک مربوط است.","difficulty":"medium","topic":{"title":"ساختار سلول","important":["سلول واحد پایهٔ حیات است.","فیمبریه به اتصال باکتری به سطح کمک می‌کند."],"microLesson":"میکروسکوپ نوری با نور مرئی کار می‌کند و رنگ‌آمیزی، تمایز اجزای نمونه را آسان‌تر می‌سازد. پروکاریوت‌ها سلول‌های کوچک فاقد هستهٔ غشادار هستند. اندازهٔ کوچک، تبادل مواد از راه انتشار را تسهیل می‌کند. فیمبریه و تاژک نقش‌های متفاوتی در اتصال و حرکت دارند.","branches":[{"title":"مشاهدهٔ سلول","points":["میکروسکوپ نوری","رنگ‌آمیزی برای افزایش کنتراست"]},{"title":"سلول پروکاریوتی","points":["انتشار و نسبت سطح به حجم","فیمبریه برای اتصال؛ تاژک برای حرکت"]}]},"language":"fa","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi · ترجمه و توضیح فارسی","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66446/index.cnxml#fs-id866358","license":"CC-BY-4.0","questionId":"m66446#fs-id866358","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}');
