('fe8795202e5b3162579d566b66a0a398','reference-openstax-medical-basics-genetics-en-1','genetics','چرخهٔ سلولی','medium','{"key":"be84f760c3243141d32947980e5309fc","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"An organism’s traits are determined by the specific combination of inherited _____.","options":["cells.","genes.","proteins.","chromatids."],"correctIndex":1,"explanation":"Published solution key: B — genes.. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66477/index.cnxml#fs-id1359443","license":"CC-BY-4.0","questionId":"m66477#fs-id1359443","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('26a74b2ff7325f1d751c4dcc98bc431f','reference-openstax-medical-basics-genetics-en-1','genetics','چرخهٔ سلولی','medium','{"key":"53b5493792addf76a9127fe6b8960aec","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"Which of the following events does not occur during some stages of interphase?","options":["DNA duplication","organelle duplication","increase in cell size","separation of sister chromatids"],"correctIndex":3,"explanation":"Published solution key: D — separation of sister chromatids. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66478/index.cnxml#fs-id2755057","license":"CC-BY-4.0","questionId":"m66478#fs-id2755057","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('e44b7a567eec24086756325d1e2a5cbd','reference-openstax-medical-basics-genetics-en-1','genetics','چرخهٔ سلولی','medium','{"key":"058bb445e94deedc9971fee2f269ba62","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"The mitotic spindles arise from which cell structure?","options":["centromere","centrosome","kinetochore","cleavage furrow"],"correctIndex":1,"explanation":"Published solution key: B — centrosome. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66478/index.cnxml#fs-id1458009","license":"CC-BY-4.0","questionId":"m66478#fs-id1458009","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('5148ce1a27c59121f8b40e83b0e05837','reference-openstax-medical-basics-genetics-en-1','genetics','چرخهٔ سلولی','medium','{"key":"a0dc834f72da5c04b9b1e3b690d81846","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"Attachment of the mitotic spindle fibers to the kinetochores is a characteristic of which stage of mitosis?","options":["prophase","prometaphase","metaphase","anaphase"],"correctIndex":1,"explanation":"Published solution key: B — prometaphase. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66478/index.cnxml#fs-id1462637","license":"CC-BY-4.0","questionId":"m66478#fs-id1462637","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('bbf1915ec221fdfc59a2b2dbfb75703b','reference-openstax-medical-basics-genetics-en-1','genetics','چرخهٔ سلولی','medium','{"key":"be41f00542e57d4bbcb735252ce23e1d","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"Unpacking of chromosomes and the formation of a new nuclear envelope is a characteristic of which stage of mitosis?","options":["prometaphase","metaphase","anaphase","telophase"],"correctIndex":3,"explanation":"Published solution key: D — telophase. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66478/index.cnxml#fs-id1565777","license":"CC-BY-4.0","questionId":"m66478#fs-id1565777","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('945b55060e10a2e1161da4c36dfcd11d','reference-openstax-medical-basics-genetics-en-1','genetics','چرخهٔ سلولی','medium','{"key":"734356d22c4bfdb6c5f7f59325b1d507","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"Separation of the sister chromatids is a characteristic of which stage of mitosis?","options":["prometaphase","metaphase","anaphase","telophase"],"correctIndex":2,"explanation":"Published solution key: C — anaphase. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66478/index.cnxml#fs-id1506066","license":"CC-BY-4.0","questionId":"m66478#fs-id1506066","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
('c118baa1f0a3de6ca37c88499932329c','reference-openstax-medical-basics-genetics-en-1','genetics','چرخهٔ سلولی','medium','{"key":"6ef960aeadaf95feba9f3461f9bc0338","subjectId":"genetics","chapter":"چرخهٔ سلولی","prompt":"The chromosomes become visible under a light microscope during which stage of mitosis?","options":["prophase","prometaphase","metaphase","anaphase"],"correctIndex":0,"explanation":"Published solution key: A — prophase. The source section linked below contains the underlying concepts.","difficulty":"medium","topic":null,"language":"en","source":{"name":"OpenStax Biology 2e — Clark, Douglas & Choi","url":"https://github.com/openstax/osbooks-biology-bundle/blob/4460012626ee747bdb9db8c4418317798fbc67ce/modules/m66478/index.cnxml#fs-id1433213","license":"CC-BY-4.0","questionId":"m66478#fs-id1433213","revision":"4460012626ee747bdb9db8c4418317798fbc67ce"}}'),
